/* ==========================================================================
   JOC CLOUD CONFIG — default SharePoint/OneDrive "Data App" folder for
   Toolkits → JOC Data Processor's automatic file connection. It is
   completely separate from the Supabase config above; nothing else in
   the app reads this.

   DATA_APP_SHARE_URL below is only the *initial default*. Once a user
   saves a folder URL in Settings → Data Location, that saved value
   (persisted in localStorage — see the JocDataLocation module) always
   takes priority over this default. See JocDataLocation.getLocation().
   ========================================================================== */
const JOC_CLOUD_CONFIG = {
  DATA_APP_SHARE_URL: 'https://swiftfreightindia-my.sharepoint.com/:f:/g/personal/ritesh_das_swiftcargo_com/IgCIUnj4oVtYS5YlvXcSIiJxAYimFU656tzbIAxHPLiPWW8?e=Ak9pfo',

  MASTER_FILENAME: 'Master File - JOC Goup.xlsx',
  PIERS_FILENAME_HINT: 'PIERS import records needed automation.xlsx',

  AUTO_DETECT_POLL_MS: 5 * 60 * 1000
};

/* ==========================================================================
   JOC DATA LOCATION — Settings → Data Location.
   Owns: reading/saving the user's SharePoint/OneDrive folder URL
   (localStorage only — never the workbook itself), testing whether the
   browser can actually reach that folder, and reflecting real status
   into both the Settings pane and the Toolkits → JOC cloud connection
   card. Self-contained; does not touch any other app functionality.
   ========================================================================== */
const JocDataLocation = (() => {
  const STORAGE_KEY = 'joc_data_location_url';
  const MSAL_STORAGE_KEY = 'joc_ms_auth_config'; // { clientId, tenantId } — no secrets, just app/tenant IDs
  const GRAPH_SCOPES = ['Files.Read.All'];
  let lastResult = null;
  let pollTimer = null;
  let msalInstance = null;

  function byId(id){ return document.getElementById(id); }

  /* ---------- Data location (folder URL) persistence ---------- */
  function getSavedUrl(){
    try{ return (localStorage.getItem(STORAGE_KEY) || '').trim(); }
    catch(e){ return ''; }
  }
  function getLocation(){
    return getSavedUrl() || JOC_CLOUD_CONFIG.DATA_APP_SHARE_URL;
  }
  function saveUrl(url){
    try{ localStorage.setItem(STORAGE_KEY, (url||'').trim()); return true; }
    catch(e){ return false; }
  }
  function clearSaved(){
    try{ localStorage.removeItem(STORAGE_KEY); } catch(e){}
  }
  function looksLikeCloudFolderUrl(url){
    if (!url) return false;
    try{
      const u = new URL(url);
      return /(^|\.)sharepoint\.com$/i.test(u.hostname)
          || /(^|\.)1drv\.ms$/i.test(u.hostname)
          || /(^|\.)onedrive\.live\.com$/i.test(u.hostname);
    } catch(e){ return false; }
  }

  /* ---------- Microsoft sign-in config persistence (optional) ---------- */
  function getMsalConfig(){
    try{ return JSON.parse(localStorage.getItem(MSAL_STORAGE_KEY) || 'null'); }
    catch(e){ return null; }
  }
  function saveMsalConfig(clientId, tenantId){
    try{ localStorage.setItem(MSAL_STORAGE_KEY, JSON.stringify({ clientId: (clientId||'').trim(), tenantId: (tenantId||'').trim() })); return true; }
    catch(e){ return false; }
  }
  function clearMsalConfig(){
    try{ localStorage.removeItem(MSAL_STORAGE_KEY); } catch(e){}
  }

  function ensureMsalInstance(){
    const cfg = getMsalConfig();
    if (!cfg || !cfg.clientId) return null;
    if (typeof msal === 'undefined') return null; // msal-browser.min.js failed to load / offline
    if (msalInstance) return msalInstance;
    msalInstance = new msal.PublicClientApplication({
      auth: {
        clientId: cfg.clientId,
        authority: 'https://login.microsoftonline.com/' + (cfg.tenantId || 'common'),
        redirectUri: window.location.origin + window.location.pathname
      },
      cache: { cacheLocation: 'sessionStorage' }
    });
    return msalInstance;
  }
  function getActiveAccount(){
    const inst = ensureMsalInstance();
    if (!inst) return null;
    return inst.getActiveAccount() || inst.getAllAccounts()[0] || null;
  }
  function isSignedIn(){ return !!getActiveAccount(); }

  async function signIn(){
    const inst = ensureMsalInstance();
    if (!inst) throw new Error('Add an Azure AD Client ID in Settings → Data Location first.');
    const result = await inst.loginPopup({ scopes: GRAPH_SCOPES });
    inst.setActiveAccount(result.account);
    return result.account;
  }
  async function signOut(){
    const inst = ensureMsalInstance();
    const account = inst && inst.getActiveAccount();
    if (inst && account){
      try{ await inst.logoutPopup({ account }); } catch(e){ /* user closed popup, ignore */ }
    }
  }
  async function getAccessToken(){
    const inst = ensureMsalInstance();
    const account = getActiveAccount();
    if (!inst || !account) return null;
    try{
      const res = await inst.acquireTokenSilent({ scopes: GRAPH_SCOPES, account });
      return res.accessToken;
    } catch(e){
      const res = await inst.acquireTokenPopup({ scopes: GRAPH_SCOPES, account });
      return res.accessToken;
    }
  }

  /* ---------- Microsoft Graph: resolve a share link → folder → files ---------- */
  function encodeSharingUrl(url){
    const b64 = btoa(unescape(encodeURIComponent(url)))
      .replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-');
    return 'u!' + b64;
  }
  async function graphGet(url, token){
    const res = await fetch(url, { headers: { Authorization: 'Bearer ' + token } });
    if (!res.ok) throw new Error(`Microsoft Graph request failed (${res.status})`);
    return res.json();
  }
  async function findFilesInFolder(folderUrl, token){
    const shareId = encodeSharingUrl(folderUrl);
    const data = await graphGet(`https://graph.microsoft.com/v1.0/shares/${shareId}/driveItem/children?$top=200`, token);
    const items = (data.value || []).filter(i => i.file);
    const masterItem = items.find(i => i.name === JOC_CLOUD_CONFIG.MASTER_FILENAME) || null;
    const piersCandidates = items
      .filter(i => i.name === JOC_CLOUD_CONFIG.PIERS_FILENAME_HINT || /piers/i.test(i.name))
      .sort((a,b) => new Date(b.lastModifiedDateTime) - new Date(a.lastModifiedDateTime));
    return { masterItem, piersItem: piersCandidates[0] || null };
  }
  async function downloadDriveItem(item, token){
    let downloadUrl = item['@microsoft.graph.downloadUrl'];
    if (!downloadUrl && item.parentReference){
      const full = await graphGet(`https://graph.microsoft.com/v1.0/drives/${item.parentReference.driveId}/items/${item.id}`, token);
      downloadUrl = full['@microsoft.graph.downloadUrl'];
    }
    if (!downloadUrl) throw new Error(`Couldn't get a download URL for ${item.name}`);
    const res = await fetch(downloadUrl);
    if (!res.ok) throw new Error(`Failed to download ${item.name} (${res.status})`);
    const buf = await res.arrayBuffer();
    return new File([buf], item.name, { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  }
  function fmtBytes(n){
    if (!n && n !== 0) return '';
    if (n < 1024*1024) return (n/1024).toFixed(0) + ' KB';
    return (n/1024/1024).toFixed(1) + ' MB';
  }

  // Real, unfaked reachability check used when Microsoft sign-in isn't
  // configured. Browsers cannot list or download files from an authenticated
  // SharePoint/OneDrive folder using only a sharing link — that requires a
  // signed-in Graph request. So this never claims "Connected" unless an
  // actual request to the folder succeeds; any auth/CORS failure is reported.
  async function testConnectionUnauthenticated(url){

  // A SharePoint/OneDrive sharing URL cannot be reliably tested
  // from a local file:// page using a direct browser fetch().
  // Do NOT make a cross-origin request here.
  //
  // Actual SharePoint access is handled through Microsoft Graph
  // after Microsoft authentication. The Data Hub local-folder
  // importer does NOT depend on this legacy URL test.

  if (!url){
    return {
      ok:false,
      code:'missing',
      message:'No SharePoint/OneDrive folder URL is configured.'
    };
  }

  return {
    ok:false,
    code:'auth',
    message:'SharePoint access requires Microsoft sign-in. Use "Connect to Microsoft" or use the local folder connection.'
  };
}

  function applyResult(result){
    lastResult = result;

    // Settings → Data Location pane
    const dot = byId('dl-status-dot');
    const text = byId('dl-status-text');
    const errBox = byId('dl-status-error');
    const errSub = byId('dl-status-error-sub');
    if (dot) dot.className = 'joc-status-dot ' + (result.ok ? 'ok' : 'err');
    if (text) text.textContent = result.ok ? '\u25CF Connected' : '\u25CF Unable to access folder';
    if (errBox && errSub){
      errBox.classList.toggle('hidden', result.ok);
      errSub.textContent = result.message || '';
    }

    // Settings → Microsoft Sign-in status
    const account = getActiveAccount();
    const msDot = byId('ms-status-dot');
    const msText = byId('ms-status-text');
    if (msDot) msDot.className = 'joc-status-dot ' + (account ? 'ok' : '');
    if (msText) msText.textContent = account ? `Signed in as ${account.username}` : 'Not signed in';

    // Toolkits → JOC cloud connection card
    const cloudText = byId('joc-cloud-status-text');
    const cloudPill = byId('joc-cloud-status-pill');
    const cloudSynced = byId('joc-cloud-synced');
    const cloudErrorBox = byId('joc-cloud-error');
    const cloudErrorTitle = byId('joc-cloud-error-title');
    const cloudErrorSub = byId('joc-cloud-error-sub');
    const masterName = byId('joc-master-name');
    const masterMeta = byId('joc-master-meta');
    const masterStatus = byId('joc-master-status');
    const piersName = byId('joc-piers-name');
    const piersMeta = byId('joc-piers-meta');
    const piersStatus = byId('joc-piers-status');
    const connectMsBtn = byId('joc-connect-ms-btn');

    if (cloudPill){
      cloudPill.textContent = result.ok ? 'Connected' : 'Unable to access folder';
      cloudPill.className = 'pill ' + (result.ok ? 'pill-green' : 'pill-red');
    }
    if (cloudText) cloudText.textContent = result.ok ? 'Connected to the configured SharePoint folder' : result.message;
    if (cloudSynced) cloudSynced.textContent = result.ok ? ('Synced ' + new Date().toLocaleTimeString()) : 'Not connected';
    if (connectMsBtn) connectMsBtn.classList.toggle('hidden', !!account);

    if (cloudErrorBox && cloudErrorTitle && cloudErrorSub){
      cloudErrorBox.classList.toggle('hidden', result.ok);
      cloudErrorTitle.textContent = result.code === 'auth'
        ? 'Folder requires Microsoft authentication/access permission.'
        : 'Unable to access the selected data folder.';
      cloudErrorSub.textContent = result.code === 'auth'
        ? 'Click "Connect to Microsoft" (or set it up in Settings → Data Location) to sign in, or use a local file instead.'
        : (result.message || 'Please verify the folder URL, its sharing permissions, and that the required Excel files exist.');
    }

    if (masterName) masterName.textContent = result.ok ? JOC_CLOUD_CONFIG.MASTER_FILENAME : 'Master File - JOC Goup not found';
    if (masterMeta) masterMeta.textContent = (result.ok && result.masterItem) ? `${fmtBytes(result.masterItem.size)} · modified ${new Date(result.masterItem.lastModifiedDateTime).toLocaleString()}` : '';
    if (masterStatus){ masterStatus.textContent = result.ok ? 'Found' : 'Missing'; masterStatus.className = 'joc-file-row-status ' + (result.ok ? 'ok' : 'err'); }
    if (piersName) piersName.textContent = result.ok ? JOC_CLOUD_CONFIG.PIERS_FILENAME_HINT : 'PIERS import records needed automation.xlsx not found';
    if (piersMeta) piersMeta.textContent = (result.ok && result.piersItem) ? `${fmtBytes(result.piersItem.size)} · modified ${new Date(result.piersItem.lastModifiedDateTime).toLocaleString()}` : '';
    if (piersStatus){ piersStatus.textContent = result.ok ? 'Found' : 'Missing'; piersStatus.className = 'joc-file-row-status ' + (result.ok ? 'ok' : 'err'); }

    // Surface the manual upload fallback automatically whenever the cloud
    // folder isn't reachable, so the toolkit stays usable either way.
    const manualPanel = byId('joc-manual-panel');
    if (manualPanel && !result.ok) manualPanel.classList.remove('hidden');
  }

  async function runTest(url){
    const target = (url || getLocation()).trim();
    const dot = byId('dl-status-dot'); if (dot) dot.className = 'joc-status-dot pending';
    const text = byId('dl-status-text'); if (text) text.textContent = 'Testing\u2026';
    const cloudPill = byId('joc-cloud-status-pill');
    if (cloudPill){ cloudPill.textContent = 'Connecting'; cloudPill.className = 'pill pill-gray'; }

    if (!target){ applyResult({ ok:false, code:'empty', message:'Please paste a SharePoint or OneDrive folder URL.' }); return lastResult; }
    if (!looksLikeCloudFolderUrl(target)){ applyResult({ ok:false, code:'invalid', message:'That doesn\u2019t look like a SharePoint/OneDrive folder link. Please check the URL.' }); return lastResult; }

    if (isSignedIn()){
      try{
        const token = await getAccessToken();
        const { masterItem, piersItem } = await findFilesInFolder(target, token);
        if (!masterItem){
          applyResult({ ok:false, code:'missing-master', message: `${JOC_CLOUD_CONFIG.MASTER_FILENAME} not found in the folder.` });
          return lastResult;
        }
        if (!piersItem){
          applyResult({ ok:false, code:'missing-piers', message: `${JOC_CLOUD_CONFIG.PIERS_FILENAME_HINT} not found in the folder.` });
          return lastResult;
        }
        const [masterFile, piersFile] = await Promise.all([
          downloadDriveItem(masterItem, token),
          downloadDriveItem(piersItem, token)
        ]);
        if (window.JOCToolkit){
          await JOCToolkit.loadLookupFile(masterFile);
          await JOCToolkit.loadMainFile(piersFile);
        }
        applyResult({ ok:true, code:'connected', message:'Connected', masterItem, piersItem });
        toast('Connected — Master File and PIERS import loaded from SharePoint.', 'success');
      } catch(e){
        applyResult({ ok:false, code:'graph-error', message: `Signed in to Microsoft, but couldn\u2019t read the folder: ${e.message || e}` });
      }
      return lastResult;
    }

    const result = await testConnectionUnauthenticated(target);
    applyResult(result);
    return lastResult;
  }

  function renderSettingsPane(){
    const input = byId('dl-url-input');
    if (input && document.activeElement !== input) input.value = getLocation();
    const cfg = getMsalConfig();
    const clientInput = byId('ms-client-id-input');
    const tenantInput = byId('ms-tenant-id-input');
    if (clientInput && document.activeElement !== clientInput) clientInput.value = cfg?.clientId || '';
    if (tenantInput && document.activeElement !== tenantInput) tenantInput.value = cfg?.tenantId || '';
    if (lastResult) applyResult(lastResult);
    else applyResult({ ok:false, code:'idle', message:'Not tested yet' });
  }

  function schedulePolling(enabled){
    if (pollTimer){ clearInterval(pollTimer); pollTimer = null; }
    if (enabled){
      pollTimer = setInterval(() => { runTest(getLocation()); }, JOC_CLOUD_CONFIG.AUTO_DETECT_POLL_MS);
    }
  }

  function wireUI(){
    const saveBtn = byId('dl-save-btn');
    const testBtn = byId('dl-test-btn');
    const resetBtn = byId('dl-reset-btn');
    const input = byId('dl-url-input');

    if (saveBtn) saveBtn.addEventListener('click', async () => {
      const val = (input?.value || '').trim();
      if (!val){ toast('Enter a SharePoint/OneDrive folder URL first.', 'error'); return; }
      saveUrl(val);
      toast('Data location saved.', 'success');
      await runTest(val);
    });
    if (testBtn) testBtn.addEventListener('click', async () => {
      const val = (input?.value || getLocation()).trim();
      await runTest(val);
    });
    if (resetBtn) resetBtn.addEventListener('click', async () => {
      clearSaved();
      if (input) input.value = JOC_CLOUD_CONFIG.DATA_APP_SHARE_URL;
      toast('Reset to the default data location.', '');
      await runTest(getLocation());
    });

    const retryBtn = byId('joc-retry-btn');
    if (retryBtn) retryBtn.addEventListener('click', () => runTest(getLocation()));
    const refreshBtn = byId('joc-refresh-btn');
    if (refreshBtn) refreshBtn.addEventListener('click', () => runTest(getLocation()));
    const useLocalBtn = byId('joc-use-local-btn');
    if (useLocalBtn) useLocalBtn.addEventListener('click', () => {
      const panel = byId('joc-manual-panel');
      if (panel) panel.classList.remove('hidden');
    });
    const manualCloseBtn = byId('joc-manual-close-btn');
    if (manualCloseBtn) manualCloseBtn.addEventListener('click', () => {
      const panel = byId('joc-manual-panel');
      if (panel) panel.classList.add('hidden');
    });
    const autoToggle = byId('joc-auto-detect-toggle');
    if (autoToggle) autoToggle.addEventListener('change', () => schedulePolling(autoToggle.checked));

    // Microsoft sign-in (Settings pane)
    const msSaveBtn = byId('ms-save-btn');
    const msSignoutBtn = byId('ms-signout-btn');
    const clientInput = byId('ms-client-id-input');
    const tenantInput = byId('ms-tenant-id-input');
    if (msSaveBtn) msSaveBtn.addEventListener('click', async () => {
      const clientId = (clientInput?.value || '').trim();
      if (!clientId){ toast('Enter an Azure AD Client ID first.', 'error'); return; }
      if (typeof msal === 'undefined'){ toast('Microsoft sign-in library failed to load — check your connection and reload.', 'error'); return; }
      saveMsalConfig(clientId, tenantInput?.value || '');
      msalInstance = null; // force re-init with new config
      try{
        setLoading(msSaveBtn, true);
        await signIn();
        toast('Signed in to Microsoft.', 'success');
        await runTest(getLocation());
      } catch(e){
        toast(`Microsoft sign-in failed: ${e.message || e}`, 'error');
        applyResult({ ok:false, code:'signin-failed', message: `Microsoft sign-in failed: ${e.message || e}` });
      } finally{
        setLoading(msSaveBtn, false);
      }
    });
    if (msSignoutBtn) msSignoutBtn.addEventListener('click', async () => {
      await signOut();
      clearMsalConfig();
      msalInstance = null;
      toast('Signed out of Microsoft.', '');
      await runTest(getLocation());
    });

    // "Connect to Microsoft" quick button on the Toolkits cloud card
    const connectMsBtn = byId('joc-connect-ms-btn');
    if (connectMsBtn) connectMsBtn.addEventListener('click', async () => {
      const cfg = getMsalConfig();
      if (!cfg || !cfg.clientId){
        toast('Add an Azure AD Client ID in Settings → Data Location first.', 'error');
        goPage('settings');
        const navBtn = $('#settings-nav [data-pane="datalocation"]');
        if (navBtn) navBtn.click();
        return;
      }
      try{
        setLoading(connectMsBtn, true);
        await signIn();
        toast('Signed in to Microsoft.', 'success');
        await runTest(getLocation());
      } catch(e){
        toast(`Microsoft sign-in failed: ${e.message || e}`, 'error');
      } finally{
        setLoading(connectMsBtn, false);
      }
    });
  }

  function init(){
    wireUI();
    const input = byId('dl-url-input');
    if (input) input.value = getLocation();
    runTest(getLocation());
  }

  return { init, getLocation, saveUrl, clearSaved, runTest, renderSettingsPane, isSignedIn };
})();

/* ==========================================================================
   JOC LOCAL DATA FOLDER — Settings → Data Location "Data Folder" +
   Toolkits → JOC Data Processor "Data Source" (Excel file explorer).

   Owns: picking a local/OneDrive-synced folder via the File System Access
   API, persisting only the FileSystemDirectoryHandle (never file bytes) in
   IndexedDB, restoring it on startup, verifying/re-requesting permission,
   scanning the folder for EVERY .xlsx/.xlsm/.xls file it contains,
   classifying each one by CONTENT (never filename) as a Lookup workbook,
   a JOC-compatible source workbook, or Other Excel, and feeding detected
   files into the EXISTING JOCToolkit pipeline via
   JOCToolkit.loadLookupFile()/loadMainFile()/processCurrentFiles() — no
   second processing engine.

   There is no "Import" step: any JOC-compatible workbook that hasn't been
   processed yet (or has changed since it was last processed) is queued and
   run through the pipeline automatically. A lightweight processing history
   (localStorage, metadata only) means unchanged files are never
   reprocessed on a later scan — SCAN ≠ PROCESS.

   This is the preferred/primary data source. The legacy SharePoint URL
   flow (JocDataLocation, above) is left completely untouched and remains
   available as an advanced/legacy fallback.
   ========================================================================== */
const JocLocalFolder = (() => {
  // Shares the exact same IndexedDB database/store/key as DataHubFolder (see below), so the
  // folder picked once in Settings → Data Hub Source Folder is the ONE connection both features
  // use — there is no separate picker for the JOC toolkit.
  const DB_NAME = 'datahub_folder_db';
  const DB_VERSION = 2;
  const STORE = 'handles';
  const HANDLE_KEY = 'datahub_fixed_source_folder_v1';
  const FOLDER_NAME_CACHE_KEY = 'joc_local_folder_name'; // display-only, no file data
  const EXCEL_EXT = /\.(xlsx|xlsm|xls)$/i;
  const HISTORY_KEY = 'joc_processing_history_v1'; // processing memory — survives reloads (metadata only)

  let dirHandle = null;
  let scanning = false;
  let pollTimer = null;
  let lastLookupKey = null; // fingerprint of the lookup workbook currently loaded into JOCToolkit

  // fingerprint -> { kind:'lookup'|'joc'|'other', detection, sheetNames, headers, rowCount }
  // Avoids re-reading/re-classifying a file that hasn't changed — this is what
  // keeps repeat folder scans lightweight (spec #10/#18: SCAN ≠ PROCESS).
  const detectionCache = new Map();
  // fingerprint -> Blob — in-memory only, so a processed file can be
  // re-downloaded from its details panel without re-running the pipeline.
  const outputBlobs = new Map();

  let historyMap = {};   // fileName -> processing record (persisted)
  let lastModels = [];   // most recent scan result, for the details panel
  let openDetailsFp = null;

  function byId(id){ return document.getElementById(id); }
  function show(el, on){ if (el) el.classList.toggle('hidden', !on); }
  function supported(){ return 'showDirectoryPicker' in window; }
  function safeName(h){ return (h && h.name) ? h.name : 'Selected folder'; }
  function jocEscHtml(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  /* ---------- IndexedDB: persists ONLY the directory handle/permission info ---------- */
  function openDb(){
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => { const db = req.result; if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE); };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  async function idbSet(key, value){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(value, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
  async function idbGet(key){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => reject(req.error);
    });
  }

  function fmtBytes(n){
    if (n == null) return '';
    if (n < 1024*1024) return (n/1024).toFixed(0) + ' KB';
    return (n/1024/1024).toFixed(1) + ' MB';
  }
  function fmtTime(ms){
    if (!ms) return '';
    return new Date(ms).toLocaleString([], { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' });
  }
  function fileKey(meta){ return meta ? `${meta.name}|${meta.size}|${meta.lastModified}` : ''; }

  /* ---------- processing history (memory of what's already been processed) ---------- */
  function loadHistory(){
    try{
      const raw = localStorage.getItem(HISTORY_KEY);
      historyMap = raw ? JSON.parse(raw) : {};
    } catch(e){ historyMap = {}; }
  }
  function saveHistory(){
    try{ localStorage.setItem(HISTORY_KEY, JSON.stringify(historyMap)); } catch(e){ /* best-effort */ }
  }

  /* ---------- permission handling ---------- */
  async function checkPermission(handle, request){
    if (!handle) return 'prompt';
    const opts = { mode: 'read' };
    try{
      let perm = await handle.queryPermission(opts);
      if (perm === 'granted') return perm;
      if (request) perm = await handle.requestPermission(opts);
      return perm;
    } catch(e){ return 'denied'; }
  }

  /* ---------- scan folder contents (metadata only, until a file is actually needed) ---------- */
  async function scanEntries(handle){
    const files = [];
    for await (const [name, entryHandle] of handle.entries()){
      if (entryHandle.kind !== 'file') continue;
      if (!EXCEL_EXT.test(name)) continue;
      if (name.startsWith('~$')) continue; // Excel lock files
      try{
        const file = await entryHandle.getFile();
        files.push({ name: file.name, size: file.size, lastModified: file.lastModified, handle: entryHandle });
      } catch(e){
        // OneDrive Files-On-Demand: entry is listed but not currently downloaded/readable.
        files.push({ name, size:null, lastModified:null, handle: entryHandle, unreadable:true });
      }
    }
    return files;
  }

  /* ---------- classify a single file: Lookup / JOC / Other — by CONTENT, never filename ---------- */
  async function classifyFile(fileMeta){
    const fp = fileKey(fileMeta);
    if (detectionCache.has(fp)) return detectionCache.get(fp);
    let info;
    try{
      const f = await fileMeta.handle.getFile();
      info = await JOCToolkit.readWorkbookInfo(f);
    } catch(e){
      const errInfo = { kind:'error', error: e.message || String(e) };
      detectionCache.set(fp, errInfo);
      return errInfo;
    }
    const lookup = JOCToolkit.detectLookupWorkbook(info.sheetNames);
    let result;
    if (lookup.isLookup){
      result = { kind:'lookup', sheetNames: info.sheetNames, lookupMatch: lookup, rowCount: info.rowCount };
    } else {
      const detection = JOCToolkit.classifyWorkbook(info.headers);
      result = { kind: detection.isJoc ? 'joc' : 'other', sheetNames: info.sheetNames, detection, rowCount: info.rowCount };
    }
    detectionCache.set(fp, result);
    return result;
  }

  /* ---------- folder picking ---------- */
  /* The Data Hub Source Folder in Settings is the ONE folder connection in the app (spec #1/#2/#18) —
     this toolkit never opens its own picker. Selecting/reconnecting the folder always happens there;
     DataHubFolder then calls adoptSharedHandle() below to hand the same handle to this module. */
  async function pickFolder(){
    toast('Connect the Data Hub Source Folder in Settings — the same folder powers this toolkit.', '');
    if (typeof goPage === 'function') goPage('settings');
    const paneBtn = document.querySelector('.settings-nav [data-pane="datalocation"]');
    if (paneBtn) paneBtn.click();
    setTimeout(() => byId('dh-folder-panel')?.scrollIntoView({ behavior:'smooth', block:'center' }), 80);
  }

  async function grantAccess(){
    if (!dirHandle){ await pickFolder(); return; }
    const perm = await checkPermission(dirHandle, true);
    if (perm === 'granted'){
      await scanAndLoad();
      schedulePolling(true);
    } else {
      render({ status:'permission-denied', folderName: safeName(dirHandle) });
      toast('Folder access denied.', 'error');
    }
  }

  /* ---------- called by DataHubFolder right after it picks/reconnects the ONE shared folder ---------- */
  async function adoptSharedHandle(handle){
    if (!handle) return;
    dirHandle = handle;
    lastLookupKey = null; detectionCache.clear(); outputBlobs.clear(); // don't mix folders (spec #23)
    try{ await idbSet(HANDLE_KEY, handle); } catch(e){ /* best-effort persistence */ }
    try{ localStorage.setItem(FOLDER_NAME_CACHE_KEY, safeName(handle)); } catch(e){}
    await scanAndLoad();
    schedulePolling(true);
  }

  /* ---------- derive a file's processing status from history + fingerprint ---------- */
  function statusFor(name, fp){
    const hist = historyMap[name];
    if (!hist) return 'new';
    if (hist.fingerprint === fp) return 'processed';
    return 'updated'; // same filename, different fingerprint — spec #12
  }

  /* ---------- scan + classify every xlsx + auto-process new/changed JOC files ---------- */
  async function scanAndLoad(){
    if (!dirHandle || scanning) return;
    scanning = true;
    render({ status:'scanning', folderName: safeName(dirHandle) });
    try{
      const files = await scanEntries(dirHandle);

      const models = [];
      for (const f of files){
        const fp = fileKey(f);
        if (f.unreadable){
          models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fingerprint:fp, handle:f.handle, kind:'unreadable', status:'offline' });
          continue;
        }
        const info = await classifyFile(f);
        if (info.kind === 'error'){
          models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fingerprint:fp, handle:f.handle, kind:'error', status:'error', errorMsg:info.error });
          continue;
        }
        const model = {
          name:f.name, size:f.size, lastModified:f.lastModified, fingerprint:fp, handle:f.handle,
          kind: info.kind, sheetNames: info.sheetNames, rowCount: info.rowCount, detection: info.detection || null,
        };
        if (info.kind === 'lookup'){
          model.status = 'lookup';
        } else if (info.kind === 'other'){
          model.status = 'not-joc';
        } else {
          model.status = statusFor(f.name, fp);
        }
        model.hist = historyMap[f.name] || null;
        models.push(model);
      }

      // sort: lookup first, then JOC (new/updated before processed), then other, then problem files
      const rank = m => ({ lookup:0, joc:1, other:2, unreadable:3, error:3 }[m.kind] ?? 4);
      const statusRank = s => ({ new:0, updated:0, processing:0, processed:1, 'not-joc':2 }[s] ?? 1);
      models.sort((a,b) => rank(a) - rank(b) || statusRank(a.status) - statusRank(b.status) || a.name.localeCompare(b.name));

      // pick the lookup workbook — most recently modified, if more than one qualifies
      const lookupCandidates = models.filter(m => m.kind === 'lookup');
      lookupCandidates.sort((a,b) => (b.lastModified||0) - (a.lastModified||0));
      const lookupModel = lookupCandidates[0] || null;

      let loadErr = null;
      if (lookupModel && lookupModel.fingerprint !== lastLookupKey){
        try{
          const f = await lookupModel.handle.getFile();
          await JOCToolkit.loadLookupFile(f);
          lastLookupKey = lookupModel.fingerprint;
        } catch(e){ loadErr = `Couldn't read ${lookupModel.name}: ${e.message || e}`; }
      } else if (!lookupModel){
        lastLookupKey = null;
      }

      lastModels = models;
      render({ status: lookupModel ? 'connected' : 'partial', folderName: safeName(dirHandle), models, lastSync: new Date(), loadErr });

      // ── AUTOMATIC PROCESSING: only files that are NEW or UPDATED, and only
      // if a lookup workbook is actually loaded. Already-processed and
      // non-JOC files are never re-sent through the pipeline (spec #10/#13).
      if (lastLookupKey){
        const toProcess = models.filter(m => m.kind === 'joc' && (m.status === 'new' || m.status === 'updated'));
        for (const m of toProcess){
          await processModel(m);
          render({ status:'connected', folderName: safeName(dirHandle), models: lastModels, lastSync: new Date() });
        }
      }
    } catch(e){
      render({ status:'unavailable', folderName: safeName(dirHandle), errorMessage: e.message || String(e) });
    } finally{
      scanning = false;
    }
  }

  /* ---------- run the existing JOC pipeline for exactly one file model ---------- */
  async function processModel(m){
    m.status = 'processing';
    render({ status:'connected', folderName: safeName(dirHandle), models: lastModels, lastSync: new Date() });
    try{
      const f = await m.handle.getFile();
      await JOCToolkit.loadMainFile(f);
      const result = await JOCToolkit.processCurrentFiles();
      if (result.ok){
        outputBlobs.set(m.fingerprint, JOCToolkit.getOutputBlob());
        historyMap[m.name] = {
          fileName: m.name,
          fingerprint: m.fingerprint,
          detectionType: m.detection ? m.detection.matchLevel : '',
          matchCount: m.detection ? m.detection.count : 0,
          totalFields: m.detection ? m.detection.total : 0,
          status: 'Processed',
          processedAt: Date.now(),
          rowsProcessed: result.rows,
          outputGenerated: true,
          outputFileName: `JOC_Output_${m.name.replace(/\.(xlsx|xlsm|xls)$/i,'')}.xlsx`,
        };
        saveHistory();
        m.status = 'processed';
        m.hist = historyMap[m.name];
        // The import is complete; release the parsed workbook/row arrays from the scan cache.
        // Keeping 100k+ row arrays alive makes Chrome's GC and rendering progressively slower.
        const cached = detectionCache.get(m.fingerprint);
        if (cached) { delete cached.headers; delete cached.wb; delete cached.dataRows; }
        toast(`${m.name} processed — ${result.rows.toLocaleString()} rows.`, 'success');
        await saveCurrentProcessedWorkbookToJOC(m.name, result.rows);
      } else {
        m.status = 'error';
        m.errorMsg = result.error;
        toast(`${m.name} failed to process: ${result.error}`, 'error');
      }
    } catch(e){
      m.status = 'error';
      m.errorMsg = e.message || String(e);
      toast(`${m.name} failed to process: ${m.errorMsg}`, 'error');
    }
  }

  /* ---------- manual "Process Now" from the details panel (also covers reprocessing) ---------- */
  async function processFileNow(fp){
    const m = lastModels.find(x => x.fingerprint === fp);
    if (!m || m.kind !== 'joc') return;
    if (!lastLookupKey){
      toast('No lookup / master workbook detected in this folder yet.', 'error');
      return;
    }
    await processModel(m);
    render({ status:'connected', folderName: safeName(dirHandle), models: lastModels, lastSync: new Date() });
    renderDetails(fp);
  }

  function schedulePolling(enabled){
    if (pollTimer){ clearInterval(pollTimer); pollTimer = null; }
    if (enabled){
      pollTimer = setInterval(() => { scanAndLoad(); }, JOC_CLOUD_CONFIG.AUTO_DETECT_POLL_MS);
    }
  }

  /* ---------- small render helpers for the file explorer table ---------- */
  const KIND_ICON = {
    lookup: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16"/></svg>',
    joc: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 12h8M8 16h5M8 8h3"/></svg>',
    other: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6"/></svg>',
    unreadable: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/></svg>',
    error: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="9"/><path d="M12 8v4M12 16h.01"/></svg>',
  };

  function typeLabel(m){
    if (m.kind === 'lookup') return 'Lookup';
    if (m.kind === 'joc') return `JOC — ${m.detection.matchLevel}`;
    if (m.kind === 'other') return 'Other Excel';
    if (m.kind === 'unreadable') return 'Offline';
    return 'Error';
  }
  function matchLabel(m){
    if (m.kind === 'joc' || m.kind === 'other') return `${m.detection.count} / ${m.detection.total} fields`;
    if (m.kind === 'lookup') return `${m.lookupMatch ? m.lookupMatch.matched.length : '—'} / 4 sheets`;
    return '—';
  }
  function statusPill(m){
    const map = {
      new:        ['● New', 'pill-blue'],
      updated:    ['● Updated', 'pill-orange'],
      processing: ['● Processing…', 'pill-amber'],
      processed:  ['✓ Processed', 'pill-green'],
      'not-joc':  ['— Not JOC', 'pill-gray'],
      lookup:     ['✓ Ready', 'pill-purple'],
      offline:    ['Offline', 'pill-red'],
      error:      ['✕ Error', 'pill-red'],
    };
    const [label, cls] = map[m.status] || ['—', 'pill-gray'];
    return `<span class="pill ${cls}">${label}</span>`;
  }

  function renderExplorerRow(m){
    const meta = m.kind === 'unreadable'
      ? 'Not currently available offline'
      : m.kind === 'error'
        ? jocEscHtml(m.errorMsg || 'Could not be read')
        : `${typeLabel(m)} · ${matchLabel(m)} · ${fmtBytes(m.size)}`;
    return `<div class="joc-file-row joc-explorer-row" data-fp="${jocEscHtml(m.fingerprint)}" style="cursor:pointer;">
      <div class="joc-file-row-icon">${KIND_ICON[m.kind] || KIND_ICON.other}</div>
      <div class="joc-file-row-body">
        <div class="joc-file-row-name">${jocEscHtml(m.name)}</div>
        <div class="joc-file-row-meta">${meta}</div>
      </div>
      <div class="joc-file-row-status">${statusPill(m)}</div>
    </div>`;
  }

  function renderExplorer(models){
    const summaryEl = byId('joc-explorer-summary');
    const tableEl = byId('joc-explorer-table');
    if (!tableEl) return;

    if (!models || !models.length){
      if (summaryEl) summaryEl.innerHTML = '';
      tableEl.innerHTML = `<div class="joc-file-row-meta" style="padding:14px 2px;">No Excel files found in this folder yet.</div>`;
      return;
    }

    const counts = {
      total: models.length,
      joc: models.filter(m => m.kind === 'joc').length,
      lookup: models.filter(m => m.kind === 'lookup').length,
      other: models.filter(m => m.kind === 'other').length,
      processed: models.filter(m => m.status === 'processed').length,
      pending: models.filter(m => m.status === 'new' || m.status === 'updated' || m.status === 'processing').length,
    };

    if (summaryEl){
      summaryEl.innerHTML = `
        <span class="chip">${counts.total} Excel File${counts.total===1?'':'s'}</span>
        <span class="chip">${counts.joc} JOC</span>
        <span class="chip">${counts.lookup} Lookup</span>
        <span class="chip">${counts.other} Other Excel</span>
        <span class="chip" style="background:#F0FDF4; color:#15803D;">${counts.processed} Processed</span>
        ${counts.pending ? `<span class="chip" style="background:#FFF7ED; color:#C2410C;">${counts.pending} Pending</span>` : ''}
      `;
    }

    tableEl.innerHTML = models.map(renderExplorerRow).join('');

    // settings pane summary
    const dlText = byId('dl-folder-box-text');
    const dlSub = byId('dl-folder-box-sub');
    if (dlText) dlText.textContent = `${counts.total} Excel file${counts.total===1?'':'s'} detected`;
    if (dlSub) dlSub.textContent = `${counts.joc} JOC · ${counts.lookup} Lookup · ${counts.other} Other · ${counts.processed} already processed`;
  }

  /* ---------- file details panel ---------- */
  function renderDetails(fp){
    const m = lastModels.find(x => x.fingerprint === fp);
    const overlay = byId('joc-file-details-overlay');
    const body = byId('joc-file-details-body');
    const titleEl = byId('joc-file-details-title');
    if (!overlay || !body) return;
    if (!m){ overlay.classList.add('hidden'); return; }

    if (titleEl) titleEl.textContent = m.name;

    let chipsHtml = '';
    if (m.detection){
      chipsHtml = `
        <div class="joc-panel-label" style="margin-top:14px;">Detected columns (${m.detection.count})</div>
        <div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:6px;">
          ${m.detection.detected.length ? m.detection.detected.map(c=>`<span class="chip">${jocEscHtml(c)}</span>`).join('') : '<span style="font-size:12px;color:var(--text-secondary);">None</span>'}
        </div>
        <div class="joc-panel-label" style="margin-top:14px;">Missing columns (${m.detection.missing.length})</div>
        <div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:6px;">
          ${m.detection.missing.length ? m.detection.missing.map(c=>`<span class="chip" style="background:#F2F2F8; color:#6B6E8A;">${jocEscHtml(c)}</span>`).join('') : '<span style="font-size:12px;color:var(--text-secondary);">None — full match.</span>'}
        </div>`;
    } else if (m.kind === 'lookup'){
      chipsHtml = `
        <div class="joc-panel-label" style="margin-top:14px;">Lookup sheets found</div>
        <div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:6px;">
          ${(m.sheetNames||[]).map(c=>`<span class="chip">${jocEscHtml(c)}</span>`).join('')}
        </div>`;
    }

    const histHtml = m.hist ? `
      <div class="joc-v-item ok" style="margin-top:14px;">
        <span class="dot"></span>Previously processed: ${jocEscHtml(fmtTime(m.hist.processedAt))}
        <em>${(m.hist.rowsProcessed||0).toLocaleString()} rows</em>
      </div>
      ${m.status === 'updated' ? `<div class="joc-v-item err"><span class="dot"></span>File changed since last processed — will reprocess.</div>` : ''}
      ${m.status === 'processed' ? `<div style="font-size:11.5px; color:var(--text-secondary); margin-top:8px;">This exact version has already been processed. No repeat processing required.</div>` : ''}
    ` : '';

    const canProcess = m.kind === 'joc' && m.status !== 'processing';
    const hasOutput = outputBlobs.has(m.fingerprint);

    body.innerHTML = `
      <div style="display:flex; align-items:center; gap:10px; margin-bottom:4px;">
        ${statusPill(m)}
        ${m.kind==='joc' ? `<span class="pill pill-blue">${typeLabel(m)}</span>` : ''}
      </div>
      <div class="joc-file-row-meta" style="margin-top:6px;">${fmtBytes(m.size)} · Modified ${jocEscHtml(fmtTime(m.lastModified))}${m.rowCount!=null ? ` · ${m.rowCount.toLocaleString()} rows` : ''}</div>
      ${histHtml}
      ${chipsHtml}
      ${m.errorMsg ? `<div class="joc-cloud-error" style="margin-top:14px;"><div class="joc-cloud-error-title">Couldn't process this file.</div><div class="joc-cloud-error-sub">${jocEscHtml(m.errorMsg)}</div></div>` : ''}
      <div style="display:flex; gap:8px; margin-top:18px; flex-wrap:wrap;">
        ${canProcess ? `<button class="btn btn-sm btn-primary" id="joc-details-process-btn">${m.status==='processed' ? 'Reprocess' : 'Process Now'}</button>` : ''}
        ${hasOutput ? `<button class="btn btn-sm" id="joc-details-download-btn">Download Output</button>` : ''}
      </div>
    `;

    const processBtn = byId('joc-details-process-btn');
    if (processBtn) processBtn.addEventListener('click', () => processFileNow(fp));
    const downloadBtn = byId('joc-details-download-btn');
    if (downloadBtn) downloadBtn.addEventListener('click', () => {
      const blob = outputBlobs.get(fp);
      if (!blob) return;
      const ts = new Date().toISOString().replace(/[:.]/g,'').slice(0,15);
      const safe = m.name.replace(/\.(xlsx|xlsm|xls)$/i,'');
      const a = document.createElement('a');
      const url = URL.createObjectURL(blob);
      a.href = url; a.download = `JOC_Output_${safe}_${ts}.xlsx`;
      document.body.appendChild(a); a.click();
      setTimeout(()=>{ URL.revokeObjectURL(url); a.remove(); }, 1000);
    });

    overlay.classList.remove('hidden');
    openDetailsFp = fp;
  }

  function openDetails(fp){ renderDetails(fp); }
  function closeDetails(){
    const overlay = byId('joc-file-details-overlay');
    if (overlay) overlay.classList.add('hidden');
    openDetailsFp = null;
  }

  /* ---------- live stats for the premium landing card — derived ENTIRELY from
     the existing lastModels (current scan classification) + historyMap
     (persisted processing history). No second counting system. ---------- */
  function getStats(){
    const jocModels = (lastModels || []).filter(m => m.kind === 'joc');
    const filesDetected = jocModels.length;
    const pending = jocModels.filter(m => m.status === 'new' || m.status === 'updated' || m.status === 'processing').length;
    const completed = jocModels.filter(m => m.status === 'processed').length;
    let recordsProcessed = 0, lastRunTs = 0, lastOutputName = '';
    Object.values(historyMap).forEach(h => {
      recordsProcessed += (h.rowsProcessed || 0);
      if (h.processedAt && h.processedAt > lastRunTs){ lastRunTs = h.processedAt; lastOutputName = h.outputFileName || ''; }
    });
    return { filesDetected, pending, completed, recordsProcessed, lastRunTs, lastOutputName };
  }

  function updateLandingCard(){
    const s = getStats();
    const set = (id, val) => { const el = byId(id); if (el) el.textContent = val; };
    set('joc-card-kpi-files', s.filesDetected.toLocaleString());
    set('joc-card-kpi-pending', s.pending.toLocaleString());
    set('joc-card-kpi-completed', s.completed.toLocaleString());
    set('joc-card-kpi-records', s.recordsProcessed.toLocaleString());
    set('joc-card-lastrun', s.lastRunTs ? fmtTime(s.lastRunTs) : '—');
    const outEl = byId('joc-card-output');
    const outBadge = byId('joc-card-output-badge');
    if (outEl){
      outEl.childNodes[0].nodeValue = s.lastOutputName || '—';
    }
    if (outBadge) outBadge.classList.toggle('hidden', !s.lastOutputName);
  }

  /* ---------- render: drives the Toolkits explorer AND the Settings box ---------- */
  let lastModel = { status:'checking' };
  function render(model){
    lastModel = model;
    updateLandingCard();
    const status = model.status;

    const pill = byId('joc-folder-status-pill');
    const subText = byId('joc-folder-status-text');
    const synced = byId('joc-folder-synced');
    const browseBtn = byId('joc-folder-browse-btn');
    const changeBtn = byId('joc-folder-change-btn');
    const grantBtn = byId('joc-folder-grant-btn');
    const refreshBtn = byId('joc-folder-refresh-btn');
    const errBox = byId('joc-folder-error');
    const errTitle = byId('joc-folder-error-title');
    const errSub = byId('joc-folder-error-sub');

    const dlBox = byId('dl-folder-box');
    const dlText = byId('dl-folder-box-text');
    const dlSub = byId('dl-folder-box-sub');
    const dlBrowse = byId('dl-folder-browse-btn');
    const dlChange = byId('dl-folder-change-btn');
    const dlGrant = byId('dl-folder-grant-btn');
    const dlRefresh = byId('dl-folder-refresh-btn');
    const dlErr = byId('dl-folder-error');
    const dlErrTitle = byId('dl-folder-error-title');
    const dlErrSub = byId('dl-folder-error-sub');
    const dlUnsupported = byId('dl-folder-unsupported-msg');

    [browseBtn,changeBtn,grantBtn,refreshBtn,dlBrowse,dlChange,dlGrant,dlRefresh].forEach(b => show(b,false));
    show(errBox,false); show(dlErr,false); show(dlUnsupported,false);
    if (dlBox) dlBox.classList.remove('loaded');
    if (changeBtn) changeBtn.textContent = 'Change Folder';
    if (dlChange) dlChange.textContent = 'Change Folder';

    if (status === 'unsupported'){
      if (subText) subText.textContent = 'Not supported in this browser';
      if (pill){ pill.textContent='Unsupported'; pill.className='pill pill-gray'; }
      if (synced) synced.textContent = 'Use a Chromium-based browser (Chrome/Edge) to enable folder sync';
      if (dlText) dlText.textContent = 'Folder selection is not supported in this browser.';
      if (dlSub) dlSub.textContent = '';
      show(dlUnsupported, true);
      renderExplorer([]);
      return;
    }
    if (status === 'checking'){
      if (subText) subText.textContent = 'Checking saved folder…';
      if (pill){ pill.textContent='Checking'; pill.className='pill pill-gray'; }
      if (dlText) dlText.textContent = 'Checking saved folder…';
      return;
    }
    if (status === 'no-folder'){
      if (subText) subText.textContent = 'No folder connected';
      if (pill){ pill.textContent='Not selected'; pill.className='pill pill-gray'; }
      if (synced) synced.textContent = 'Connect it in Settings → Data Hub Source';
      show(browseBtn, true);
      if (dlText) dlText.textContent = 'No folder selected';
      if (dlSub) dlSub.textContent = 'Choose the folder containing your Excel files.';
      show(dlBrowse, true);
      renderExplorer([]);
      return;
    }
    if (status === 'permission-needed'){
      if (subText) subText.textContent = 'Folder permission required';
      if (pill){ pill.textContent='Permission needed'; pill.className='pill pill-orange'; }
      if (synced) synced.textContent = `Folder: ${model.folderName || '—'}`;
      show(grantBtn, true); show(changeBtn, true);
      if (dlText) dlText.textContent = 'Folder permission required';
      if (dlSub) dlSub.textContent = model.folderName ? `Folder: ${model.folderName}` : '';
      show(dlGrant, true); show(dlChange, true);
      return;
    }
    if (status === 'permission-denied'){
      if (subText) subText.textContent = 'Folder access denied';
      if (pill){ pill.textContent='Access denied'; pill.className='pill pill-red'; }
      show(errBox,true);
      if (errTitle) errTitle.textContent = 'Folder access denied.';
      if (errSub) errSub.textContent = 'Grant access again, or choose a different folder.';
      show(grantBtn, true); show(changeBtn, true);
      if (dlText) dlText.textContent = 'Folder access denied';
      show(dlErr, true);
      if (dlErrTitle) dlErrTitle.textContent = 'Folder access denied.';
      if (dlErrSub) dlErrSub.textContent = 'Grant access again, or choose a different folder.';
      show(dlGrant, true); show(dlChange, true);
      return;
    }
    if (status === 'scanning'){
      if (subText) subText.textContent = 'Scanning folder…';
      if (pill){ pill.textContent='Scanning'; pill.className='pill pill-gray'; }
      if (dlText) dlText.textContent = `Scanning ${model.folderName || 'folder'}…`;
      show(changeBtn,true); show(refreshBtn,true);
      show(dlChange,true); show(dlRefresh,true);
      return;
    }
    if (status === 'unavailable'){
      if (subText) subText.textContent = 'Folder access lost';
      if (pill){ pill.textContent='● FOLDER ACCESS LOST'; pill.className='pill pill-red'; }
      if (synced) synced.textContent = 'The selected folder is no longer accessible.';
      show(errBox,true);
      if (errTitle) errTitle.textContent = 'Folder access lost.';
      if (errSub) errSub.textContent = model.errorMessage || 'The selected folder is no longer accessible.';
      show(changeBtn,true); if (changeBtn) changeBtn.textContent = 'Reconnect Folder';
      if (dlText) dlText.textContent = 'Folder access lost';
      show(dlErr,true);
      if (dlErrTitle) dlErrTitle.textContent = 'Folder access lost.';
      if (dlErrSub) dlErrSub.textContent = model.errorMessage || 'The selected folder is no longer accessible.';
      show(dlChange,true); if (dlChange) dlChange.textContent = 'Reconnect Folder';
      return;
    }

    // status === 'connected' (a lookup workbook was found) or 'partial' (folder ok, no lookup workbook yet)
    const live = status === 'connected';
    if (pill){ pill.textContent = live ? '● LIVE' : 'Folder connected'; pill.className = 'pill ' + (live ? 'pill-green' : 'pill-orange'); }
    if (subText) subText.textContent = live ? 'Connected — live' : 'Connected — no Lookup workbook found yet';
    if (synced && model.lastSync){
      const next = new Date(model.lastSync.getTime() + JOC_CLOUD_CONFIG.AUTO_DETECT_POLL_MS);
      synced.textContent = `Last synchronized: ${model.lastSync.toLocaleTimeString()} · Next check: ${next.toLocaleTimeString()}`;
    }
    show(changeBtn,true); show(refreshBtn,true);

    if (model.loadErr){
      show(errBox,true);
      if (errTitle) errTitle.textContent = 'Some files could not be read.';
      if (errSub) errSub.textContent = model.loadErr;
    }

    if (dlBox) dlBox.classList.toggle('loaded', live);
    show(dlChange,true); show(dlRefresh,true);

    renderExplorer(model.models || lastModels);

    // keep an open details panel in sync as scans/processing update the model
    if (openDetailsFp) renderDetails(openDetailsFp);
  }

  function renderCurrent(){ render(lastModel); }

  function wireUI(){
    const b1 = byId('joc-folder-browse-btn'); if (b1) b1.addEventListener('click', pickFolder);
    const b2 = byId('joc-folder-change-btn'); if (b2) b2.addEventListener('click', pickFolder);
    const b3 = byId('joc-folder-grant-btn'); if (b3) b3.addEventListener('click', grantAccess);
    const b4 = byId('joc-folder-refresh-btn'); if (b4) b4.addEventListener('click', () => scanAndLoad());
    const d1 = byId('dl-folder-browse-btn'); if (d1) d1.addEventListener('click', pickFolder);
    const d2 = byId('dl-folder-change-btn'); if (d2) d2.addEventListener('click', pickFolder);
    const d3 = byId('dl-folder-grant-btn'); if (d3) d3.addEventListener('click', grantAccess);
    const d4 = byId('dl-folder-refresh-btn'); if (d4) d4.addEventListener('click', () => scanAndLoad());

    const tableEl = byId('joc-explorer-table');
    if (tableEl) tableEl.addEventListener('click', (e) => {
      const row = e.target.closest('.joc-explorer-row');
      if (row) openDetails(row.dataset.fp);
    });

    const detailsClose = byId('joc-file-details-close');
    if (detailsClose) detailsClose.addEventListener('click', closeDetails);
    const detailsOverlay = byId('joc-file-details-overlay');
    if (detailsOverlay) detailsOverlay.addEventListener('click', (e) => { if (e.target === detailsOverlay) closeDetails(); });

    const bookmarkBtn = byId('joc-card-bookmark-btn');
    if (bookmarkBtn){
      const BOOKMARK_KEY = 'joc_card_bookmarked';
      try{ bookmarkBtn.classList.toggle('active', localStorage.getItem(BOOKMARK_KEY) === '1'); } catch(e){}
      bookmarkBtn.addEventListener('click', (e) => {
        e.stopPropagation(); // don't trigger the card's "open toolkit" click
        const on = bookmarkBtn.classList.toggle('active');
        try{ localStorage.setItem(BOOKMARK_KEY, on ? '1' : '0'); } catch(err){}
      });
    }
  }

  async function init(){
    loadHistory();
    wireUI();
    if (!supported()){ render({ status:'unsupported' }); return; }
    render({ status:'checking' });
    let handle = null;
    try{ handle = await idbGet(HANDLE_KEY); } catch(e){ handle = null; }
    if (!handle){ render({ status:'no-folder' }); return; }
    dirHandle = handle;
    const perm = await checkPermission(handle, false);
    if (perm === 'granted'){
      await scanAndLoad();
      schedulePolling(true);
    } else if (perm === 'prompt'){
      render({ status:'permission-needed', folderName: safeName(handle) });
    } else {
      render({ status:'permission-denied', folderName: safeName(handle) });
    }
  }

  return { init, refresh: scanAndLoad, renderCurrent, getStats, adoptSharedHandle };
})();

/* ==========================================================================
   DATA HUB SOURCE FOLDER  (Settings → Data Hub Source → "Data Hub Source
   Folder")

   This is the ONE local/OneDrive folder connection for the entire app —
   there is no second folder picker. It persists a single
   FileSystemDirectoryHandle in IndexedDB (fixed key: HANDLE_KEY above),
   restores it automatically on every launch, and re-requests permission
   only when the browser actually revokes it.

   Every .xlsx/.xlsm/.xls file inside the folder is inspected by CONTENT —
   never by filename — and classified deterministically against the
   17-column Data Hub database schema (classifyDatabaseSchema, defined with
   the rest of the column-detection code below). Only files that match the
   full schema are treated as databases and fed into performImport(), the
   exact same pipeline the manual "Import Database" button uses — no manual
   import step is required. Non-matching files are shown as Lookup/Other and
   are never imported as a database.

   This exact same folder handle (same DB_NAME/STORE/HANDLE_KEY) is also
   used by JocLocalFolder, below, for Toolkits → JOC Data Processor's own
   Lookup/JOC classification — so picking the folder once here connects
   both features.
   ========================================================================== */
// Tracks whether the optional Supabase `import_source`/`source_fingerprint` columns exist
// on the databases table. Starts true (optimistic); performImport() flips it to false the
// first time an insert/update rejects those columns, and callers fall back to the
// localStorage fingerprint cache instead. Must be declared here — it's read by
// DataHubFolder.statusFor() below and written by performImport() further down the file.
let importSourceColumnsAvailable = true;
const DataHubFolder = (() => {
  const DB_NAME = 'datahub_folder_db';
  const DB_VERSION = 2;
  const STORE = 'handles';
  // Fixed key: this is the ONE folder connection in the whole app. JocLocalFolder
  // (Toolkits → JOC Data Processor) reads/writes the exact same DB_NAME/STORE/HANDLE_KEY
  // so both features share a single picked FileSystemDirectoryHandle — there is no
  // second folder picker anywhere.
  const HANDLE_KEY = 'datahub_fixed_source_folder_v1';
  const FOLDER_NAME_CACHE_KEY = 'datahub_folder_name';
  const FP_CACHE_KEY = 'datahub_folder_fp_cache_v1'; // per-device fallback dedupe, only used until the
                                                       // import_source/source_fingerprint columns exist
  const DEFAULT_ASSIGNEE_KEY = 'datahub_folder_default_assignee_id';
  const EXCEL_EXT = /\.(xlsx|xlsm|xls)$/i;

const POLL_MS = 180000; // 180s — background watcher; manual Refresh remains immediate

// Optional Supabase metadata columns.
// These are optional and must NEVER stop XLSX import.


let dirHandle = null;

let scanning = false;

let pollTimer = null;

let lastModel = {
  status: 'checking'
};

let lastFiles = [];
let hasEverConnected = false; // once true, periodic re-scans keep showing the compact card, not the dropzone

// ---------- Per-scan statistics (spec: Source Folder panel must update its stats after every
// automatic sync) — reset at the start of every scanAndLoad() run and rendered into the
// compact status card + Detection Activity panel once the scan (and any auto-import it
// triggers) has finished. ----------
let scanStats = { databasesDetected:0, newlyImported:0, updatedDatabases:0, recordsImported:0, duplicatesSkipped:0, errors:0 };

// ---------- LEGACY: new-database assignment prompt (superseded — see "Auto-import" in
// scanAndLoad above) ----------
// New database files used to sit in this queue waiting for someone to explicitly confirm a
// "Who should this database be assigned to?" modal before anything was imported. Per the
// current spec, the Source Folder scanner now auto-imports every detected database
// immediately (as Unassigned — an Admin can reassign afterwards from the card), so nothing
// pushes into this queue anymore. The queue/modal plumbing below is kept only so nothing else
// in the file needs touching; it is inert.
let assignQueue = [];              // no longer populated — kept for compatibility only
let assignQueueBusy = false;       // true while the modal is open / a confirmed import is running

/* ---------- Resolve the detected file's display name for the "New database detected" modal ----------
   The scanner (scanAndLoad, above) always sets `name` on the model straight from the File System
   Access API handle (f.name — a plain filename, never a full path), so `m.name` is normally all
   that's needed. This resolver exists purely as a defensive fallback in case a differently-shaped
   detection object (e.g. from a future source) reaches the modal without a plain `name`, per the
   required priority order. It never guesses or hardcodes a filename. */
function getDetectedFileName(m){
  if (!m) return '';
  const direct = m.name || m.fileName || m.filename || m.sourceFileName || m.source_name;
  if (direct) return String(direct);
  const pathLike = m.source_path || m.file_path || m.sourcePath || m.import_source;
  if (pathLike && typeof pathLike === 'string'){
    const parts = pathLike.split(/[\\/]/).filter(Boolean);
    if (parts.length) return parts[parts.length - 1];
  }
  return '';
}
const assignDismissedFps = new Set(); // fingerprints skipped this session — won't re-prompt until the file changes

  function byId(id){ return document.getElementById(id); }
  function show(el, on){ if (el) el.classList.toggle('hidden', !on); }
  function supported(){ return 'showDirectoryPicker' in window; }
  function safeName(h){ return (h && h.name) ? h.name : 'Selected folder'; }
  function fileKey(meta){ return meta ? `${meta.name}|${meta.size}|${meta.lastModified}` : ''; }
  function fmtBytes(n){ if (n==null) return ''; return n < 1024*1024 ? (n/1024).toFixed(0)+' KB' : (n/1024/1024).toFixed(1)+' MB'; }

  function readFpCache(){ try{ return JSON.parse(localStorage.getItem(FP_CACHE_KEY) || '{}'); } catch(e){ return {}; } }
  function writeFpCache(map){ try{ localStorage.setItem(FP_CACHE_KEY, JSON.stringify(map)); } catch(e){ /* best-effort */ } }
  function rememberFp(name, fp){ const m = readFpCache(); m[name] = fp; writeFpCache(m); }

  /* ---------- IndexedDB: persists ONLY the directory handle ---------- */
  function openDb(){
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => { const db = req.result; if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE); };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  async function idbSet(key, value){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(value, key);
      tx.oncomplete = () => resolve(); tx.onerror = () => reject(tx.error);
    });
  }
  async function idbGet(key){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve(req.result || null); req.onerror = () => reject(req.error);
    });
  }

  async function checkPermission(handle, request){
    if (!handle) return 'prompt';
    const opts = { mode:'read' };
    try{
      let perm = await handle.queryPermission(opts);
      if (perm === 'granted') return perm;
      if (request) perm = await handle.requestPermission(opts);
      return perm;
    } catch(e){ return 'denied'; }
  }

  const folderUiYield = () => new Promise(resolve => {
    if (typeof requestIdleCallback === 'function') requestIdleCallback(()=>resolve(), {timeout:40});
    else setTimeout(resolve, 0);
  });

  async function scanEntries(handle){
    const files = [];
    let visited = 0;
    for await (const [name, entryHandle] of handle.entries()){
      if (entryHandle.kind !== 'file') continue;
      if (!EXCEL_EXT.test(name)) continue;
      if (name.startsWith('~$')) continue; // Excel lock files
      try{
        const file = await entryHandle.getFile();
        files.push({ name:file.name, size:file.size, lastModified:file.lastModified, handle:entryHandle });
      } catch(e){
        files.push({ name, size:null, lastModified:null, handle:entryHandle, unreadable:true });
      }
      // Large folders must never monopolize the main event loop.
      if (++visited % 40 === 0) await folderUiYield();
    }
    return files;
  }

  function findExistingDb(originalFilename){
    return (S.databases||[]).find(d => d.original_filename === originalFilename);
  }
  
  function statusFor(fmeta){
    const existing = findExistingDb(fmeta.name);
    if (!existing) return { status:'new', existing:null };
    if (existing.status === 'error') return { status:'changed', existing }; // retry failed imports
    if (importSourceColumnsAvailable && existing.source_fingerprint){
      return { status: existing.source_fingerprint === fmeta.fp ? 'unchanged' : 'changed', existing };
    }
    const cached = readFpCache()[fmeta.name];
    if (!cached) return { status:'changed', existing }; // never fingerprinted locally — import once, then cache
    return { status: cached === fmeta.fp ? 'unchanged' : 'changed', existing };
  }

  function pickDefaultAssignUser(){
    // Automatic XLSX imports are silent and remain UNASSIGNED by default.
    // Never assign the currently logged-in user, or any other user, automatically.
    return { id: null, name: null, email: null };
  }

  // fingerprint -> { ok, headers, dataRows, wb, dbClass, fileType } — avoids re-reading/re-classifying
  // a file that hasn't changed on repeat scans (SCAN ≠ PROCESS).
  const classifyCache = new Map();

  /* Parse XLSX away from the UI thread. SheetJS parsing + sheet_to_json on a 100k+
     row workbook is CPU-heavy and was the main cause of Folder Scan freezes. */
  async function parseFolderWorkbookOffThread(file){
    if (typeof Worker === 'undefined') return null;
    const workerCode = `
      self.onmessage = async (e) => {
        try {
          importScripts('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js');
          const wb = XLSX.read(e.data, { type:'array' });
          const first = wb.SheetNames[0];
          const rows = first ? XLSX.utils.sheet_to_json(wb.Sheets[first], { header:1, defval:'', raw:true, blankrows:false }) : [];
          self.postMessage({ ok:true, sheetNames:wb.SheetNames, rows });
        } catch (err) {
          self.postMessage({ ok:false, error:String(err && err.message || err) });
        }
      };`;
    const url = URL.createObjectURL(new Blob([workerCode], {type:'text/javascript'}));
    const worker = new Worker(url);
    try{
      const buf = await file.arrayBuffer();
      return await new Promise((resolve, reject)=>{
        worker.onmessage = e => e.data?.ok ? resolve(e.data) : reject(new Error(e.data?.error || 'Workbook worker failed'));
        worker.onerror = e => reject(new Error(e.message || 'Workbook worker failed'));
        worker.postMessage(buf, [buf]);
      });
    } finally {
      worker.terminate();
      URL.revokeObjectURL(url);
    }
  }

  /* ---------- read a workbook once and classify it by CONTENT, never by filename ---------- */
  async function readAndClassify(fmeta){
    const fp = fileKey(fmeta);
    if (classifyCache.has(fp)) return classifyCache.get(fp);
    let result;
    try{
      const file = await fmeta.handle.getFile();
      let parsed = null;
      try{ parsed = await parseFolderWorkbookOffThread(file); }
      catch(workerErr){ console.warn('[Folder XLSX] Worker parse unavailable; using main-thread fallback.', workerErr); }
      let allRows, sheetNames;
      if (parsed){
        allRows = parsed.rows || [];
        sheetNames = parsed.sheetNames || [];
      } else {
        // Compatibility fallback only. Yield before/after so browsers can paint status updates.
        await folderUiYield();
        const buf = await file.arrayBuffer();
        const wb = XLSX.read(buf, { type:'array' });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        allRows = XLSX.utils.sheet_to_json(sheet, { header:1, defval:'', raw:true, blankrows:false });
        sheetNames = wb.SheetNames || [];
        await folderUiYield();
      }
      if (!allRows.length){
        result = { ok:false, error:'That file looks empty.' };
      } else {
        const headers = allRows[0].map(h=>String(h||'').trim());
        const dataRows = allRows.slice(1).filter(r=> r.some(c=> String(c||'').trim()!==''));
        // Deterministic 17-column schema check — the ONLY thing that decides DATABASE vs not.
        const dbClass = classifyDatabaseSchema(headers, dataRows);
        let fileType = 'other';
        if (dbClass.isDatabase){
          fileType = 'database';
        } else if (typeof JOCToolkit !== 'undefined' && JOCToolkit.detectLookupWorkbook){
          try{
            const lookup = JOCToolkit.detectLookupWorkbook(sheetNames);
            if (lookup && lookup.isLookup) fileType = 'lookup';
          } catch(e){ /* best-effort label only — never blocks classification */ }
        }
        result = { ok:true, headers, dataRows, dbClass, fileType };
      }
    } catch(e){
      result = { ok:false, error: 'Unable to read workbook: ' + (e.message || e) };
    }
    classifyCache.set(fp, result);
    return result;
  }

  async function importOneFile(fmeta, existingDb, meta, overrideAssignUser){
    const fp = fileKey(fmeta);
    const { headers, dataRows } = meta;
    const mapping = detectColumns(headers, dataRows); // same column detection used by manual import (spec #7)

    // Source-folder imports are intentionally silent and remain Unassigned unless an Admin
    // later assigns the database from its card. No confirmation modal is used.
    const assignUser = overrideAssignUser || pickDefaultAssignUser();
    const dbName = existingDb ? existingDb.name : fmeta.name.replace(EXCEL_EXT, '');
    const result = await performImport({
      dbName, originalFilename: fmeta.name, assignedTo: assignUser.name || '', assignUser,
      headers, rows: dataRows, mapping, source:'folder', sourceFingerprint: fp,
      existingDbId: existingDb ? existingDb.id : null,
    });
    if (result.ok) rememberFp(fmeta.name, fp);
    return result;
  }

  async function pickFolder(){
    if (!supported()){ toast('Folder selection is not supported in this browser. Please use Chrome or Edge.', 'error'); return; }
    try{
      const handle = await window.showDirectoryPicker({ id:'datahub-source-folder', mode:'read' });
      dirHandle = handle;
      classifyCache.clear(); // don't mix folders
      try{ await idbSet(HANDLE_KEY, handle); } catch(e){}
      try{ localStorage.setItem(FOLDER_NAME_CACHE_KEY, safeName(handle)); } catch(e){}
      toast('Folder connected — scanning…', '');
      await scanAndLoad();
      schedulePolling(true);
      // Same folder connection feeds Toolkits → JOC Data Processor — no second picker (spec #1/#18).
      if (typeof JocLocalFolder !== 'undefined' && JocLocalFolder.adoptSharedHandle) JocLocalFolder.adoptSharedHandle(handle);
    } catch(e){
      if (e && e.name === 'AbortError') return;
      toast(`Couldn't open the folder picker: ${e.message || e}`, 'error');
    }
  }
  async function grantAccess(){
    if (!dirHandle){ await pickFolder(); return; }
    const perm = await checkPermission(dirHandle, true);
    if (perm === 'granted'){
      await scanAndLoad(); schedulePolling(true);
      if (typeof JocLocalFolder !== 'undefined' && JocLocalFolder.adoptSharedHandle) JocLocalFolder.adoptSharedHandle(dirHandle);
    }
    else { render({ status:'permission-denied', folderName:safeName(dirHandle) }); toast('Folder access denied.', 'error'); }
  }

  async function scanAndLoad(){
    if (!dirHandle || scanning) return;
    scanning = true;
    render({ status:'scanning', folderName:safeName(dirHandle) });
    try{
      const files = await scanEntries(dirHandle);
      const models = [];
      for (const f of files){
        if (f.unreadable){
          models.push({ name:f.name, status:'error', errorMsg:'File is not currently downloaded (OneDrive Files-On-Demand?).', size:f.size, lastModified:f.lastModified, fileType:'other' });
          continue;
        }
        const fp = fileKey(f);
        // Fast path: if this known database has the same fingerprint, do NOT open/parse its
        // XLSX again. This turns repeat scans into cheap metadata checks instead of 100k-row work.
        const known = findExistingDb(f.name);
        if (known){
          const quick = statusFor({ ...f, fp });
          if (quick.status === 'unchanged'){
            models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fp, handle:f.handle,
              status:'unchanged', existing:quick.existing, fileType:'database', dbClass:null });
            continue;
          }
        }
        const classified = await readAndClassify(f);
        if (!classified.ok){
          models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fp, handle:f.handle, status:'error', errorMsg:classified.error, fileType:'other' });
          continue;
        }
        if (classified.fileType !== 'database'){
          // Schema didn't match the 17 required columns — never imported as a database (spec #10/#11).
          models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fp, handle:f.handle, status:'not-database', fileType:classified.fileType, dbClass:classified.dbClass });
          continue;
        }
        const { status, existing } = statusFor({ ...f, fp });
        models.push({ name:f.name, size:f.size, lastModified:f.lastModified, fp, handle:f.handle, status, existing, fileType:'database', dbClass:classified.dbClass, _meta:classified });
      }
      lastFiles = models;
      // Reset per-scan stats BEFORE the first render of this cycle so the summary card never
      // flashes the previous scan's numbers while this one is still in flight (spec #7).
      scanStats = {
        databasesDetected: models.filter(m=>m.fileType==='database').length,
        newlyImported: 0, updatedDatabases: 0, recordsImported: 0, duplicatesSkipped: 0,
        errors: models.filter(m=>m.status==='error').length,
      };
      render({ status:'connected', folderName:safeName(dirHandle), models, lastSync:new Date() });

      // ---------- Auto-import (spec: never ask the user to confirm) ----------
      // Every detected DATABASE-schema file — brand new OR a changed re-import of an
      // already-tracked database — is imported automatically through the exact same
      // performImport() pipeline manual "Import Database" uses. Nothing here waits on user
      // confirmation. New databases are imported Unassigned (an Admin can reassign afterwards
      // from the card); changed files update the same database row (spec #12/#20/#23).
      // Row-level duplicate prevention lives inside performImport()/recordIdentityKey(), so
      // this loop itself never needs to worry about creating duplicate records.
      const toAutoProcess = models.filter(m=> m.fileType==='database' && (m.status==='changed' || m.status==='new'));
      for (const m of toAutoProcess){
        const isNew = m.status === 'new';
        m.status = 'processing';
        render({ status:'connected', folderName:safeName(dirHandle), models:lastFiles, lastSync:new Date() });
        const result = await importOneFile(m, m.existing, m._meta);
        if (result.ok){
          if (isNew){ S.dbHub.newIds.add(result.dbRow.id); scanStats.newlyImported++; }
          else { S.dbHub.updatedIds.add(result.dbRow.id); scanStats.updatedDatabases++; }
          scanStats.recordsImported += result.insertedCount || 0;
          scanStats.duplicatesSkipped += result.duplicatesSkipped || 0;
          m.status = 'imported';
          // Free the parsed workbook rows after import; the database is now the source of truth.
          if (m._meta) { delete m._meta.wb; delete m._meta.dataRows; delete m._meta.headers; }
          const cached = classifyCache.get(m.fp);
          if (cached) { delete cached.wb; delete cached.dataRows; delete cached.headers; }
        } else {
          m.status = 'error'; m.errorMsg = result.error;
          scanStats.errors++;
          toast(`${m.name}: ${result.error}`, 'error');
        }
        render({ status:'connected', folderName:safeName(dirHandle), models:lastFiles, lastSync:new Date() });
      }

      if (toAutoProcess.length){
        const refresh = ()=>refreshAllDataView();
        if (window.requestIdleCallback) requestIdleCallback(refresh, {timeout:1200});
        else setTimeout(refresh, 250);
      }
    } catch(e){
      render({ status:'unavailable', folderName:safeName(dirHandle), errorMessage: e.message || String(e) });
    } finally{ scanning = false; }
  }

  function schedulePolling(immediate){
    if (pollTimer) clearInterval(pollTimer);
    if (immediate === false) return;
    pollTimer = setInterval(()=> scanAndLoad(), POLL_MS);
  }

  /* ---------- New-database assignment prompt ---------- */
  function maybeShowAssignPrompt(){
    // Intentionally disabled. New database detection must be silent.
    // Users should not receive an unexpected modal while using the app.
    return;
  }

  function openAssignPrompt(m){
    assignQueueBusy = true;
    const overlay = byId('dh-new-db-modal-overlay');
    const nameEl = byId('dh-new-db-modal-name');
    const sel = byId('dh-new-db-modal-user');
    const err = byId('dh-new-db-modal-error');
    const countBadge = byId('dh-new-db-modal-count');
    if (!overlay || !sel) return;

    // BUGFIX: nameEl is an <input>, so it must be set via .value — setting .textContent on an
    // <input> has no visual effect at all, which is why the File field always rendered empty
    // even though the detected filename (m.name) was correct and present the whole time.
    const resolvedName = getDetectedFileName(m);
    if (resolvedName){
      nameEl.value = resolvedName;
      nameEl.title = resolvedName; // full filename on hover if the input clips it
    } else {
      nameEl.value = 'Unable to determine source filename';
      nameEl.title = '';
      console.warn('[Data Hub] Could not resolve a filename for a detected database. Detection object:', m);
    }
    const users = [...(S.profiles||[])].sort((a,b)=> (a.full_name||a.email||'').localeCompare(b.full_name||b.email||''));
    sel.innerHTML = `<option value="" selected>Unassigned</option>` + users.map(p=>
      `<option value="${esc(p.id)}">${esc(p.full_name||p.email)}${p.role==='admin'?' (Admin)':''}</option>`
    ).join('');
    sel.value = ''; // always default to Unassigned, regardless of any saved default-assignee setting
    if (err){ err.className = 'auth-alert'; err.textContent = ''; }
    if (countBadge){
      const remaining = assignQueue.length;
      countBadge.textContent = remaining > 1 ? `1 of ${remaining} new databases` : 'New database detected';
    }
    overlay.classList.remove('hidden');
  }

  function closeAssignPrompt(){
    const overlay = byId('dh-new-db-modal-overlay');
    if (overlay) overlay.classList.add('hidden');
    assignQueueBusy = false;
  }

  async function confirmAssignPrompt(){
    const m = assignQueue[0];
    if (!m) { closeAssignPrompt(); return; }
    const sel = byId('dh-new-db-modal-user');
    const btn = byId('dh-new-db-modal-import-btn');
    const userId = sel ? sel.value : '';
    const chosen = userId ? (S.profiles||[]).find(p=>p.id===userId) : null;
    const assignUser = chosen ? { id: chosen.id, name: chosen.full_name || chosen.email, email: chosen.email } : { id:null, name:null, email:null };

    if (btn) setLoading(btn, true);
    m.status = 'processing';
    render({ status:'connected', folderName:safeName(dirHandle), models:lastFiles, lastSync:new Date() });

    const result = await importOneFile(m, m.existing, m._meta, assignUser);
    if (result.ok){
      S.dbHub.newIds.add(result.dbRow.id);
      m.status = 'imported';
      toast(assignUser.id ? `"${m.name}" imported and assigned to ${assignUser.name}` : `"${m.name}" imported as Unassigned`);
    } else {
      m.status = 'error'; m.errorMsg = result.error;
      toast(`${m.name}: ${result.error}`, 'error');
    }
    render({ status:'connected', folderName:safeName(dirHandle), models:lastFiles, lastSync:new Date() });
    refreshAllDataView();

    if (btn) setLoading(btn, false);
    assignQueue.shift();
    assignQueueBusy = false;
    closeAssignPrompt();
    if (assignQueue.length) maybeShowAssignPrompt();
  }

  function skipAssignPrompt(){
    const m = assignQueue[0];
    if (m) assignDismissedFps.add(m.fp); // won't re-prompt again this session unless the file changes
    assignQueue.shift();
    assignQueueBusy = false;
    closeAssignPrompt();
    if (assignQueue.length) maybeShowAssignPrompt();
  }

  function populateDefaultAssigneeSelect(){
    const sel = byId('dh-folder-default-assignee');
    const wrap = sel ? sel.closest('.field') : null;
    if (!sel) return;
    show(wrap, S.isAdmin !== false); // hide the whole field for non-admins (they auto-assign to themselves)
    if (wrap) wrap.classList.toggle('hidden', !S.isAdmin);
    if (!S.isAdmin) return;
    const saved = (()=>{ try{ return localStorage.getItem(DEFAULT_ASSIGNEE_KEY) || ''; } catch(e){ return ''; } })();
    const users = [...(S.profiles||[])].sort((a,b)=> (a.full_name||a.email||'').localeCompare(b.full_name||b.email||''));
    sel.innerHTML = `<option value="">Leave Unassigned</option>` + users.map(p=>
      `<option value="${esc(p.id)}" ${p.id===saved?'selected':''}>${esc(p.full_name||p.email)}${p.role==='admin'?' (Admin)':''}</option>`
    ).join('');
  }

  const TYPE_LABEL = { database:'Database', lookup:'Lookup', other:'Other' };
  function typeBadge(m){
    const t = m.fileType || 'other';
    const cls = t==='database' ? 'pill-purple' : t==='lookup' ? 'pill-blue' : 'pill-gray';
    return `<span class="pill ${cls}">${TYPE_LABEL[t] || 'Other'}</span>`;
  }
  function fileRowHtml(m){
    const statusPill = {
      new: `<span class="pill pill-blue">New</span>`,
      changed: `<span class="pill pill-amber">Changed</span>`,
      processing: `<span class="pill pill-gray">Processing…</span>`,
      imported: `<span class="pill pill-green">Imported</span>`,
      unchanged: `<span class="pill pill-gray">Unchanged</span>`,
      'not-database': `<span class="pill pill-gray">Ignored</span>`,
      error: `<span class="pill pill-red">Error</span>`,
    }[m.status] || `<span class="pill pill-gray">${esc(m.status)}</span>`;
    const title = m.errorMsg ? esc(m.errorMsg)
      : (m.dbClass && m.dbClass.missing && m.dbClass.missing.length)
        ? `Matched ${esc(m.dbClass.matched.length)}/${esc(m.dbClass.total)} database columns — missing: ${esc(m.dbClass.missing.join(', '))}`
        : '';
    return `<tr title="${title}">
      <td>${esc(m.name)}</td><td>${typeBadge(m)}</td><td>${statusPill}</td>
      <td>${m.size!=null ? fmtBytes(m.size) : '—'}</td>
      <td>${m.lastModified ? fmtDate(m.lastModified) : '—'}</td>
    </tr>`;
  }
  function renderFileList(models){
    const el = byId('dh-folder-filelist');
    const statsEl = byId('dh-folder-stats');
    if (statsEl){
      if (!models || !models.length){ statsEl.textContent = ''; }
      else {
        const dbCount = models.filter(m=>m.fileType==='database').length;
        const lookupCount = models.filter(m=>m.fileType==='lookup').length;
        const otherCount = models.filter(m=>!m.fileType || m.fileType==='other').length;
        statsEl.innerHTML = `${models.length} Excel file${models.length===1?'':'s'} detected<br>`
          + `${dbCount} Database file${dbCount===1?'':'s'}<br>`
          + `${lookupCount} Lookup file${lookupCount===1?'':'s'}<br>`
          + `${otherCount} Other file${otherCount===1?'':'s'}<br>`
          + `<br><b>Last automatic sync:</b><br>`
          + `${scanStats.newlyImported} newly imported, ${scanStats.updatedDatabases} updated<br>`
          + `${scanStats.recordsImported} record${scanStats.recordsImported===1?'':'s'} imported, `
          + `${scanStats.duplicatesSkipped} duplicate${scanStats.duplicatesSkipped===1?'':'s'} skipped<br>`
          + `${scanStats.errors} error${scanStats.errors===1?'':'s'}`;
      }
    }
    if (!el) return;
    if (!models || !models.length){ el.innerHTML = ''; return; }
    el.innerHTML = `<table><thead><tr><th>File</th><th>Type</th><th>Status</th><th>Size</th><th>Modified</th></tr></thead>
      <tbody>${models.map(fileRowHtml).join('')}</tbody></table>`;
  }

  function render(model){
    lastModel = model;
    populateDefaultAssigneeSelect();
    const status = model.status;
    const box = byId('dh-folder-box'), text = byId('dh-folder-box-text'), sub = byId('dh-folder-box-sub');
    const browseBtn = byId('dh-folder-browse-btn'), changeBtn = byId('dh-folder-change-btn');
    const grantBtn = byId('dh-folder-grant-btn'), refreshBtn = byId('dh-folder-refresh-btn');
    const errBox = byId('dh-folder-error'), errTitle = byId('dh-folder-error-title'), errSub = byId('dh-folder-error-sub');
    const unsupported = byId('dh-folder-unsupported-msg');
    const summaryCard = byId('dh-folder-summary-card');
    const activityDetails = byId('dh-folder-activity-details');
    const cardChangeBtn = byId('dh-folder-card-change-btn'), cardGrantBtn = byId('dh-folder-card-grant-btn');

    [browseBtn, changeBtn, grantBtn, refreshBtn, cardGrantBtn].forEach(b=> show(b, false));
    show(errBox, false); show(unsupported, false); show(summaryCard, false); show(activityDetails, false);
    show(box, true);
    if (box) box.classList.remove('loaded');
    if (changeBtn) changeBtn.textContent = 'Change Folder';

    renderDbHubPageStatusBar(model); // keep the Data Hub page's bottom source bar in sync with every state

    if (status === 'unsupported'){
      if (text) text.textContent = 'Not supported in this browser';
      if (sub) sub.textContent = '';
      show(unsupported, true);
      renderFileList([]);
      return;
    }
    if (status === 'checking'){ if (text) text.textContent = 'Checking saved folder…'; return; }
    if (status === 'no-folder'){
      if (text) text.textContent = 'No folder selected';
      if (sub) sub.textContent = 'Select the Data Hub Source Folder DataVault should watch for Excel files.';
      show(browseBtn, true);
      renderFileList([]);
      return;
    }
    if (status === 'permission-needed'){
      if (text) text.textContent = 'Folder permission required';
      if (sub) sub.textContent = model.folderName ? `Folder: ${model.folderName}` : '';
      show(grantBtn, true); show(changeBtn, true);
      return;
    }
    if (status === 'permission-denied'){
      if (text) text.textContent = 'Folder access denied';
      show(errBox, true);
      if (errTitle) errTitle.textContent = 'Folder access denied.';
      if (errSub) errSub.textContent = 'Grant access again, or choose a different folder.';
      show(grantBtn, true); show(changeBtn, true);
      return;
    }
    if (status === 'scanning'){
      if (hasEverConnected){
        // Rescanning an already-connected folder (manual refresh or the 90s poll) — keep
        // showing the compact card instead of flashing back to the dropzone every scan.
        show(box, false);
        show(summaryCard, true);
        const badge = byId('dh-folder-summary-badge');
        if (badge){ badge.textContent = 'Scanning…'; badge.className = 'pill pill-blue'; }
        show(activityDetails, true);
        return;
      }
      if (text) text.textContent = `Scanning ${model.folderName || 'folder'}…`;
      show(changeBtn, true); show(refreshBtn, true);
      return;
    }
    if (status === 'unavailable'){
      if (text) text.textContent = 'Folder access lost';
      show(errBox, true);
      if (errTitle) errTitle.textContent = 'Folder access required';
      if (errSub) errSub.textContent = model.errorMessage || 'The connected folder cannot currently be accessed.';
      show(changeBtn, true); if (changeBtn) changeBtn.textContent = 'Change Folder';
      return;
    }

    // connected — replace the dropzone with the compact status card (spec: Settings must not
    // be a file browser). Full per-file results still live behind "Detection Activity →".
    hasEverConnected = true;
    show(box, false);
    show(summaryCard, true);
    const badge = byId('dh-folder-summary-badge');
    if (badge){ badge.textContent = 'Connected'; badge.className = 'pill pill-green'; }
    renderFolderSummaryCard(model);
    renderFileList(model.models || lastFiles);
    show(activityDetails, true);
  }

  // ---------- Compact Settings status card (spec #7: stats must reflect the automatic sync) ----------
  function renderFolderSummaryCard(model){
    const path = byId('dh-folder-summary-path'), lastScan = byId('dh-folder-summary-lastscan');
    const dbCountEl = byId('dh-folder-summary-dbcount'), otherCountEl = byId('dh-folder-summary-othercount');
    const newCountEl = byId('dh-folder-summary-newcount'), updatedCountEl = byId('dh-folder-summary-updatedcount');
    const recordsCountEl = byId('dh-folder-summary-recordscount'), dupCountEl = byId('dh-folder-summary-dupcount');
    const errorCountEl = byId('dh-folder-summary-errorcount');
    const models = model.models || lastFiles || [];
    if (path) path.textContent = model.folderName || '—';
    if (lastScan) lastScan.textContent = model.lastSync ? `Last scanned: ${fmtDateTime(model.lastSync)}` : 'Last scanned: —';
    // "Databases detected" reflects the latest scan pass; the rest reflect what that same
    // pass's automatic sync actually did (spec #7: databases detected / newly imported /
    // updated / records imported / duplicate records skipped / errors).
    if (dbCountEl) dbCountEl.textContent = scanStats.databasesDetected || models.filter(m=>m.fileType==='database').length;
    if (otherCountEl) otherCountEl.textContent = models.filter(m=>m.fileType!=='database').length;
    if (newCountEl) newCountEl.textContent = scanStats.newlyImported;
    if (updatedCountEl) updatedCountEl.textContent = scanStats.updatedDatabases;
    if (recordsCountEl) recordsCountEl.textContent = scanStats.recordsImported;
    if (dupCountEl) dupCountEl.textContent = scanStats.duplicatesSkipped;
    if (errorCountEl) errorCountEl.textContent = scanStats.errors || models.filter(m=>m.status==='error').length;
  }

  // ---------- Data Hub page bottom source-folder bar: REMOVED ----------
  // The Data Hub page no longer shows folder connection status at all — that now lives
  // exclusively in Settings → Data Hub Source Folder (the compact status card + Detection
  // Activity). This is now a no-op kept only so the single call site below doesn't need
  // touching; it does not read or write anything.
  function renderDbHubPageStatusBar(){ /* intentionally empty — see comment above */ }

  function renderCurrent(){ render(lastModel); }

  function wireUI(){
    const b1 = byId('dh-folder-browse-btn'); if (b1) b1.addEventListener('click', pickFolder);
    const b2 = byId('dh-folder-change-btn'); if (b2) b2.addEventListener('click', pickFolder);
    const b3 = byId('dh-folder-grant-btn'); if (b3) b3.addEventListener('click', grantAccess);
    const b4 = byId('dh-folder-refresh-btn'); if (b4) b4.addEventListener('click', ()=> scanAndLoad());
    // Same actions, surfaced again on the compact connected-state card (spec: Change Folder /
    // Reconnect Folder / Scan Now buttons). Settings is the only place these controls live now.
    const c1 = byId('dh-folder-card-change-btn'); if (c1) c1.addEventListener('click', pickFolder);
    const c2 = byId('dh-folder-card-grant-btn'); if (c2) c2.addEventListener('click', grantAccess);
    const c3 = byId('dh-folder-card-scan-btn'); if (c3) c3.addEventListener('click', ()=> scanAndLoad());
    // (dbb-source-bar-change-btn removed — Data Hub page no longer shows the folder status bar;
    // folder connect/reconnect actions live only in Settings → Data Hub Source Folder now.)
    const sel = byId('dh-folder-default-assignee');
    if (sel) sel.addEventListener('change', ()=>{ try{ localStorage.setItem(DEFAULT_ASSIGNEE_KEY, sel.value || ''); } catch(e){} });

    const promptOverlay = byId('dh-new-db-modal-overlay');
    const importBtn = byId('dh-new-db-modal-import-btn');
    const skipBtn = byId('dh-new-db-modal-skip-btn');
    if (importBtn) importBtn.addEventListener('click', confirmAssignPrompt);
    if (skipBtn) skipBtn.addEventListener('click', skipAssignPrompt);
    // Intentionally no click-outside-to-close / no [x]: an explicit choice (Import or Skip for
    // now) is required so a new database is never silently left in limbo unnoticed.
  }


async function init(){

  // Initialize all Data Hub UI controls
  wireUI();

  // Browser/File System Access API support check
  if (!supported()){
    render({
      status:'unsupported'
    });
    return;
  }

  // Show checking state while restoring the previously
  // connected folder
  render({
    status:'checking'
  });

  // Restore the previously selected folder handle
  let handle = null;

  try{
    handle = await idbGet(HANDLE_KEY);
  }catch(e){
    console.warn('Data Hub: Could not restore saved folder handle:', e);

    handle = null;
  }

  // No previously connected folder
  if (!handle){
    render({
      status:'no-folder'
    });
    return;
  }

  // Restore handle into the active Data Hub state
  dirHandle = handle;

  // Check current browser permission without immediately
  // triggering a permission popup
  let perm = 'denied';

  try{
    perm = await checkPermission(handle, false);
  }catch(e){
    console.warn('Data Hub: Folder permission check failed:', e);

    perm = 'denied';
  }

  // ---------------------------------------------------------
  // PERMISSION GRANTED
  // ---------------------------------------------------------

  if (perm === 'granted'){

    try{

      // Immediately scan the connected folder
      await scanAndLoad();

      // Continue automatic folder polling
      schedulePolling(true);

    }catch(e){

      console.error(
        'Data Hub: Initial folder scan failed:',
        e
      );

      render({
        status:'permission-needed',
        folderName:safeName(handle),
        errorMessage:
          'The connected folder needs to be authorized again.'
      });

    }

    return;
  }

  // ---------------------------------------------------------
  // PERMISSION CAN BE REQUESTED
  // ---------------------------------------------------------

  if (perm === 'prompt'){

    render({
      status:'permission-needed',
      folderName:safeName(handle),
      errorMessage:
        'Folder access needs to be granted again.'
    });

    return;
  }

  // ---------------------------------------------------------
  // PERMISSION DENIED / LOST
  // ---------------------------------------------------------

  render({
    status:'permission-needed',
    folderName:safeName(handle),
    errorMessage:
      'Folder access was lost. Click "Grant Access" to reconnect it.'
  });

}

return {
  init,
  refresh: scanAndLoad,
  renderCurrent,
  pickFolder,
  getModel: ()=> lastModel
};

})();

