  for(const raw of values){const v=String(raw??'').trim();const pin=/\b[1-9][0-9]{5}\b/.test(v),india=/\bindia\b/i.test(v),parts=/\b(?:road|street|plot|floor|building|bldg|unit|suite|industrial area|estate|sector|nagar|marg|lane|phase|district|state|maharashtra|gujarat|delhi|mumbai|chennai|kolkata|bengaluru|hyderabad|pune)\b/i.test(v);if(v.length>=24&&(pin||india)&&parts)hits++;else if(v.length>=28&&parts&&/[,.]/.test(v))hits++;}
