function dtDesignationSignalScore(values){if(!values.length)return 0;return values.filter(v=>/\b(?:CEO|Director|Managing Director|Owner|Proprietor|Export Manager|Sales Manager|Purchase Manager|Manager|Head|President|Vice President|Coordinator|Executive|Officer|Founder|Partner)\b/i.test(String(v))).length/values.length;}
