/* ---------- Daily Updates (Supabase table `updates`, additive) ----------
   Automatic-only creation: the frontend NEVER inserts into `updates` anymore.
   Run this once in the Supabase SQL editor so a row is created automatically
   whenever an Admin assigns a database (i.e. whenever a row is inserted into
   `databases` with assigned_user_id set):

   alter table updates add column if not exists assignment_id uuid references databases(id) on delete cascade;
   -- "on delete cascade" above means: when an Admin deletes a database, its
   -- matching row in `updates` is deleted automatically for every user (owner
   -- and Admin alike) — no extra code needed for that. Admins can additionally
   -- delete a single update card WITHOUT deleting the database (a plain
   -- `delete from updates where id = ...`, wired to the 🗑 icon on each card) —
   -- if that database is later reassigned, the trigger below recreates the card.
   create unique index if not exists updates_assignment_id_key on updates(assignment_id) where assignment_id is not null;

   create or replace function public.create_update_on_db_assignment()
   returns trigger language plpgsql security definer as $$
   begin
     if new.assigned_user_id is not null then
       insert into public.updates (
         assignment_id, owner_id, database_name, total_customers,
         customers_contacted, appointments, remarks, assigned_date, created_at, updated_at
       ) values (
         new.id, new.assigned_user_id, new.name, coalesce(new.customer_count,0),
         0, 0, null, coalesce(new.assigned_at, now()), now(), now()
       )
       on conflict (assignment_id) do nothing;
     end if;
     return new;
   end;
   $$;

   drop trigger if exists trg_update_on_db_insert on databases;
   create trigger trg_update_on_db_insert
     after insert on databases
     for each row execute function public.create_update_on_db_assignment();

   drop trigger if exists trg_update_on_db_reassign on databases;
   create trigger trg_update_on_db_reassign
     after update of assigned_user_id on databases
     for each row when (new.assigned_user_id is not null and new.assigned_user_id is distinct from old.assigned_user_id)
     execute function public.create_update_on_db_assignment();

   -- RLS: same pattern as `records` (owner_id = auth.uid() or admin role). Users
   -- should only be granted UPDATE on customers_contacted/appointments/remarks/
   -- updated_at — never on database_name/total_customers/assigned_date/owner_id/assignment_id.

   -- Delete policy (additive): Users may delete only their own update card;
   -- Admins may delete any update card. The database row and its records are
   -- never touched by this policy — deleting an update card only removes the
   -- row from `updates` (a new card is recreated automatically if the
   -- underlying database is reassigned, via the trigger above).
   drop policy if exists updates_delete_own_or_admin on updates;
   create policy updates_delete_own_or_admin on updates
     for delete
     using (
       owner_id = auth.uid()
       or exists (select 1 from profiles p where p.id = auth.uid() and p.role = 'admin')
     );
   */
// ============================================================================
// LOAD USER PROFILES FOR UPDATE CARDS
// Fixed Version
// Supports:
// ✓ assigned_user_id
// ✓ owner_id fallback
// ✓ assigned_user_name fallback
// ✓ assigned_user_email fallback
// Prevents "Unknown User"
// ============================================================================

async function loadUpdates(){

    const { data, error } = await supa
        .from('updates')
        .select('*')
        .order('assigned_date', { ascending:false });

    let updates = error ? [] : (data || []);

    // ===========================================
    // REPLACE ONLY THIS ENTIRE BLOCK
    // ===========================================

    if (updates.length) {

       const userIds = [
    ...new Set(
        updates
            .map(u => u.owner_id)
            .filter(Boolean)
    )
];
        let profilesById = {};

        if (userIds.length) {

            const { data: profs, error: profErr } = await supa
                .from("profiles")
                .select("id,full_name,email,role,avatar_url")
                .in("id", userIds);

            if (profErr) {
                console.error(profErr);
            }

            (profs || []).forEach(profile=>{
                profilesById[profile.id]=profile;
            });
        }

        updates = updates.map(update=>{

            const userId = update.owner_id;

            let profile =
                profilesById[userId] ||
                S.profiles.find(p=>p.id===userId);

            if(!profile){

                profile={

                    id:userId,

                    full_name:
                        update.assigned_user_name ||
                        "Unknown User",

                    username:
                        update.assigned_user_name ||
                        "",

                    email:
                        update.assigned_user_email ||
                        "",

                    role:"user",

                    avatar_url:null
                };

            }

            return{

                ...update,

                _profile:profile,

                assigned_user_name:
                    profile.full_name,

                assigned_user_email:
                    profile.email,

                assigned_user_role:
                    profile.role

            };

        });

    }

    S.updates = updates;
    dhStashServerSnapshots(); dhReconcileAfterLoad();

} // ← THIS closing brace MUST exist

/* ---------- Reminders ---------- */

/* ---------- Reminders (Supabase table `reminders`, additive) ----------
   Schema (run once in the Supabase SQL editor, shipped alongside schema.sql):

   create table if not exists reminders (
     id uuid primary key default gen_random_uuid(),
     record_id uuid references records(id) on delete cascade,
     database_id uuid references databases(id) on delete set null,
     database_name text,
     company_name text,
     assigned_to text,
     owner_id uuid references auth.users(id),
     reminder_date date not null,
     quarter text,
     remarks text,
     completed boolean not null default false,
     created_at timestamptz not null default now(),
     updated_at timestamptz not null default now()
   );
   -- RLS: same pattern as `records` / `updates` (owner_id = auth.uid() or admin role). */
/* ---------- Completion ratings (Supabase table `ratings`, additive) ----------
   Schema (run once in the Supabase SQL editor — see security_migration.sql
   shipped alongside this file for the full statements including RLS):

   create table if not exists ratings (
     id uuid primary key default gen_random_uuid(),
     assignment_id uuid not null references databases(id) on delete cascade,
     database_name text,
     user_id uuid not null references auth.users(id) on delete cascade,
     rating smallint check (rating between 1 and 5),
     review text,
     skipped boolean not null default false,
     created_at timestamptz not null default now(),
     unique (assignment_id, user_id),
     constraint ratings_rating_or_skip check (skipped = true or rating is not null)
   );

   RLS (enforced server-side — never trust a client-supplied user_id):
     - insert: with check (user_id = auth.uid() AND the matching `updates` row
       for this assignment_id has customers_contacted >= total_customers —
       i.e. a user cannot insert a rating before actually completing the
       assignment, even via a direct REST call. See security_migration.sql.)
     - select: using (user_id = auth.uid() or admin)
     - update: using (user_id = auth.uid()) with check (user_id = auth.uid())  -- editing own rating only
   The unique(assignment_id, user_id) constraint is what prevents duplicate
   rating prompts/records for the same completed assignment.

   Loading is role-aware: Admins load every rating (their RLS select policy
   permits it) so they can see team-wide feedback; regular users are scoped
   to their own rows both by this query AND by the server-side RLS select
   policy (defense in depth — the query alone is not the real boundary). */
async function loadRatings(){
  let q = supa.from('ratings').select('*').order('created_at', { ascending:false });
  if (!S.isAdmin) q = q.eq('user_id', S.session.user.id);
  const { data, error } = await q;
  if (error) logSupaError('select', 'ratings', error);
  S.ratings = error ? [] : (data || []);
}
function hasRatingRecord(assignmentId, userId){
  if (!assignmentId) return false;
  const uid = userId || (S.session && S.session.user.id);
  return S.ratings.some(r => String(r.assignment_id) === String(assignmentId) && String(r.user_id) === String(uid));
}
function myRatingFor(assignmentId){
  if (!assignmentId || !S.session) return null;
  return S.ratings.find(r => String(r.assignment_id) === String(assignmentId) && String(r.user_id) === String(S.session.user.id) && r.rating != null) || null;
}

