function flagDuplicates(){
  const seen = { company:{}, bemail:{}, pemail:{}, mobile:{}, site:{}, li:{}, phone:{} };
  S.records.forEach(r=>{
    r._dup = false;
    const keys = [
      ['company', r.company_name], ['bemail', r.business_email_1], ['pemail', r.personal_email_1],
      ['mobile', r.mobile_phone_1], ['site', r.company_website_1], ['li', r.linkedin_1]
    ];
    keys.forEach(([bucket, val])=>{
      if (!val) return;
      const k = String(val).trim().toLowerCase();
      if (!k) return;
      if (seen[bucket][k]) r._dup = true;
      seen[bucket][k] = true;
    });
    // Phone duplicates are based on normalized individual numbers, never the
    // original combined cell formatting. This covers all six approved fields.
    DH_PHONE_SOURCE_FIELDS.forEach(field=>{
      dhParsePhoneCell(r[field]).forEach(p=>{
        if (seen.phone[p.identity]) r._dup = true;
        seen.phone[p.identity] = true;
      });
    });
  });
  refreshDuplicateCompanyIndex(); // keep the cross-database "Duplicate Companies" index in sync with S.records
  if (typeof _dhQualityCache !== 'undefined') _dhQualityCache.clear();
}
// Same exact duplicate semantics as flagDuplicates(), but yields between bounded
// batches so opening a large database does not monopolize the browser main thread.
async function dhFlagDuplicatesYielding(batchSize=750){
  const seen = { company:Object.create(null), bemail:Object.create(null), pemail:Object.create(null), mobile:Object.create(null), site:Object.create(null), li:Object.create(null), phone:Object.create(null) };
  const rows = S.records || [];
  for (let start=0; start<rows.length; start+=batchSize){
    const end = Math.min(rows.length, start+batchSize);
    for (let i=start; i<end; i++){
      const r = rows[i];
      r._dup = false;
      const keys = [
        ['company', r.company_name], ['bemail', r.business_email_1], ['pemail', r.personal_email_1],
        ['mobile', r.mobile_phone_1], ['site', r.company_website_1], ['li', r.linkedin_1]
      ];
      for (const [bucket,val] of keys){
        if (!val) continue;
        const k = String(val).trim().toLowerCase();
        if (!k) continue;
        if (seen[bucket][k]) r._dup = true;
        seen[bucket][k] = true;
      }
      for (const field of DH_PHONE_SOURCE_FIELDS){
        const parsed = dhParsePhoneCell(r[field]);
        for (const phone of parsed){
          if (seen.phone[phone.identity]) r._dup = true;
          seen.phone[phone.identity] = true;
        }
      }
    }
    if (end < rows.length) await new Promise(resolve=>setTimeout(resolve,0));
  }
  refreshDuplicateCompanyIndex();
  if (typeof _dhQualityCache !== 'undefined') _dhQualityCache.clear();
}

/* ==========================================================================
   Data Hub Source Folder — DUPLICATE DETECTION (row-level + company-level)

   Two independent, additive layers on top of the existing flagDuplicates()
   (which already flags exact-match duplicate records within S.records):

   1) recordIdentityKey() — a normalized "is this the same customer" key used by
      performImport() to decide, per row, whether a matching record already exists
      in the target database BEFORE inserting it. This is what makes re-scanning
      the same database/folder idempotent (never creates duplicate records).

   2) computeDuplicateCompanyGroups() — groups every cached record by normalized
      Company Name and reports the companies that appear in 2+ DIFFERENT databases,
      together with the source database(s) and occurrence count for each. This never
      deletes or merges anything — different source spreadsheets may legitimately
      each have their own contact for the same company — it only makes those
      overlaps easy to find (Advanced Filters "Duplicate Company Name" checkbox,
      the "Duplicate Companies" quick chip, and the dedicated Duplicate Companies
      panel opened from the Data Hub toolbar).
   ========================================================================== */
function normalizeForMatch(v){
  return String(v==null ? '' : v).trim().toLowerCase().replace(/\s+/g, ' ');
}
// Normalizes a Company Name for comparison: trims/lowercases/collapses whitespace and strips
// common legal-entity suffixes and punctuation so "Acme Pvt. Ltd.", "ACME PVT LTD" and
// "Acme  Pvt  Ltd" are all recognized as the same company (spec: Duplicate Companies filter).
function normalizeCompanyName(v){
  let s = normalizeForMatch(v);
  if (!s) return '';
  s = s.replace(/[.,]/g, ' ');
  s = s.replace(/[^a-z0-9&\s]/g, ' ');
  s = s.replace(/\b(pvt|private|ltd|limited|llc|llp|inc|incorporated|corp|corporation|co|company|gmbh|plc|pte)\b/g, ' ');
  s = s.replace(/\s+/g, ' ').trim();
  return s;
}
// Best-available "same customer" identity for one record: normalized Company Name paired
// with the first strong identifier present (any email/phone/website/LinkedIn — these are the
// fields most likely to be unique to one real customer). Falls back to company+contact when no
// such identifier exists. Returns null only when the row has nothing identifying at all.
function recordIdentityKeys(rec){
  const company = normalizeCompanyName(rec.company_name);
  const keys = [];
  const strongFields = [
    rec.business_email_1, rec.business_email_2, rec.personal_email_1, rec.personal_email_2,
    rec.mobile_phone_1, rec.mobile_phone_2, rec.work_phone_1, rec.work_phone_2,
    rec.linkedin_1, rec.company_website_1, rec.company_website_number_1, rec.company_website_number_2,
  ];
  const phoneValues = [rec.mobile_phone_1,rec.mobile_phone_2,rec.work_phone_1,rec.work_phone_2,rec.company_website_number_1,rec.company_website_number_2];
  phoneValues.forEach(f=>{ dhParsePhoneCell(f).forEach(p=>{ keys.push(`${company}||phone:${p.identity}`); keys.push(`phone:${p.identity}`); }); });
  const nonPhoneFields = [rec.business_email_1,rec.business_email_2,rec.personal_email_1,rec.personal_email_2,rec.linkedin_1,rec.company_website_1,rec.company_website_number_1,rec.company_website_number_2];
  for (const f of nonPhoneFields){ const v=normalizeForMatch(f); if(v) keys.push(`${company}||${v}`); }
  const contact = normalizeForMatch(rec.contact_person);
  if (!keys.length && (company || contact)) keys.push(`${company}||c:${contact}`);
  return [...new Set(keys)];
}
function recordIdentityKey(rec){
  return recordIdentityKeys(rec)[0] || null;
}

/* Fetch the identity fields for the ENTIRE Data Hub, not just S.records.
   S.records is intentionally capped at 50,000 rows, so using it for duplicate prevention
   can miss an older matching customer. This paginated identity-only query makes duplicate
   protection workspace-wide while keeping the payload much smaller than select('*'). */
function dhDuplicateIdentityValues(rec){
  const out = new Set();
  if (!rec) return out;
  const phoneFields = ['mobile_phone_1','mobile_phone_2','work_phone_1','work_phone_2','company_website_number_1','company_website_number_2'];
  phoneFields.forEach(field=>{
    dhParsePhoneCell(rec[field]).forEach(p=>{ if (p?.identity) out.add('phone:' + p.identity); });
  });
  ['business_email_1','business_email_2','personal_email_1','personal_email_2','linkedin_1','company_website_1'].forEach(field=>{
    const value = normalizeForMatch(rec[field]);
    if (value) out.add(field + ':' + value);
  });
  return out;
}

function isTrueDuplicateRecord(incomingRecord, existingRecord){
  const incomingCompany = normalizeCompanyName(incomingRecord?.company_name);
  const existingCompany = normalizeCompanyName(existingRecord?.company_name);
  if (!incomingCompany || !existingCompany || incomingCompany !== existingCompany){
    return { duplicate:false, reason:'different-or-uncertain-company' };
  }
  const incomingSupporting = dhDuplicateIdentityValues(incomingRecord);
  const existingSupporting = dhDuplicateIdentityValues(existingRecord);
  for (const value of incomingSupporting){
    if (existingSupporting.has(value)){
      return { duplicate:true, reason:'exact normalized company + supporting identity match', matchedIdentity:value };
    }
  }
  return { duplicate:false, reason:'same-company-no-supporting-match' };
}

function buildFolderDuplicateIndex(records){
  const byCompany = new Map();
  const bySupporting = new Map();

  (records || []).forEach(record=>{
    const company = normalizeCompanyName(record?.company_name);
    if (company){
      let list = byCompany.get(company);
      if (!list){ list=[]; byCompany.set(company,list); }
      list.push(record);
    }

    dhDuplicateIdentityValues(record).forEach(identity=>{
      let list = bySupporting.get(identity);
      if (!list){ list=[]; bySupporting.set(identity,list); }
      list.push(record);
    });
  });

  return { byCompany, bySupporting };
}

async function fetchWorkspaceIdentityRecords(){
  const PAGE = 1000;
  const fields = 'company_name,contact_person,personal_email_1,personal_email_2,business_email_1,business_email_2,mobile_phone_1,mobile_phone_2,work_phone_1,work_phone_2,linkedin_1,company_website_1,company_website_number_1,company_website_number_2';
  const records = [];
  let from = 0;
  while (true){
    const { data, error } = await supa.from('records').select(fields).order('id',{ascending:true}).range(from, from + PAGE - 1);
    if (error) throw error;
    records.push(...(data || []));
    if (!data || data.length < PAGE) break;
    from += PAGE;
  }
  return records;
}
// Groups whatever is currently cached in S.records by normalized Company Name and keeps only
// the companies that span 2+ distinct databases. Recomputed on demand (records are cheap to
// iterate; nothing here is persisted or requires a schema migration).
function computeDuplicateCompanyGroups(){
  const groups = new Map();
  (S.records||[]).forEach(r=>{
    const norm = normalizeCompanyName(r.company_name);
    if (!norm) return;
    let g = groups.get(norm);
    if (!g){ g = { key:norm, name:String(r.company_name||'').trim(), databases:new Map(), recordCount:0 }; groups.set(norm, g); }
    g.recordCount++;
    if (!g.name) g.name = String(r.company_name||'').trim();
    const dbKey = r.database_id != null ? String(r.database_id) : ('name:'+(r.database_name||'unknown'));
    let db = g.databases.get(dbKey);
    if (!db){ db = { id: r.database_id ?? null, name: r.database_name || 'Unknown database', count:0 }; g.databases.set(dbKey, db); }
    db.count++;
  });
  const out = [];
  groups.forEach(g=>{
    if (g.databases.size >= 2){
      out.push({
        companyName: g.name,
        occurrenceCount: g.databases.size, // number of DIFFERENT databases this company appears in
        recordCount: g.recordCount,        // total customer records for this company across all of them
        databases: [...g.databases.values()].sort((a,b)=> b.count - a.count),
      });
    }
  });
  out.sort((a,b)=> b.occurrenceCount - a.occurrenceCount || b.recordCount - a.recordCount || a.companyName.localeCompare(b.companyName));
  return out;
}
// Cached per S.records refresh (see flagDuplicates()) so per-card lookups during a render pass
// stay O(1) instead of re-scanning every record for every database card.
let _dhDupCompanyGroups = [];
let _dhDupCompanyDbKeys = new Set();
function refreshDuplicateCompanyIndex(){
  _dhDupCompanyGroups = computeDuplicateCompanyGroups();
  _dhDupCompanyDbKeys = new Set();
  _dhDupCompanyGroups.forEach(g=> g.databases.forEach(db=> _dhDupCompanyDbKeys.add(db.id!=null ? String(db.id) : ('name:'+db.name))));
}
function dbbHasDuplicateCompany(d){
  return _dhDupCompanyDbKeys.has(String(d.id)) || _dhDupCompanyDbKeys.has('name:'+d.name);
}
function dbbDuplicateCompanyGroupsForDb(d){
  const id = String(d?.id || '');
  const nameKey = 'name:' + String(d?.name || '');
  return (_dhDupCompanyGroups || []).filter(g => g.databases.some(db =>
    (db.id != null && String(db.id) === id) || (db.id == null && ('name:'+String(db.name||'')) === nameKey)
  ));
}
function dbbDuplicateCompanySummary(d){
  const groups = dbbDuplicateCompanyGroupsForDb(d);
  const otherDbIds = new Set();
  const otherDbNames = new Set();
  groups.forEach(g=>g.databases.forEach(db=>{
    const isThis = (db.id != null && String(db.id) === String(d.id)) || (db.id == null && String(db.name||'') === String(d.name||''));
    if (!isThis){
      if (db.id != null) otherDbIds.add(String(db.id));
      otherDbNames.add(String(db.name||'Unknown database'));
    }
  }));
  return { companyCount:groups.length, otherDbCount:otherDbIds.size || otherDbNames.size, otherDbNames:[...otherDbNames].sort() };
}

