const PAGE_TITLES = { dashboard:'Dashboard', alldata:'Data Hub', calendar:'Calendar', updates:'Updates', joc:'JOC', analytics:'Analytics', toolkits:'Toolkits', settings:'Settings', audit:'Audit Logs' };
$all('.nav-item').forEach(item=>{
  item.addEventListener('click', ()=>{
    // Clicking "Data Hub" in the sidebar always returns to the database browser
    // (deep links elsewhere, e.g. Analytics "View", call openDatabaseView() directly
    // right after goPage('alldata'), which switches back to the table view).
    if (item.dataset.page==='alldata'){ S.dbHub.view='list'; S.grid.dbFilter=''; S.grid.dbIdFilter=''; }
    goPage(item.dataset.page);
  });
});
function goPage(page){
  // Analytics is Admin-only. Block navigation at the router level (not just
  // CSS/nav-item hiding) so a non-admin can never land on the page — via a
  // stale link, dev tools, or any other path that bypasses the sidebar click.
  if ((page === 'analytics' || page === 'joc') && !S.isAdmin){
    goPage('dashboard');
    return;
  }
  S.page = page;
  $all('.nav-item').forEach(n=>n.classList.toggle('active', n.dataset.page===page));
  $all('.page').forEach(p=>p.classList.remove('active'));
  $('#page-'+page).classList.add('active');
  $('#page-title').textContent = PAGE_TITLES[page] || 'SWIFT CARGO';
  if (page==='alldata') renderAllDataView();
  if (page==='calendar') renderCalendar();
  if (page==='updates') renderUpdatesPage();
  if (page==='joc') renderJOCPage();
  if (page==='analytics') renderAnalyticsPage();
}
