/* Storage stats are shared by the dashboard KPI calc (kept for parity) and the
   Settings → Storage Card. The "Logged-in User" and "Storage Used" tiles have
   moved off the dashboard entirely per the profile/storage cards in Settings. */
function computeStorageStats(){
  const myDbs = myAssignedDatabases();
  const totalCustomers = dhTotalCustomers(myDbs);
  const usedMB = totalCustomers * 0.6 / 1024; // rough estimate for display
  const availableMB = 500; // plan allowance placeholder for display purposes
  const pct = Math.min(100, Math.round((usedMB/availableMB)*100));
  return { usedMB, availableMB, pct, dbCount: myDbs.length };
}

function renderDashboard(){
  const myDbs = myAssignedDatabases();
  const totalDatabases = myDbs.length;
  const totalCustomers = dhTotalCustomers(myDbs);
  const recentDb = myDbs[0];
  const todayStr = new Date().toDateString();
  const todaysImports = myDbs.filter(d=> new Date(d.upload_date).toDateString()===todayStr).length;
  // Count only rows with a real assigned_user_id that resolves to an existing profile.
  // Admin KPI covers the workspace; regular users remain scoped to their own assigned rows.
  const validProfileIds = new Set((S.profiles||[]).map(p=>String(p.id)));
  const assignedToMe = (myDbs||[]).filter(d=>d.assigned_user_id && validProfileIds.has(String(d.assigned_user_id))).length;

  const kpis = [
    { label:'Recently Added Database', value: recentDb ? recentDb.name : '—', wrap:true, featured:true,
      meta: recentDb ? [
        { k:'Assigned User', v: recentDb.assigned_user_name || recentDb.assigned_to || '—' },
        { k:'Customer Count', v: (recentDb.customer_count ?? 0).toLocaleString() },
        { k:'Import Date', v: fmtDate(recentDb.upload_date) },
      ] : [],
      sub: recentDb ? '' : 'No databases yet', icon:iconClock, color:'#4F6BFF' },
    { label:'Total Databases', value:totalDatabases, sub:`Across ${S.isAdmin?'the whole workspace':'your account'}`, icon:iconDb, color:'#4F6BFF' },
    { label:'All Customers', value:totalCustomers.toLocaleString(), sub:'', icon:iconUsers, color:'#4EA8FF' },
    { label:'Recent Imports', value: myDbs.filter(d=> (Date.now()-new Date(d.upload_date))/86400000 < 7).length, sub:'Databases imported in the last 7 days', icon:iconImport, color:'#FFB648' },
    { label:'Assigned Databases', value: assignedToMe, sub:'', icon:iconAssign, color:'#9B6BFF' },
  ];
  $('#kpi-grid').innerHTML = kpis.map(k=>{
    /* Each KPI type maps to its own logo image in assets/. If the image is
       missing or fails to load, kpiLogoFallback() swaps it for the card's
       own icon so the frame never renders empty — and if a KPI type has no
       dedicated asset at all, no frame is rendered (the card falls back to
       symmetric padding via .no-logo instead of a decorative placeholder). */
    const logoPath = KPI_LOGO_MAP[k.label];
    const logoSrc = logoPath || '';
    const logoFrame = logoSrc
      ? `<div class="card-logo-frame" title="${esc(k.label)} logo"><img src="${logoSrc}" alt="" loading="lazy" onerror="kpiLogoFallback(this, '${k.label.replace(/'/g,"\\'")}');"></div>`
      : '';
    const tint = `background:linear-gradient(160deg, ${k.color}0D 0%, #FFFFFF 55%);`;
    const iconStyle = `background:linear-gradient(135deg, ${k.color} 0%, ${k.color}CC 100%); color:#fff;`;
    if (k.featured){
      return `
      <div class="kpi-card kpi-featured" style="${tint}">
        <div class="kpi-featured-head">
          <div class="kpi-icon" style="${iconStyle}">${k.icon}</div>
          <span class="pill pill-blue">Most recent</span>
          ${logoFrame}
        </div>
        <div class="kpi-label" style="margin-top:16px;">${k.label}</div>
        <div class="kpi-value ${k.wrap?'name-wrap':''}" ${k.wrap?`title="${esc(String(k.value))}"`:''}>${esc(String(k.value))}</div>
        ${k.meta.length ? `<div class="kpi-meta-row">${k.meta.map(m=>`
          <div class="kpi-meta-item"><div class="k">${esc(m.k)}</div><div class="v">${esc(String(m.v))}</div></div>`).join('')}</div>`
          : `<div class="kpi-sub">${k.sub}</div>`}
      </div>`;
    }
    return `
    <div class="kpi-card ${logoFrame?'':'no-logo'}" style="${tint}">
      <div class="kpi-top">
        ${logoFrame}
      </div>
      <div>
        <div class="kpi-label">${k.label}</div>
        <div class="kpi-value" style="font-size:${String(k.value).length>10?'20px':'26px'};">${esc(String(k.value))}</div>
      </div>
      <div class="kpi-sub">${k.sub}</div>
    </div>`;
  }).join('');

  $('#db-total-pill').textContent = totalDatabases + ' total';
  $('#cust-total-pill').textContent = totalCustomers.toLocaleString() + ' total';
  renderDbDistributionChart(myDbs);
  renderCustDistributionChart(myDbs);
  renderRecentDbList(myDbs);
  renderTopAssigned(myDbs);
  renderActivityTimeline(myDbs);
  renderUpdatesStatsPanel();
  renderReminderDashboardPanel();
  animateKpiNumbers($('#kpi-grid'));
  animateKpiNumbers($('#upd-stats-grid'));
  animateKpiNumbers($('#reminder-stats-grid'));
}

/* ---------- Premium KPI count-up animation (Dashboard only, additive) ----------
   Purely a presentation layer on top of the existing KPI rendering: it never
   recomputes or alters a value, it only animates the already-rendered digits
   from 0 up to the exact figure renderDashboard() calculated. Runs once per
   render (when the Dashboard loads/re-renders) — never on a timer/loop.
   Non-numeric KPI cells (database names, dates, "—" placeholders) are left
   untouched, and prefers-reduced-motion skips straight to the final value. */
function animateKpiNumbers(container){
  if (!container) return;
  const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  $all('.kpi-value', container).forEach(node=>{
    const raw = node.textContent.trim();
    if (!/^[0-9][0-9,]*$/.test(raw)) return; // only pure numbers get animated
    const finalValue = parseInt(raw.replace(/,/g,''), 10);
    if (!Number.isFinite(finalValue)) return;
    if (reduceMotion || finalValue === 0){ node.textContent = finalValue.toLocaleString(); return; }
    const duration = Math.min(1200, Math.max(700, 700 + Math.log10(finalValue+1)*80));
    const start = performance.now();
    const easeOutExpo = t => t===1 ? 1 : 1 - Math.pow(2, -10*t);
    (function tick(now){
      const t = Math.min(1, (now-start)/duration);
      node.textContent = Math.round(easeOutExpo(t)*finalValue).toLocaleString();
      if (t < 1) requestAnimationFrame(tick);
    })(start);
  });
}

/* Additive: auto-calculated Updates statistics shown on the Dashboard.
   Recomputed whenever an Update is added, edited, or deleted. */
function renderUpdatesStatsPanel(){
  const grid = $('#upd-stats-grid');
  if (!grid) return;
  const rows = S.isAdmin ? S.updates : S.updates.filter(u=>u.owner_id===S.session.user.id);
  const totalUpdates = rows.length;
  const totalAssigned = rows.reduce((s,u)=> s + Number(u.total_customers||0), 0);
  // Each update row stores the overall total for that assignment. Use one
  // assignment record so the dashboard does not double-count the same database.
  const byDatabase = new Map();
  rows.forEach(u=>{
    const key=String(u.id||u.assignment_id||u.database_name||'');
    const current=byDatabase.get(key)||{contacted:0,appointments:0};
    current.contacted=Math.max(current.contacted, Number(u.customers_contacted||0));
    current.appointments=Math.max(current.appointments, Number(u.appointments||0));
    byDatabase.set(key,current);
  });
  const totalContacted = [...byDatabase.values()].reduce((s,u)=>s+u.contacted,0);
  const totalAppointments = [...byDatabase.values()].reduce((s,u)=>s+u.appointments,0);

  const stats = [
    { label:'Total Updates', value:totalUpdates.toLocaleString(), icon:iconClock, color:'#4F6BFF' },
    { label:'Customers Assigned', value:totalAssigned.toLocaleString(), icon:iconUsers, color:'#4EA8FF' },
    { label:'Customers Contacted', value:totalContacted.toLocaleString(), icon:iconAssign, color:'#9B6BFF' },
    { label:'Appointments', value:totalAppointments.toLocaleString(), icon:iconImport, color:'#FFB648' },
  ];

  grid.innerHTML = stats.map(k=>{
    const tint = `background:linear-gradient(160deg, ${k.color}0D 0%, #FFFFFF 55%);`;
    const iconStyle = `background:linear-gradient(135deg, ${k.color} 0%, ${k.color}CC 100%); color:#fff;`;
    return `
    <div class="kpi-card no-logo" style="${tint}">
      <div class="kpi-top">
        <div class="kpi-icon" style="${iconStyle}">${k.icon}</div>
      </div>
      <div>
        <div class="kpi-label">${k.label}</div>
        <div class="kpi-value" style="font-size:${String(k.value).length>10?'20px':'26px'};">${esc(String(k.value))}</div>
      </div>
    </div>`;
  }).join('');
}

const CHART_COLORS = ['#2563EB','#60A5FA','#7C3AED','#DB2777','#D97706','#16A34A','#0EA5E9','#DC2626','#4F46E5','#059669'];

function groupBy(arr, keyFn){
  const m = {};
  arr.forEach(x=>{ const k = keyFn(x) || 'Unassigned'; m[k]=(m[k]||0)+1; });
  return m;
}
function renderDbDistributionChart(dbs){
  const grouped = groupBy(dbs, d=>d.assigned_to);
  const labels = Object.keys(grouped); const values = Object.values(grouped);
  drawDoughnut('chart-db-dist', labels, values);
  renderLegend('#chart-db-dist', labels, values); // uses sibling append via helper below
}
function renderCustDistributionChart(dbs){
  const top = [...dbs].sort((a,b)=>b.customer_count-a.customer_count).slice(0,8);
  const labels = top.map(d=>d.name); const values = top.map(d=>d.customer_count);
  drawDoughnut('chart-cust-dist', labels, values);
  renderLegend2('#chart-cust-dist', labels, values);
}
function drawDoughnut(canvasId, labels, values){
  const ctx = document.getElementById(canvasId).getContext('2d');
  if (S.charts[canvasId]) S.charts[canvasId].destroy();
  if (!labels.length){ labels=['No data']; values=[1]; }
  S.charts[canvasId] = new Chart(ctx, {
    type:'doughnut',
    data:{ labels, datasets:[{ data:values, backgroundColor:CHART_COLORS, borderWidth:2, borderColor:'#fff', hoverOffset:6 }] },
    options:{ responsive:true, maintainAspectRatio:false, cutout:'68%', plugins:{ legend:{ display:false }, tooltip:{ backgroundColor:'#111827', padding:10, cornerRadius:8 } } }
  });
}
function legendHtml(labels, values){
  const total = values.reduce((a,b)=>a+b,0) || 1;
  return labels.map((l,i)=>`
    <div class="legend-row"><span class="legend-dot" style="background:${CHART_COLORS[i%CHART_COLORS.length]}"></span>
      <span class="lname">${esc(l)}</span><span class="lval">${values[i]} · ${Math.round(values[i]/total*100)}%</span></div>`).join('');
}
function renderLegend(canvasSel, labels, values){
  const wrap = document.getElementById('chart-db-dist').closest('.panel');
  let holder = wrap.querySelector('.legend-list'); if(!holder){ holder=document.createElement('div'); holder.className='legend-list'; wrap.appendChild(holder); }
  holder.innerHTML = legendHtml(labels, values);
}
function renderLegend2(canvasSel, labels, values){
  const wrap = document.getElementById('chart-cust-dist').closest('.panel');
  let holder = wrap.querySelector('.legend-list'); if(!holder){ holder=document.createElement('div'); holder.className='legend-list'; wrap.appendChild(holder); }
  holder.innerHTML = legendHtml(labels, values);
}

