// Lightweight, client-side relevance scoring used only on the returned company names.
// Kept self-contained here because the existing entity-resolution Levenshtein helper lives
// inside another scope and is not globally callable from Advanced Search.
function dhAdvancedSearchLevenshteinRatio(a, b){
  a = String(a || ''); b = String(b || '');
  if (!a && !b) return 1;
  if (!a || !b) return 0;
  if (a === b) return 1;
  const maxLen = Math.max(a.length, b.length);
  if (maxLen > 1200) return 0;
  let prev = new Array(b.length + 1);
  let cur = new Array(b.length + 1);
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++){
    cur[0] = i;
    for (let j = 1; j <= b.length; j++){
      cur[j] = Math.min(
        cur[j-1] + 1,
        prev[j] + 1,
        prev[j-1] + (a[i-1] === b[j-1] ? 0 : 1)
      );
    }
    [prev, cur] = [cur, prev];
  }
  return 1 - prev[b.length] / maxLen;
}

function dhAdvancedSearchScore(query, candidate){
  const rawQ = String(query || '').trim().toLowerCase();
  const rawC = String(candidate || '').trim().toLowerCase();
  if (!rawQ || !rawC) return 0;

  const clean = s => s
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const q = clean(rawQ);
  const c = clean(rawC);
  if (!q || !c) return 0;

  if (c === q) return 100;
  if (c.startsWith(q)) return 98;
  if (c.includes(q)) return 94;

  const qTokens = q.split(' ').filter(Boolean);
  const cTokens = c.split(' ').filter(Boolean);

  // Exact token / token-prefix coverage is especially useful for "loxim" → "loxim industries".
  let tokenScore = 0;
  for (const qt of qTokens){
    let best = 0;
    for (const ct of cTokens){
      if (ct === qt) best = Math.max(best, 1);
      else if (ct.startsWith(qt) || qt.startsWith(ct)) best = Math.max(best, .92);
      else if (Math.abs(ct.length - qt.length) <= 4) best = Math.max(best, dhAdvancedSearchLevenshteinRatio(qt, ct));
    }
    tokenScore += best;
  }
  tokenScore /= Math.max(1, qTokens.length);

  const compactQ = q.replace(/\s/g,'');
  const compactC = c.replace(/\s/g,'');
  const charScore = dhAdvancedSearchLevenshteinRatio(compactQ, compactC);

  // Partial-token containment without allowing a generic suffix to dominate.
  const sharedTokenCount = qTokens.filter(qt => cTokens.some(ct => ct === qt || ct.startsWith(qt))).length;
  const coverage = sharedTokenCount / Math.max(1, qTokens.length);

  return Math.max(0, Math.min(100,
    tokenScore * 42 +
    charScore * 23 +
    coverage * 30 +
    (compactC.startsWith(compactQ) ? 5 : 0)
  ));
}

async function runDhAdvancedSearch(){
  dhEnsureAdvancedSearchState();
  const input = $('#dh-as-company-input');
  const dbSelect = $('#dh-as-database');
  const userSelect = $('#dh-as-user');
  if (!input || !dbSelect || !userSelect) return;

  const companyName = input.value.trim();
  const databaseId = dbSelect.value || '';
  const userId = userSelect.value || '';

  S.advancedSearch = {
    companyName, databaseId, userId, resultCount:0,
    results:[], hasSearched:true, loading:false
  };

  if (!companyName) {
    renderDhStatsRow();
    toast('Enter a company name to search.', 'error');
    return;
  }

  renderDhStatsRow();
  S.advancedSearch.loading = true;
  renderDhStatsRow();

  try {
    // Use the authenticated Supabase records query directly. RLS is therefore still
    // authoritative; no new access path, table, schema, or cache is introduced.
    // Fetch only fields required for the result display + matching.
    const PAGE = 1000;
    const selectedDbIds = databaseId ? [databaseId] : null;
    const rows = [];
    let from = 0;

    while (true){
      let query = supa
        .from('records')
        .select('id,database_id,company_name,owner_id,assigned_to,database_name');

      if (selectedDbIds) query = query.eq('database_id', selectedDbIds[0]);

      const { data, error } = await query
        .order('id', { ascending:true })
        .range(from, from + PAGE - 1);

      if (error) throw error;
      rows.push(...(data || []));

      if (!data || data.length < PAGE) break;
      from += PAGE;
    }

    // Build database/user display maps from the already-loaded accessible state.
    const dbMap = new Map((dataHubBrowseDatabases() || []).map(d=>[
      String(d.id), d
    ]));
    const profileMap = new Map((S.profiles || []).map(u=>[
      String(u.id), u
    ]));

    // If the database filter is not selected, use the actual database row from state;
    // RLS has already restricted what the query can return.
    const filtered = rows.filter(r=>{
      if (databaseId && String(r.database_id) !== String(databaseId)) return false;

      // Records in this app can carry assignment as assigned_to while the database card
      // uses assigned_user_id. Respect the record's own assignment when available, with
      // the database assignment as fallback.
      const assignedId = r.assigned_to || dbMap.get(String(r.database_id))?.assigned_user_id || '';
      if (userId && String(assignedId) !== String(userId)) return false;
      return !!String(r.company_name || '').trim();
    });

    const scored = filtered.map(r=>{
      const db = dbMap.get(String(r.database_id));
      const assignedId = r.assigned_to || db?.assigned_user_id || '';
      const profile = profileMap.get(String(assignedId));

      const score = dhAdvancedSearchScore(companyName, r.company_name);
      return {
        ...r,
        _search_score: score,
        _database_name: db?.name || r.database_name || 'Unknown Database',
        _assigned_user_name:
          profile?.full_name ||
          profile?.email ||
          db?.assigned_user_name ||
          'Unassigned'
      };
    })
    // Only surface meaningful fuzzy matches. Exact/contains/prefix matches are always
    // included; weaker typo matches need a reasonable score.
    .filter(r=>r._search_score >= (companyName.length <= 3 ? 55 : 48))
    .sort((a,b)=>
      b._search_score - a._search_score ||
      String(a.company_name || '').localeCompare(String(b.company_name || ''))
    );

    S.advancedSearch.results = scored;
    S.advancedSearch.resultCount = scored.length;
    S.advancedSearch.loading = false;
    renderDhStatsRow();

  } catch (e) {
    console.error('Data Hub Advanced Search failed:', e);
    S.advancedSearch.results = [];
    S.advancedSearch.resultCount = 0;
    S.advancedSearch.loading = false;
    renderDhStatsRow();
    toast('Could not complete the global company search: ' + (e.message || e), 'error');
  }
}

// ---------- Advanced Filters popover (spec #3) ----------
