const CAL_EVENT_META={
  import:{label:'Import',color:'blue',icon:CAL_ICO_IMPORT}, reminder:{label:'Reminder',color:'orange',icon:CAL_ICO_REMINDER}, followup:{label:'Follow-up',color:'violet',icon:CAL_ICO_FOLLOWUP},
  meeting:{label:'Meeting',color:'cyan',icon:CAL_ICO_MEETING}, task:{label:'Task',color:'blue',icon:CAL_ICO_TASK}, analytics:{label:'Analytics',color:'violet',icon:CAL_ICO_ANALYTICS}, system:{label:'System Activity',color:'cyan',icon:CAL_ICO_SYSTEM}
};
function calIsoDate(d){ const x=new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; }
function calEventLoad(){ try{return JSON.parse(localStorage.getItem(CAL_EVENT_KEY)||'[]')}catch(e){return []} }
function calEventSave(){ try{localStorage.setItem(CAL_EVENT_KEY,JSON.stringify(S.cal.events||[]))}catch(e){} }
function calSeedEvents(){
  const now=new Date(), y=now.getFullYear(), m=now.getMonth();
  const seed=[
    {id:'seed-1',title:'Logistics Contacts – 1,284',type:'import',date:calIsoDate(new Date(y,m,26)),start:'10:00',end:'11:00',description:'Contact import review for the logistics workspace.',related:'Swift Cargo contacts',priority:'High'},
    {id:'seed-2',title:'Client Follow-up',type:'followup',date:calIsoDate(new Date(y,m,26)),start:'13:30',end:'14:00',description:'Follow up on outstanding customer conversations.',related:'Priority accounts',priority:'High'},
    {id:'seed-3',title:'Weekly Analytics Review',type:'analytics',date:calIsoDate(new Date(y,m,29)),start:'11:00',end:'12:00',description:'Review weekly database and contact activity.',related:'Analytics',priority:'Normal'},
    {id:'seed-4',title:'Data Verification',type:'task',date:calIsoDate(new Date(y,m,27)),start:'15:00',end:'16:00',description:'Verify the latest imported contact records.',related:'Data Hub',priority:'Normal'},
    {id:'seed-5',title:'Company Update',type:'system',date:calIsoDate(new Date(y,m,30)),start:'09:30',end:'10:00',description:'Review recent company profile changes.',related:'Company records',priority:'Normal'},
    {id:'seed-6',title:'Database Import',type:'import',date:calIsoDate(new Date(y,m,28)),start:'14:00',end:'15:00',description:'Scheduled database import window.',related:'Data Hub',priority:'High'},
  ];
  const existing=calEventLoad(); const ids=new Set(existing.map(x=>x.id)); S.cal.events=[...existing,...seed.filter(x=>!ids.has(x.id))]; calEventSave();
}
function calWorkspaceEventsFor(day){ const date=calIsoDate(day); let ev=(S.cal.events||[]).filter(e=>e.date===date); const dbs=calEventsFor(day.toDateString()).map((d,i)=>({id:'db-'+d.id,title:d.name,type:'import',date, start:'',end:'',description:`Database imported with ${(d.customer_count||0).toLocaleString()} customers.`,related:d.assigned_to||'—',priority:'Normal',database:d})); return [...dbs,...ev]; }
function calFilteredEvents(){ const q=(S.cal.search||'').trim().toLowerCase(), f=S.cal.filter; const all=S.cal.events||[]; return all.filter(e=>(!f||e.type===f)&&(!q||[e.title,e.description,e.related,e.type].join(' ').toLowerCase().includes(q))); }
function calEventMeta(e){return CAL_EVENT_META[e.type]||CAL_EVENT_META.task}
function calTimeLabel(t){ if(!t)return ''; const [h,m]=t.split(':').map(Number); const ap=h>=12?'PM':'AM', hh=h%12||12; return `${hh}:${String(m).padStart(2,'0')} ${ap}`; }
function calEventPill(e){ const meta=calEventMeta(e); return `<div class="cal-event-pill ${meta.color}" data-event-id="${esc(e.id)}"><span class="cal-event-pill-dot"></span><span>${esc(meta.icon)} ${esc(e.title)}</span></div>`; }
function calUpcoming(){ const now=new Date(), today=calIsoDate(now); const all=calFilteredEvents().filter(e=>e.date>=today).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).slice(0,6); const el=$('#cal-upcoming-list'); if(!el)return; $('#cal-upcoming-count').textContent=all.length; el.innerHTML=all.length?all.map(e=>{const meta=calEventMeta(e);return `<div class="upcoming-item" data-event-id="${esc(e.id)}"><div class="upcoming-date">${new Date(e.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div><div class="upcoming-main"><span class="upcoming-dot" style="background:${meta.color==='orange'?'#F59E0B':meta.color==='violet'?'#7C3AED':meta.color==='cyan'?'#0EA5E9':'#3159E0'}"></span><div><div class="upcoming-title">${esc(e.title)}</div><div class="upcoming-time">${calTimeLabel(e.start)||'All day'} · ${esc(meta.label)}</div></div></div></div>`}).join(''):`<div class="upcoming-empty">No upcoming events match your filters.</div>`; $all('.upcoming-item',el).forEach(x=>x.addEventListener('click',()=>openCalEventDetail((S.cal.events||[]).find(e=>e.id===x.dataset.eventId)))); }
function wirePremiumEventClicks(){ $all('[data-event-id]', $('#cal-body')).forEach(x=>x.addEventListener('click',ev=>{ev.stopPropagation();const e=(S.cal.events||[]).find(z=>z.id===x.dataset.eventId);if(e)openCalEventDetail(e)})); $all('.upcoming-item').forEach(x=>x.addEventListener('click',()=>{const e=(S.cal.events||[]).find(z=>z.id===x.dataset.eventId);if(e)openCalEventDetail(e)})); }
function renderUpcoming(){calUpcoming()}
function calOccurrenceEvents(day){
  const target=calIsoDate(day), base=S.cal.events||[], out=[];
  for(const e of base){
    if(!e.date) continue;
    if(!e.repeat||e.repeat==='none'){if(e.date===target)out.push(e);continue}
    const start=new Date(e.date+'T12:00:00'), d=new Date(target+'T12:00:00');
    if(d<start)continue;
    if(e.repeatUntil && target>e.repeatUntil)continue;
    const diff=Math.round((d-start)/86400000); let ok=false;
    if(e.repeat==='daily') ok=diff%(e.repeatInterval||1)===0;
    else if(e.repeat==='weekly') ok=diff%((e.repeatInterval||1)*7)===0;
    else if(e.repeat==='monthly') ok=start.getDate()===d.getDate() && ((d.getFullYear()-start.getFullYear())*12+d.getMonth()-start.getMonth())%(e.repeatInterval||1)===0;
    else if(e.repeat==='custom'){
      if(e.repeatUnit==='week') ok=diff%((e.repeatInterval||1)*7)===0;
      else if(e.repeatUnit==='month') ok=start.getDate()===d.getDate() && ((d.getFullYear()-start.getFullYear())*12+d.getMonth()-start.getMonth())%(e.repeatInterval||1)===0;
      else ok=diff%(e.repeatInterval||1)===0;
    }
    if(ok)out.push({...e,id:e.id+'@'+target,_occurrence:true,date:target,sourceId:e.id});
  }
  return out;
}
function calDayEvents(day){return [...calWorkspaceEventsFor(day).filter(e=>e.database),...calOccurrenceEvents(day)];}
function calMatches(e){const q=(S.cal.search||'').trim().toLowerCase(),f=S.cal.filter;return (!f||e.type===f)&&(!q||[e.title,e.description,e.related,e.type,e.date].join(' ').toLowerCase().includes(q));}
function bindCalendarCells(){
  $all('.cal-cell', $('#cal-body')).forEach(cell=>{
    cell.addEventListener('click',()=>{const day=new Date(+cell.dataset.daynum);openDayDetail(day,calEventsFor(day.toDateString()));});
    cell.addEventListener('dragover',ev=>{ev.preventDefault();cell.classList.add('cal-drop-target')});
    cell.addEventListener('dragleave',()=>cell.classList.remove('cal-drop-target'));
    cell.addEventListener('drop',ev=>{ev.preventDefault();cell.classList.remove('cal-drop-target');const id=ev.dataTransfer.getData('text/calendar-event');const base=S.cal.events.find(x=>x.id===id);if(base){base.date=calIsoDate(new Date(+cell.dataset.daynum));calEventSave();renderCalendar();toast('Event moved','success')}});
  });
  $all('.cal-event-pill[draggable="true"]').forEach(el=>el.addEventListener('dragstart',ev=>{ev.stopPropagation();const id=el.dataset.eventId.split('@')[0];ev.dataTransfer.setData('text/calendar-event',id);el.classList.add('cal-dragging')}));
  $all('.cal-event-pill[draggable="true"]').forEach(el=>el.addEventListener('dragend',()=>el.classList.remove('cal-dragging')));
}
function renderPremiumCalendarBody(){
  const cursor=S.cal.cursor;
  if(S.cal.view==='agenda'){
    const all=[];for(let i=-7;i<45;i++){const d=new Date(cursor);d.setDate(d.getDate()+i);calDayEvents(d).filter(calMatches).forEach(e=>all.push(e))}
    const groups={};all.sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).forEach(e=>(groups[e.date]??=[]).push(e));const dates=Object.keys(groups);
    $('#cal-body').innerHTML=dates.length?`<div class="agenda-premium">${dates.map(date=>`<div class="agenda-day-head">${new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</div>${groups[date].map(e=>{const m=calEventMeta(e);return `<div class="agenda-event-row" data-event-id="${esc(e.id)}"><div class="agenda-event-time">${calTimeLabel(e.start)||'—'}</div><div class="agenda-event-icon">${esc(m.icon)}</div><div><div class="agenda-event-title">${esc(e.title)}</div><div class="agenda-event-sub">${esc(m.label)} · ${esc(e.related||'Workspace')}${e.repeat&&e.repeat!=='none'?' · Repeats':''}</div></div></div>`}).join('')}`).join('')}</div>`:`<div class="agenda-premium"><div class="upcoming-empty">No events found.</div></div>`;wirePremiumEventClicks();return;
  }
  if(S.cal.view==='day'){
    const d=new Date(cursor), ev=calDayEvents(d).filter(calMatches).sort((a,b)=>(a.start||'').localeCompare(b.start||''));
    $('#cal-body').innerHTML=`<div class="calendar-day-focus"><div class="agenda-day-head">${d.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</div>${ev.length?ev.map(e=>{const m=calEventMeta(e);return `<div class="agenda-event-row" data-event-id="${esc(e.id)}"><div class="agenda-event-time">${calTimeLabel(e.start)||'All day'}${e.end?' – '+calTimeLabel(e.end):''}</div><div class="agenda-event-icon">${esc(m.icon)}</div><div><div class="agenda-event-title">${esc(e.title)}</div><div class="agenda-event-sub">${esc(m.label)} · ${esc(e.related||'Workspace')}</div></div></div>`}).join(''):`<div class="upcoming-empty" style="padding:40px">No events on this day.</div>`}</div>`;wirePremiumEventClicks();return;
  }
  if(S.cal.view==='week'){
    const start=new Date(cursor);start.setDate(cursor.getDate()-cursor.getDay());const hours=Array.from({length:15},(_,i)=>i+7);let html='<div class="cal-week-grid"><div class="week-time"></div>'+Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `<div class="week-head ${d.toDateString()===new Date().toDateString()?'today':''}">${d.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}<strong>${d.getDate()}</strong></div>`}).join('');
    hours.forEach(h=>{html+=`<div class="week-time-label">${h%12||12}:00 ${h>=12?'PM':'AM'}</div>`;for(let i=0;i<7;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ev=calDayEvents(d).filter(e=>calMatches(e)&&e.start&&parseInt(e.start.split(':')[0])===h);html+=`<div class="week-slot" data-daynum="${d.getTime()}" data-hour="${h}">${ev.map(e=>{const m=calEventMeta(e);return `<div class="week-event ${m.color}" draggable="${!e._occurrence&&!e.database}" data-event-id="${esc(e.id)}">${esc(e.title)}<br><span style="font-weight:500;opacity:.82">${calTimeLabel(e.start)}</span></div>`}).join('')}</div>`}});html+='</div>';$('#cal-body').innerHTML=html;wirePremiumEventClicks();$all('.week-slot').forEach(slot=>{slot.addEventListener('dragover',e=>{e.preventDefault();slot.classList.add('cal-drop-target')});slot.addEventListener('dragleave',()=>slot.classList.remove('cal-drop-target'));slot.addEventListener('drop',e=>{e.preventDefault();slot.classList.remove('cal-drop-target');const id=e.dataTransfer.getData('text/calendar-event'),base=S.cal.events.find(x=>x.id===id);if(base){base.date=calIsoDate(new Date(+slot.dataset.daynum));base.start=String(slot.dataset.hour).padStart(2,'0')+':00';const end=(+slot.dataset.hour+1);base.end=String(end).padStart(2,'0')+':00';calEventSave();renderCalendar();toast('Event moved','success')}})});return;
  }
  const first=new Date(cursor.getFullYear(),cursor.getMonth(),1),startDay=new Date(first);startDay.setDate(first.getDate()-first.getDay());let html='<div class="cal-grid">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-dow">${d}</div>`).join('');
  for(let i=0;i<42;i++){const day=new Date(startDay);day.setDate(startDay.getDate()+i);const other=day.getMonth()!==cursor.getMonth(),today=day.toDateString()===new Date().toDateString(),ev=calDayEvents(day).filter(calMatches),dbs=calEventsFor(day.toDateString());html+=`<div class="cal-cell ${other?'other':''} ${today?'today':''} ${ev.length?'has-events':''}" data-daynum="${day.getTime()}"><div class="cal-daynum">${day.getDate()}</div>${ev.slice(0,3).map(e=>calEventPill(e).replace('class="cal-event-pill','draggable="'+(!e._occurrence&&!e.database)+'" class="cal-event-pill')).join('')}${ev.length>3?`<div class="cal-more">+${ev.length-3} more</div>`:''}${dbs.length&&!ev.some(e=>e.database)?`<div class="cal-day-badge"><span class="dot"></span>${ICON_FOLDER_SM}<span>${calBadgeLabel(dbs.length)}</span></div>`:''}</div>`}
  html+='</div>';$('#cal-body').innerHTML=html;bindCalendarCells();wirePremiumEventClicks();
}
function renderCalendar(){const cursor=S.cal.cursor;$('#cal-month-label').textContent=cursor.toLocaleDateString(undefined,{month:'long',year:'numeric'});const sel=$('#cal-month-select');if(sel){sel.innerHTML=Array.from({length:12},(_,i)=>`<option value="${i}">${new Date(cursor.getFullYear(),i,1).toLocaleDateString(undefined,{month:'long'})}</option>`).join('');sel.value=cursor.getMonth();}renderPremiumCalendarBody();renderUpcoming();}
function openCalEventDetail(e){if(!e)return;const meta=calEventMeta(e);$('#evt-detail-type').textContent=meta.label.toUpperCase();$('#evt-detail-title').textContent=e.title;$('#cal-event-detail-body').innerHTML=`<div class="cal-detail-hero"><div style="font-size:14px;font-weight:700;color:#2448B9">${esc(meta.icon)} ${esc(meta.label)}</div><div style="font-size:13px;color:#667085;margin-top:6px">${esc(e.description||'No description added.')}</div></div><div class="cal-detail-grid"><div class="cal-detail-item"><div class="k">Date & Time</div><div class="v">${new Date(e.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'})} · ${calTimeLabel(e.start)||'All day'}${e.end?' – '+calTimeLabel(e.end):''}</div></div><div class="cal-detail-item"><div class="k">Priority</div><div class="v">${esc(e.priority||'Normal')}</div></div><div class="cal-detail-item"><div class="k">Related</div><div class="v">${esc(e.related||'Workspace')}</div></div><div class="cal-detail-item"><div class="k">Reminder</div><div class="v">${e.reminder&&e.reminder!=='none'?esc(e.reminder)+' minutes before':'No reminder'}</div></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px"><button class="btn" id="cal-event-delete">Delete</button><button class="btn btn-primary" id="cal-event-edit">Edit</button></div>`;$('#cal-event-detail-overlay').classList.remove('hidden');$('#cal-event-delete').onclick=()=>{S.cal.events=S.cal.events.filter(x=>x.id!==e.id);calEventSave();$('#cal-event-detail-overlay').classList.add('hidden');renderCalendar();toast('Event deleted','success')};$('#cal-event-edit').onclick=()=>{openCalEventModal(e);$('#cal-event-detail-overlay').classList.add('hidden')}}
function openCalEventModal(edit){const d=edit||{};$('#cal-event-modal-title').textContent=edit?'Edit Event':'Create Event';$('#evt-title').value=d.title||'';$('#evt-type').value=d.type||'task';$('#evt-date').value=d.date||calIsoDate(new Date());$('#evt-start').value=d.start||'10:00';$('#evt-end').value=d.end||'11:00';$('#evt-priority').value=d.priority||'Normal';$('#evt-description').value=d.description||'';$('#evt-related').value=d.related||'';$('#evt-reminder').value=d.reminder||'none';if($('#evt-color'))$('#evt-color').value=d.color||'blue';if($('#evt-repeat'))$('#evt-repeat').value=d.repeat||'none';if($('#evt-repeat-interval'))$('#evt-repeat-interval').value=d.repeatInterval||1;if($('#evt-repeat-unit'))$('#evt-repeat-unit').value=d.repeatUnit||'day';if($('#evt-repeat-until'))$('#evt-repeat-until').value=d.repeatUntil||'';$('#evt-repeat-custom-wrap')?.classList.toggle('hidden',(d.repeat||'none')!=='custom');$('#evt-repeat-until-wrap')?.classList.toggle('hidden',(d.repeat||'none')==='none');$('#cal-event-form').dataset.editId=edit?.id||'';$('#cal-event-overlay').classList.remove('hidden')}
function saveCalEvent(e){
  const form=$('#cal-event-form'), editId=form.dataset.editId;
  const obj={
    id:editId||'evt-'+Date.now(),title:$('#evt-title').value.trim(),type:$('#evt-type').value,
    date:$('#evt-date').value,start:$('#evt-start').value,end:$('#evt-end').value,priority:$('#evt-priority').value,
    description:$('#evt-description').value.trim(),related:$('#evt-related').value.trim(),reminder:$('#evt-reminder').value,
    color:$('#evt-color')?.value||'blue',repeat:$('#evt-repeat')?.value||'none',
    repeatInterval:parseInt($('#evt-repeat-interval')?.value||1,10)||1,repeatUnit:$('#evt-repeat-unit')?.value||'day',
    repeatUntil:$('#evt-repeat-until')?.value||''
  };
  if(!obj.title||!obj.date)return toast('Add an event title and date','error');
  if(obj.start&&obj.end&&obj.end<=obj.start)return toast('End time must be after start time','error');
  if(editId){const i=S.cal.events.findIndex(x=>x.id===editId);if(i>=0)S.cal.events[i]=obj}
  else S.cal.events.push(obj);
  calEventSave();$('#cal-event-overlay').classList.add('hidden');form.reset();
  $('#evt-repeat-custom-wrap')?.classList.add('hidden');$('#evt-repeat-until-wrap')?.classList.add('hidden');
  renderCalendar();toast(editId?'Event updated':'Event created','success')
}
function shiftCal(dir){
  const c = S.cal.cursor;
  if (S.cal.view==='month') c.setMonth(c.getMonth()+dir);
  else if (S.cal.view==='week') c.setDate(c.getDate()+7*dir);
  else if (S.cal.view==='day') c.setDate(c.getDate()+dir);
  else c.setDate(c.getDate()+7*dir);
  renderCalendar();
}

/* Global command palette — Ctrl/Cmd + K */
const COMMAND_ITEMS=[
  {label:'Contacts',sub:'Open Data Hub',page:'alldata',icon:'users'},
  {label:'Companies',sub:'Open Data Hub',page:'alldata',icon:'building'},
  {label:'Events',sub:'Open Calendar',page:'calendar',icon:'calendar'},
  {label:'Imports',sub:'Open Data Hub',page:'alldata',icon:'download'},
  {label:'Analytics',sub:'Open Analytics',page:'analytics',icon:'chart'},
  {label:'Settings',sub:'Workspace settings',page:'settings',icon:'settings'}
];
function commandIcon(){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="8"/><path d="M12 8v4l2.5 2.5"/></svg>`}
function renderCommandResults(q=''){
 const root=$('#command-results'); if(!root)return; const x=q.toLowerCase().trim();
 const items=COMMAND_ITEMS.filter(i=> (i.page!=='analytics' || S.isAdmin) && (!x||`${i.label} ${i.sub}`.toLowerCase().includes(x)));
 root.innerHTML=items.map(i=>`<div class="command-item" data-command-page="${i.page}">${commandIcon()}<strong>${i.label}</strong><span>${i.sub}</span></div>`).join('')||`<div class="upcoming-empty">No workspace results found.</div>`;
 $all('[data-command-page]',root).forEach(el=>el.addEventListener('click',()=>{const page=el.dataset.commandPage;$('#command-overlay').classList.add('hidden');const nav=$(`[data-page="${page}"]`);if(nav)nav.click()}));
}
function openCommandPalette(){ $('#command-overlay').classList.remove('hidden'); $('#command-search').value=''; renderCommandResults(); setTimeout(()=>$('#command-search').focus(),30); }
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette()} if(e.key==='Escape'){$('#command-overlay')?.classList.add('hidden');$('#cal-event-overlay')?.classList.add('hidden');$('#cal-event-detail-overlay')?.classList.add('hidden')}});
$('#command-overlay')?.addEventListener('click',e=>{if(e.target.id==='command-overlay')e.currentTarget.classList.add('hidden')});
$('#command-search')?.addEventListener('input',e=>renderCommandResults(e.target.value));
$('#top-command-hint')?.addEventListener('click',openCommandPalette);

/* Premium calendar controls */
calSeedEvents();
$('#cal-new-event')?.addEventListener('click',()=>openCalEventModal());
$('#cal-event-close')?.addEventListener('click',()=>$('#cal-event-overlay').classList.add('hidden'));
$('#cal-event-cancel')?.addEventListener('click',()=>$('#cal-event-overlay').classList.add('hidden'));
$('#cal-event-overlay')?.addEventListener('click',e=>{if(e.target.id==='cal-event-overlay')e.currentTarget.classList.add('hidden')});
$('#cal-event-form')?.addEventListener('submit',e=>{e.preventDefault();saveCalEvent(e)});
$('#evt-repeat')?.addEventListener('change',e=>{const custom=e.target.value==='custom';$('#evt-repeat-custom-wrap')?.classList.toggle('hidden',!custom);$('#evt-repeat-until-wrap')?.classList.toggle('hidden',e.target.value==='none')});
$('#cal-event-detail-close')?.addEventListener('click',()=>$('#cal-event-detail-overlay').classList.add('hidden'));
$('#cal-event-detail-overlay')?.addEventListener('click',e=>{if(e.target.id==='cal-event-detail-overlay')e.currentTarget.classList.add('hidden')});
$('#cal-search')?.addEventListener('input',e=>{S.cal.search=e.target.value;renderCalendar()});
$('#cal-filter-type')?.addEventListener('change',e=>{S.cal.filter=e.target.value;renderCalendar()});
$('#cal-month-select')?.addEventListener('change',e=>{S.cal.cursor.setMonth(parseInt(e.target.value));renderCalendar()});

function calEventsFor(dateStr){
  const dbs = myAssignedDatabases();
  return dbs.filter(d=> new Date(d.upload_date).toDateString() === dateStr);
}

const DAY_ICON_DB = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v6c0 1.66 3.58 3 8 3s8-1.34 8-3V5"/><path d="M4 11v6c0 1.66 3.58 3 8 3s8-1.34 8-3v-6"/></svg>`;
const ICON_FOLDER_SM = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/></svg>`;
const ICON_DB_CIRCLE = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="12" cy="6" rx="7.5" ry="2.8"/><path d="M4.5 6v6c0 1.55 3.36 2.8 7.5 2.8s7.5-1.25 7.5-2.8V6"/><path d="M4.5 12v6c0 1.55 3.36 2.8 7.5 2.8s7.5-1.25 7.5-2.8v-6"/></svg>`;
const ICON_FOLDER_OPEN = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2H9.5a2 2 0 0 0-1.9 1.4L5 19H3V7Z"/><path d="M5 19l2.4-8.1A2 2 0 0 1 9.3 9.5H21l-2.3 7.9A2 2 0 0 1 16.8 19H5Z"/></svg>`;
const ICON_USER_SM = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-6 8-6s8 2 8 6"/></svg>`;
const ICON_USERS_SM = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>`;
const ICON_CLOCK_SM = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>`;
const ICON_CAL_SM = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>`;

/* Compact single-line summary badge shown inside a calendar cell —
   never the raw database name(s), just a scannable count. */
function calBadgeLabel(n){ return n===1 ? '1 Database' : `${n} Databases`; }
function calDayBadgeHtml(events){
  if (!events.length) return '';
  return `<span class="cal-day-badge"><span class="dot"></span>${ICON_FOLDER_SM}<span>${calBadgeLabel(events.length)}</span></span>`;
}
function calTooltipText(day, events){
  const dateLabel = day.toLocaleDateString(undefined,{day:'numeric', month:'long'});
  const summary = events.length ? `${events.length} database${events.length===1?'':'s'} imported.` : 'No databases imported.';
  return `${dateLabel}\n${summary}\nClick to view details.`;
}

function openDayDetail(day, events){
  $('#day-modal-title').textContent = day.toLocaleDateString(undefined, {weekday:'long', month:'long', day:'numeric', year:'numeric'});
  if (!events.length){
    $('#day-modal-body').innerHTML = `
      <div class="day-empty-state">
        <div class="ic">${ICON_FOLDER_OPEN}</div>
        <div class="t">No database imported on this date.</div>
        <div class="d">Nothing was added to the workspace on this day.</div>
      </div>`;
  } else {
    $('#day-modal-body').innerHTML = `<div class="day-detail-count">${events.length} database${events.length===1?'':'s'} imported</div>` +
      events.map(e=>`
      <div class="day-stat-row">
        <div class="day-stat-top">
          <div class="day-stat-ic">${DAY_ICON_DB}</div>
          <div class="day-stat-body">
            <div class="n" title="${esc(e.name)}">${esc(e.name)}</div>
          </div>
          <span class="pill pill-green day-stat-status">${esc(e.status||'active')}</span>
        </div>
        <div class="day-stat-grid">
          <div class="day-stat-field"><div class="k">${ICON_USER_SM} Assigned User</div><div class="v">${esc(e.assigned_to||'—')}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_USERS_SM} Customer Count</div><div class="v">${(e.customer_count ?? 0).toLocaleString()}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_CLOCK_SM} Import Time</div><div class="v">${fmtTime(e.upload_date)}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_CAL_SM} Imported Date</div><div class="v">${fmtDate(e.upload_date)}</div></div>
        </div>
      </div>`).join('');
  }
  $('#day-modal-body').innerHTML += renderDayUpdatesSection(day);
  $('#day-modal-body').innerHTML += renderDayRemindersSection(day);
  wireDayReminderCardActions(day);
  $('#day-modal-overlay').classList.remove('hidden');
}

/* Additive: Updates records logged for the same calendar day, rendered
   underneath the existing "databases imported" list inside the day modal. */
function renderDayUpdatesSection(day){
  const upds = updatesEventsFor(day.toDateString());
  let html = `<div class="day-detail-count" style="margin-top:22px; padding-top:18px; border-top:1px solid #F0F0F6;">
    <strong>Updates</strong> — ${upds.length} record${upds.length===1?'':'s'} on this date</div>`;
  if (!upds.length){
    html += `<div class="day-empty-state" style="padding:24px 20px 8px;">
      <div class="t">No Updates Available</div>
    </div>`;
  } else {
    html += upds.map(u=>`
      <div class="day-stat-row">
        <div class="day-stat-top">
          <div class="day-stat-ic">${DAY_ICON_DB}</div>
          <div class="day-stat-body">
            <div class="n" title="${esc(u.database_name)}">${esc(u.database_name)}</div>
          </div>
        </div>
        <div class="day-stat-grid">
          <div class="day-stat-field"><div class="k">${ICON_CAL_SM} Assigned Date</div><div class="v">${fmtDateTime(u.assigned_date)}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_USERS_SM} Total Customers</div><div class="v">${(u.total_customers ?? 0).toLocaleString()}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_USER_SM} Contacted Today</div><div class="v">${(u.customers_contacted ?? 0).toLocaleString()}</div></div>
          <div class="day-stat-field"><div class="k">${ICON_CLOCK_SM} Appointments</div><div class="v">${(u.appointments ?? 0).toLocaleString()}</div></div>
        </div>
        ${u.remarks ? `<div class="hint" style="margin-top:10px; white-space:pre-wrap;">${esc(u.remarks)}</div>` : ''}
      </div>`).join('');
  }
  return html;
}
$('#day-modal-close').addEventListener('click', ()=> { $('#day-modal-overlay').classList.add('hidden'); $all('#page-calendar .cal-cell').forEach(c=>c.classList.remove('is-selected')); });
$('#day-modal-overlay').addEventListener('click', (e)=>{ if (e.target.id==='day-modal-overlay'){ $('#day-modal-overlay').classList.add('hidden'); $all('#page-calendar .cal-cell').forEach(c=>c.classList.remove('is-selected')); } });

function renderCalendarLegacy(){
  const dbs = myAssignedDatabases();
  const cursor = S.cal.cursor;
  $('#cal-month-label').textContent = cursor.toLocaleDateString(undefined, {month:'long', year:'numeric'});

  if (S.cal.view==='agenda'){
    const upcoming = [...dbs].sort((a,b)=> new Date(b.upload_date)-new Date(a.upload_date));
    $('#cal-body').innerHTML = upcoming.length ? upcoming.map((d,i)=>{
      const dt = new Date(d.upload_date);
      return `<div class="agenda-row" data-agenda-idx="${i}"><div class="agenda-date"><div class="d">${dt.getDate()}</div><div class="m">${dt.toLocaleDateString(undefined,{month:'short'})}</div></div>
        <div class="list-body"><div class="list-title">${esc(d.name)}</div><div class="list-sub">Assigned to ${esc(d.assigned_to||'—')} · Uploaded by ${esc(d.imported_by_name||'—')} · ${d.customer_count} customers</div></div>
        <span class="pill pill-green">${esc(d.status)}</span></div>`;
    }).join('') : emptyRow('No events yet');
    $all('[data-agenda-idx]', $('#cal-body')).forEach(el=> el.addEventListener('click', ()=>{
      const d = upcoming[el.dataset.agendaIdx];
      openDayDetail(new Date(d.upload_date), calEventsFor(new Date(d.upload_date).toDateString()));
    }));
    return;
  }

  if (S.cal.view==='week'){
    const start = new Date(cursor); start.setDate(cursor.getDate()-cursor.getDay());
    let html = `<div class="cal-grid">` + ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-dow">${d}</div>`).join('');
    for (let i=0;i<7;i++){
      const day = new Date(start); day.setDate(start.getDate()+i);
      const events = calEventsFor(day.toDateString());
      const rems = reminderEventsFor(day.toDateString());
      const isToday = day.toDateString()===new Date().toDateString();
      const weekend = i===0||i===6;
      html += `<div class="cal-cell ${isToday?'today':''} ${weekend?'weekend':''} ${events.length?'has-events':''} ${rems.length?'has-reminder':''}" style="min-height:180px;" data-daynum="${day.getTime()}" data-tip="${esc(calTooltipText(day, events))}"><div class="cal-daynum">${day.getDate()}</div>${calDayBadgeHtml(events)}${calReminderBadgeHtml(rems)}</div>`;
    }
    html += `</div>`;
    $('#cal-body').innerHTML = html;
    wireCalCells();
    wireReminderTooltips();
    return;
  }

  // month view
  const firstOfMonth = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
  const startDay = new Date(firstOfMonth); startDay.setDate(firstOfMonth.getDate()-firstOfMonth.getDay());
  let html = `<div class="cal-grid">` + ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-dow">${d}</div>`).join('');
  for (let i=0;i<42;i++){
    const day = new Date(startDay); day.setDate(startDay.getDate()+i);
    const other = day.getMonth()!==cursor.getMonth();
    const isToday = day.toDateString()===new Date().toDateString();
    const events = calEventsFor(day.toDateString());
    const rems = reminderEventsFor(day.toDateString());
    const weekend = i%7===0 || i%7===6;
    html += `<div class="cal-cell ${other?'other':''} ${isToday?'today':''} ${weekend?'weekend':''} ${events.length?'has-events':''} ${rems.length?'has-reminder':''}" data-daynum="${day.getTime()}" data-tip="${esc(calTooltipText(day, events))}">
      <div class="cal-daynum">${day.getDate()}</div>
      ${calDayBadgeHtml(events)}
      ${calReminderBadgeHtml(rems)}
    </div>`;
  }
  html += `</div>`;
  $('#cal-body').innerHTML = html;
  wireCalCells();
  wireReminderTooltips();
}

function wireCalCells(){
  $all('.cal-cell', $('#cal-body')).forEach(cell=> cell.addEventListener('click', ()=>{
    const day = new Date(parseInt(cell.dataset.daynum));
    openDayDetail(day, calEventsFor(day.toDateString()));
  }));
}

/* ==========================================================================
   UPDATES  (daily progress logs per database — Supabase-backed, additive)
   ========================================================================== */
function updatesEventsFor(dateStr){
  const rows = S.isAdmin ? S.updates : S.updates.filter(u=>u.owner_id===S.session.user.id);
  return rows.filter(u=> u.assigned_date && new Date(u.assigned_date).toDateString() === dateStr);
}

function myUpdates(){
  const rows = S.isAdmin ? S.updates : S.updates.filter(u=>u.owner_id===S.session.user.id);
  const q = (S.updatesSearch||'').trim().toLowerCase();
  const filtered = q ? rows.filter(u=> [u.database_name, u.remarks, updUserDisplay(u)].some(v=> String(v||'').toLowerCase().includes(q))) : rows;
  return [...filtered].sort((a,b)=> new Date(b.assigned_date) - new Date(a.assigned_date));
}

/* ---------- Updates page premium helpers (additive) ---------- */
const S_updFilters = { from:'', to:'', user:'', quarter:'', status:'', db:'' };
function updContactRate(u){ const t=u.total_customers||0, c=u.customers_contacted||0; return t>0 ? Math.min(100, Math.round((c/t)*100)) : 0; }
function updProgressStatus(rate){
  if (rate>=80) return { key:'excellent', label:'Excellent', pill:'pill-green' };
  if (rate>=50) return { key:'progress', label:'In Progress', pill:'pill-blue' };
  if (rate>=25) return { key:'attention', label:'Needs Attention', pill:'pill-orange' };
  return { key:'low', label:'Low Progress', pill:'pill-red' };
}
function updQuarterOf(dateStr){ if (!dateStr) return ''; const m = new Date(dateStr).getMonth(); return 'Q'+(Math.floor(m/3)+1); }
function updUserDisplay(u){
  const p = u._profile || S.profiles.find(pr=>pr.id===u.owner_id) || {};
  const name = (p.full_name && String(p.full_name).trim()) || null;
  const uname = (p.username && String(p.username).trim()) || null;
  if (name && uname) return `${name} (@${uname})`;
  if (name) return name;
  if (uname) return `@${uname}`;
  return 'Unknown User';
}
function filteredUpdateRows(){
  let rows = myUpdates();
  const f = S_updFilters;
  if (f.from) rows = rows.filter(u=> new Date(u.assigned_date) >= new Date(f.from));
  if (f.to) rows = rows.filter(u=> new Date(u.assigned_date) <= new Date(f.to+'T23:59:59'));
  if (f.user) rows = rows.filter(u=> (S.records.find(r=>r.database_name===u.database_name)?.assigned_to || '') === f.user || u.assigned_to===f.user);
  if (f.quarter) rows = rows.filter(u=> updQuarterOf(u.assigned_date)===f.quarter);
  if (f.status) rows = rows.filter(u=> updProgressStatus(updContactRate(u)).key===f.status);
  if (f.db) rows = rows.filter(u=> u.database_name===f.db);
  return rows;
}
function populateUpdateFilterOptions(){
  const rows = myUpdates();
  const dbSel = $('#upd-filter-db'), userSel = $('#upd-filter-user');
  if (dbSel){
    const dbs = [...new Set(rows.map(u=>u.database_name).filter(Boolean))].sort();
    dbSel.innerHTML = `<option value="">All Databases</option>` + dbs.map(d=>`<option value="${esc(d)}" ${S_updFilters.db===d?'selected':''}>${esc(d)}</option>`).join('');
  }
  if (userSel){
    const users = [...new Set(S.databases.map(d=>d.assigned_user_name || d.assigned_to).filter(Boolean))].sort();
    userSel.innerHTML = `<option value="">All assigned users</option>` + users.map(u=>`<option value="${esc(u)}" ${S_updFilters.user===u?'selected':''}>${esc(u)}</option>`).join('');
  }
}
function renderUpdatesKPISummary(){
  const grid = $('#upd-kpi-summary'); if (!grid) return;
  const myDbs = myAssignedDatabases();
  const activeDatabases = myDbs.filter(d=> (d.status||'active')==='active').length;
  const todayStr = new Date().toDateString();
  const rowsToday = myUpdates().filter(u=> new Date(u.assigned_date).toDateString()===todayStr);
  const assignedToday = rowsToday.reduce((s,u)=>s+(u.total_customers||0),0);
  const contactedToday = rowsToday.reduce((s,u)=>s+(u.customers_contacted||0),0);
  const appointmentsBooked = myUpdates().reduce((s,u)=>s+(u.appointments||0),0);
  const kpis = [
    { label:'Active Databases', value:activeDatabases, icon:iconDb, color:'#4F6BFF' },
    { label:'Customers Assigned Today', value:assignedToday.toLocaleString(), icon:iconUsers, color:'#4EA8FF' },
    { label:'Customers Contacted Today', value:contactedToday.toLocaleString(), icon:iconAssign, color:'#9B6BFF' },
    { label:'Appointments Booked', value:appointmentsBooked.toLocaleString(), icon:iconImport, color:'#FFB648' },
  ];
  grid.innerHTML = kpis.map(k=>{
    const tint = `background:linear-gradient(160deg, ${k.color}0D 0%, #FFFFFF 55%);`;
    const iconStyle = `background:linear-gradient(135deg, ${k.color} 0%, ${k.color}CC 100%); color:#fff;`;
    return `<div class="kpi-card no-logo ${k.label==='Appointments Booked'?'upd-kpi-clickable':''}" ${k.label==='Appointments Booked'?'data-upd-kpi="appointments"':''} style="${tint}" title="${k.label==='Appointments Booked'?'View appointment records':''}">
      <div class="kpi-top"><div class="kpi-icon" style="${iconStyle}">${k.icon}</div></div>
      <div><div class="kpi-label">${k.label}</div><div class="kpi-value" style="font-size:${String(k.value).length>8?'20px':'26px'};">${esc(String(k.value))}</div></div>
    </div>`;
  }).join('');

  // Direct binding: the KPI is freshly rendered above, so bind the actual DOM
  // element instead of relying on delegated/inline click handling.
  const appointmentsKpi = grid.querySelector('[data-upd-kpi="appointments"]');
  if (appointmentsKpi) {
    appointmentsKpi.addEventListener('click', () => window.updOpenAppointmentsBooked());
    appointmentsKpi.setAttribute('role','button');
    appointmentsKpi.setAttribute('tabindex','0');
    appointmentsKpi.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); window.updOpenAppointmentsBooked(); }
    });
  }
}

function updOpenAppointmentsBooked(){
  let viewer=$('#upd-appointments-booked-viewer');
  if(!viewer){
    viewer=document.createElement('div');
    viewer.id='upd-appointments-booked-viewer';
    viewer.className='modal-overlay upd-appointments-booked-viewer hidden';
    viewer.innerHTML=`<section class="upd-abv-workspace" role="dialog" aria-modal="true" aria-labelledby="upd-abv-title">
      <header class="upd-abv-header">
        <div class="upd-abv-title-wrap">
          <div class="upd-abv-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3.5" y="5" width="17" height="15" rx="3"/><path d="M7.5 3.5v3M16.5 3.5v3M3.5 9.5h17"/><path d="M8 13h.01M12 13h.01M16 13h.01M8 17h.01M12 17h.01M16 17h.01"/></svg></div>
          <div><h2 id="upd-abv-title">Appointments Booked</h2><p>Manage and review all booked appointments</p></div>
        </div>
        <div class="upd-abv-head-actions"><span class="upd-abv-status" id="upd-abv-status">Loading…</span><button type="button" class="upd-abv-close" id="upd-abv-close" aria-label="Close">×</button></div>
      </header>
      <div class="upd-abv-body" id="upd-abv-body"><div class="upd-abv-loading"><div class="upd-abv-spinner"></div><div><strong>Loading appointments</strong><span>Reading permanent daily entry history…</span></div></div></div>
    </section>`;
    document.body.appendChild(viewer);
    const close=()=>{viewer.classList.add('hidden');document.body.classList.remove('upd-abv-open');};
    viewer.querySelector('#upd-abv-close')?.addEventListener('click',close);
    viewer.addEventListener('click',e=>{if(e.target===viewer)close();});
    if(!window.__updAbvEscBound){
      window.__updAbvEscBound=true;
      document.addEventListener('keydown',e=>{
        const v=$('#upd-appointments-booked-viewer');
        if(e.key==='Escape'&&v&&!v.classList.contains('hidden')){v.classList.add('hidden');document.body.classList.remove('upd-abv-open');}
      });
    }
  }

  const body=viewer.querySelector('#upd-abv-body'),status=viewer.querySelector('#upd-abv-status');
  if(!body||!status){ console.error('[APPOINTMENTS VIEWER] Required viewer DOM is missing.'); return; }
  viewer.classList.remove('hidden');document.body.classList.add('upd-abv-open');status.textContent='Loading…';
  body.innerHTML='<div class="upd-abv-loading"><div class="upd-abv-spinner"></div><div><strong>Loading appointments</strong><span>Reading permanent daily entry history…</span></div></div>';

  requestAnimationFrame(async()=>{
    try{
      if(!S.session?.user?.id) throw new Error('You are not signed in.');
      const scopedUpdates=S.isAdmin?(S.updates||[]):(S.updates||[]).filter(u=>String(u.owner_id)===String(S.session.user.id));
      const history=await updFetchAllHistory(scopedUpdates.map(u=>u.id));
      const byId=new Map(scopedUpdates.map(u=>[String(u.id),u]));
      const records=[];
      history.forEach(row=>{
        const v=updParseDailyRow(row),u=byId.get(String(row.update_id));
        (v.appointmentDetails||[]).forEach(d=>{
          const ownerId=row?.owner_id||u?.owner_id||null, p=updUserProfile(ownerId);
          const assignedUserName=(p?.full_name&&String(p.full_name).trim())||(p?.username&&String(p.username).trim())||(ownerId?'Unknown User':'—');
          records.push({detail:d,row,u,ownerId,assignedUserName});
        });
      });
      const seen=new Set(),allRecords=[];
      records.forEach(x=>{const fp=updAppointmentFingerprint(x.detail);if(!fp||seen.has(fp))return;seen.add(fp);allRecords.push(x);});

      const dateValue=x=>{
        const raw=x?.detail?.appointmentDate??x?.detail?.appointment_date;
        if(!raw)return null; const d=new Date(raw); return Number.isNaN(d.getTime())?null:d;
      };
      const dateKey=d=>d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';
      const today=new Date();today.setHours(0,0,0,0);const todayKey=dateKey(today);
      const uniqueSorted=fn=>[...new Set(allRecords.map(fn).filter(v=>String(v||'').trim()))].map(String).sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));
      const state={search:'',database:'',assigned:'',from:'',to:''};
      const assignedUser=x=>x.assignedUserName||updUserDisplay(x.u||{})||x.u?.assigned_to||x.u?.assigned_user_name||'—';
      const detailPhone=d=>Array.isArray(d?.phoneNumbers)?d.phoneNumbers.join(', '):String(d?.phone||'');
      const detailEmail=d=>Array.isArray(d?.emails)?d.emails.join(', '):String(d?.email||'');
      const detailDb=x=>String(x.detail?.databaseName||x.detail?.database_name||x.u?.database_name||'');
      const matches=x=>{
        const d=x.detail||{},q=state.search.trim().toLowerCase();
        const hay=[d.companyName,d.company_name,d.contactPerson,d.position,detailPhone(d),detailEmail(d),d.branch,detailDb(x),assignedUser(x)]
          .map(v=>String(v??'').toLowerCase());
        if(q&&!hay.some(v=>v.includes(q)))return false;
        if(state.database&&detailDb(x)!==state.database)return false;
        if(state.assigned&&assignedUser(x)!==state.assigned)return false;
        const k=dateKey(dateValue(x));
        if(state.from&&(!k||k<state.from))return false;
        if(state.to&&(!k||k>state.to))return false;
        return true;
      };
      const options=(items,sel,ph)=>`<option value="">${ph}</option>`+items.map(v=>`<option value="${esc(v)}" ${v===sel?'selected':''}>${esc(v)}</option>`).join('');
      const render=()=>{
        const filtered=allRecords.filter(matches), total=allRecords.length;
        const dates=filtered.map(dateValue).filter(Boolean);
        const todayN=dates.filter(d=>dateKey(d)===todayKey).length;
        const upcomingN=dates.filter(d=>dateKey(d)>todayKey).length;
        const pastN=dates.filter(d=>dateKey(d)<todayKey).length;
        const databases=new Set(filtered.map(detailDb).filter(Boolean)).size;
        const filterLabels=[];
        if(state.search)filterLabels.push(`Search: “${state.search}”`);
        if(state.database)filterLabels.push(`Database: ${state.database}`);
        if(state.assigned)filterLabels.push(`Assigned User: ${state.assigned}`);
        if(state.from||state.to)filterLabels.push(`Date: ${state.from||'Any'} → ${state.to||'Any'}`);

        body.innerHTML=`
          <div class="upd-abv-content">
            <section class="upd-abv-summary">
              <div class="upd-abv-kpi"><span>Total Appointments</span><strong>${filtered.length.toLocaleString()}</strong></div>
              <div class="upd-abv-kpi"><span>Today</span><strong>${todayN.toLocaleString()}</strong></div>
              <div class="upd-abv-kpi"><span>Upcoming</span><strong>${upcomingN.toLocaleString()}</strong></div>
              <div class="upd-abv-kpi"><span>Completed / Past</span><strong>${pastN.toLocaleString()}</strong></div>
              <div class="upd-abv-kpi"><span>Databases</span><strong>${databases.toLocaleString()}</strong></div>
            </section>

            <section class="upd-abv-filterbar">
              <div class="upd-abv-filter-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input id="upd-abv-search-input" type="search" autocomplete="off" placeholder="Search customer, contact, phone…" value="${esc(state.search)}"></div>
              <select id="upd-abv-filter-db">${options(uniqueSorted(detailDb),state.database,'All Databases')}</select>
              <select id="upd-abv-filter-assigned">${options(uniqueSorted(assignedUser),state.assigned,'All Assigned Users')}</select>
              <div class="upd-abv-date-field"><label>From</label><input id="upd-abv-filter-from" type="date" value="${esc(state.from)}"></div>
              <div class="upd-abv-date-field"><label>To</label><input id="upd-abv-filter-to" type="date" value="${esc(state.to)}"></div>
              <button type="button" class="btn upd-abv-clear" id="upd-abv-clear-filters">Clear Filters</button>
            </section>

            <div class="upd-abv-filter-summary">
              <strong>Showing ${filtered.length.toLocaleString()} of ${total.toLocaleString()} appointments</strong>
              <div class="upd-abv-selected-filters">${filterLabels.length?filterLabels.map(v=>`<span class="upd-abv-filter-chip">${esc(v)}</span>`).join(''):'<span class="upd-abv-filter-none">No filters applied</span>'}</div>
            </div>

            <section class="upd-abv-table-card">
              <div class="upd-abv-table-wrap">
                <table class="upd-abv-table">
                  <colgroup><col class="c-customer"><col class="c-database"><col class="c-contact"><col class="c-phone"><col class="c-date"><col class="c-assigned"></colgroup>
                  <thead><tr><th>Customer</th><th>Database</th><th>Contact Person</th><th>Phone</th><th>Appointment Date</th><th>Assigned User</th></tr></thead>
                  <tbody>${filtered.length?filtered.map(x=>{
                    const d=x.detail||{};
                    const cell=(value,cls='')=>{const val=String(value??'').trim()||'—';return `<td class="${cls}"><span class="upd-abv-truncate" title="${esc(val)}">${esc(val)}</span></td>`;};
                    return `<tr>${cell(d.companyName||d.company_name,'abv-strong')}${cell(detailDb(x))}${cell(d.contactPerson)}${cell(detailPhone(d))}${cell(d.appointmentDate||d.appointment_date?updEntryFormatDate(d.appointmentDate||d.appointment_date):'—','abv-date')}${cell(assignedUser(x),'abv-assigned')}</tr>`;
                  }).join(''):`<tr><td colspan="6" class="upd-abv-empty"><div class="upd-abv-empty-icon">⌕</div><strong>No appointments found</strong><span>Try changing your filters or search.</span></td></tr>`}</tbody>
                </table>
              </div>
            </section>

            <footer class="upd-abv-footer">
              <span>Showing <strong>${filtered.length.toLocaleString()}</strong> of <strong>${total.toLocaleString()}</strong> appointments</span>
              <button type="button" class="btn btn-primary" id="upd-abv-export">Export XLSX</button>
            </footer>
          </div>`;

        const bind=(sel,key,event='change')=>{const el=body.querySelector(sel);if(el)el.addEventListener(event,e=>{state[key]=e.target.value;render();});};
        bind('#upd-abv-search-input','search','input');
        bind('#upd-abv-filter-db','database');
        bind('#upd-abv-filter-assigned','assigned');
        bind('#upd-abv-filter-from','from');
        bind('#upd-abv-filter-to','to');
        body.querySelector('#upd-abv-clear-filters')?.addEventListener('click',()=>{Object.keys(state).forEach(k=>state[k]='');render();});

        body.querySelector('#upd-abv-export')?.addEventListener('click',async()=>{
          if(!filtered.length){toast('No filtered appointments to export','error');return;}
          const btn=body.querySelector('#upd-abv-export');setLoading(btn,true);
          try{
            if(typeof ExcelJS==='undefined') throw new Error('Excel export library is unavailable.');
            const wb=new ExcelJS.Workbook();
            wb.creator='Swift Cargo';wb.lastModifiedBy=S.profile?.full_name||S.profile?.username||'Swift Cargo';wb.created=new Date();wb.modified=new Date();
            wb.properties={title:'Swift Cargo Appointments Export',subject:'Filtered permanently saved appointment records'};
            const ws=wb.addWorksheet('Appointments',{views:[{showGridLines:false}]});
            ws.columns=[
              {header:'Customer',key:'customer',width:34},{header:'Database',key:'database',width:28},{header:'Contact Person',key:'contact',width:24},
              {header:'Position',key:'position',width:20},{header:'Phone',key:'phone',width:26},{header:'Email',key:'email',width:34},
              {header:'Branch',key:'branch',width:16},{header:'Assigned User',key:'assignedUser',width:24},{header:'Appointment Date',key:'appointmentDate',width:20},
              {header:'Salesperson Name',key:'salesperson',width:24},{header:'Created Date/Time',key:'created',width:25},{header:'Remarks',key:'remarks',width:36},
              {header:'Additional Remarks',key:'additionalRemarks',width:42}
            ];
            if(typeof updExcelHeaderSimple==='function')updExcelHeaderSimple(ws.getRow(1));
            filtered.forEach((x,i)=>{
              const d=x.detail||{},r=x.row,u=x.u||{},v=updParseDailyRow(r);
              const salesperson=x.salespersonName||((updUserProfile(x.ownerId)?.full_name)||updUserProfile(x.ownerId)?.username)||'';
              const rr=ws.addRow({
                customer:d.companyName||d.company_name||'',database:detailDb(x),contact:d.contactPerson||'',position:d.position||'',
                phone:detailPhone(d),email:detailEmail(d),branch:d.branch||'',assignedUser:assignedUser(x),
                appointmentDate:d.appointmentDate||d.appointment_date?updExportFriendlyDate(d.appointmentDate||d.appointment_date):'',
                salesperson,created:updExportFriendlyDateTime(r?.created_at||r?.updated_at),remarks:v?.remarks||d.remarks||'',
                additionalRemarks:d.additionalRemarks??d.additional_remarks??d.additionalRemarksText??''
              });
              if(typeof updExcelBodySimple==='function')updExcelBodySimple(rr,i%2===1);
            });
            ws.views=[{state:'frozen',ySplit:1,showGridLines:false}];
            if(ws.rowCount>1)ws.autoFilter={from:{row:1,column:1},to:{row:1,column:ws.columnCount}};
            ws.pageSetup={orientation:'landscape',fitToPage:true,fitToWidth:1,fitToHeight:0,paperSize:9};
            const buffer=await wb.xlsx.writeBuffer(),blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
            const url=URL.createObjectURL(blob),a=document.createElement('a');
            a.href=url;a.download=`${(S.profile?.username||'user').replace(/[^a-zA-Z0-9_-]/g,'')||'user'}_appointments.xlsx`;
            document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
            toast(`Exported ${filtered.length} filtered appointment records`,'success');
          }catch(e){console.error('[APPOINTMENTS XLSX EXPORT FAILED]',e);toast('XLSX export failed: '+(e?.message||'Unknown error'),'error');}
          finally{setLoading(btn,false);}
        });
      };
      render();status.textContent=`${allRecords.length} appointment${allRecords.length===1?'':'s'}`;
    }catch(e){
      console.error('[APPOINTMENTS VIEWER LOAD FAILED]',e);status.textContent='Load failed';
      body.innerHTML=`<div class="upd-abv-error"><div class="upd-abv-error-icon">!</div><div><strong>Could not load appointment records</strong><p>${esc(e?.message||'Unknown database error')}</p></div><button type="button" class="btn" id="upd-abv-retry">Retry</button></div>`;
      body.querySelector('#upd-abv-retry')?.addEventListener('click',()=>window.updOpenAppointmentsBooked());
    }
  });
}
window.updOpenAppointmentsBooked = updOpenAppointmentsBooked;

function ratingStarsHtml(n){
  const v = Math.max(0, Math.min(5, n||0));
  return '★★★★★☆☆☆☆☆'.slice(5-v, 10-v);
}
function updUserProfile(userId){
  if (!userId) return null;
  if (S.profile && S.profile.id === userId) return S.profile;
  return S.profiles.find(p=>p.id===userId) || null;
}
/* Renders the Ratings panel: Admins see every submitted rating (from
   Supabase, role-aware via loadRatings()); regular users see only their own
   — this is a UI convenience, the actual boundary is the `ratings` RLS
   policy (see security_migration.sql), not this filter. */
function renderUpdatesSidebar(){
  const el = $('#updates-sidebar'); if (!el) return;

  const ratings = (S.ratings||[])
    .filter(r=> r.rating != null && !r.skipped)
    .sort((a,b)=> new Date(b.created_at||0) - new Date(a.created_at||0));

  const ratingRowHtml = (r)=>{
    const match = S.updates.find(u=> String(u.assignment_id)===String(r.assignment_id) && String(u.owner_id)===String(r.user_id));
    const total = match?.total_customers ?? null;
    const contacted = match?.customers_contacted ?? null;
    const pct = (total && total>0) ? Math.min(100, Math.round(((contacted||0)/total)*100)) : null;
    const profile = updUserProfile(r.user_id);
    const who = (S.isAdmin ? (profile?.full_name || profile?.email) : null) || 'You';
    const whoEmail = (S.isAdmin && profile?.email && profile.email !== who) ? profile.email : '';
    return `
      <div class="us-rating-row">
        <div class="us-rating-top">
          <div class="us-rating-stars" title="${r.rating}/5 stars">${ratingStarsHtml(r.rating)}</div>
          <div class="us-rating-date">${fmtDate(r.created_at)}</div>
        </div>
        <div class="us-rating-db" title="${esc(r.database_name||'')}">${esc(r.database_name||'\u2014')}</div>
        ${S.isAdmin ? `<div class="us-rating-user">${esc(who)}${whoEmail ? ` \u00b7 ${esc(whoEmail)}` : ''}</div>` : ''}
        ${pct!==null ? `<div class="us-rating-meta">${(contacted||0).toLocaleString()} / ${total.toLocaleString()} contacted (${pct}%)</div>` : ''}
        ${r.review ? `<div class="us-rating-review">${esc(r.review)}</div>` : ''}
      </div>`;
  };

  el.innerHTML = `
    <div class="us-panel">
      <h4>${S.isAdmin ? 'Team Ratings' : 'Your Ratings'}</h4>
      ${ratings.length
        ? ratings.slice(0, 10).map(ratingRowHtml).join('')
        : `<div class="us-sb-empty">${S.isAdmin ? 'No ratings submitted yet.' : "You haven't rated a completed database yet — finish contacting all assigned customers to unlock rating."}</div>`}
    </div>`;
}
/* ---------- Update Reviews button ---------- */
function openUpdateReviews(update){
  const all = (S.ratings||[])
    .filter(r => String(r.assignment_id) === String(update.assignment_id) && r.rating != null && !r.skipped)
    .sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));
  const my = S.session ? all.find(r => String(r.user_id) === String(S.session.user.id)) : null;

  let modal = $('#update-reviews-overlay');
  if (!modal){
    modal = document.createElement('div');
    modal.id = 'update-reviews-overlay';
    modal.className = 'modal-overlay';
    modal.innerHTML = `<div class="modal update-review-modal" style="max-width:560px;width:calc(100% - 32px);">
      <div class="modal-head" style="margin-bottom:6px;"><h3 id="update-reviews-title">Reviews</h3><button class="modal-close" id="update-reviews-close" aria-label="Close">×</button></div>
      <div id="update-reviews-body"></div>
    </div>`;
    document.body.appendChild(modal);
    $('#update-reviews-close',modal).addEventListener('click',()=>modal.classList.add('hidden'));
    modal.addEventListener('click',e=>{ if(e.target===modal) modal.classList.add('hidden'); });
  }

  $('#update-reviews-title',modal).textContent = `${update.database_name || 'Database'} — Reviews`;
  const body = $('#update-reviews-body',modal);

  // Admins review the team's submitted ratings here. They do not overwrite
  // another user's review from this screen.
  if (S.isAdmin){
    if (!all.length){
      body.innerHTML = `<div class="review-empty-state"><div class="review-empty-emoji">📝</div><div class="review-empty-title">No review submitted yet</div><div class="review-empty-sub">Reviews submitted by the assigned user will appear here.</div></div>`;
    } else {
      body.innerHTML = `<div class="review-admin-list">${all.map(r=>{
        const profile = updUserProfile(r.user_id);
        const who = profile?.full_name || profile?.username || profile?.email || 'User';
        return `<div class="update-review-record">
          <div class="update-review-record-top"><div class="update-review-who">${esc(who)}</div><div class="update-review-date">${updExportFriendlyDateTime(r.created_at)}</div></div>
          <div class="update-review-emoji-rating">${['','😞','😕','😐','😊','🤩'][Number(r.rating)||0]} <span>${ratingStarsHtml(r.rating)}</span></div>
          <div class="update-review-text">${esc(r.review || 'No remarks added.')}</div>
        </div>`;
      }).join('')}</div>`;
    }
    modal.classList.remove('hidden');
    return;
  }

  // Regular users get the actual rating form from the Reviews button.
  // Ratings use the same five emoji meanings as the completion-rating flow.
  const existing = my || myRatingFor(update.assignment_id);
  body.innerHTML = `
    <div class="review-form-intro">
      <div class="review-form-emoji">⭐</div>
      <div class="review-form-title">How would you rate this database?</div>
      <div class="review-form-sub">Choose an emoji rating and add remarks if you want.</div>
    </div>
    <div class="rating-stars-row update-review-stars" role="radiogroup" aria-label="Rate this database, 1 to 5">
      <button type="button" class="rating-star-btn update-review-star" data-value="1" role="radio" aria-checked="false" aria-label="1 — Not great"><span class="emoji">😞</span><span class="stars">★</span><span class="num">1</span><small>Not great</small></button>
      <button type="button" class="rating-star-btn update-review-star" data-value="2" role="radio" aria-checked="false" aria-label="2 — Could be better"><span class="emoji">😕</span><span class="stars">★★</span><span class="num">2</span><small>Could be better</small></button>
      <button type="button" class="rating-star-btn update-review-star" data-value="3" role="radio" aria-checked="false" aria-label="3 — Okay"><span class="emoji">😐</span><span class="stars">★★★</span><span class="num">3</span><small>Okay</small></button>
      <button type="button" class="rating-star-btn update-review-star" data-value="4" role="radio" aria-checked="false" aria-label="4 — Good"><span class="emoji">😊</span><span class="stars">★★★★</span><span class="num">4</span><small>Good</small></button>
      <button type="button" class="rating-star-btn update-review-star" data-value="5" role="radio" aria-checked="false" aria-label="5 — Amazing"><span class="emoji">🤩</span><span class="stars">★★★★★</span><span class="num">5</span><small>Amazing</small></button>
    </div>
    <div class="rating-review-field update-review-field">
      <label for="update-review-input">Remarks <span>(optional)</span></label>
      <textarea id="update-review-input" maxlength="1000" placeholder="Write any remarks about this database (optional)">${esc(existing?.review || '')}</textarea>
    </div>
    <div class="update-review-existing">${existing ? `Your current rating: <strong>${['','😞','😕','😐','😊','🤩'][Number(existing.rating)||0]} ${Number(existing.rating)||0}/5</strong>` : 'Your rating will be saved permanently.'}</div>
    <div class="rating-btn-row">
      <button type="button" class="btn" id="update-review-cancel" style="flex:1;">Cancel</button>
      <button type="button" class="btn btn-primary" id="update-review-submit" style="flex:1;" disabled>${existing ? 'Update Review' : 'Submit Review'}</button>
    </div>`;

  let selected = Number(existing?.rating || 0);
  const stars = $all('.update-review-star',body);
  const submit = $('#update-review-submit',body);
  const input = $('#update-review-input',body);

  const paint = (value)=>{
    selected = value;
    stars.forEach(b=>{
      const active = Number(b.dataset.value) <= value;
      b.classList.toggle('active',active);
      b.setAttribute('aria-checked',String(Number(b.dataset.value)===value));
    });
    submit.disabled = !selected;
  };
  stars.forEach(b=>b.addEventListener('click',()=>paint(Number(b.dataset.value))));
  if (existing) paint(selected);
  $('#update-review-cancel',body).addEventListener('click',()=>modal.classList.add('hidden'));

  submit.addEventListener('click',async()=>{
    if (!selected || !S.session) return;
    setLoading(submit,true);
    const payload={
      assignment_id:update.assignment_id,
      database_name:update.database_name,
      user_id:S.session.user.id,
      rating:selected,
      review:input.value.trim()||null,
      skipped:false
    };
    try{
      let result;
      if (existing){
        result=await supa.from('ratings').update({rating:selected,review:payload.review,skipped:false}).eq('id',existing.id).select().single();
      }else{
        result=await supa.from('ratings').insert(payload).select().single();
      }
      if(result.error){
        if(result.error.code==='23505') toast('You already submitted a review for this database.','error');
        else toast('Failed to save review: '+result.error.message,'error');
        return;
      }
      const saved=result.data||payload;
      const idx=S.ratings.findIndex(r=>existing && String(r.id)===String(existing.id));
      if(idx>=0) S.ratings[idx]=saved;
      else S.ratings.push(saved);
      modal.classList.add('hidden');
      refreshRatingsUI();
      renderUpdatesSidebar();
      toast('Review saved permanently! ⭐','success');
    }finally{
      setLoading(submit,false);
    }
  });

  modal.classList.remove('hidden');
}

/* ---------- Central sync point (single source of truth: S.updates) ----------
   Every code path that mutates S.updates (Daily Update save, Daily Update
   delete, etc.) must call this afterwards instead of hand-picking which
   renderers to refresh. This is what keeps the Updates KPI/sidebar,
   Dashboard, Analytics (when open) and the Updates page's Team Work cards
   from going stale relative to S.updates. Cheap: every renderer here reads
   purely from in-memory state, no network calls. */
function syncAfterUpdateChange(){
  renderUpdatesKPISummary();
  renderUpdatesSidebar();
  renderDashboard();
  // Team Work cards live on the Updates page but aren't patched by the
  // per-card optimistic update below, so refresh them explicitly whenever
  // that page is the one currently visible.
  if ($('#page-updates')?.classList.contains('active')) renderTeamWorkCards();
  // Analytics derives everything from S.updates too — if it happens to be
  // the active page, bring it current immediately rather than waiting for
  // the next goPage('analytics') navigation.
  if ($('#page-analytics')?.classList.contains('active') && typeof renderAnalyticsPage==='function') renderAnalyticsPage();
}
/* ---------- Daily Update premium cards (automatic-only; additive) ---------- */
function dailyUpdateStatus(rate){
  if (rate<=0) return { key:'not_started', label:'Not Started', emoji:'🟡' };
  if (rate>=100) return { key:'completed', label:'Completed', emoji:'🟢' };
  return { key:'in_progress', label:'In Progress', emoji:'🔵' };
}
/* AUTHORITATIVE TOTAL CUSTOMERS:
   Total Cust. must come from the assigned Data Hub database, not from the
   snapshot stored in updates.total_customers.  The assignment trigger copies
   customer_count into updates when the assignment is created, so using that
   snapshot can show an old/wrong total after the Data Hub database changes.
*/
function updAuthoritativeTotalCustomers(u){
  const _m = dhGetDatabaseMetrics(u?.assignment_id);
  if (_m) return _m.total;
  const db = (S.databases || []).find(d => String(d.id) === String(u?.assignment_id));
  if (db && db.customer_count != null && Number.isFinite(Number(db.customer_count))) {
    return Math.max(0, Number(db.customer_count));
  }
  return Math.max(0, Number(u?.total_customers || 0));
}
/* CONTINUE-FROM-PREVIOUS-VALUE (additive):
   "Customers Contacted Today" is a cumulative counter, not a replacement
   field. The card must always suggest current authoritative value + 1 as
   the starting point for the *next* entry — never re-show the same value
   (which would look like the counter reset) and never skip ahead by more
   than 1. Capped at `total` since contacted can never exceed the database
   size. This function only computes a *display suggestion* for the input —
   it never writes to the database by itself. */
function nextContactedSuggestion(total, current){
  const t = Number(total)||0;
  const c = Math.max(0, Number(current)||0);
  if (t<=0) return c; // nothing to bound against — leave as-is
  return Math.max(0, Math.min(t, c+1));
}
function dailyUpdateCardHtml(u){
  const assignedDb = (S.databases || []).find(d => String(d.id) === String(u.assignment_id) || String(d.name) === String(u.database_name));
  const isAssignedUser = !!assignedDb && String(assignedDb.assigned_user_id) === String(S.session.user.id);
  const isOwner = String(u.owner_id) === String(S.session.user.id);
  const total = updAuthoritativeTotalCustomers(u);
  const _dm = dhGetDatabaseMetrics(u.assignment_id);
  const contacted = _dm ? _dm.contacted : Math.max(0, Number(u.customers_contacted || 0));
  const pct = total > 0 ? Math.min(100, Math.round((contacted / total) * 100)) : 0;
  const status = dailyUpdateStatus(pct);
  const priority = String(u.priority || 'Medium').replace(/_/g,' ');
  const priorityClass = /high/i.test(priority) ? 'upd-card-priority-high' : /low/i.test(priority) ? 'upd-card-priority-low' : 'upd-card-priority-medium';
  const canEdit = S.isAdmin || isAssignedUser;
  return `
  <article class="upd-card-v4" data-upd-id="${esc(u.id)}" data-total="${total}" data-entry-count="0">
    <div class="upd-card-v4-top">
      <div class="upd-card-v4-title-wrap">
        <h3 class="upd-card-v4-title" title="${esc(u.database_name||'')}">${esc(u.database_name||'Untitled Database')}</h3>
        <div class="upd-card-v4-sub">${total.toLocaleString()} customers</div>
        ${S.isAdmin ? `<div class="upd-card-v4-assigned"><span class="upd-card-v4-assigned-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></span>Assigned to: ${esc(analyticsUserName(u.owner_id))}</div>` : ''}
      </div>
      <div class="upd-card-v4-badges">
        <span class="upd-card-v4-status ${status.key}"><span class="upd-card-v4-dot"></span>${esc(status.label)}</span>
        <span class="upd-card-v4-priority ${priorityClass}">${esc(priority)}</span>
        ${(S.isAdmin || canEdit) ? `<button type="button" class="upd-card-v4-icon danger" data-role="delete-card" title="Delete update card" aria-label="Delete update card"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg></button>` : ''}
      </div>
    </div>

    <div class="upd-card-v4-stats" data-role="stats">
      <div class="upd-card-v4-stat total">
        <div class="upd-card-v4-stat-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></div>
        <div><div class="upd-card-v4-stat-label">Total Cust.</div><div class="upd-card-v4-stat-value" data-role="stat-total">${total.toLocaleString()}</div><div class="upd-card-v4-stat-note">All count from all day</div></div>
      </div>
      <div class="upd-card-v4-stat contacted">
        <div class="upd-card-v4-stat-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.362 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.338 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/></svg></div>
        <div><div class="upd-card-v4-stat-label">Total Contacted</div><div class="upd-card-v4-stat-value" data-role="stat-contacted">${contacted.toLocaleString()}</div><div class="upd-card-v4-stat-note">All count from all day</div></div>
      </div>
      <div class="upd-card-v4-stat pending">
        <div class="upd-card-v4-stat-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg></div>
        <div><div class="upd-card-v4-stat-label">Pending</div><div class="upd-card-v4-stat-value" data-role="stat-pending">${Math.max(0,total-contacted).toLocaleString()}</div><div class="upd-card-v4-stat-note">All count from all day</div></div>
      </div>
    </div>

    <div class="upd-card-v4-kicker">OVERALL CONTACT PROGRESS</div>
    <div class="upd-card-v4-progress-head">
      <div><strong data-role="contacted-total">${contacted.toLocaleString()}</strong><span> / ${total.toLocaleString()} contacted</span></div>
      <strong data-role="progress-pct">${pct.toFixed(2)}%</strong>
    </div>
    <div class="upd-card-v4-progress"><div data-role="progress-fill" style="width:${pct}%"></div></div>

    <div class="upd-card-v4-meta">
      <span class="upd-card-v4-saved" data-role="save-state">${contacted > 0 ? '✓ Permanently saved' : ''}</span>
      <span class="upd-card-v4-entry-count" data-role="entry-count">0 entries</span>
    </div>

    <div class="upd-card-v4-actions">
      ${canEdit ? `<button type="button" class="upd-card-v4-btn primary" data-role="entry"><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M12 5v14M5 12h14"/></svg></span> Entry</button>` : ''}
      ${canEdit ? `<button type="button" class="upd-card-v4-btn" data-role="edit"><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 3a2.85 2.85 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/></svg></span> Edit</button>` : ''}
      <button type="button" class="upd-card-v4-btn" data-role="reviews"><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2.5l3.09 6.26 6.91 1-5 4.87 1.18 6.87L12 18.27l-6.18 3.23L7 14.63l-5-4.87 6.91-1z"/></svg></span> Reviews</button>
      ${(S.isAdmin || canEdit) ? `<button type="button" class="upd-card-v4-btn danger-outline" data-role="delete-inline"><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg></span> Del</button>` : ''}
    </div>
    <div class="upd-card-v4-entry-panel hidden" data-role="entry-panel"></div>
    <div class="upd-card-v4-history" data-role="history"></div>
  </article>`;
}

function updEntryToday(){
  const d=new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function updEntryFormatDate(v){
  if(!v) return '—';
  const d=new Date(`${v}T00:00:00`);
  return Number.isNaN(d.getTime()) ? v : d.toLocaleDateString(undefined,{day:'2-digit',month:'long',year:'numeric'});
}
function updEntryFormatTime(v){
  if(!v) return '—';
  const m=String(v).match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if(!m) return v;
  const h=Number(m[1]), min=m[2];
  if(!Number.isInteger(h)||h<0||h>23) return v;
  const ap=h>=12?'PM':'AM', hh=(h%12)||12;
  return `${String(hh).padStart(2,'0')}:${min} ${ap}`;
}
function updEntryFormatDateTime(row){
  if(!row) return '—';
  const date=updEntryFormatDate(row.entry_date);
  if(row.entry_time) return `${date} · ${updEntryFormatTime(row.entry_time)}`;
  const raw=row.updated_at||row.created_at;
  if(!raw) return date;
  const d=new Date(raw);
  return Number.isNaN(d.getTime()) ? date : d.toLocaleString(undefined,{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'});
}
function updParseDailyRow(row){
  let appointments=row?.appointments ?? null, remarks=row?.remarks ?? null, appointmentDetails=row?.appointmentDetails ?? null;
  if(row?.notes){
    try{
      const n=JSON.parse(row.notes);
      appointments ??= n?.appointments;
      remarks ??= n?.remarks;
      appointmentDetails ??= n?.appointmentDetails;
    }catch(_){ remarks ??= row.notes; }
  }
  if(!Array.isArray(appointmentDetails) && appointmentDetails && typeof appointmentDetails==='object') appointmentDetails=[appointmentDetails];
  const customers=row?.completed_today != null ? Number(row.completed_today) : Number(row?.customers_contacted ?? 0);
  return {customers:Number.isFinite(customers)?customers:0,appointments:Number(appointments??0)||0,remarks:String(remarks??''),appointmentDetails:Array.isArray(appointmentDetails)?appointmentDetails:[]};
}

/* ==========================================================================
   DAILY WORK UPDATE EMAIL — generated after every Daily Work save/update.
   Uses existing daily_entries data only; no schema/RLS/auth changes.
   ========================================================================== */
function dailyWorkEmailEscape(v){
  return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function dailyWorkEmailHeader(v){
  const text=String(v||'').replace(/[\r\n]+/g,' ').trim();
  if(!text) return '';
  if(/^[\\x20-\\x7E]*$/.test(text)) return text;
  const bytes=new TextEncoder().encode(text); let binary='';
  for(let i=0;i<bytes.length;i+=0x8000) binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));
  return '=?UTF-8?B?'+btoa(binary)+'?=';
}
function dailyWorkEmailBase64(buffer){
  const bytes=buffer instanceof Uint8Array?buffer:new Uint8Array(buffer); let binary='';
  for(let i=0;i<bytes.length;i+=0x8000) binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));
  const b64=btoa(binary), lines=[]; for(let i=0;i<b64.length;i+=76) lines.push(b64.slice(i,i+76)); return lines.join('\r\n');
}
function dailyWorkEmailBase64Text(text){ return dailyWorkEmailBase64(new TextEncoder().encode(String(text||''))); }
function dailyWorkEmailFilename(v){ return String(v||'daily-work-update').replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,' ').trim().slice(0,100)||'daily-work-update'; }
function dailyWorkEmailLocalDate(){ return updEntryToday(); }
function dailyWorkEmailDateLabel(date){ return updEntryFormatDate(date); }
function dailyWorkEmailTimeLabel(v){ return updEntryFormatTime(v); }
function dailyWorkEmailAdmin(){
  const admins=(S.profiles||[]).filter(p=>String(p.role||'').toLowerCase()==='admin' && String(p.email||'').trim());
  return admins[0]||null;
}
async function generateDailyWorkUpdateEmail(updateOwnerId){
  const ownerId=String(updateOwnerId||S.session?.user?.id||'').trim();
  if(!ownerId) return;
  const today=dailyWorkEmailLocalDate();
  let admin=dailyWorkEmailAdmin();
  if(!admin){
    const ar=await supa.from('profiles').select('id,full_name,email,role').eq('role','admin').not('email','is',null).limit(1);
    if(!ar.error && ar.data?.length) admin=ar.data[0];
  }
  if(!admin?.email) throw new Error('Admin email address is not available.');

  const {data:rows,error}=await supa.from('daily_entries').select('*')
    .eq('owner_id',ownerId).eq('entry_date',today)
    .order('entry_time',{ascending:true}).order('created_at',{ascending:true});
  if(error) throw error;

  const owner=(S.profiles||[]).find(p=>String(p.id)===ownerId) || (String(S.session?.user?.id)===ownerId?S.profile:null) || {};
  const userName=String(owner.full_name||owner.username||owner.email||'User').trim();
  const entries=rows.map(r=>{
    const v=updParseDailyRow(r);
    return {...r,...v};
  });

  const totalCustomers=entries.reduce((n,r)=>n+Number(r.customers||0),0);
  const appointments=entries.flatMap(r=>(Array.isArray(r.appointmentDetails)?r.appointmentDetails:[]));
  const appointmentCount=Math.max(
    appointments.length,
    entries.reduce((n,r)=>n+Number(r.appointments||0),0)
  );

  // Email-only presentation helpers. Existing automation, data, fields,
  // Supabase schema and daily-entry logic remain unchanged.
  const adminFullName=String(admin.full_name||admin.username||'Admin').trim();
  const adminFirstName=(adminFullName.split(/\s+/)[0]||'Admin').trim();
  const adminGreetingName=dailyWorkEmailEscape(adminFirstName);

  const databaseNames=[...new Set(
    entries.map(r=>String(r.database_name||'').trim()).filter(Boolean)
  )];
  const databaseLabel=databaseNames.length===1
    ? `${dailyWorkEmailEscape(databaseNames[0])} database`
    : databaseNames.length>1
      ? `${databaseNames.map(d=>dailyWorkEmailEscape(d)).join(', ')} databases`
      : 'the assigned database';

  const entryBreakdownHtml=entries.length
    ? `<ul style="margin:12px 0 0;padding-left:22px;color:#263242;">
        ${entries.map(r=>{
          const count=Number(r.customers||0);
          const db=r.database_name ? ` <span style="color:#64748B;">— ${dailyWorkEmailEscape(r.database_name)}</span>` : '';
          return `<li style="margin:0 0 7px;font-size:13.5px;line-height:1.65;color:#263242;">
            <span style="font-weight:600;">${count.toLocaleString()} customer${count===1?'':'s'} contacted</span>${db}
          </li>`;
        }).join('')}
      </ul>`
    : `<p style="margin:10px 0 0;font-size:13.5px;line-height:1.75;color:#64748B;">No daily work entry details were saved today.</p>`;

  const entryBreakdownText=entries.length
    ? entries.map(r=>{
        const count=Number(r.customers||0);
        return `- ${count.toLocaleString()} customer${count===1?'':'s'} contacted${r.database_name?' — '+r.database_name:''}`;
      }).join('\r\n')
    : '- No daily work entry details were saved today.';

  const apptHtml=appointments.length
    ? `<p style="margin:0 0 9px;font-size:13.5px;line-height:1.75;color:#263242;">
         A total of ${appointmentCount} appointment${appointmentCount===1?'':'s'} ${appointmentCount===1?'was':'were'} booked today.
       </p>
       <ul style="margin:0;padding-left:22px;">
         ${appointments.map(a=>`
           <li style="margin:0 0 7px;color:#263242;font-size:13.5px;line-height:1.65;">
             <b>${dailyWorkEmailEscape(a.companyName||a.company_name||'Customer')}</b>${a.appointmentDate?` — ${dailyWorkEmailEscape(dailyWorkEmailDateLabel(a.appointmentDate))}`:''}${a.appointmentTime?` at ${dailyWorkEmailEscape(a.appointmentTime)}`:''}${a.salesperson?` · ${dailyWorkEmailEscape(a.salesperson)}`:''}${a.branch?` · ${dailyWorkEmailEscape(a.branch)}`:''}${a.additionalRemarks?`<br><span style="color:#64748B;">${dailyWorkEmailEscape(a.additionalRemarks)}</span>`:''}
           </li>`).join('')}
       </ul>`
    : `<p style="margin:0;font-size:13.5px;line-height:1.75;color:#64748B;">No appointments were booked today.</p>`;

  const html=`<!doctype html>
<html>
<body style="margin:0;padding:28px 20px;background:#ffffff;font-family:Arial,Helvetica,sans-serif;color:#172033;">
  <div style="max-width:680px;margin:0 auto;">
    <div style="font-size:14px;line-height:1.7;color:#172033;">
      Dear ${adminGreetingName} mam,
    </div>

    <div style="height:18px;"></div>

    <div style="font-size:13.5px;line-height:1.75;color:#263242;">
      Please find below my work update for today.
    </div>

    <div style="height:12px;"></div>

    <div style="font-size:13.5px;line-height:1.75;color:#263242;">
      Today, I worked on the <strong>${databaseLabel}</strong> and contacted
      <strong>${totalCustomers.toLocaleString()} customer${totalCustomers===1?'':'s'}</strong>
      as part of my daily outreach.
    </div>

    ${entryBreakdownHtml}

    <div style="height:18px;"></div>

    <div style="font-size:14px;font-weight:700;color:#1F3A68;margin:0 0 9px;">
      Appointments
    </div>
    ${apptHtml}

    <div style="height:22px;"></div>

    <div style="font-size:13.5px;line-height:1.75;color:#263242;">
      Thank you.
    </div>

    <div style="height:2px;"></div>

    <div style="font-size:13.5px;line-height:1.75;color:#263242;">
      Best regards,<br>${dailyWorkEmailEscape(userName)}
    </div>
  </div>
</body>
</html>`;

  const text=[
    `Dear ${adminFirstName} mam,`,'',
    'Please find below my work update for today.','',
    `Today, I worked on the ${databaseNames.length===1 ? databaseNames[0]+' database' : databaseNames.length>1 ? databaseNames.join(', ')+' databases' : 'assigned database'} and contacted ${totalCustomers.toLocaleString()} customer${totalCustomers===1?'':'s'} as part of my daily outreach.`,
    '',
    entryBreakdownText,
    '',
    'Appointments',
    ...(appointments.length
      ? [
          `A total of ${appointmentCount} appointment${appointmentCount===1?'':'s'} ${appointmentCount===1?'was':'were'} booked today.`,
          ...appointments.map(a=>`- ${a.companyName||a.company_name||'Customer'}${a.appointmentDate?' — '+dailyWorkEmailDateLabel(a.appointmentDate):''}${a.appointmentTime?' at '+a.appointmentTime:''}${a.salesperson?' · '+a.salesperson:''}${a.branch?' · '+a.branch:''}${a.additionalRemarks?' — '+a.additionalRemarks:''}`)
        ]
      : ['No appointments were booked today.']),
    '',
    'Thank you.',
    '',
    'Best regards,',
    userName
  ].join('\r\n');

  const senderEmail=String(S.session?.user?.email||'').trim();
  if(!senderEmail) throw new Error('Current user email address is not available.');
  const senderName=String(userName||'Swift Cargo User').trim();
  const subject=`Today's Work Update – ${dailyWorkEmailDateLabel(today)}`;
  const boundary='=_SwiftCargo_Daily_'+crypto.randomUUID();
  const eml=[
    `From: ${dailyWorkEmailHeader(senderName)} <${senderEmail}>`,
    `To: ${dailyWorkEmailHeader(admin.full_name||'Admin')} <${admin.email}>`,
    `Subject: ${dailyWorkEmailHeader(subject)}`,
    `Date: ${new Date().toUTCString()}`,
    'MIME-Version: 1.0',
    'X-Unsent: 1',
    `Content-Type: multipart/alternative; boundary="${boundary}"`,'',
    `--${boundary}`,'Content-Type: text/plain; charset=UTF-8','Content-Transfer-Encoding: base64','',dailyWorkEmailBase64Text(text),'',
    `--${boundary}`,'Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','',dailyWorkEmailBase64Text(html),'',
    `--${boundary}--`,''
  ].join('\r\n');

  const blob=new Blob([new TextEncoder().encode(eml)],{type:'message/rfc822'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;
  a.download=dailyWorkEmailFilename(`Daily_Work_Update_${today}_${userName}`)+'.eml';
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),5000);
  toast('Daily Work Update email regenerated and downloaded','success');
}

async function regenerateDailyWorkUpdateEmailSafe(ownerId){
  try{ await generateDailyWorkUpdateEmail(ownerId); }
  catch(e){ console.error('[DAILY WORK EMAIL FAILED]',e); toast('Work saved, but the Daily Work Update email could not be generated: '+(e?.message||'Unknown error'),'error'); }
}

/* Overall contacted is the sum of every permanently saved daily entry.
   Each daily_entries row represents customers contacted ON THAT DAY.
   Re-reading and summing the complete history means the overall value
   continues forward and editing one day recalculates the total without
   deleting or overwriting any other day's history. */
function updOverallContacted(rows, fallback=0){
  const values=(rows||[]).map(r=>Number(updParseDailyRow(r).customers)||0).filter(Number.isFinite);
  if(values.length) return Math.max(0, values.reduce((sum,v)=>sum+v,0));
  return Math.max(0, Number(fallback)||0);
}
async function updLoadDailyRows(updateId){
  let q=supa.from('daily_entries').select('*').eq('update_id',updateId).order('entry_date',{ascending:false}).order('created_at',{ascending:false}).limit(365);
  if(!S.isAdmin) q=q.eq('owner_id',S.session.user.id);
  const {data,error}=await q;
  if(error) throw error;
  return data||[];
}
