async function updAppointmentRecordsForUpdate(rec){
  const dbId=rec?.assignment_id;
  if(!dbId) return [];
  const local=S.records.filter(r=>String(r.database_id)===String(dbId));
  if(local.length) return local;
  let q=supa.from('records').select('id,database_id,database_name,company_name,contact_person,position,mobile_phone_1,mobile_phone_2,work_phone_1,work_phone_2,personal_email_1,personal_email_2,business_email_1,business_email_2,location,remark').eq('database_id',dbId).limit(5000);
  if(!S.isAdmin) q=q.eq('owner_id',S.session.user.id);
  const {data,error}=await q;
  if(error){ console.error('[APPOINTMENTS] customer lookup failed',error); return []; }
  return data||[];
}
function updAppointmentScore(q,name){
  return typeof dhAdvancedSearchScore==='function' ? dhAdvancedSearchScore(q,name) : (String(name||'').toLowerCase().includes(String(q||'').toLowerCase())?80:0);
}
function updAppointmentSearchResults(records,q){
  q=String(q||'').trim();
  if(!q) return records.slice(0,8);
  return records.map(r=>({...r,_score:updAppointmentScore(q,r.company_name)}))
    .filter(r=>r._score>0).sort((a,b)=>b._score-a._score).slice(0,8);
}
let updApptContext=null, updApptSelected=null;
async function updOpenAppointmentPopup(rec, existingDetail=null, appointmentIndex=1, appointmentTotal=1){
  const modal=updAppointmentModalHtml();
  updApptContext={rec,records:[],resolve:null,appointmentIndex,appointmentTotal};
  updApptSelected=null;
  $('#upd-appt-progress').textContent = appointmentTotal > 1 ? `(${appointmentIndex} of ${appointmentTotal})` : '';
  $('#upd-appt-subtitle').textContent = appointmentTotal > 1 ? `Appointment ${appointmentIndex} of ${appointmentTotal} — select a customer and add the details.` : 'Select a customer from your assigned database and add the appointment information.';
  const apptSaveBtn = $('#upd-appointment-modal [data-role="appt-save"]');
  if(apptSaveBtn) apptSaveBtn.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4L19 6"/></svg>${appointmentIndex < appointmentTotal ? 'Save & Next' : 'Save Appointment'}`;
  $('#upd-appt-company-search').value=existingDetail?.companyName||existingDetail?.company_name||'';
  $('#upd-appt-date').value=existingDetail?.appointmentDate||existingDetail?.appointment_date||'';
  $('#upd-appt-salesperson').value=existingDetail?.salesperson||'';
  $('#upd-appt-branch').value=existingDetail?.branch||'';
  $('#upd-appt-remarks').value=existingDetail?.additionalRemarks||'';
  $('#upd-appt-results').classList.add('hidden');
  $('#upd-appt-selected').classList.add('hidden');
  modal.classList.remove('hidden');
  updApptContext.records=await updAppointmentRecordsForUpdate(rec);
  if(existingDetail?.recordId){
    updApptSelected=updApptContext.records.find(r=>String(r.id)===String(existingDetail.recordId))||null;
  }
  if(!updApptSelected && existingDetail?.companyName){
    updApptSelected=updApptContext.records.find(r=>String(r.company_name||'').toLowerCase()===String(existingDetail.companyName).toLowerCase())||null;
  }
  if(updApptSelected) updRenderAppointmentSelected(updApptSelected);
  return new Promise(resolve=>{updApptContext.resolve=resolve;});
}
function updRenderAppointmentSelected(r){
  const box=$('#upd-appt-selected'); if(!box) return;
  box.classList.remove('hidden');
  box.innerHTML=`<strong>${esc(r.company_name||'Unnamed company')}</strong><span>${esc([r.contact_person,r.position,r.database_name].filter(Boolean).join(' · ')||'Customer record selected')}</span>`;
}
function updCloseAppointmentPopup(result){
  const modal=$('#upd-appointment-modal');
  if(modal) modal.classList.add('hidden');
  const resolve=updApptContext?.resolve;
  updApptContext=null; updApptSelected=null;
  if(resolve) resolve(result||null);
}
document.addEventListener('input', e=>{
  if(e.target.id!=='upd-appt-company-search' || !updApptContext) return;
  const results=updAppointmentSearchResults(updApptContext.records,e.target.value);
  const box=$('#upd-appt-results');
  if(!results.length){box.classList.add('hidden');box.innerHTML='';return;}
  box.classList.remove('hidden');
  box.innerHTML=results.map(r=>`<button type="button" class="upd-appt-result" data-appt-record-id="${esc(r.id)}"><span class="upd-appt-result-main"><span class="upd-appt-result-name">${esc(r.company_name||'Unnamed company')}</span><span class="upd-appt-result-meta">${esc([r.contact_person,r.position].filter(Boolean).join(' · ')||'No contact details')}</span></span><span class="upd-appt-score">${Math.round(r._score||0)}%</span></button>`).join('');
});
document.addEventListener('click', e=>{
  const result=e.target.closest('[data-appt-record-id]');
  if(result && updApptContext){
    const r=updApptContext.records.find(x=>String(x.id)===String(result.dataset.apptRecordId));
    if(r){updApptSelected=r;$('#upd-appt-company-search').value=r.company_name||'';updRenderAppointmentSelected(r);$('#upd-appt-results').classList.add('hidden');}
    return;
  }
  if(e.target.closest('[data-role="appt-close"],[data-role="appt-cancel"]')){updCloseAppointmentPopup(null);return;}
  if(e.target.closest('[data-role="appt-save"]') && updApptContext){
    if(!updApptSelected){toast('Select a customer from the assigned database.','error');return;}
    const r=updApptSelected;
    updCloseAppointmentPopup({
      recordId:r.id, companyName:r.company_name||'', databaseName:r.database_name||updApptContext.rec.database_name||'',
      contactPerson:r.contact_person||'', position:r.position||'',
      phoneNumbers:[r.mobile_phone_1,r.mobile_phone_2,r.work_phone_1,r.work_phone_2].filter(Boolean),
      emails:[r.business_email_1,r.business_email_2,r.personal_email_1,r.personal_email_2].filter(Boolean),
      appointmentDate:$('#upd-appt-date').value||'', salesperson:$('#upd-appt-salesperson').value.trim(), branch:$('#upd-appt-branch').value.trim(),
      additionalRemarks:$('#upd-appt-remarks').value.trim()
    }); 
  }
});

async function updCollectAppointmentDetails(rec, existingDetails, count){
  const details=[];
  const existing=Array.isArray(existingDetails) ? existingDetails : [];
  for(let i=0;i<count;i++){
    const detail=await updOpenAppointmentPopup(rec, existing[i]||null, i+1, count);
    if(!detail) return null;
    details.push(detail);
  }
  return details;
}

function updAppointmentFingerprint(d){
  const norm=v=>String(v??'').trim().toLowerCase().replace(/\s+/g,' ');
  const phones=(Array.isArray(d?.phoneNumbers)?d.phoneNumbers:[]).map(norm).filter(Boolean).sort().join('|');
  const emails=(Array.isArray(d?.emails)?d.emails:[]).map(norm).filter(Boolean).sort().join('|');
  return [
    norm(d?.recordId||d?.record_id),
    norm(d?.companyName||d?.company_name),
    norm(d?.appointmentDate||d?.appointment_date),
    norm(d?.salesperson),
    norm(d?.branch),
    phones,
    emails
  ].join('::');
}

function updMergeAppointmentDetails(existing, incoming){
  const out=[];
  const seen=new Set();
  const add=(d)=>{
    if(!d || typeof d!=='object') return;
    const clean={...d};
    if(!Array.isArray(clean.phoneNumbers)) clean.phoneNumbers=clean.phoneNumbers?[clean.phoneNumbers]:[];
    if(!Array.isArray(clean.emails)) clean.emails=clean.emails?[clean.emails]:[];
    const fp=updAppointmentFingerprint(clean);
    if(!fp || seen.has(fp)) return;
    seen.add(fp); out.push(clean);
  };
  (Array.isArray(existing)?existing:[]).forEach(add);
  (Array.isArray(incoming)?incoming:[]).forEach(add);
  return out;
}

function updAllSavedAppointmentDetails(rows){
  const out=[];
  (rows||[]).forEach(row=>{
    const v=updParseDailyRow(row);
    (v.appointmentDetails||[]).forEach(detail=>out.push({
      detail,
      row,
      updateId:row.update_id
    }));
  });
  const seen=new Set(), deduped=[];
  out.forEach(x=>{
    const fp=updAppointmentFingerprint(x.detail);
    if(!fp || seen.has(fp)) return;
    seen.add(fp); deduped.push(x);
  });
  return deduped;
}

function updAppointmentDetailsFromValue(v){
  return Array.isArray(v?.appointmentDetails) ? v.appointmentDetails : [];
}

function updRenderEntryPanel(card, rows, selectedDate, editId=null){
  const rec=S.updates.find(u=>String(u.id)===String(card.dataset.updId));
  if(!rec) return;
  const current=editId ? (rows.find(r=>String(r.id)===String(editId))||null) : null;
  const val=current ? updParseDailyRow(current) : {customers:0,appointments:0,remarks:'',appointmentDetails:[]};
  const panel=$('[data-role="entry-panel"]',card);
  panel.classList.remove('hidden');
  panel.innerHTML=`
    <div class="upd-entry-editor">
      <div class="upd-entry-editor-head">
        <div><b>${current?'Edit Entry':'New Entry'}</b><small>${esc(updEntryFormatDate(selectedDate))}</small></div>
        <button type="button" class="upd-entry-close" data-role="entry-close">×</button>
      </div>
      <div class="upd-entry-grid">
        <label>Customers Contacted<input type="number" min="0" max="${updAuthoritativeTotalCustomers(rec)}" step="1" data-role="entry-contacted" value="${esc(val.customers)}"></label>
        <label>Appointments<input type="number" min="0" step="1" data-role="entry-appointments" value="${esc(val.appointments)}"></label>
        <label class="full">Additional Remarks<textarea data-role="entry-remarks" placeholder="Optional notes, blockers, follow-ups…">${esc(val.remarks)}</textarea></label>
      </div>
      <div class="upd-entry-editor-foot"><button type="button" class="btn btn-primary" data-role="entry-save">${current?'Update':'Save'} Entry</button></div>
    </div>`;
  $('[data-role="entry-close"]',panel)?.addEventListener('click',()=>panel.classList.add('hidden'));
  // Appointment details are collected only when Save Entry is clicked.
  // This prevents the old bug where typing "10" opened the popup after the first digit.
  $('[data-role="entry-save"]',panel)?.addEventListener('click',async()=>{
    const btn=$('[data-role="entry-save"]',panel), ci=$('[data-role="entry-contacted"]',panel), ai=$('[data-role="entry-appointments"]',panel), ri=$('[data-role="entry-remarks"]',panel);
    const customers=Number(ci.value), requestedAppointments=ai.value===''?0:Number(ai.value), total=Number(rec.total_customers||0);
    if(!Number.isInteger(customers)||customers<0||customers>total){toast(`Customers Contacted must be between 0 and ${total}.`,'error');return;}
    if(!Number.isInteger(requestedAppointments)||requestedAppointments<0){toast('Appointments must be 0 or a positive whole number.','error');return;}

    setLoading(btn,true);
    try{
      // Always re-read the current server history immediately before writing.
      // This prevents a new entry from replacing appointments saved on an older day.
      const {data:liveRows,error:liveErr}=await supa.from('updates').select('*').eq('id',rec.id).limit(1);
      const live=Array.isArray(liveRows)?liveRows[0]:null;
      if(liveErr||!live) throw liveErr||new Error('Update record could not be found.');
      const serverRows=await updLoadDailyRows(live.id);
      const currentServer=current ? (serverRows.find(r=>String(r.id)===String(current.id))||null) : null;
      const currentParsed=currentServer ? updParseDailyRow(currentServer) : {customers:0,appointments:0,remarks:'',appointmentDetails:[]};

      // For a new daily entry, the requested appointment count means NEW appointments.
      // For an edit, keep the existing appointments in that row unless the user replaces them.
      let newDetails=[];
      if(requestedAppointments>0){
        const seedForEdit=current ? currentParsed.appointmentDetails : [];
        const collected=await updCollectAppointmentDetails(live,seedForEdit,requestedAppointments);
        if(!collected){
          toast('Appointment entry cancelled. Nothing was saved.','error');
          return;
        }
        newDetails=collected;
      }

      const now=new Date().toISOString();
      const existingRowDetails=Array.isArray(currentParsed.appointmentDetails)?currentParsed.appointmentDetails:[];
      const otherSavedDetails=serverRows
        .filter(r=>!currentServer || String(r.id)!==String(currentServer.id))
        .flatMap(r=>updParseDailyRow(r).appointmentDetails||[]);
      const otherFingerprints=new Set(otherSavedDetails.map(updAppointmentFingerprint));
      // Do not insert the same appointment again if it already exists in another
      // permanently saved daily entry. Existing details in the row being edited
      // remain intact.
      const uniqueNewDetails=newDetails.filter(d=>!otherFingerprints.has(updAppointmentFingerprint(d)));
      const mergedRowDetails=current
        ? updMergeAppointmentDetails(existingRowDetails,uniqueNewDetails)
        : updMergeAppointmentDetails([],uniqueNewDetails);

      const payload={
        update_id:live.id,
        owner_id:(S.isAdmin ? (live.owner_id || S.session.user.id) : S.session.user.id),
        database_name:live.database_name,
        entry_date:selectedDate,
        entry_time:new Date().toTimeString().slice(0,8),
        completed_today:customers,
        notes:JSON.stringify({
          appointments:mergedRowDetails.length,
          remarks:ri.value.trim(),
          appointmentDetails:mergedRowDetails
        }),
        updated_at:now
      };

      let dr;
      if(currentServer) dr=await supa.from('daily_entries').update(payload).eq('id',currentServer.id);
      else dr=await supa.from('daily_entries').insert(payload);
      if(dr.error) throw dr.error;

      // Re-read after the write and derive all counters from permanent history.
      const freshRows=await updLoadDailyRows(live.id);
      const allSaved=updAllSavedAppointmentDetails(freshRows);
      const overallCustomers=updOverallContacted(freshRows,0);
      if(overallCustomers>total) throw new Error(`Overall Contacted (${overallCustomers}) cannot exceed Total Customers (${total}). Check the daily entries.`);
      const overallAppointments=allSaved.length;
      const latestByTime=[...freshRows].sort((a,b)=>{
        const ak=`${a.entry_date||''} ${a.entry_time||''} ${a.updated_at||a.created_at||''}`;
        const bk=`${b.entry_date||''} ${b.entry_time||''} ${b.updated_at||b.created_at||''}`;
        return bk.localeCompare(ak);
      })[0];
      const latestParsed=latestByTime?updParseDailyRow(latestByTime):{remarks:''};
      const overallRemarks=String(latestParsed.remarks||'').trim();

      // Do not coerce the UPDATE response to a single JSON object. RLS can
      // legitimately make the returned row set empty, which previously caused
      // PostgREST 406 / "Cannot coerce the result to a single JSON object".
      const {error:parentUpdateError}=await supa.from('updates').update({
        customers_contacted:overallCustomers,
        appointments:overallAppointments,
        remarks:overallRemarks||null,
        updated_at:now
      }).eq('id',live.id);
      if(parentUpdateError) throw parentUpdateError;

      const confirmed={...live,customers_contacted:overallCustomers,appointments:overallAppointments,remarks:overallRemarks||null,updated_at:now};
      const idx=S.updates.findIndex(x=>String(x.id)===String(live.id));
      if(idx>=0) S.updates[idx]={...S.updates[idx],...confirmed}; else S.updates.push(confirmed);

      // Refresh every dependent surface from the permanent rows.
      updRefreshCardSummary(card,confirmed,freshRows);
      panel.classList.add('hidden');
      await updRefreshAppointmentCalendarCache().catch(e=>console.warn('[APPOINTMENT CALENDAR REFRESH FAILED]',e));
      syncAfterUpdateChange();
      toast(current?'Entry updated permanently':'Entry saved permanently','success');
      // Regenerate the complete current-day email from permanent daily_entries data.
      await regenerateDailyWorkUpdateEmailSafe(live.owner_id || S.session.user.id);
    }catch(e){
      console.error('[UPDATES ENTRY SAVE FAILED]',e);
      toast('Could not save entry: '+(e?.message||'Unknown database error'),'error');
    }finally{setLoading(btn,false);}
  });
}

function updRefreshCardSummary(card,rec,rows){
  const total=updAuthoritativeTotalCustomers(rec);
  /* Contacted is authoritative from Data Hub feedback. Daily entries remain historical
     work logs and are rendered below without changing this counter. */
  const _dm=dhGetDatabaseMetrics(rec.assignment_id);
  const contacted=_dm ? _dm.contacted : Math.max(0,Number(rec.customers_contacted||0));
  const pct=total>0?Math.min(100,(contacted/total)*100):0;
  const count=rows.length;
  const ce=$('[data-role="contacted-total"]',card), pp=$('[data-role="progress-pct"]',card), pf=$('[data-role="progress-fill"]',card), ec=$('[data-role="entry-count"]',card), ss=$('[data-role="save-state"]',card), hist=$('[data-role="history"]',card);
  const st=$('[data-role="stat-total"]',card), sc=$('[data-role="stat-contacted"]',card), sp=$('[data-role="stat-pending"]',card);
  if(st) st.textContent=total.toLocaleString();
  if(sc) sc.textContent=contacted.toLocaleString();
  if(sp) sp.textContent=Math.max(0,total-contacted).toLocaleString();
  if(ce) ce.textContent=contacted.toLocaleString();
  if(pp) pp.textContent=pct.toFixed(2)+'%';
  if(pf) pf.style.width=pct+'%';
  if(ec) ec.textContent=`${count} ${count===1?'entry':'entries'}`;
  if(ss) ss.textContent='✓ Permanently saved';
  if(hist){
    if(!rows.length){ hist.innerHTML=''; return; }
    const sorted=[...rows].sort((a,b)=>String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||'')));
    hist.innerHTML=`<div class="upd-history-head"><strong>Previous Entries</strong><span>${sorted.length}</span></div>`+
      sorted.map((r,i)=>{
        const v=updParseDailyRow(r);
        const friendly=updEntryFormatDateTime(r);
        const raw=r.updated_at||r.created_at||'';
        return `<div class="upd-history-row"><div><b>Entry ${sorted.length-i}</b><span>${esc(updEntryFormatDate(r.entry_date))}</span></div><div><strong>${v.customers.toLocaleString()}</strong> contacted</div><div class="upd-history-time" title="Saved entry date and time">${esc(friendly)}${raw ? `<small class="upd-history-updated">Saved/edited: ${esc(new Date(raw).toLocaleString(undefined,{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}))}</small>` : ''}</div></div>`;
      }).join('');
  }
}

async function wireDailyUpdateCard(card){
  const id=card.dataset.updId;
  const rec=S.updates.find(u=>String(u.id)===String(id));
  if(!rec) return;
  const assignedDb=(S.databases||[]).find(d=>String(d.id)===String(rec.assignment_id)||String(d.name)===String(rec.database_name));
  const isAssignedUser=!!assignedDb && String(assignedDb.assigned_user_id)===String(S.session.user.id);
  const isOwner=String(rec.owner_id)===String(S.session.user.id);
  const canEdit=S.isAdmin || isAssignedUser;
  const rows=await updLoadDailyRows(id).catch(e=>{console.error('[UPDATE HISTORY LOAD FAILED]',e);return[];});

  /* Feedback is now the authoritative contacted count. Daily entries remain permanent
     history for appointments/remarks and are never deleted or used to increment contacts. */
  let effectiveRec=rec;
  try{
    // Cache-first (patched on every confirmed save); network only if the database was never measured.
    const res=await dhRefreshDatabaseMetrics(rec.assignment_id||assignedDb?.id);
    const m=res.ok ? res.metrics : dhGetDatabaseMetrics(rec.assignment_id||assignedDb?.id);
    const live=S.updates.find(u=>String(u.id)===String(id)) || rec;
    if(m) effectiveRec={...live,total_customers:m.total,customers_contacted:m.contacted};
    else console.warn('[FEEDBACK METRICS UNAVAILABLE] showing stored values');
  }catch(e){console.warn('[FEEDBACK CONTACTED RECONCILIATION FAILED]',e);}
  updRefreshCardSummary(card,effectiveRec,rows);

  $('[data-role="entry"]',card)?.addEventListener('click',()=>updRenderEntryPanel(card,rows,updEntryToday(),null));
  $('[data-role="edit"]',card)?.addEventListener('click',()=>{
    const date=rows[0]?.entry_date||updEntryToday();
    updRenderEntryPanel(card,rows,date,rows[0]?.id||null);
  });
  $('[data-role="reviews"]',card)?.addEventListener('click',()=>{
    openUpdateReviews(rec);
  });

  const deleteHandler=async(btn)=>{
    confirmAction('Delete this update?',`This removes the update card for "${esc(rec.database_name||'')}" only. The Data Hub database remains intact.`,async()=>{
      setLoading(btn,true);
      try{
        const {error}=await supa.from('updates').delete().eq('id',id);
        if(error) throw error;
        try{await supa.from('daily_entries').delete().eq('update_id',id);}catch(_){ }
        S.updates=S.updates.filter(u=>String(u.id)!==String(id));
        card.remove(); syncAfterUpdateChange();
        toast('Update deleted');
      }catch(e){toast('Failed to delete: '+(e?.message||'Unknown error'),'error');}
      finally{setLoading(btn,false);}
    });
  };
  $('[data-role="delete-card"]',card)?.addEventListener('click',e=>{e.stopPropagation();deleteHandler(e.currentTarget);});
  $('[data-role="delete-inline"]',card)?.addEventListener('click',e=>{e.stopPropagation();deleteHandler(e.currentTarget);});
}

function renderUpdatesPage(){
  populateUpdateFilterOptions();
  renderUpdatesKPISummary();
  renderUpdatesSidebar();
  renderTeamWorkCards(); // additive: auto-calculated live team cards (USER WORK UPDATE SYSTEM)
  populateTwuExportUserSelect(); // additive
  const rows = filteredUpdateRows();
  if (!myUpdates().length){
    $('#upd-card-grid').innerHTML = `<div class="duc-empty">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" style="width:40px;height:40px;margin:0 auto 16px;"><path d="M12 20a8 8 0 1 0-8-8"/><path d="M12 8v4l3 2"/><path d="M4 4v4h4"/></svg>
      <div class="t">No Updates Yet</div>
      <div class="d">Update cards are created automatically the moment an Admin assigns you a database — nothing to set up here.</div>
    </div>`;
    return;
  }
  if (!rows.length){
    $('#upd-card-grid').innerHTML = `<div class="analytics-empty" style="grid-column:1/-1;">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20a8 8 0 1 0-8-8"/><path d="M12 8v4l3 2"/></svg>
      <div>No updates match these filters.</div>
    </div>`;
    return;
  }
  $('#upd-card-grid').innerHTML = rows.map(dailyUpdateCardHtml).join('');
  $all('.upd-card-v4', $('#upd-card-grid')).forEach(wireDailyUpdateCard);
}
