/* ==========================================================================
   SIMPLE XLSX EXPORT
   - ONE sheet only: "Updates Export".
   - Every permanent daily sub-entry is included as its own row.
   - Overall Contacted continues from the complete saved history.
   - Dates/times are human-readable; no raw ISO timestamps or technical IDs.
   ========================================================================== */
function updatesXlsxFilename(){
  const raw = (S.profile?.username && String(S.profile.username).trim())
    || (S.profile?.full_name ? String(S.profile.full_name).replace(/\s+/g,'') : '')
    || (S.session?.user?.email ? S.session.user.email.split('@')[0] : 'user');
  const safe = raw.replace(/[^a-zA-Z0-9_-]/g,'') || 'user';
  return `${safe}_work_update.xlsx`;
}
function updExportFriendlyDate(v){
  if(!v) return '';
  const d=new Date(`${v}T00:00:00`);
  if(Number.isNaN(d.getTime())) return String(v);
  return d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
}
function updExportFriendlyTime(v){
  if(!v) return '';
  const m=String(v).match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if(!m) return String(v);
  const h=Number(m[1]), min=m[2], sec=m[3]||'';
  if(!Number.isInteger(h)||h<0||h>23) return String(v);
  const ap=h>=12?'PM':'AM', hh=(h%12)||12;
  return `${String(hh).padStart(2,'0')}:${min}${sec?':'+sec:''} ${ap}`;
}
function updExportFriendlyDateTime(v){
  if(!v) return '';
  const d=new Date(v);
  if(Number.isNaN(d.getTime())) return String(v);
  return d.toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});
}
async function updFetchAllHistory(updateIds){
  const out=[];
  const pageSize=1000;
  for(const id of updateIds){
    let from=0;
    while(true){
      let q=supa.from('daily_entries').select('*').eq('update_id',id)
        .order('entry_date',{ascending:true}).order('entry_time',{ascending:true}).order('created_at',{ascending:true})
        .range(from,from+pageSize-1);
      if(!S.isAdmin) q=q.eq('owner_id',S.session.user.id);
      const {data,error}=await q;
      if(error) throw error;
      const batch=data||[];
      out.push(...batch);
      if(batch.length<pageSize) break;
      from+=pageSize;
    }
  }
  return out;
}
function updExcelHeaderSimple(row){
  row.height=30;
  row.eachCell(cell=>{
    cell.font={name:'Aptos',size:11,bold:true,color:{argb:'FFFFFFFF'}};
    cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1F4E78'}};
    cell.alignment={vertical:'middle',horizontal:'center',wrapText:true};
    cell.border={top:{style:'thin',color:{argb:'FF173A5A'}},bottom:{style:'thin',color:{argb:'FF173A5A'}}};
  });
}
function updExcelBodySimple(row,shade){
  row.height=24;
  row.eachCell((cell,col)=>{
    cell.font={name:'Aptos',size:10,color:{argb:'FF17212B'}};
    cell.alignment={vertical:'middle',horizontal:[3,4,5,6,7,8,9].includes(col)?'center':'left',wrapText:true};
    cell.border={bottom:{style:'hair',color:{argb:'FFE0E6EB'}}};
    if(shade) cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF5F8FA'}};
  });
}
$('#upd-export-xlsx-btn').addEventListener('click', async ()=>{
  const rows = filteredUpdateRows();
  if (!rows.length){ toast('No updates to export', 'error'); return; }
  const btn=$('#upd-export-xlsx-btn');
  setLoading(btn,true);
  try{
    const historyRows=await updFetchAllHistory(rows.map(u=>u.id));
    const byUpdate=new Map();
    historyRows.forEach(r=>{
      const k=String(r.update_id);
      if(!byUpdate.has(k)) byUpdate.set(k,[]);
      byUpdate.get(k).push(r);
    });
    const ratingsByAssignment = new Map();
    (S.ratings||[]).forEach(r=>{
      if (r.rating == null || r.skipped) return;
      const key = `${String(r.assignment_id)}::${String(r.user_id)}`;
      ratingsByAssignment.set(key, r);
    });

    const wb=new ExcelJS.Workbook();
    wb.creator='Swift Cargo';
    wb.lastModifiedBy=S.profile?.full_name||S.profile?.username||'Swift Cargo';
    wb.created=new Date();
    wb.modified=new Date();
    wb.properties={title:'Swift Cargo Updates Export',subject:'Permanent daily customer-contact entries'};

    // ONE SIMPLE SHEET — no summary/detail/timeline tabs.
    const ws=wb.addWorksheet('Updates Export',{views:[{showGridLines:false}]});
    ws.columns=[
      {header:'Database',key:'db',width:30},
      {header:'Assigned To',key:'user',width:22},
      {header:'Entry Date',key:'date',width:16},
      {header:'Entry Time',key:'time',width:14},
      {header:'Contacted Today',key:'daily',width:18},
      {header:'Overall Contacted',key:'overall',width:19},
      {header:'Pending',key:'pending',width:14},
      {header:'Appointments',key:'appt',width:15},
      {header:'Rating',key:'rating',width:11},
      {header:'Review',key:'review',width:42},
      {header:'Remarks',key:'remarks',width:44},
      {header:'Saved / Edited At',key:'saved',width:25}
    ];
    updExcelHeaderSimple(ws.getRow(1));

    let exportedEntries=0;
    let excelRowIndex=0;

    rows.forEach(u=>{
      const total=Number(u.total_customers||0);
      const h=[...(byUpdate.get(String(u.id))||[])].sort((a,b)=>{
        const ad=`${a.entry_date||''} ${a.entry_time||''} ${a.created_at||''}`;
        const bd=`${b.entry_date||''} ${b.entry_time||''} ${b.created_at||''}`;
        return ad.localeCompare(bd);
      });

      // If there are no sub-entries, retain one clean row so the export still
      // represents the selected update.
      if(!h.length){
        const contacted=Math.max(0,Number(u.customers_contacted||0));
        const row=ws.addRow({
          db:u.database_name||'', user:updUserDisplay(u), date:updExportFriendlyDate(u.assigned_date), time:'',
          daily:0, overall:contacted, pending:Math.max(0,total-contacted), appt:Number(u.appointments||0),
          rating:(ratingsByAssignment.get(`${String(u.assignment_id)}::${String(u.owner_id)}`)?.rating ?? ''),
          review:(ratingsByAssignment.get(`${String(u.assignment_id)}::${String(u.owner_id)}`)?.review ?? ''),
          remarks:u.remarks||'', saved:updExportFriendlyDateTime(u.updated_at||u.created_at)
        });
        updExcelBodySimple(row,excelRowIndex++%2===1);
        return;
      }

      let running=0;
      h.forEach(r=>{
        const v=updParseDailyRow(r);
        running+=Math.max(0,Number(v.customers)||0);
        exportedEntries++;
        const row=ws.addRow({
          db:r.database_name||u.database_name||'',
          user:updUserDisplay(u),
          date:updExportFriendlyDate(r.entry_date),
          time:updExportFriendlyTime(r.entry_time),
          daily:v.customers,
          overall:running,
          pending:Math.max(0,total-running),
          appt:v.appointments,
          rating:(ratingsByAssignment.get(`${String(u.assignment_id)}::${String(u.owner_id)}`)?.rating ?? ''),
          review:(ratingsByAssignment.get(`${String(u.assignment_id)}::${String(u.owner_id)}`)?.review ?? ''),
          remarks:v.remarks||'',
          saved:updExportFriendlyDateTime(r.updated_at||r.created_at)
        });
        updExcelBodySimple(row,excelRowIndex++%2===1);
      });
    });

    ws.views=[{state:'frozen',ySplit:1,showGridLines:false}];
    if(ws.rowCount>1) ws.autoFilter={from:{row:1,column:1},to:{row:1,column:ws.columnCount}};
    ws.properties.tabColor='1F4E78';
    ws.pageSetup={orientation:'landscape',fitToPage:true,fitToWidth:1,fitToHeight:0,paperSize:9};
    ws.pageMargins={left:0.25,right:0.25,top:0.5,bottom:0.5,header:0.2,footer:0.2};
    ws.headerFooter.oddFooter='Swift Cargo | Page &P of &N';

    // Friendly number formats and visual emphasis without making the sheet busy.
    for(let r=2;r<=ws.rowCount;r++){
      ws.getCell(r,5).numFmt='#,##0';
      ws.getCell(r,6).numFmt='#,##0';
      ws.getCell(r,7).numFmt='#,##0';
      ws.getCell(r,8).numFmt='#,##0';
    }

    const buffer=await wb.xlsx.writeBuffer();
    const blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url; a.download=updatesXlsxFilename(); document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),1500);
    toast(`Exported ${rows.length} update(s) with ${exportedEntries} permanent sub-entry record(s) in 1 sheet`,'success');
  }catch(e){
    console.error('[UPDATES XLSX EXPORT FAILED]',e);
    toast('XLSX export failed: '+(e?.message||'Unknown error'),'error');
  }finally{setLoading(btn,false);}
});

$('#upd-search').addEventListener('input', debounce((e)=>{ S.updatesSearch = e.target.value; renderUpdatesPage(); }, 200));

/* ==========================================================================
   ANALYTICS
   ========================================================================== */
function analyticsScopedDbs(){
  return myAssignedDatabases();
}
function analyticsScopedUpdates(){
  return S.isAdmin ? S.updates : S.updates.filter(u=>u.owner_id===S.session.user.id);
}
/* Admin-only: total/assigned/unassigned database counts plus a per-user
   breakdown (databases, customers, contacted today, appointments). Matches
   updates to a database by name, mirroring the existing convention used
   throughout analytics (databases don't have a 1:1 FK to updates). */
function analyticsAssignmentOverview(){
  const dbs = S.databases;
  const total = dbs.length;
  const assigned = dbs.filter(d=>d.assigned_user_id).length;
  const unassigned = total - assigned;
  const byUser = {};
  dbs.forEach(d=>{
    const key = d.assigned_user_id || '__unassigned__';
    if (!byUser[key]) byUser[key] = { name: d.assigned_user_name || 'Unassigned', databases:0, customers:0, contactedToday:0, appointments:0 };
    byUser[key].databases += 1;
  });
  const todayStr = new Date().toDateString();
  const latestByDatabase = new Map();
  S.updates.forEach(u=>{
    const db = dbs.find(d=>d.name===u.database_name);
    const key = db?.assigned_user_id || '__unassigned__';
    if (!byUser[key]) return;
    const dbKey=String(u.id||u.assignment_id||u.database_name||'');
    const prior=latestByDatabase.get(dbKey);
    if (!prior || Number(u.customers_contacted||0) >= Number(prior.customers_contacted||0)) latestByDatabase.set(dbKey,u);
  });
  latestByDatabase.forEach(u=>{
    const db = dbs.find(d=>d.name===u.database_name);
    const key = db?.assigned_user_id || '__unassigned__';
    if (!byUser[key]) return;
    byUser[key].customers += Number(u.total_customers||0);
    if (new Date(u.assigned_date).toDateString()===todayStr) byUser[key].contactedToday += Number(u.customers_contacted||0);
    byUser[key].appointments += Number(u.appointments||0);
  });
  return { total, assigned, unassigned, byUser: Object.values(byUser).sort((a,b)=>b.databases-a.databases) };
}

