    'Assigned Date': fmtDate(r.assignedDate),
    'Total Customers': r.totalCustomers || 0,
    'Customers Contacted Today': r.contactedToday || 0,
    'Appointments': r.appointments || 0,
    'Contact %': r.contactPct || 0,
    'Status': ANALYTICS_STATUS_LABELS[r.status] || r.status,
    'Last Updated': r.lastUpdated ? fmtDateTime(r.lastUpdated) : '',
