async function loadAndRenderRecordHistory(recordId, container){
  container.innerHTML = `<div class="ws-history-row">Loading…</div>`;
  const { data, error } = await supa.from('record_history').select('*').eq('record_id', recordId).order('updated_at', { ascending:false }).limit(50);
  if (error || !data || !data.length){ container.innerHTML = `<div class="ws-history-row">No history yet.</div>`; return; }
  container.innerHTML = data.map(h=>{
    const meta = wsFieldMeta(h.field_name);
    return `<div class="ws-history-row"><b>${esc(meta?meta.label:h.field_name)}</b> changed from "${esc(h.old_value||'—')}" to "${esc(h.new_value||'—')}" by ${esc(h.updated_by_name||'someone')} · ${fmtDateTime(h.updated_at)}</div>`;
  }).join('');
}

/* ---- Instant autosave (no Save button), optimistic update + rollback ---- */
const _wsSaveTimers = {};
function autosaveRecordField(rec, field, value){
  // Debounce per record+field so rapid typing (text/date) doesn't spam Supabase.
  const timerKey = rec.id + ':' + field;
  clearTimeout(_wsSaveTimers[timerKey]);
  _wsSaveTimers[timerKey] = setTimeout(()=> doSaveRecordField(rec, field, value), 150);
}
async function doSaveRecordField(rec, field, value){
  const pill = $(`[data-ws-pill="${field}"]`);
  const prevValue = rec[field];
  if (prevValue === value) return; // nothing changed — avoid an unnecessary DB call
  // Optimistic UI update
  rec[field] = value;
  const nowIso = new Date().toISOString();
  if (pill){ pill.className = 'ws-savepill saving'; pill.textContent = 'Saving…'; }
  try{
    const { error } = await supa.from('records')
      .update({ [field]: value, updated_at: nowIso, updated_by: S.session.user.id })
      .eq('id', rec.id);
    if (error) throw error;
    rec.updated_at = nowIso; rec.updated_by = S.session.user.id;
    if (DH_ELIGIBILITY_PHONE_FIELDS.includes(field) || field==='feedback'){
      dhPatchRecordInCaches(rec.id,{[field]:value});
      if (rec.database_id!=null) dhRefreshDatabaseMetrics(rec.database_id).then(res=>{ if(res.ok) dhRerenderMetricViews(); });
    }
    if (pill){ pill.className = 'ws-savepill saved'; pill.textContent = 'Saved ✓'; setTimeout(()=> pill.classList.add('hidden'), 1800); }
    // Best-effort audit trail — failures here never block the field save itself
    supa.from('record_history').insert({
      record_id: rec.id, field_name: field, old_value: prevValue!=null?String(prevValue):null, new_value: value!=null?String(value):null,
      updated_by: S.session.user.id, updated_by_name: S.profile?.full_name || S.session.user.email, updated_at: nowIso,
    }).then(({error:histErr})=>{ if (histErr) console.warn('record_history insert failed (non-blocking):', histErr.message); });
    // Refresh anything currently on screen that derives from this record
    if (S.page==='updates') renderTeamWorkCards();
    if (S.page==='alldata') renderVirtualGrid();
    if (S.page==='dashboard') renderDashboard();
    // A follow-up date is a live calendar activity; refresh immediately when
    // the Calendar is open so the new 📞 highlight appears without reload.
    if (S.page==='calendar' && (field==='follow_up_date' || field==='contact_status')) renderCalendar();
  } catch(error){
    rec[field] = prevValue; // rollback
    if (pill){ pill.className = 'ws-savepill error'; pill.textContent = 'Save failed'; }
    toast('Could not save ' + (wsFieldMeta(field)?.label||field) + ' — ' + error.message, 'error');
  }
}

/* ---- Auto-calculated Update Cards (admin) — pure derived data, nothing
   is stored twice. Recomputed on every load and every realtime event. ---- */
function teamWorkSummaries(){

  const byUser = {};
  const databaseMap = {};

  // ============================================================
  // 1. CURRENT DATABASE ASSIGNMENTS
  // ============================================================

  (S.databases || []).forEach(db => {

    if (!db || !db.id) return;

    const databaseId = String(db.id);

    databaseMap[databaseId] = {
      assignedUserId: db.assigned_user_id
        ? String(db.assigned_user_id)
        : null,

      assignedUserName:
        db.assigned_user_name ||
        db.assigned_to ||
        'Unassigned',

      status: db.status || ''
    };

  });


  // ============================================================
  // 2. GROUP RECORDS BY CURRENT DATABASE ASSIGNEE
  // ============================================================

  (S.records || []).forEach(record => {

    if (!record || !record.database_id) return;

    const databaseId = String(record.database_id);
    const db = databaseMap[databaseId];

    if (!db || !db.assignedUserId) return;

    const userId = db.assignedUserId;

    if (!byUser[userId]) {

      byUser[userId] = {
        rows: [],
        databaseIds: []
      };

    }

    byUser[userId].rows.push(record);

    if (!byUser[userId].databaseIds.includes(databaseId)) {
      byUser[userId].databaseIds.push(databaseId);
    }

  });


  // ============================================================
  // 3. TODAY
  // ============================================================

  const todayStr = new Date().toDateString();


  // ============================================================
  // 4. BUILD TEAM CARDS
  // ============================================================

  return Object.entries(byUser)

    .map(([userId, data]) => {

      const rows = data.rows || [];

      const profile =
        (S.profiles || []).find(
          p => String(p.id) === String(userId)
        )
        ||
        (
          S.profile &&
          String(S.profile.id) === String(userId)
            ? S.profile
            : null
        );


      // ========================================================
      // TOTAL
      // ========================================================

      const total = rows.length;


      // ========================================================
      // CONTACTED TODAY
      // ========================================================

      const contactedToday = rows.filter(record => {

        if (!record.contacted_date) return false;

        const d = new Date(record.contacted_date);

        return (
          !isNaN(d.getTime()) &&
          d.toDateString() === todayStr
        );

      }).length;


      // ========================================================
      // COMPLETED
      //
      // A customer is considered completed when:
      // Contact Status = Contacted
      // OR
      // Customer Status = Converted
      // ========================================================

      const completed = rows.filter(record => {

        const contactStatus =
          String(record.contact_status || '')
            .trim()
            .toLowerCase();

        const customerStatus =
          String(record.customer_status || '')
            .trim()
            .toLowerCase();

        return (
          contactStatus === 'contacted' ||
          customerStatus === 'converted'
        );

      }).length;


      // ========================================================
      // PENDING
      // ========================================================

      const pending =
        Math.max(0, total - completed);


      // ========================================================
      // PROGRESS
      // ========================================================

      const progress =
        total > 0
          ? Math.round((completed / total) * 100)
          : 0;


      // ========================================================
      // TODAY'S UPDATES
      //
      // This is different from Contacted Today.
      // It counts records actually updated today.
      // ========================================================

      const todaysUpdates = rows.filter(record => {

        if (!record.updated_at) return false;

        const d = new Date(record.updated_at);

        return (
          !isNaN(d.getTime()) &&
          d.toDateString() === todayStr
        );

      }).length;


      // ========================================================
      // LAST UPDATED
      // ========================================================

      let lastRow = null;

      rows.forEach(record => {

        if (!record.updated_at) return;

        if (
          !lastRow ||
          new Date(record.updated_at) >
          new Date(lastRow.updated_at)
        ) {

          lastRow = record;

        }

      });


      // ========================================================
      // USER NAME
      // ========================================================

      const name =
        profile?.full_name ||
        profile?.username ||
        data.databaseIds
          .map(id => databaseMap[id]?.assignedUserName)
          .find(Boolean) ||
        'Unknown user';


      // ========================================================
      // RETURN
      // ========================================================

      return {

        ownerId: userId,

        name,

        total,

        contactedToday,

        pending,

        completed,

        progress,

        todaysUpdates,

        lastUpdated:
          lastRow?.updated_at || null,

        remarks:
          (
            lastRow?.remark &&
            String(lastRow.remark).trim()
          ) ||
          'No remarks',

        databaseIds:
          data.databaseIds

      };

    })

    .filter(summary => summary.total > 0)

    .sort((a, b) => b.total - a.total);

}
function twuProgressBadge(progress){
  if (progress>=80) return { label:'Completed', pill:'pill-green' };
  if (progress>=1) return { label:'In Progress', pill:'pill-blue' };
  return { label:'Not Started', pill:'pill-orange' };
}
function renderTeamWorkCards(){
  const section = $('#twu-section'); const grid = $('#twu-card-grid');
  if (!section || !grid) return;
  if (!S.isAdmin){ section.classList.add('hidden'); return; } // per-record editing for regular users lives in the drawer / Data Hub instead
  section.classList.remove('hidden');
  const summaries = teamWorkSummaries();
  if (!summaries.length){ grid.innerHTML = `<div class="twu-empty">No customers have been assigned to any user yet.</div>`; return; }
  grid.innerHTML = summaries.map(s=>{
    const badge = twuProgressBadge(s.progress);
    return `<div class="twu-card">
      <div class="twu-card-head">
        <div class="twu-user"><div class="twu-avatar">${esc(initials(s.name))}</div><div class="twu-user-name" title="${esc(s.name)}">${esc(s.name)}</div></div>
        <span class="pill ${badge.pill}">${badge.label}</span>
      </div>
      <div class="twu-stats">
        <div class="twu-stat"><div class="l">Total Customers</div><div class="v">${s.total.toLocaleString()}</div></div>
        <div class="twu-stat"><div class="l">Contacted Today</div><div class="v">${s.contactedToday.toLocaleString()}</div></div>
        <div class="twu-stat"><div class="l">Pending</div><div class="v">${s.pending.toLocaleString()}</div></div>
        <div class="twu-stat"><div class="l">Today's Updates</div><div class="v">${s.contactedToday.toLocaleString()}</div></div>
      </div>
      <div class="twu-progress-row"><span style="font-size:12.5px; font-weight:700; color:var(--text-secondary);">Progress</span><span style="font-weight:800; font-size:14px;">${s.progress}%</span></div>
      <div class="twu-progress-outer"><div class="twu-progress-inner" style="width:${s.progress}%;"></div></div>
      <div class="twu-remarks" title="${esc(s.remarks)}">${esc(s.remarks)}</div>
      <div class="twu-foot"><span>Last Updated</span><span>${s.lastUpdated ? fmtDateTime(s.lastUpdated) : '—'}</span></div>
    </div>`;
  }).join('');
}

/* ---- Realtime sync: listen for INSERT/UPDATE/DELETE on `records` so the
   Admin dashboard (and any other open user's grid) reflects changes within
   seconds, with no page refresh. A single shared channel + a debounced
   re-render keeps this efficient even with many simultaneous editors. ---- */
let _twuRerenderTimer = null;
function scheduleTwuRerender(){
  clearTimeout(_twuRerenderTimer);
  _twuRerenderTimer = setTimeout(()=>{
    const paint = ()=>{
      flagDuplicates(); syncFeedbackLabels();
      if (S.page==='alldata') refreshAllDataView();
      if (S.page==='updates') renderTeamWorkCards();
      if (S.page==='dashboard') renderDashboard();
    };
    if (window.requestIdleCallback) requestIdleCallback(paint, {timeout:700});
    else requestAnimationFrame(paint);
  }, 250);
}
function upsertLocalRecord(row){
  if (!row) return;
  const idx = S.records.findIndex(r=>r.id===row.id);
  if (idx>-1) S.records[idx] = { ...S.records[idx], ...row };
  else S.records.unshift(row);
}
function removeLocalRecord(id){
  const idx = S.records.findIndex(r=>r.id===id);
  if (idx>-1) S.records.splice(idx,1);
}
function handleRecordsRealtimeEvent(payload){
  if (payload.eventType === 'DELETE'){ removeLocalRecord(payload.old?.id); }
  else { upsertLocalRecord(payload.new); }
  scheduleTwuRerender();
}
async function recordsPollForChanges(){
  if (document.hidden || !S.session || S._recordsPollInFlight) return;
  S._recordsPollInFlight=true;
  // Fallback safety net (same pattern as analyticsPollForChanges) in case the
  // `records` table hasn't been added to the supabase_realtime publication.
  try{
    const uid = S.session?.user?.id; if (!uid) return;
    let q = supa.from('records').select('*').order('updated_at', { ascending:false }).limit(500);
    // BUGFIX: this used to scope to `owner_id = auth.uid()`, but owner_id is a
    // point-in-time snapshot of who imported/was-assigned the record's database
    // AT IMPORT TIME — it is never rewritten when an Admin (re)assigns the
    // database afterwards (by design, see applyDbAssignment/spec #5). Scoping
    // the poll to owner_id therefore silently returned 0 rows for anyone who
    // became the assigned user via a later assignment/reassignment, even
    // though the `records` RLS policy (parent-database-based) would happily
    // return their rows. Assignment is database-level, so the poll must be
    // scoped the same way: by the user's currently-assigned database IDs.
    if (!S.isAdmin){
      const dbIds = [...myAssignedDatabaseIds()];
      if (!dbIds.length) return; // no assigned databases — nothing to poll
      q = q.in('database_id', dbIds);
    }
    const { data, error } = await q;
    if (error || !data) return;
    let changed = false;
    data.forEach(row=>{
      const seen = S._recordsSeen.get(row.id);
      const stamp = row.updated_at || row.import_date || '';
      if (seen === undefined || seen !== stamp){ S._recordsSeen.set(row.id, stamp); upsertLocalRecord(row); changed = true; }
    });
    if (changed) scheduleTwuRerender();
  } catch(e){ console.error('Records poll failed:', e); }
  finally{ S._recordsPollInFlight=false; }
}
function initRecordsWorkSync(){
  (S._recordsChannel ? [S._recordsChannel] : []).forEach(ch=>{try{supa.removeChannel(ch);}catch(e){console.warn('[records realtime cleanup]',e);}});
  S._recordsChannel=null;
  S._recordsPollInFlight=false;
  S._recordsSeen = new Map();
  S.records.forEach(r=> S._recordsSeen.set(r.id, r.updated_at || r.import_date || ''));

  const channelConfig = { event:'*', schema:'public', table:'records' };
  // BUGFIX: was `owner_id=eq.${uid}` — owner_id is a point-in-time snapshot set at
  // import/first-assignment and is intentionally never rewritten on reassignment
  // (assignment lives on `databases`, not on every record — see spec #5/#12). Filtering
  // realtime by owner_id meant a user who gained access to a database via a LATER
  // assignment never received live updates for its records (and, combined with the
  // matching bug in recordsPollForChanges, could look like "no records" while the
  // Data Hub table itself — which queries by database_id — showed them correctly).
  // Scope by the user's currently-assigned database IDs instead, matching the same
  // database-level rule enforced by RLS. If they have no assigned databases yet,
  // skip subscribing entirely — there's nothing to listen for.
  let skip = false;
  if (!S.isAdmin){
    const dbIds = [...myAssignedDatabaseIds()];
    if (!dbIds.length) skip = true;
    else channelConfig.filter = `database_id=in.(${dbIds.join(',')})`;
  }
  if (!skip){
    S._recordsChannel=supa.channel('public:records-work-sync')
      .on('postgres_changes',channelConfig,handleRecordsRealtimeEvent)
      .subscribe(status=>console.log('[records realtime] work-sync channel:',status));
  }

  if (S._recordsPollTimer) clearInterval(S._recordsPollTimer);
  S._recordsPollTimer = setInterval(recordsPollForChanges, 30000);
}

/* ---- Export: "<Username>_work_updates.xlsx" (plural, per spec) — separate
   from the existing Updates-page XLSX export above (that one is untouched). ---- */
function twuSanitizeFilenamePart(raw){
  return String(raw||'user').replace(/\s+/g,'').replace(/[^a-zA-Z0-9_-]/g,'') || 'user';
}
function twuExportFilenameFor(profile, fallbackEmail){
  const raw = (profile?.username && String(profile.username).trim())
    || (profile?.full_name ? String(profile.full_name) : '')
    || (fallbackEmail ? fallbackEmail.split('@')[0] : 'user');
  return `${twuSanitizeFilenamePart(raw)}_work_updates.xlsx`;
}
function twuExportRowsFor(ownerId){
  const dbById = {}; S.databases.forEach(d=> dbById[d.id]=d);
  return S.records.filter(r=>r.owner_id===ownerId).map(r=>{
    const db = dbById[r.database_id];
    return {
      'Customer Name': r.contact_person || '',
      'Company': r.company_name || '',
      'Phone': r.mobile_phone_1 || r.work_phone_1 || '',
      'Email': r.business_email_1 || r.personal_email_1 || '',
      'Assigned Date': fmtDate(db?.assigned_at || r.import_date),
      'Assigned By': db?.assigned_by_name || '',
      'Updated Date': fmtDate(r.updated_at),
      'Contact Status': r.contact_status || '',
      'Meeting Status': r.meeting_status || '',
      'Call Status': r.phone_status || '',
      'Remarks': r.remark || '',
      'Follow-up Date': fmtDate(r.follow_up_date),
      'Last Updated': fmtDateTime(r.updated_at),
      'Updated By': r.updated_by === S.session.user.id ? (S.profile?.full_name||S.session.user.email) : (S.profiles.find(p=>p.id===r.updated_by)?.full_name || ''),
    };
  });
}
function populateTwuExportUserSelect(){
  const sel = $('#twu-export-user-select'); if (!sel) return;
  sel.classList.toggle('hidden', !S.isAdmin);
  if (!S.isAdmin) return;
  const owners = [...new Set(S.records.map(r=>r.owner_id).filter(Boolean))];
  const options = owners.map(id=>{
    const p = S.profiles.find(pr=>pr.id===id);
    return { id, name: p?.full_name || p?.username || 'Unknown user' };
  }).sort((a,b)=> a.name.localeCompare(b.name));
  sel.innerHTML = options.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('');
}
$('#twu-export-btn').addEventListener('click', ()=>{
  const ownerId = S.isAdmin ? $('#twu-export-user-select').value : S.session.user.id;
  if (!ownerId){ toast('No user selected to export', 'error'); return; }
  const rows = twuExportRowsFor(ownerId);
  if (!rows.length){ toast('No customer records to export for this user', 'error'); return; }
  const profile = S.isAdmin ? S.profiles.find(p=>p.id===ownerId) : S.profile;
  const ws = XLSX.utils.json_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Work Updates');
  XLSX.writeFile(wb, twuExportFilenameFor(profile, S.session.user.email));
  toast('Exported customer updates to XLSX');
  logAudit('export_work_updates_xlsx', { owner_id: ownerId, count: rows.length });
});


/* ADMIN EMAIL AUTOMATION — STORAGE ONLY
   The Company Profile PDF remains permanently stored in Supabase Storage.
   No Resend API key, Edge Function, or automatic email sending is used.
*/
(function(){
  const BUCKET='avatars', PDF_PATH='email-automation/company-profile.pdf';
  const E=id=>document.getElementById(id);
  const status=(id,t,s='')=>{const x=E(id);if(x){x.textContent=t;x.classList.remove('ok','error');if(s)x.classList.add(s)}};
  const errShow=m=>{const x=E('email-auto-error');if(x){x.textContent=String(m||'Unexpected error');x.classList.remove('hidden')}};
  const errClear=()=>E('email-auto-error')?.classList.add('hidden');
  const subject=()=>String(E('email-auto-subject')?.value||'Swift Cargo Company Profile').trim()||'Swift Cargo Company Profile';
  const attachment=()=>({bucket:BUCKET,path:PDF_PATH,filename:'Swift Cargo Company Profile.pdf'});

  async function pdfStatus(){
    if(!supa||!S.session?.user) throw new Error('Your session has expired. Please sign in again.');
    const {data,error}=await supa.storage.from(BUCKET).list('email-automation',{limit:100,search:'company-profile.pdf',sortBy:{column:'updated_at',order:'desc'}});
    if(error) throw error;
    const file=(data||[]).find(x=>x.name==='company-profile.pdf'), ok=!!file;
    E('email-auto-storage-path').textContent=PDF_PATH;
    E('email-auto-storage-bucket').textContent=BUCKET;
    E('email-auto-file-name').textContent=ok?'Swift Cargo Company Profile.pdf':'No PDF uploaded';
    E('email-auto-file-sub').textContent=ok?'Permanently stored in Supabase Storage':'Upload a PDF to enable Company Profile downloads';
    E('email-auto-last-updated').textContent=ok&&file.updated_at?new Date(file.updated_at).toLocaleString():'—';
    status('email-auto-upload-status',ok?'Uploaded':'Not configured',ok?'ok':'');
    const s=E('email-auto-config-summary');
    if(s)s.textContent=ok?`PDF is available at ${BUCKET}/${PDF_PATH}. It will be attached locally when the user confirms the .eml download.`:'No Company Profile PDF is configured yet.';
    return {exists:ok,file};
  }

  async function refresh(){
    if(!S.isAdmin)return;
    try{await pdfStatus()}
    catch(e){
      status('email-auto-upload-status','Storage error','error');
      const s=E('email-auto-config-summary');
      if(s)s.textContent='Could not read Supabase Storage: '+(e?.message||e);
    }
  }

  async function upload(file){
    errClear();
    if(!S.isAdmin)return errShow('Admin access is required.');
    if(!file)return;
    if(file.type!=='application/pdf'&&!/\.pdf$/i.test(file.name))return errShow('Only PDF files are allowed.');
    try{
      status('email-auto-upload-status','Uploading…');
      const {error}=await supa.storage.from(BUCKET).upload(PDF_PATH,file,{upsert:true,contentType:'application/pdf',cacheControl:'3600'});
      if(error)throw error;
      E('email-auto-pdf-input').value='';
      await pdfStatus();
      toast('Company Profile PDF stored permanently','success');
    }catch(e){
      status('email-auto-upload-status','Upload failed','error');
      errShow('PDF upload failed: '+(e?.message||e));
    }
  }

  async function testAttachment(){
    errClear();
    try{
      const s=await pdfStatus();
      if(!s.exists)throw new Error('No Company Profile PDF is configured.');
      const {data,error}=await supa.storage.from(BUCKET).download(PDF_PATH);
      if(error)throw error;
      const u=URL.createObjectURL(data),a=document.createElement('a');
      a.href=u;a.download='Swift Cargo Company Profile.pdf';
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(u),1500);
      toast('Stored PDF attachment verified','success');
    }catch(e){
      errShow('Attachment test failed: '+(e?.message||e));
      toast('Attachment test failed','error');
    }
  }

  function save(){
    errClear();
    if(!S.isAdmin)return errShow('Admin access is required.');
    E('email-auto-subject').value=subject();
    const s=E('email-auto-config-summary');
    if(s)s.textContent=`Configuration saved. PDF: ${BUCKET}/${PDF_PATH}. Email sending is manual via .eml download after confirmation.`;
    toast('Email Automation configuration saved','success');
  }

  function bind(){
    if(E('email-auto-pdf-input')?.dataset.bound)return;
    E('email-auto-pdf-input')?.addEventListener('change',e=>upload(e.target.files?.[0]));
    E('email-auto-test-attachment')?.addEventListener('click',testAttachment);
    E('email-auto-refresh-status')?.addEventListener('click',refresh);
    E('email-auto-save')?.addEventListener('click',save);
    if(E('email-auto-pdf-input'))E('email-auto-pdf-input').dataset.bound='1';
  }

  window.SwiftEmailAutomation={BUCKET,PDF_PATH,attachment,pdfStatus,currentSubject:subject};
  bind();
  window.refreshSwiftEmailAutomation=refresh;
  setTimeout(()=>{if(S.isAdmin)refresh()},700);
})();

