S.dbAssignSearch = S.dbAssignSearch || '';
function renderDatabaseAssignments(){
  const listEl = $('#db-assign-list'); if (!listEl) return;
  const q = (S.dbAssignSearch||'').trim().toLowerCase();
  const rows = [...S.databases]
    .filter(d=> !q || [d.name, d.assigned_user_name, d.assigned_user_email, d.assigned_by_name].some(v=> String(v||'').toLowerCase().includes(q)))
    .sort((a,b)=> new Date(b.upload_date||0) - new Date(a.upload_date||0));
  $('#db-assign-count-pill').textContent = `${S.databases.length} database${S.databases.length===1?'':'s'}`;
  if (!rows.length){
    listEl.innerHTML = `<div class="aw-sb-empty" style="grid-column:1/-1;">No databases match.</div>`;
    return;
  }
  listEl.innerHTML = rows.map(d=>`
    <div class="upd2-card" data-db-id="${esc(d.id)}">
      <div class="upd2-head">
        <div class="upd2-avatar">${ICON_DB_CIRCLE}</div>
        <div class="upd2-head-info">
          <div class="upd2-dbname" title="${esc(d.name)}">${esc(d.name)}</div>
          <div class="upd2-assigned-label">Assigned To</div>
          <div class="upd2-assigned-name" title="${esc(d.assigned_user_name||'Unassigned')}">${esc(d.assigned_user_name || 'Unassigned')}</div>
          <div class="upd2-date">${esc(d.assigned_user_email || '')}</div>
        </div>
      </div>
      <div class="upd2-status ${d.assigned_user_id ? 'st-excellent' : 'st-low'}"><span class="upd2-dot ${d.assigned_user_id?'dot-excellent':'dot-low'}"></span>${d.assigned_user_id ? 'Assigned' : 'Unassigned'}</div>
      <div class="upd2-stats">
        <div class="upd2-stat"><div class="upd2-stat-num">${(d.customer_count||0).toLocaleString()}</div><div class="upd2-stat-label">Customers</div></div>
        <div class="upd2-stat"><div class="upd2-stat-num" style="font-size:14px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${esc(d.assigned_by_name||'—')}">${esc(d.assigned_by_name || '—')}</div><div class="upd2-stat-label">Assigned By</div></div>
        <div class="upd2-stat"><div class="upd2-stat-num" style="font-size:13px;">${d.assigned_at ? fmtDate(d.assigned_at) : '—'}</div><div class="upd2-stat-label">Assigned Date</div></div>
      </div>
      <div class="upd2-footer">Last Updated ${fmtDateTime(d.updated_at || d.upload_date)}</div>
      <div style="display:flex; gap:8px; margin-top:14px;">
        <button class="btn btn-sm assign-db-btn" data-id="${esc(d.id)}" style="flex:1;">${d.assigned_user_id ? 'Reassign' : 'Assign'}</button>
        ${d.assigned_user_id ? `<button class="btn btn-sm btn-danger unassign-db-btn" data-id="${esc(d.id)}" style="flex:1;">Remove</button>` : ''}
      </div>
    </div>`).join('');

  $all('.assign-db-btn', listEl).forEach(b=> b.addEventListener('click', ()=> openAssignDbModal(b.dataset.id)));
  $all('.unassign-db-btn', listEl).forEach(b=> b.addEventListener('click', ()=> removeDbAssignment(b.dataset.id)));
}
