// Core assignment save — used by both the Settings → Database Assignments modal and the
// inline "Assign" dropdown on each Data Hub card (spec #4). Never creates a duplicate
// database record: it's always an UPDATE against the existing row by id.
/* ---------- Assignment email + Excel attachment ----------
   When an Admin assigns/reassigns a database, create a real Outlook-compatible
   .eml draft and download it automatically. The Excel customer database is
   embedded as an attachment, so the Admin does not have to attach it manually.
   This is a browser download/draft: a plain HTML page cannot silently send mail
   through Outlook without a mail service/API and user permission.
*/
function assignmentMailSafeFileName(name){
  return String(name||'database').replace(/[^a-zA-Z0-9._ -]/g,'_').replace(/\s+/g,' ').trim().slice(0,100) || 'database';
}
function assignmentBase64FromArrayBuffer(buffer){
  const bytes = new Uint8Array(buffer);
  const chunk = 0x8000;
  let binary = '';
  for(let i=0;i<bytes.length;i+=chunk){
    binary += String.fromCharCode(...bytes.subarray(i, Math.min(i+chunk, bytes.length)));
  }
  return btoa(binary);
}
function assignmentB64Utf8(text){
  const bytes = new TextEncoder().encode(String(text||''));
  return assignmentBase64FromArrayBuffer(bytes.buffer);
}
function assignmentMimeB64(base64, width=76){
  const out=[];
  for(let i=0;i<base64.length;i+=width) out.push(base64.slice(i,i+width));
  return out.join('\r\n');
}
function assignmentEmailHeader(v){
  // RFC 2047 UTF-8 subject/header encoding for Outlook-compatible .eml.
  return '=?UTF-8?B?'+assignmentB64Utf8(v)+'?=';
}
function assignmentFriendlyTimestamp(v){
  if(!v) return '';
  const d=new Date(v);
  if(Number.isNaN(d.getTime())) return String(v);
  return d.toLocaleString('en-IN',{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true});
}
function assignmentExcelDisplayValue(v, key){
  if(v===null || v===undefined) return '';
  if(typeof v==='object') return JSON.stringify(v);
  const k=String(key||'').toLowerCase();
  if(k.includes('timestamp') || k.endsWith('_at') || k==='created' || k==='updated'){
    const d=new Date(v);
    if(!Number.isNaN(d.getTime()) && typeof v==='string' && /T|Z|[+-]\d\d:\d\d/.test(v)) return assignmentFriendlyTimestamp(v);
  }
  return v;
}
async function buildAssignmentCustomerXlsx(db){
  if(typeof ExcelJS==='undefined') throw new Error('Excel export library is unavailable.');
  const result=await fetchAllRecordsForDatabase(db.id);
  if(result.error) throw result.error;
  const sourceRows=result.rows||[];
  const eligibleCustomerCount = countCountableCustomers(sourceRows);

  // Preserve every field returned by the records table, while presenting it in
  // a clean single-sheet customer workbook.
  const keys=[];
  const seen=new Set();
  sourceRows.forEach(r=>Object.keys(r||{}).forEach(k=>{
    if(!seen.has(k)){seen.add(k);keys.push(k);}
  }));
  if(!keys.length){
    keys.push('Customer Name');
  }

  const wb=new ExcelJS.Workbook();
  wb.creator='Swift Cargo';
  wb.created=new Date();
  wb.modified=new Date();
  wb.properties={title:`${db.name} - Customer Database`,subject:'Assigned customer database'};
  const ws=wb.addWorksheet('Customers',{views:[{showGridLines:false}]});
  ws.columns=keys.map(k=>({header:k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),key:k,width:Math.min(42,Math.max(14,Math.max(k.length+3,18)))}));
  const header=ws.getRow(1);
  header.height=30;
  header.eachCell(cell=>{
    cell.font={name:'Aptos',size:11,bold:true,color:{argb:'FFFFFFFF'}};
    cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1F4E78'}};
    cell.alignment={vertical:'middle',horizontal:'center',wrapText:true};
    cell.border={bottom:{style:'thin',color:{argb:'FF173A5A'}}};
  });
  sourceRows.forEach((r,i)=>{
    const vals={};
    keys.forEach(k=>vals[k]=assignmentExcelDisplayValue(r?.[k],k));
    const row=ws.addRow(vals);
    row.height=22;
    row.eachCell(cell=>{
      cell.font={name:'Aptos',size:10,color:{argb:'FF17212B'}};
      cell.alignment={vertical:'middle',horizontal:'left',wrapText:true};
      cell.border={bottom:{style:'hair',color:{argb:'FFE0E6EB'}}};
      if(i%2===1) cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF5F8FA'}};
    });
  });
  ws.views=[{state:'frozen',ySplit:1,showGridLines:false}];
  if(sourceRows.length) ws.autoFilter={from:{row:1,column:1},to:{row:1,column:keys.length}};
  ws.properties.tabColor='1F4E78';
  ws.pageSetup={orientation:'landscape',fitToPage:true,fitToWidth:1,fitToHeight:0,paperSize:9};
  ws.pageMargins={left:0.25,right:0.25,top:0.5,bottom:0.5,header:0.2,footer:0.2};
  ws.headerFooter.oddFooter=`Swift Cargo | ${db.name} | Page &P of &N`;
  return {buffer:await wb.xlsx.writeBuffer(), count:sourceRows.length, eligibleCustomerCount};
}
async function downloadAssignmentEmail(db,newUser){
  if(!newUser?.email) throw new Error('Assigned user does not have an email address.');
  const {buffer,count,eligibleCustomerCount}=await buildAssignmentCustomerXlsx(db);
  const attachmentName=`${assignmentMailSafeFileName(db.name)}_Customers.xlsx`;
  const attachmentB64=assignmentMimeB64(assignmentBase64FromArrayBuffer(buffer));
  const adminName=S.profile?.full_name || S.profile?.username || S.session?.user?.email || 'Admin';
  const customerCount=Number(eligibleCustomerCount||0).toLocaleString('en-IN');
  const firstName=String(newUser.full_name||newUser.username||newUser.email.split('@')[0]||'User').trim().split(/\s+/)[0];
  const subject=`Database Assigned – ${customerCount} Customers – ${db.name}`;
  const body=[
    `Dear ${firstName},`,
    '',
    `I have assigned you ${customerCount} customers. Kindly start calling on this database.`,
    '',
    `Please find the customer database attached in Excel format.`,
    '',
    `Database: ${db.name}`,
    `Total Customers: ${customerCount}`,
    '',
    'Regards,',
    adminName
  ].join('\r\n');
  const boundary='----=_SwiftCargo_Assignment_'+Date.now().toString(36);
  const eml=[
    'MIME-Version: 1.0',
    `From: ${adminName.replace(/[\r\n]/g,' ')} <${S.session.user.email}>`,
    `To: ${newUser.full_name||newUser.email} <${newUser.email}>`,
    `Subject: ${assignmentEmailHeader(subject)}`,
    'Date: '+new Date().toUTCString(),
    'X-Unsent: 1',
    `Content-Type: multipart/mixed; boundary="${boundary}"`,
    '',
    `--${boundary}`,
    'Content-Type: text/plain; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
    '',
    assignmentMimeB64(assignmentB64Utf8(body)),
    '',
    `--${boundary}`,
    'Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'Content-Transfer-Encoding: base64',
    `Content-Disposition: attachment; filename="${attachmentName.replace(/"/g,'')}"`,
    '',
    attachmentB64,
    '',
    `--${boundary}--`,
    ''
  ].join('\r\n');
  const blob=new Blob([new TextEncoder().encode(eml)],{type:'message/rfc822'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;
  a.download=`Assignment_${assignmentMailSafeFileName(db.name)}_${assignmentMailSafeFileName(firstName)}.eml`;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),5000);
  toast(`Assignment email downloaded for ${newUser.email}`, 'success');
  logAudit('assignment_email_generated',{database_id:db.id,database_name:db.name,to:newUser.email,customer_count:Number(eligibleCustomerCount||0),records_attached:count});
  return true;
}

async function applyDbAssignment(dbId,newUserId){
  if(!S.isAdmin){toast('Only Admins can change database assignments.','error');return false;}
  const id=String(dbId??'').trim();
  if(!id){toast('Assignment failed: database ID is missing.','error');return false;}
  const locks=(S._assignmentInFlight ||= new Set());
  if(locks.has(id)){toast('This database assignment is already being updated.','info');return false;}
  const db=S.databases.find(d=>String(d.id)===id);
  if(!db){toast('Assignment failed: the selected database is no longer available. Refresh Data Hub and try again.','error');return false;}
  const requestedUserId=newUserId==null||newUserId===''?null:String(newUserId);
  const newUser=requestedUserId ? S.profiles.find(p=>String(p.id)===requestedUserId) : null;
  if(requestedUserId && !newUser){toast('Assignment failed: the selected user ID was not found in the loaded team profiles.','error');return false;}
  if(!S.session?.user?.id){toast('Assignment failed: your authenticated session is unavailable. Sign in again.','error');return false;}

  locks.add(id);
  const previousUserId=db.assigned_user_id||null;
  const previousUserName=db.assigned_user_name||null;
  const nowIso=new Date().toISOString();
  const payload=newUser ? {
    assigned_user_id:newUser.id,
    assigned_user_name:newUser.full_name||newUser.email,
    assigned_user_email:newUser.email,
    assigned_to:newUser.full_name||newUser.email,
    assigned_by:S.session.user.id,
    assigned_by_name:S.profile?.full_name||S.session.user.email,
    assigned_at:nowIso,
    updated_at:nowIso
  } : {
    assigned_user_id:null,assigned_user_name:null,assigned_user_email:null,assigned_to:null,
    assigned_by:S.session.user.id,assigned_by_name:S.profile?.full_name||S.session.user.email,
    assigned_at:nowIso,updated_at:nowIso
  };

  try{
    // No local assignment state is changed until Supabase returns the updated row.
    let savedRow=null,requestError=null;
    try{
      const result=await supa.from('databases').update(payload).eq('id',id)
        .select('id,name,assigned_user_id,assigned_user_name,assigned_user_email,assigned_to,assigned_by,assigned_by_name,assigned_at,updated_at')
        .single();
      requestError=result.error||null;
      savedRow=result.data||null;
    }catch(fetchError){requestError=fetchError;}

    if(requestError || !savedRow){
      // A transport failure can happen after the server commits but before the browser
      // receives the response. Read back the authoritative assignment before deciding.
      let confirmed=null,readbackError=null;
      try{
        const check=await supa.from('databases').select('id,assigned_user_id,assigned_user_name,assigned_user_email,assigned_to,assigned_by,assigned_by_name,assigned_at,updated_at')
          .eq('id',id).maybeSingle();
        readbackError=check.error||null; confirmed=check.data||null;
      }catch(e){readbackError=e;}
      if(!readbackError && confirmed && String(confirmed.assigned_user_id||'')===String(requestedUserId||'')){
        savedRow={...db,...confirmed};
      }else{
        const detail=requestError?.message||String(requestError||'No updated row was returned.');
        const network=/failed to fetch|networkerror|load failed/i.test(detail)||requestError instanceof TypeError;
        console.error('[ASSIGNMENT SERVER UPDATE FAILED]',{databaseId:id,requestedUserId,authenticatedUserId:S.session.user.id,error:requestError,readbackError});
        toast(network
          ? 'Assignment was not confirmed. The browser could not reach Supabase (Failed to fetch). Check the project URL, network/CORS and browser Network tab; no success was reported.'
          : 'Failed to update assignment: '+detail+(readbackError?(' | Read-back failed: '+(readbackError.message||readbackError)):''),
          'error');
        return false;
      }
    }

    // Only update local state after the server confirms the selected user ID.
    if(String(savedRow.assigned_user_id||'')!==String(requestedUserId||'')){
      toast('Assignment was not saved: Supabase returned a different assigned user.','error');
      return false;
    }
    Object.assign(db,savedRow);

    try{
      const {data:updateRows,error:updateLoadError}=await supa.from('updates')
        .select('id,assignment_id,owner_id,database_name,total_customers,assigned_date')
        .eq('assignment_id',id);
      if(updateLoadError) throw updateLoadError;
      if(!newUser){
        for(const u of (updateRows||[])){
          const {error:entryDeleteError}=await supa.from('daily_entries').delete().eq('update_id',u.id);
          if(entryDeleteError) throw entryDeleteError;
          const {error:updateDeleteError}=await supa.from('updates').delete().eq('id',u.id);
          if(updateDeleteError) throw updateDeleteError;
        }
        S.updates=(S.updates||[]).filter(u=>String(u.assignment_id)!==id);
      }else{
        for(const u of (updateRows||[])){
          const updatePayload={owner_id:newUser.id,database_name:db.name,total_customers:Number(db.customer_count||0),assigned_date:nowIso,updated_at:nowIso};
          const {error:updateError}=await supa.from('updates').update(updatePayload).eq('id',u.id);
          if(updateError) throw updateError;
          const {error:entryOwnerError}=await supa.from('daily_entries').update({owner_id:newUser.id}).eq('update_id',u.id);
          if(entryOwnerError) console.warn('[ASSIGNMENT HISTORY TRANSFER FAILED]',entryOwnerError);
        }
      }
    }catch(syncErr){
      console.error('[ASSIGNMENT UPDATE SYNC FAILED]',syncErr);
      toast('Database assignment saved, but Update ownership sync needs attention: '+(syncErr?.message||'Unknown error'),'error');
    }

    await logAudit('database_assigned',{
      action:newUser?(previousUserId?'Reassigned':'Assigned'):'Unassigned',
      database_id:id,database_name:db.name,
      previous_user:previousUserId?{id:previousUserId,name:previousUserName}:null,
      new_user:newUser?{id:newUser.id,name:newUser.full_name||newUser.email}:null,
      assigned_by:S.session.user.id,assigned_by_name:S.profile?.full_name||S.session.user.email
    });
    if(newUser){
      try{await downloadAssignmentEmail(db,newUser);}
      catch(mailErr){console.error('[ASSIGNMENT EMAIL FAILED]',mailErr);toast('Assignment saved, but the email draft could not be generated: '+(mailErr?.message||'Unknown error'),'error');}
    }
    await Promise.all([loadDatabases(),loadRecords(),loadUpdates()]);
    renderDatabaseAssignments();renderDashboard();renderAllDataFilters();refreshAllDataView();
    renderCalendar();renderAnalyticsFilters();renderAnalyticsPage();
    return true;
  }catch(error){
    console.error('[ASSIGNMENT UPDATE UNEXPECTED FAILURE]',{databaseId:id,requestedUserId,error});
    toast('Assignment failed before confirmation: '+(error?.message||String(error)),'error');
    return false;
  }finally{
    locks.delete(id);
  }
}
async function saveDbAssignment(newUserId){
  return applyDbAssignment(S.assigningDbId, newUserId);
}
$('#assign-db-save-btn').addEventListener('click', async ()=>{
  const userId = $('#assign-db-user').value;
  if (!userId){ $('#assign-db-error').className='auth-alert error'; $('#assign-db-error').textContent='Please select a user.'; return; }
  setLoading($('#assign-db-save-btn'), true);
  const ok = await saveDbAssignment(userId);
  setLoading($('#assign-db-save-btn'), false);
  if (ok){ closeAssignDbModal(); toast('Database assignment saved'); }
});
$('#assign-db-remove-btn').addEventListener('click', async ()=>{
  setLoading($('#assign-db-remove-btn'), true);
  const ok = await saveDbAssignment(null);
  setLoading($('#assign-db-remove-btn'), false);
  if (ok){ closeAssignDbModal(); toast('Assignment removed'); }
});
async function removeDbAssignment(dbId){
  const db = S.databases.find(d=>String(d.id)===String(dbId)); if (!db) return;
  confirmAction('Remove this assignment?', `"${esc(db.name)}" will no longer be visible to ${esc(db.assigned_user_name||'its current user')}.`, async ()=>{
    S.assigningDbId = dbId;
    const ok = await saveDbAssignment(null);
    if (ok) toast('Assignment removed');
  });
}

/* Logged-in user summary — moved here from the dashboard */
function renderProfileCard(){
  const av = $('#pc-avatar');
  if (S.profile?.avatar_url){ av.innerHTML = `<img src="${esc(S.profile.avatar_url)}">`; }
  else { av.textContent = initials(S.profile?.full_name || S.session.user.email); }
  $('#pc-name').textContent = S.profile?.full_name || '—';
  $('#pc-email').textContent = S.session.user.email;
  $('#pc-role').textContent = S.profile?.role || 'user';
  $('#pc-created').textContent = S.profile?.created_at ? fmtDate(S.profile.created_at) : '—';
  $('#pc-lastlogin').textContent = S.profile?.last_login ? fmtDateTime(S.profile.last_login) : '—';
  $('#pc-status').textContent = 'Active';
}

/* Storage summary — moved here from the dashboard */
function renderStorageCard(){
  const s = computeStorageStats();
  $('#storage-used-val').textContent = s.usedMB.toFixed(2) + ' MB';
  $('#storage-avail-val').textContent = s.availableMB.toFixed(0) + ' MB';
  $('#storage-dbcount-val').textContent = s.dbCount;
  $('#storage-db-count-pill').textContent = s.dbCount + (s.dbCount===1?' database':' databases');
  $('#storage-progress-fill').style.width = s.pct + '%';
  $('#storage-progress-pct').textContent = s.pct + '% used';
  $('#storage-progress-remaining').textContent = (s.availableMB - s.usedMB).toFixed(2) + ' MB remaining';
}
