/* ---------- Feedback Options Settings ---------- */
function initFeedbackOptionsSettings(){
  const input=$('#new-feedback-option-input'), btn=$('#add-feedback-option-btn');
  if(!input || !btn || btn.dataset.bound==='1') return;
  btn.dataset.bound='1';
  const submit=async()=>{
    if(!S.isAdmin){ toast('Admin access required.','error'); return; }
    const res=await addFeedbackOption(input.value);
    if(!res.ok){ toast(res.error?.message||'Could not add feedback option','error'); return; }
    input.value=''; renderFeedbackOptionsManager(); toast('Feedback option added','success');
  };
  btn.addEventListener('click',submit);
  input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();submit();}});
}
function renderRolesList(){
  const q = (S.teamSearch||'').trim().toLowerCase();
  const rows = S.profiles.filter(p=>{
    if (!q) return true;
    return String(p.full_name||'').toLowerCase().includes(q) || String(p.email||'').toLowerCase().includes(q);
  }).sort((a,b)=> String(a.full_name||a.email).localeCompare(String(b.full_name||b.email)));

  $('#team-count-pill').textContent = S.profiles.length + (S.profiles.length===1 ? ' user' : ' users');

  if (!rows.length){
    $('#roles-list').innerHTML = `<div class="analytics-empty">No team members match your search.</div>`;
    return;
  }

  $('#roles-list').innerHTML = rows.map(p=>{
    const avatar = p.avatar_url ? `<img src="${esc(p.avatar_url)}">` : initials(p.full_name || p.email);
    return `
    <div class="team-row">
      <div class="team-row-avatar">${avatar}</div>
      <div class="team-row-meta">
        <div class="team-row-name">${esc(p.full_name || 'Unnamed user')} <span class="pill ${p.role==='admin'?'pill-purple':'pill-gray'}">${p.role==='admin'?'Admin':'User'}</span></div>
        <div class="team-row-email">${esc(p.email || '—')}</div>
      </div>
      <div class="team-row-side">
        <div class="team-row-lastlogin"><span class="k">Last login</span>${p.last_login ? fmtDateTime(p.last_login) : 'Never'}</div>
        <select data-role-id="${p.id}" style="width:130px;"><option value="user" ${p.role==='user'?'selected':''}>User</option><option value="admin" ${p.role==='admin'?'selected':''}>Admin</option></select>
        ${S.isAdmin && String(p.id)!==String(S.session?.user?.id) ? `<button type="button" class="team-delete-user-btn" data-delete-user-id="${esc(p.id)}" title="Permanently delete user" aria-label="Permanently delete ${esc(p.full_name || p.email || 'user')}">Delete User</button>` : ''}
      </div>
    </div>`;
  }).join('');

  bindDeleteUserActions();

  $all('[data-role-id]').forEach(sel=> sel.addEventListener('change', async ()=>{
    const { error } = await supa.from('profiles').update({ role: sel.value }).eq('id', sel.dataset.roleId);
    if (error){ toast(error.message,'error'); return; }
    toast('Role updated', 'success');
    logAudit('change_role', { target:sel.dataset.roleId, role:sel.value });
    await loadProfiles();
    renderRolesList();
  }));
}
