/* ==========================================================================
   ADMIN: PERMANENT TEAM USER DELETION
   --------------------------------------------------------------------------
   The browser never receives a service-role key and never deletes auth.users
   directly. It invokes the deployed Supabase Edge Function using the current
   user's access token. The Edge Function performs the privileged deletion and
   dependent-record handling server-side.
   ========================================================================== */
const DELETE_USER_EDGE_FUNCTION = 'admin-delete-user';
let deleteUserTarget = null;

function openDeleteUserModal(profile){
  if (!S.isAdmin || !profile || String(profile.id) === String(S.session?.user?.id)) return;

  deleteUserTarget = profile;
  const avatar = $('#delete-user-avatar');
  if (profile.avatar_url){
    avatar.innerHTML = `<img src="${esc(profile.avatar_url)}" alt="">`;
  }else{
    avatar.textContent = initials(profile.full_name || profile.email || '?');
  }
  $('#delete-user-name').textContent = profile.full_name || 'Unnamed user';
  $('#delete-user-email').textContent = profile.email || '—';

  const alertEl = $('#delete-user-alert');
  alertEl.className = 'auth-alert';
  alertEl.textContent = '';
  $('#delete-user-confirm').disabled = false;
  $('.delete-user-confirm-label').textContent = 'Delete User Permanently';

  $('#delete-user-overlay').classList.remove('hidden');
  $('#delete-user-overlay').setAttribute('aria-hidden','false');
}

function closeDeleteUserModal(){
  if ($('#delete-user-confirm')?.disabled) return;
  $('#delete-user-overlay').classList.add('hidden');
  $('#delete-user-overlay').setAttribute('aria-hidden','true');
  deleteUserTarget = null;
}

async function permanentlyDeleteTeamUser(){
  if (!S.isAdmin || !S.session?.user || !deleteUserTarget) return;

  const target = deleteUserTarget;
  if (String(target.id) === String(S.session.user.id)){
    toast('You cannot delete your own signed-in account from Team Members.', 'error');
    return;
  }

  const btn = $('#delete-user-confirm');
  const label = $('.delete-user-confirm-label');
  const alertEl = $('#delete-user-alert');

  btn.disabled = true;
  label.textContent = 'Deleting…';
  alertEl.className = 'auth-alert';
  alertEl.textContent = '';

  try{
    const { data: sessionData, error: sessionError } = await supa.auth.getSession();
    if (sessionError || !sessionData?.session?.access_token){
      throw new Error('Your admin session has expired. Please sign in again.');
    }

    const { data, error } = await supa.functions.invoke(DELETE_USER_EDGE_FUNCTION, {
      body: { user_id: target.id }
    });

    if (error){
      let message = error.message || 'The secure deletion request failed.';
      try{
        if (error.context && typeof error.context.json === 'function'){
          const body = await error.context.json();
          if (body?.error) message = body.error;
        }
      }catch(_){}
      throw new Error(message);
    }
    if (!data?.ok) throw new Error(data?.error || 'The server did not confirm deletion.');

    $('#delete-user-overlay').classList.add('hidden');
    $('#delete-user-overlay').setAttribute('aria-hidden','true');
    deleteUserTarget = null;

    // Refresh the same Team source-of-truth already used by the page.
    await loadProfiles();
    renderRolesList();

    // Keep other existing views consistent without changing their data logic.
    await Promise.allSettled([loadDatabases(), loadUpdates(), loadReminders(), loadRatings()]);
    renderSettings();
    renderDashboard();
    renderCalendar();
    renderAnalyticsFilters();
    if (typeof renderAnalyticsPage === 'function') renderAnalyticsPage();

    toast(`${target.full_name || target.email || 'User'} was permanently deleted.`, 'success');
  }catch(e){
    console.error('[ADMIN DELETE USER]', e);
    alertEl.className = 'auth-alert error';
    alertEl.textContent = e?.message || 'Failed to permanently delete the user.';
    btn.disabled = false;
    label.textContent = 'Delete User Permanently';
    return;
  }

  btn.disabled = false;
  label.textContent = 'Delete User Permanently';
}

function bindDeleteUserActions(){
  $all('[data-delete-user-id]').forEach(btn=>{
    btn.addEventListener('click', (e)=>{
      e.preventDefault();
      e.stopPropagation();
      if (!S.isAdmin) return;
      const profile = S.profiles.find(p=>String(p.id)===String(btn.dataset.deleteUserId));
      if (profile) openDeleteUserModal(profile);
    });
  });
}

