/* ==========================================================================
   TOOLKITS — JOC DATA PROCESSOR
   Namespaced, self-contained module. Business logic is functionally
   equivalent to the JOC FINAL.html reference (same column specs, lookup
   rules, concatenation rules, date/FY formatting, pivot aggregation, and
   ExcelJS workbook generation). Only the UI shell/markup was rebuilt to
   match the existing DataVault design system. No existing app globals,
   functions, or IDs are touched — everything here is scoped inside the
   JOCToolkit module or prefixed with "joc-".
   ========================================================================== */
const JOCToolkit = (() => {

  const state = {
    mainFile: null,
    lookupFile: null,
    mainData: null,       // { headers, rows }
    lookupSheets: null,   // { carrier_group, scac, por_region, top10 }
    outputBlob: null,
    logLines: [],
    processing: false,
    stats: {},
    swiftClassification: null,
  };

  const valState = {
    mainLoaded: false, mainCols: false,
    lookupLoaded: false, carrierSheet: false, scacSheet: false, porSheet: false, top10Sheet: false,
  };

  const REQUIRED_MAIN_COLS = [
    'Shipper','Shipper Address','Shipper City','Shipper State',
    'Consignee','Consignee Address','Consignee City','Consignee State',
    'Notify Party','Notify Party Address','Notify Party City','Notify Party State',
    'Carrier','SCAC','Arrival Date','Region of Origin','Place of Receipt','TEUs'
  ];

  // ── JOC FLEXIBLE COLUMN DETECTION ───────────────────────────────────────
  // The complete/full JOC-compatible column structure. Order here is
  // irrelevant to detection — matching is done by normalized column NAME,
  // never by position. A workbook does not need every one of these columns
  // to be treated as JOC-compatible; see classifyWorkbook() below.
  const JOC_ALL_COLUMNS = [
    'Shipper','Shipper Address','Shipper City','Shipper State',
    'Consignee','Consignee Address','Consignee City','Consignee State',
    'Notify Party','Notify Party Group','Notify Party Address','Notify Party City','Notify Party State',
    'Also Notify Party','Also Notify Party Address','Also Notify Party City','Also Notify Party State',
    'Weight','Weight Unit','Quantity','Quantity Type','TEUs',
    'Carrier','SCAC','Vessel Name','Voyage Number','Bill of Lading Number','Pre Carrier',
    'IMO Number','Inbond Code','Estimated Value','Territory of Origin','Region of Origin',
    'Port of Arrival Code','Port of Arrival','Port of Departure Code','Port of Departure',
    'Final Destination','Mode of Transport','Arrival Date','Container Number','Container Piece Count',
    'Raw Commodity Description','Marks Container Number','Marks Description',
    'Quantity of Commodity Short Description','HS Code','JOC Code','Commodity Short Description',
    'Coastal Region','Clearing District','Place of Receipt','US Destination State','US Destination City'
  ];

  // Column names are normalized for matching: trimmed, case-insensitive,
  // and with internal whitespace collapsed — so "Shipper", " shipper ",
  // and "SHIPPER" are all treated as the same column.
  function normalizeColName(s){
    return String(s == null ? '' : s).trim().toLowerCase().replace(/\s+/g, ' ');
  }

  function buildHeaderIndex(headers){
    const map = new Map();
    headers.forEach((h, i) => {
      const n = normalizeColName(h);
      if (n && !map.has(n)) map.set(n, i);
    });
    return map;
  }

  // Normalized, name-based column lookup — never assumes column position.
  function findColIndex(headers, colName, headerIndexCache){
    const map = headerIndexCache || buildHeaderIndex(headers);
    const idx = map.get(normalizeColName(colName));
    return idx === undefined ? -1 : idx;
  }

  // Scores a workbook's headers against the full known JOC column set and
  // returns a flexible compatibility classification. A workbook is never
  // rejected merely for not containing every JOC column — any 10+
  // recognized columns qualify it as JOC-compatible.
  function classifyWorkbook(headers){
    const headerIndex = buildHeaderIndex(headers || []);
    const detected = [];
    const missing = [];
    JOC_ALL_COLUMNS.forEach(c => {
      if (findColIndex(headers, c, headerIndex) !== -1) detected.push(c);
      else missing.push(c);
    });
    const total = JOC_ALL_COLUMNS.length;
    const count = detected.length;
    const pct = total ? count / total : 0;

    let matchLevel, isJoc;
    if (count === total){ matchLevel = 'Full Match'; isJoc = true; }
    else if (pct >= 0.75){ matchLevel = 'Strong Match'; isJoc = true; }
    else if (pct >= 0.50){ matchLevel = 'Compatible'; isJoc = true; }
    else if (count >= 10){ matchLevel = 'Partial Match'; isJoc = true; }
    else { matchLevel = 'Not JOC-compatible'; isJoc = false; }

    return { detected, missing, count, total, pct, matchLevel, isJoc };
  }

  // ── LOOKUP WORKBOOK DETECTION ────────────────────────────────────────────
  // A workbook is treated as the lookup/master workbook when it contains at
  // least 2 of the 4 known lookup sheets — detected by SHEET NAME, never by
  // filename. This lets any correctly-structured master workbook be found
  // automatically, regardless of what it's called.
  const LOOKUP_SHEET_NAMES = ['Carrier Group','SCAC Code & SCAC Full Name','POR & Region','TOP 10 Criteria'];
  function detectLookupWorkbook(sheetNames){
    const norm = (sheetNames || []).map(s => normalizeColName(s));
    const matched = LOOKUP_SHEET_NAMES.filter(n => norm.includes(normalizeColName(n)));
    return { isLookup: matched.length >= 2, matched, total: LOOKUP_SHEET_NAMES.length };
  }

  // Lightweight-ish metadata read: opens the workbook and extracts sheet
  // names + the first sheet's header row + row count, without holding on to
  // full row data. Used by the folder explorer to classify every workbook
  // it finds (Lookup / JOC / Other Excel) — cached by fingerprint by the
  // caller so unchanged files are never re-read on repeat scans.
  async function readWorkbookInfo(file){
    const buf = await readFileAsBuffer(file);
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(buf);
    const sheetNames = wb.worksheets.map(s => s.name);
    const ws = wb.worksheets[0];
    const headers = [];
    let rowCount = 0;
    if (ws){
      ws.getRow(1).eachCell({ includeEmpty: true }, (cell, c) => {
        headers[c - 1] = cell.value != null ? String(cell.value) : '';
      });
      rowCount = Math.max(0, ws.rowCount - 1);
    }
    return { sheetNames, headers, rowCount };
  }

  const SPEC_BLOCK_INTERNAL = [
    'Shipper_Concat','Shipper','Shipper Address','Shipper City','Shipper State',
    'Consignee_Concat','Consignee','Consignee Address','Consignee City','Consignee State',
    'Notify Party','Notify Party Group','Notify Party Address','Notify Party City','Notify Party State',
    'Carrier','Carrier Group','SCAC','SCAC Full Name',
    'Arrival Date','Arrival','Month','Financial Year',
    'Region of Origin','Region','Place of Receipt','TEUs',
  ];

  const EXPECTED_HEADERS = [
    'Shipper','Shipper','Shipper Address','Shipper City','Shipper State',
    'Consignee','Consignee','Consignee Address','Consignee City','Consignee State',
    'Notify Party','Notify Party Group','Notify Party Address','Notify Party City','Notify Party State',
    'Carrier','Carrier Group','SCAC','SCAC Full Name',
    // Three additional columns (spec addendum), always inserted immediately
    // after 'SCAC Full Name'.
    'SWIFT TEU','OTHER TEU','SWIFT%SHARE',
    'Arrival Date','Arrival','Month','Financial Year',
    'Region of Origin','Region','Place of Receipt','TEUs',
  ];

  const NULL_VALS = new Set(['', 'NAN','NaN','NONE','None','nan','none','undefined','null','NULL']);
  const TOTAL_STEPS = 11;
  let currentStep = -1;
  let initialized = false;

  function jocEscHtml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function byId(id){ return document.getElementById(id); }

  // ── LOGGING ──────────────────────────────────────────────────────────────
  function log(level, msg){
    const now = new Date();
    const ts = now.toTimeString().slice(0,8);
    state.logLines.push(`${ts} - ${level} - ${msg}`);
    renderLogEntry({ ts, level, msg });
  }
  function renderLogEntry({ ts, level, msg }){
    const box = byId('joc-logBox');
    if (!box) return;
    const div = document.createElement('div');
    div.className = 'joc-log-entry';
    div.innerHTML = `<span class="joc-log-ts">${ts}</span><span class="joc-log-lvl ${level}">${level}</span><span class="joc-log-msg${level==='ERROR'?' err':''}">${jocEscHtml(msg)}</span>`;
    box.appendChild(div);
    box.scrollTop = box.scrollHeight;
  }

  // ── DRAG & DROP UPLOAD ZONES ─────────────────────────────────────────────
  function setupZone(zoneId, inputId, fileNameId, onFile){
    const zone = byId(zoneId);
    const input = byId(inputId);
    const nameEl = byId(fileNameId);
    if (!zone || !input || !nameEl) return;

    zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('drag'); });
    zone.addEventListener('dragleave', () => zone.classList.remove('drag'));
    zone.addEventListener('drop', e => {
      e.preventDefault(); zone.classList.remove('drag');
      const f = e.dataTransfer.files[0];
      if (f) handleFile(f);
    });
    input.addEventListener('change', () => { if (input.files[0]) handleFile(input.files[0]); });

    function handleFile(f){
      nameEl.textContent = f.name;
      zone.classList.add('loaded');
      const status = byId('joc-status-text');
      if (status) status.textContent = `Loading ${f.name}…`;
      onFile(f);
    }
  }

  // Reflects a file (from a dropzone OR downloaded via Microsoft Graph) into a
  // dropzone's display, without duplicating the drag/drop wiring above.
  function markZoneLoaded(zoneId, fileNameId, name){
    const zone = byId(zoneId), nameEl = byId(fileNameId);
    if (zone) zone.classList.add('loaded');
    if (nameEl) nameEl.textContent = name;
  }

  // Public entry points: used by both the manual dropzones and JocDataLocation's
  // Microsoft Graph loader, so there is exactly one code path that loads a file
  // into the pipeline regardless of where the file came from.
  async function loadMainFileObject(f){
    state.mainFile = f;
    markZoneLoaded('joc-mainZone','joc-mainFileName', f.name);
    log('INFO', `Main file selected: ${f.name} (${(f.size/1024/1024).toFixed(1)} MB)`);
    await parseMainFile(f);
    checkRunReady();
  }
  async function loadLookupFileObject(f){
    state.lookupFile = f;
    markZoneLoaded('joc-lookupZone','joc-lookupFileName', f.name);
    log('INFO', `Lookup file selected: ${f.name} (${(f.size/1024/1024).toFixed(1)} MB)`);
    await parseLookupFile(f);
    checkRunReady();
  }

  // ── PARSE FILES (ExcelJS) ────────────────────────────────────────────────
  async function readFileAsBuffer(file){
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = e => resolve(e.target.result);
      reader.onerror = reject;
      reader.readAsArrayBuffer(file);
    });
  }

  // ── FAST FILE PARSING ────────────────────────────────────────────────────
  // SheetJS is substantially faster than walking every cell through ExcelJS
  // when a user merely selects an input workbook. ExcelJS remains responsible
  // for the final JOC workbook generation.
  function sheetJsMatrixToRows(sheet){
    return XLSX.utils.sheet_to_json(sheet, {
      header: 1,
      defval: null,
      raw: true,
      blankrows: false
    });
  }

  async function parseMainFile(file){
    try{
      log('INFO', `Reading source workbook quickly (${(file.size/1024/1024).toFixed(1)} MB)...`);

      const buf = await readFileAsBuffer(file);
      // Keep parsing in the browser, but avoid the expensive ExcelJS
      // worksheet/row/cell object walk during file selection.
      const wb = XLSX.read(buf, {
        type: 'array',
        cellDates: true,
        dense: true
      });

      const sheetName = wb.SheetNames[0];
      const ws = sheetName ? wb.Sheets[sheetName] : null;
      if (!ws) throw new Error('No worksheet found in source workbook');

      // IMPORTANT PERFORMANCE PATH:
      // sheet_to_json(header:1) already gives us the row matrix. The previous
      // implementation walked every cell a second time just to copy/filter
      // the matrix. On large PIERS files that duplicate O(rows × columns)
      // pass was one of the biggest causes of the long "Loading…" delay.
      const matrix = sheetJsMatrixToRows(ws);
      const headers = (matrix[0] || []).map(v => v != null ? String(v) : '');
      if (!headers.length) throw new Error('The source worksheet has no header row');

      // `blankrows:false` has already removed completely blank worksheet rows,
      // so keep the arrays returned by SheetJS directly. This avoids another
      // full-cell copy while preserving the same row/column values.
      const rows = matrix.slice(1);

      state.mainData = { headers, rows };
      log('INFO', `Source workbook loaded: ${rows.length.toLocaleString()} rows, ${headers.length} columns`);

      const detection = classifyWorkbook(headers);
      state.jocDetection = detection;
      log('INFO', `JOC compatibility: ${detection.count} of ${detection.total} known JOC columns detected (${detection.matchLevel})`);
      if (detection.missing.length){
        log('INFO', `${detection.missing.length} known JOC columns are not present in this workbook.`);
      }

      setVal('mainLoaded', true);
      setVal('mainCols', detection.isJoc, detection.isJoc ? detection.matchLevel : 'Not enough recognized JOC fields');

      renderCompatibilityCard();
      byId('joc-statRows').textContent = rows.length.toLocaleString();
      byId('joc-statCols').textContent = headers.length;
    } catch(e){
      log('ERROR', `Failed to read source workbook: ${e.message}`);
      setVal('mainLoaded', false, e.message); setVal('mainCols', false);
      toast('Could not read the source workbook — check the log for details.', 'error');
    }
  }

  async function parseLookupFile(file){
    try{
      log('INFO', `Reading lookup file quickly (${(file.size/1024/1024).toFixed(1)} MB)...`);

      const buf = await readFileAsBuffer(file);
      const wb = XLSX.read(buf, {
        type: 'array',
        cellDates: true,
        dense: true
      });

      const sheetNames = wb.SheetNames || [];
      log('INFO', `Lookup sheets found: ${sheetNames.join(', ')}`);

      const sheets = {};

      function readSheet(name){
        const actualName = sheetNames.find(s => normalizeColName(s) === normalizeColName(name));
        if (!actualName) return null;

        const ws = wb.Sheets[actualName];
        if (!ws) return null;

        const matrix = sheetJsMatrixToRows(ws);
        const hdrs = (matrix[0] || []).map(v => v != null ? String(v) : '');
        const rows = [];

        for (let i = 1; i < matrix.length; i++){
          const srcRow = matrix[i] || [];
          const r = {};
          let hasValue = false;

          for (let c = 0; c < hdrs.length; c++){
            const h = hdrs[c];
            if (!h) continue;
            const v = srcRow[c] !== undefined && srcRow[c] !== null ? String(srcRow[c]) : '';
            r[h] = v;
            if (v !== '') hasValue = true;
          }

          if (hasValue) rows.push(r);
        }

        return { headers: hdrs, rows };
      }

      const carrierSheet = readSheet('Carrier Group');
      const scacSheet    = readSheet('SCAC Code & SCAC Full Name');
      const porSheet     = readSheet('POR & Region');
      const top10Sheet   = readSheet('TOP 10 Criteria');

      setVal('lookupLoaded', true);

      if (!carrierSheet || !carrierSheet.headers.includes('Carrier') || !carrierSheet.headers.includes('Carrier Group')){
        setVal('carrierSheet', false, 'Missing columns or sheet');
      } else {
        sheets.carrier_group = carrierSheet.rows;
        setVal('carrierSheet', true);
        log('INFO', `Carrier Group: ${carrierSheet.rows.length.toLocaleString()} entries`);
      }

      if (!scacSheet || !scacSheet.headers.includes('SCAC') || !scacSheet.headers.includes('SCAC Full Name')){
        setVal('scacSheet', false, 'Missing columns or sheet');
      } else {
        sheets.scac = scacSheet.rows;
        setVal('scacSheet', true);
        log('INFO', `SCAC lookup: ${scacSheet.rows.length.toLocaleString()} entries`);
      }

      if (!porSheet || !porSheet.headers.includes('Place of Receipt') || !porSheet.headers.includes('Region Wise')){
        setVal('porSheet', false, 'Missing columns or sheet');
      } else {
        sheets.por_region = porSheet.rows;
        setVal('porSheet', true);
        log('INFO', `POR & Region: ${porSheet.rows.length.toLocaleString()} entries`);
      }

      if (!top10Sheet || !top10Sheet.headers.includes('SCAC Full Name') || !top10Sheet.headers.includes('Forwarder') || !top10Sheet.headers.includes('Carrier')){
        setVal('top10Sheet', false, 'Missing columns or sheet');
      } else {
        sheets.top10 = top10Sheet.rows;
        setVal('top10Sheet', true);
        log('INFO', `TOP 10 Criteria: ${top10Sheet.rows.length.toLocaleString()} entries`);
      }

      state.lookupSheets = sheets;
      log('INFO', 'Lookup file processing complete');
    } catch(e){
      log('ERROR', `Failed to read lookup file: ${e.message}`);
      setVal('lookupLoaded', false, e.message);
      ['carrierSheet','scacSheet','porSheet','top10Sheet'].forEach(k => setVal(k, false));
      toast('Could not read the lookup file — check the log for details.', 'error');
    }
  }

  // ── VALIDATION UI ────────────────────────────────────────────────────────
  function setVal(key, ok, msg){
    valState[key] = ok;
    const el = document.querySelector(`#joc-validationList [data-key="${key}"]`);
    if (!el) return;
    el.className = `joc-v-item ${ok ? 'ok' : 'err'}`;
    const label = el.dataset.label || '';
    el.innerHTML = `<span class="dot"></span>${label}${msg ? ` <em>${jocEscHtml(msg)}</em>` : ''}`;
  }

  // Data Type dropdown: 'auto' | 'joc' | 'other'. Resolves against the
  // detected compatibility to decide whether the JOC pipeline is offered.
  function getEffectiveDataTypeMode(){
    const sel = byId('joc-dataType-select');
    const manual = sel ? sel.value : 'auto';
    if (manual === 'joc') return 'joc';
    if (manual === 'other') return 'other';
    if (!state.jocDetection) return 'other';
    return state.jocDetection.isJoc ? 'joc' : 'other';
  }

  // Premium compact "JOC Compatibility" info card — shows detected/missing
  // columns and the current processing mode. Never treats a low match as
  // a fatal error; it's purely informational.
  function renderCompatibilityCard(){
    const card = byId('joc-compat-card');
    if (!card) return;
    const detection = state.jocDetection;
    if (!detection){
      card.classList.add('hidden');
      return;
    }
    card.classList.remove('hidden');

    const mode = getEffectiveDataTypeMode();
    const isJocMode = mode === 'joc';

    const pill = byId('joc-compat-pill');
    if (pill){
      pill.textContent = isJocMode ? (detection.matchLevel === 'Full Match' ? 'JOC — Full Match' : 'JOC ✓') : 'Other Excel Data';
      pill.className = 'pill ' + (isJocMode ? 'pill-green' : 'pill-gray');
    }

    const headline = byId('joc-compat-headline');
    if (headline){
      headline.textContent = isJocMode
        ? '✓ JOC-compatible workbook detected'
        : 'This workbook does not currently qualify for JOC processing.';
    }

    const detectedCountEl = byId('joc-compat-detected-count');
    if (detectedCountEl) detectedCountEl.textContent = `${detection.count} of ${detection.total}`;
    const matchEl = byId('joc-compat-match-strength');
    if (matchEl) matchEl.textContent = detection.matchLevel;
    const modeEl = byId('joc-compat-mode');
    if (modeEl) modeEl.textContent = isJocMode ? 'JOC' : 'Other Excel Data';

    const detWrap = byId('joc-compat-detected-chips');
    if (detWrap){
      detWrap.innerHTML = detection.detected.length
        ? detection.detected.map(c => `<span class="chip">${jocEscHtml(c)}</span>`).join('')
        : '<span style="font-size:12px; color:var(--text-secondary);">No known JOC columns detected.</span>';
    }
    const missWrap = byId('joc-compat-missing-chips');
    if (missWrap){
      missWrap.innerHTML = detection.missing.length
        ? detection.missing.map(c => `<span class="chip" style="background:#F2F2F8; color:#6B6E8A;">${jocEscHtml(c)}</span>`).join('')
        : '<span style="font-size:12px; color:var(--text-secondary);">All known JOC columns present.</span>';
    }

    const statusText = byId('joc-status-text');
    if (statusText){
      statusText.textContent = isJocMode
        ? `JOC processing available — ${detection.count}/${detection.total} known fields detected (${detection.matchLevel}).`
        : `Not JOC-compatible — only ${detection.count}/${detection.total} known JOC fields detected.`;
    }

    checkRunReady();
  }

  function checkRunReady(){
    const mode = getEffectiveDataTypeMode();
    const allOk = valState.mainLoaded && valState.lookupLoaded && mode === 'joc';
    const btn = byId('joc-runBtn');
    if (btn) btn.disabled = !allOk || state.processing;
  }

  // ── STEP TRACKING ────────────────────────────────────────────────────────
function setStep(n, label){
  if (currentStep >= 0){
    const prev = document.querySelector(
      `#joc-stepsList [data-step="${currentStep}"]`
    );

    if (prev){
      prev.className = 'joc-step done';

      const icon = prev.querySelector('.ic');
      if (icon) icon.textContent = '✓';
    }
  }

  currentStep = n;

  const el = document.querySelector(
    `#joc-stepsList [data-step="${n}"]`
  );

  if (el){
    el.className = 'joc-step active';

    const icon = el.querySelector('.ic');
    if (icon) icon.textContent = '▶';
  }

  const pct = Math.round((n / TOTAL_STEPS) * 100);

  const progressFill = byId('joc-progressFill');
  if (progressFill){
    progressFill.style.width = pct + '%';
  }

  const progressPct = byId('joc-progressPct');
  if (progressPct){
    progressPct.textContent = pct + '%';
  }

  const progressLabel = byId('joc-progressLabel');
  if (progressLabel && label){
    progressLabel.textContent = label;
  }
}

function finishSteps(){
  for (let i = 0; i <= TOTAL_STEPS; i++){
    const el = document.querySelector(
      `#joc-stepsList [data-step="${i}"]`
    );

    if (el){
      el.className = 'joc-step done';

      const icon = el.querySelector('.ic');
      if (icon) icon.textContent = '✓';
    }
  }

  const progressFill = byId('joc-progressFill');
  if (progressFill){
    progressFill.style.width = '100%';
  }

  const progressPct = byId('joc-progressPct');
  if (progressPct){
    progressPct.textContent = '100%';
  }

  const progressLabel = byId('joc-progressLabel');
  if (progressLabel){
    progressLabel.textContent = 'Complete!';
  }
}

  // ── CORE UTILITIES (mirror reference logic exactly) ─────────────────────
  function cleanString(s){
    if (s == null) return '';
    return String(s).trim().toUpperCase().replace(/\s+/g,' ');
  }

  function safeConcat(row, headers, colNames){
    const parts = [];
    for (const col of colNames){
      const idx = headers.indexOf(col);
      if (idx === -1) continue;
      const val = row[idx];
      const s = val != null ? String(val).trim() : '';
      if (s && !NULL_VALS.has(s) && s.toUpperCase() !== 'NAN' && s.toUpperCase() !== 'NONE'){
        parts.push(s);
      }
    }
    return parts.join(', ');
  }

  // Same result as safeConcat(), but column positions are resolved once.
  // This is used in the large PIERS row loops to avoid thousands of repeated
  // Array#indexOf calls.
  function safeConcatIndices(row, indices){
    const parts = [];
    for (const idx of indices){
      if (idx == null || idx < 0) continue;
      const val = row[idx];
      const s = val != null ? String(val).trim() : '';
      if (s && !NULL_VALS.has(s) && s.toUpperCase() !== 'NAN' && s.toUpperCase() !== 'NONE') parts.push(s);
    }
    return parts.join(', ');
  }

  function buildLookupMap(rows, keyCol, valCol){
    const map = new Map();
    const seen = new Set();
    let dups = 0;
    for (const row of rows){
      const k = cleanString(row[keyCol]);
      if (!k) continue;
      if (seen.has(k)){ dups++; continue; }
      seen.add(k);
      map.set(k, row[valCol] || '');
    }
    if (dups > 0) log('WARN', `Found ${dups * 2} duplicate keys in ${keyCol} lookup. Keeping first occurrence.`);
    return map;
  }

  function parseDateYMD(val){
    if (val == null) return null;
    const s = String(val).trim();
    if (!s || NULL_VALS.has(s)) return null;
    const m = s.match(/^(\d{4})(\d{2})(\d{2})$/);
    if (m){
      const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
      if (!isNaN(d)) return d;
    }
    const d = new Date(s);
    if (!isNaN(d)) return d;
    return null;
  }

  function fmtDDMMYYYY(d){
    if (!d) return '';
    const dd = String(d.getUTCDate()).padStart(2,'0');
    const mm = String(d.getUTCMonth()+1).padStart(2,'0');
    const yyyy = d.getUTCFullYear();
    return `${dd}-${mm}-${yyyy}`;
  }

  function fmtYYYYMM(d){
    if (!d) return '';
    const yyyy = d.getUTCFullYear();
    const mm = String(d.getUTCMonth()+1).padStart(2,'0');
    return `${yyyy}-${mm}`;
  }

  function getFinancialYear(d){
    if (!d) return '';
    const month = d.getUTCMonth() + 1;
    const year  = d.getUTCFullYear();
    let fyStart, fyEnd;
    if (month >= 4){ fyStart = year; fyEnd = year + 1; }
    else { fyStart = year - 1; fyEnd = year; }
    const s1 = String(fyStart).slice(-2);
    const s2 = String(fyEnd).slice(-2);
    return `Apr'${s1}-Mar'${s2}`;
  }

  function yieldFrame(){ return new Promise(r => setTimeout(r, 0)); }

  // ── PROCESSING PIPELINE (identical stages/order to the reference) ───────
  async function runPipeline(){
    state.jocAnalytics = null;
    setStep(0, 'Loading data…');
    await yieldFrame();

    let headers = [...state.mainData.headers];
    let rows = state.mainData.rows.map(r => [...r]);
    function has(col){ return headers.indexOf(col) !== -1; }

    log('INFO', `Loaded ${rows.length} rows from source workbook`);
    log('INFO', 'Calculating JOC compatibility…');
    const detection = state.jocDetection || classifyWorkbook(headers);
    state.jocDetection = detection;
    log('INFO', `Detected ${detection.count} of ${detection.total} known JOC fields (${detection.matchLevel})`);
    log('INFO', 'Identifying available processing capabilities…');

    // STEP 1: Shipper_Concat at position 0 — only if Shipper is available.
    setStep(1, 'Creating Shipper concat column…');
    await yieldFrame();
    const shipCols = ['Shipper','Shipper Address','Shipper City','Shipper State'];
    if (has('Shipper')){
      log('INFO', 'Part 1: Creating Shipper_Concat column...');
      shipCols.slice(1).forEach(c => { if (!has(c)) log('INFO', `${c} not found — continuing with available Shipper fields.`); });
      // Resolve the source positions once; this loop touches every PIERS row.
      const shipConcatIndices = shipCols.map(c => headers.indexOf(c));
      headers.unshift('Shipper_Concat');
      rows.forEach(r => {
        r.unshift(safeConcatIndices(r, shipConcatIndices));
      });
      log('INFO', 'Part 1 completed: Shipper_Concat column created at position A');
    } else {
      log('INFO', 'Shipper column not detected — Shipper processing skipped.');
    }

    // STEP 2: Consignee_Concat — only if Consignee is available.
    setStep(2, 'Creating Consignee concat column…');
    await yieldFrame();
    const consCols = ['Consignee','Consignee Address','Consignee City','Consignee State'];
    if (has('Consignee')){
      log('INFO', 'Part 2: Creating Consignee_Concat column...');
      consCols.slice(1).forEach(c => { if (!has(c)) log('INFO', `${c} not found — continuing with available Consignee fields.`); });
      const shipStateIdx = headers.indexOf('Shipper State');
      const shipConcatIdx = headers.indexOf('Shipper_Concat');
      const insertPos = shipStateIdx !== -1 ? shipStateIdx + 1 : (shipConcatIdx !== -1 ? shipConcatIdx + 1 : 0);
      // Resolve positions once and build the new column in the same pass.
      const consConcatIndices = consCols.map(c => headers.indexOf(c));
      const vals = new Array(rows.length);
      for (let i = 0; i < rows.length; i++) vals[i] = safeConcatIndices(rows[i], consConcatIndices);
      headers.splice(insertPos, 0, 'Consignee_Concat');
      rows.forEach((r, i) => r.splice(insertPos, 0, vals[i]));
      log('INFO', 'Part 2 completed: Consignee_Concat column created');
    } else {
      log('INFO', 'Consignee column not detected — Consignee processing skipped.');
    }

    // STEP 3: Notify Party processing — only if Notify Party is available.
    setStep(3, 'Processing Notify Party…');
    await yieldFrame();
    if (has('Notify Party')){
      log('INFO', 'Part 3: Processing Notify Party...');
      const npIdx = headers.indexOf('Notify Party');
      headers[npIdx] = 'Notify Party Group';

      const npConcatCols = ['Notify Party Group','Notify Party Address','Notify Party City','Notify Party State'];
      npConcatCols.slice(1).forEach(c => { if (!has(c)) log('INFO', `${c} not found — continuing with available Notify Party fields.`); });
      const npVals = rows.map(r => safeConcat(r, headers, npConcatCols));

      const npBlock = ['Notify Party','Notify Party Group','Notify Party Address','Notify Party City','Notify Party State'];
      headers.push('Notify Party');
      rows.forEach((r,i) => r.push(npVals[i]));

      function reorderBlock(blockCols, anchorCol){
        const indices = blockCols.map(c => headers.indexOf(c));
        if (indices.some(i => i === -1)) return false;
        const colVals = indices.map(ci => rows.map(r => r[ci]));
        const sorted = [...indices].sort((a,b) => b-a);
        sorted.forEach(ci => {
          headers.splice(ci, 1);
          rows.forEach(r => r.splice(ci, 1));
        });
        const anchorIdx = headers.indexOf(anchorCol);
        if (anchorIdx === -1) return false;
        blockCols.forEach((col, bi) => {
          const pos = anchorIdx + 1 + bi;
          headers.splice(pos, 0, col);
          rows.forEach((r, ri) => r.splice(pos, 0, colVals[bi][ri]));
        });
        return true;
      }
      const anchorCol = has('Consignee State') ? 'Consignee State' : (headers.indexOf('Consignee_Concat') !== -1 ? 'Consignee_Concat' : null);
      const reordered = anchorCol ? reorderBlock(npBlock, anchorCol) : false;
      log('INFO', reordered
        ? 'Part 3 completed: Notify Party processed and positioned'
        : 'Part 3 completed: Notify Party processed (kept in current position — no anchor column available for reordering)');
    } else {
      log('INFO', 'Notify Party column not detected — Notify Party enrichment skipped.');
    }

    // STEP 4: Carrier Group lookup — only if Carrier column + lookup sheet exist.
    setStep(4, 'Carrier Group lookup…');
    await yieldFrame();
    if (has('Carrier') && state.lookupSheets && Array.isArray(state.lookupSheets.carrier_group)){
      log('INFO', 'Part 4: Creating Carrier Group...');
      const carrierMap = buildLookupMap(state.lookupSheets.carrier_group, 'Carrier', 'Carrier Group');
      const carrierIdx = headers.indexOf('Carrier');
      const vals = rows.map(r => {
        const k = cleanString(r[carrierIdx]);
        return carrierMap.get(k) ?? null;
      });
      const insertPos = carrierIdx + 1;
      headers.splice(insertPos, 0, 'Carrier Group');
      rows.forEach((r, i) => r.splice(insertPos, 0, vals[i]));
      const matched = vals.filter(v => v !== null).length;
      state.stats.carrierMatched = matched;
      byId('joc-statCarrier').textContent = matched.toLocaleString();
      log('INFO', `Part 4 completed: ${matched} Carrier Groups matched out of ${rows.length}`);
    } else {
      if (!has('Carrier')) log('INFO', 'Carrier column not detected — Carrier Group lookup skipped.');
      else log('INFO', 'Carrier Group lookup sheet not available — Carrier Group lookup skipped.');
      byId('joc-statCarrier').textContent = '—';
    }

    // STEP 5: SCAC Full Name lookup — only if SCAC column + lookup sheet exist.
    setStep(5, 'SCAC Full Name lookup…');
    await yieldFrame();
    if (has('SCAC') && state.lookupSheets && Array.isArray(state.lookupSheets.scac)){
      log('INFO', 'Part 5: Creating SCAC Full Name...');
      const scacMap = buildLookupMap(state.lookupSheets.scac, 'SCAC', 'SCAC Full Name');
      const scacIdx = headers.indexOf('SCAC');
      const vals = rows.map(r => {
        const k = cleanString(r[scacIdx]);
        return scacMap.get(k) ?? null;
      });
      const insertPos = scacIdx + 1;
      headers.splice(insertPos, 0, 'SCAC Full Name');
      rows.forEach((r, i) => r.splice(insertPos, 0, vals[i]));
      const matched = vals.filter(v => v !== null).length;
      state.stats.scacMatched = matched;
      byId('joc-statSCAC').textContent = matched.toLocaleString();
      log('INFO', `Part 5 completed: ${matched} SCAC Full Names matched out of ${rows.length}`);
    } else {
      if (!has('SCAC')) log('INFO', 'SCAC column not detected — SCAC lookup skipped.');
      else log('INFO', 'SCAC lookup sheet not available — SCAC lookup skipped.');
      byId('joc-statSCAC').textContent = '—';
    }

    // STEP 6: Arrival Date processing — only if Arrival Date is available.
    setStep(6, 'Arrival Date processing…');
    await yieldFrame();
    if (has('Arrival Date')){
      log('INFO', 'Part 6: Processing Arrival Date...');
      const adIdx = headers.indexOf('Arrival Date');
      const arrivalVals = [];
      const monthVals   = [];
      const fyVals      = [];
      for (const r of rows){
        const d = parseDateYMD(r[adIdx]);
        arrivalVals.push(fmtDDMMYYYY(d));
        monthVals.push(fmtYYYYMM(d));
        fyVals.push(getFinancialYear(d));
      }
      const insertBase = adIdx + 1;
      headers.splice(insertBase, 0, 'Arrival');
      rows.forEach((r, i) => r.splice(insertBase, 0, arrivalVals[i]));
      headers.splice(insertBase + 1, 0, 'Month');
      rows.forEach((r, i) => r.splice(insertBase + 1, 0, monthVals[i]));
      headers.splice(insertBase + 2, 0, 'Financial Year');
      rows.forEach((r, i) => r.splice(insertBase + 2, 0, fyVals[i]));
      log('INFO', 'Part 6 completed: Arrival Date columns created');
    } else {
      log('INFO', 'Arrival Date column not detected — Arrival Date processing skipped.');
    }

    // STEP 7: Region lookup — only if Place of Receipt, Region of Origin
    // and the POR & Region lookup sheet are all available.
    setStep(7, 'Region lookup…');
    await yieldFrame();
    if (has('Place of Receipt') && has('Region of Origin') && state.lookupSheets && Array.isArray(state.lookupSheets.por_region)){
      log('INFO', 'Part 7: Creating Region column...');
      const porMap = buildLookupMap(state.lookupSheets.por_region, 'Place of Receipt', 'Region Wise');
      const porIdx = headers.indexOf('Place of Receipt');
      const regionOriginIdx = headers.indexOf('Region of Origin');
      const vals = rows.map(r => {
        const k = cleanString(r[porIdx]);
        return porMap.get(k) ?? null;
      });
      const insertPos = regionOriginIdx + 1;
      headers.splice(insertPos, 0, 'Region');
      rows.forEach((r, i) => r.splice(insertPos, 0, vals[i]));
      const matched = vals.filter(v => v !== null).length;
      state.stats.regionMatched = matched;
      byId('joc-statRegion').textContent = matched.toLocaleString();
      log('INFO', `Part 7 completed: ${matched} Regions matched out of ${rows.length}`);
    } else {
      if (!has('Place of Receipt')) log('INFO', 'Place of Receipt column not detected — Region lookup skipped.');
      else if (!has('Region of Origin')) log('INFO', 'Region of Origin column not detected — Region lookup skipped.');
      else log('INFO', 'POR & Region lookup sheet not available — Region lookup skipped.');
      byId('joc-statRegion').textContent = '—';
    }

    // STEP 8: Final column order — the full spec block runs first (in its
    // established order) using only the columns that were actually
    // created/available, followed by any remaining columns.
    setStep(8, 'Finalizing column order…');
    await yieldFrame();
    const hasFullSpec = SPEC_BLOCK_INTERNAL.every(c => has(c));
    log('INFO', hasFullSpec
      ? 'Full JOC spec column set present — preserving exact established output order.'
      : 'Finalizing column order using the columns available in this workbook...');
    {
      const specPresent = SPEC_BLOCK_INTERNAL.filter(c => has(c));
      const specSet = new Set(specPresent);
      const remaining = headers.filter(c => !specSet.has(c));
      const finalOrder = [...specPresent, ...remaining];
      const newIndices = finalOrder.map(c => headers.indexOf(c));
      rows = rows.map(r => newIndices.map(i => r[i]));
      headers = finalOrder;
      log('INFO', `Column order finalized: ${specPresent.length} recognized JOC columns + ${remaining.length} other columns = ${finalOrder.length} total`);
      byId('joc-statCols').textContent = headers.length;
    }

    // STEP 8a: SWIFT TEU / OTHER TEU / SWIFT%SHARE — additional integration on
    // top of the existing JOC pipeline. Adds three new columns immediately
    // after 'SCAC Full Name': SWIFT TEU (TEUs where SCAC = SIFK, else 0),
    // OTHER TEU (TEUs where SCAC <> SIFK, else 0), and SWIFT%SHARE
    // (SWIFT TEU / TEUs * 100, or 0 if TEUs is 0/blank/invalid).
    // Runs after column-order finalization (Step 8) so the three columns land
    // immediately after 'SCAC Full Name' in the final Main Data output rather
    // than being pushed to the end with the other non-spec columns.
    // IMPORTANT: the SCAC and TEUs columns are located dynamically by header
    // name (never by a fixed column letter/position like BB or T), so this
    // keeps working correctly even if those columns move in a future layout.
    await yieldFrame();
    {
      const scacIdxForShare = headers.indexOf('SCAC');
      const teuIdxForShare  = headers.indexOf('TEUs');
      if (scacIdxForShare !== -1 && teuIdxForShare !== -1){
        log('INFO', 'Part 8a: Creating SWIFT TEU, OTHER TEU and SWIFT%SHARE...');
        const fullNameIdx = headers.indexOf('SCAC Full Name');
        // Insert right after "SCAC Full Name" per spec; if that column isn't
        // present in this workbook, fall back to right after "SCAC".
        const insertPos = fullNameIdx !== -1 ? fullNameIdx + 1 : scacIdxForShare + 1;
        const swiftVals = new Array(rows.length);
        const otherVals = new Array(rows.length);
        const shareVals = new Array(rows.length);
        for (let i = 0; i < rows.length; i++){
          const r = rows[i];
          const teu = jocNumber(r[teuIdxForShare]);
          const isSwift = cleanString(r[scacIdxForShare]) === 'SIFK';
          const swiftTeu = isSwift ? teu : 0;
          swiftVals[i] = swiftTeu;
          otherVals[i] = isSwift ? 0 : teu;
          shareVals[i] = teu ? (swiftTeu / teu) * 100 : 0;
        }
        headers.splice(insertPos, 0, 'SWIFT TEU', 'OTHER TEU', 'SWIFT%SHARE');
        for (let i = 0; i < rows.length; i++){
          rows[i].splice(insertPos, 0, swiftVals[i], otherVals[i], shareVals[i]);
        }
        byId('joc-statCols').textContent = headers.length;
        log('INFO', `Part 8a completed: SWIFT TEU / OTHER TEU / SWIFT%SHARE calculated for all ${rows.length} rows.`);
      } else {
        if (scacIdxForShare === -1) log('INFO', 'SCAC column not detected — SWIFT TEU / OTHER TEU / SWIFT%SHARE skipped.');
        else log('INFO', 'TEUs column not detected — SWIFT TEU / OTHER TEU / SWIFT%SHARE skipped.');
      }
    }

    // STEP 8b (RELOCATED): Category Forwarder / NVOCC / Category Carrier
    // classification now depends on the actual generated Pivot sheet (built
    // in STEP 10, after the Swift/Non-Swift classification below), so that
    // logic lives right after the Pivot table is created — see "STEP 10b"
    // further down. Nothing is computed here any more.

    // Pre-calculate JOC intelligence from the already-loaded in-memory rows.
    // This avoids parsing the generated XLSX a second time after processing.
    {
      const idx = jocHeaderIndexes(headers);
      const shipperIdx = jocPickColumn(idx, 'Shipper', 1);
      const teuIdx = jocPickColumn(idx, 'TEUs');
      const weightIdx = jocPickColumn(idx, 'Weight');
      const unitIdx = jocPickColumn(idx, 'Weight Unit');
      const arrivalIdx = jocPickColumn(idx, 'Port of Arrival');
      const departureIdx = jocPickColumn(idx, 'Port of Departure');
      const codeIdx = jocPickColumn(idx, 'JOC Code');
      const groups = new Map();

      if (shipperIdx >= 0){
        for (const r of rows){
          const rawShipper = jocText(r[shipperIdx]);
          if (!rawShipper || jocIsExcludedShipper(rawShipper)) continue;
          const key = jocNorm(rawShipper);
          let g = groups.get(key);
          if (!g){
            g = {
              shipper: rawShipper, teus: 0, weight: 0,
              weightByUnit: new Map(), arrivals: [], departures: [], jocCodes: []
            };
            groups.set(key, g);
          }
          g.teus += jocNumber(r[teuIdx]);
          const w = jocNumber(r[weightIdx]);
          const unit = jocText(r[unitIdx]);
          g.weight += w;
          if (w){
            const uk = jocNorm(unit || 'UNSPECIFIED');
            g.weightByUnit.set(uk, (g.weightByUnit.get(uk) || 0) + w);
          }
          if (arrivalIdx >= 0) g.arrivals.push(r[arrivalIdx]);
          if (departureIdx >= 0) g.departures.push(r[departureIdx]);
          if (codeIdx >= 0) g.jocCodes.push(r[codeIdx]);
        }
      }

      state.jocAnalytics = {
        rows: Array.from(groups.values()).map(g => ({
          shipper: g.shipper,
          teus: g.teus,
          weight: g.weight,
          weightUnits: Array.from(g.weightByUnit.entries()).map(([unit, value]) => ({
            unit: unit === 'UNSPECIFIED' ? '' : unit, value
          })),
          arrivals: jocUniqueValues(g.arrivals),
          departures: jocUniqueValues(g.departures),
          jocCodes: jocUniqueValues(g.jocCodes)
        })),
        totals: {
          shippers: groups.size,
          teus: Array.from(groups.values()).reduce((s,g) => s + g.teus, 0),
          weight: Array.from(groups.values()).reduce((s,g) => s + g.weight, 0),
          weightUnits: (() => {
            const m = new Map();
            for (const g of groups.values()){
              for (const [u,v] of g.weightByUnit) m.set(u, (m.get(u)||0) + v);
            }
            return Array.from(m.entries()).map(([unit,value]) => ({
              unit: unit === 'UNSPECIFIED' ? '' : unit, value
            }));
          })()
        }
      };
      log('INFO', `JOC intelligence prepared: ${state.jocAnalytics.totals.shippers.toLocaleString()} unique shippers`);
    }

    // STEP 9: Automatically classify every unique JOC shipper against the permanent Swift Customer Master.
    setStep(9, 'Swift / Non-Swift shipper classification…');
    await yieldFrame();
    if (typeof SwiftToolkit === 'undefined' || typeof SwiftToolkit.classifyJOCShippers !== 'function') {
      throw new Error('Swift & Non-Swift Intelligence is not available.');
    }
    if (!state.jocAnalytics || !state.jocAnalytics.rows.length) {
      throw new Error('No valid JOC shippers were found for Swift / Non-Swift classification.');
    }
    log('INFO', `Classifying ${state.jocAnalytics.rows.length.toLocaleString()} unique JOC shippers against the permanent Swift Customer Master…`);
    const swiftResults = await SwiftToolkit.classifyJOCShippers(
      state.jocAnalytics.rows.map(g => g.shipper),
      (done, total) => {
        if (done === total || done % 1500 === 0) log('INFO', `Swift classification progress: ${done.toLocaleString()} / ${total.toLocaleString()}`);
      }
    );
    const swiftMap = new Map();
    swiftResults.forEach(r => swiftMap.set(jocNorm(r.original), r));
    state.jocAnalytics.rows = state.jocAnalytics.rows.map(g => {
      const r = swiftMap.get(jocNorm(g.shipper));
      return { ...g, swiftClassification: r?.remark === 'Swift' ? 'Swift' : 'Non-Swift', swiftMatchedMaster: r?.bestName || '', swiftMatchScore: r?.bestScore ?? '', swiftMatchMethod: r?.method || '', swiftConfidence: r?.strength || '', swiftEvidence: r?.evidence || [] };
    });
    state.jocAnalytics.swift = {
      total: swiftResults.length,
      swift: swiftResults.filter(r => r.remark === 'Swift').length,
      nonSwift: swiftResults.filter(r => r.remark === 'Non swift').length,
      manual: swiftResults.filter(r => r.remark === 'Manual Check').length,
      pending: swiftResults.filter(r => r.remark === 'Pending Verification').length
    };
    state.swiftClassification = { results: swiftResults, map: swiftMap, summary: state.jocAnalytics.swift };
    log('INFO', `Swift classification complete: ${state.jocAnalytics.swift.swift.toLocaleString()} Swift · ${state.jocAnalytics.swift.nonSwift.toLocaleString()} Non Swift · ${state.jocAnalytics.swift.manual.toLocaleString()} Manual Check · ${state.jocAnalytics.swift.pending.toLocaleString()} Pending Verification`);

    // IMPORTANT: Swift intelligence belongs ONLY in the dedicated
    // 'Swift & Non-Swift' sheet. Never append the six Swift columns to
    // Main Data. Main Data must remain the complete processed JOC dataset
    // (67k+ rows in a typical import) with the established JOC columns only.
    const shipperForClassIdx = jocPickColumn(jocHeaderIndexes(headers), 'Shipper', 1);
    if (shipperForClassIdx < 0) throw new Error('The processed JOC workbook does not contain a Shipper column for classification output.');
    if (byId('joc-statSwift')) byId('joc-statSwift').textContent = state.jocAnalytics.swift.swift.toLocaleString();
    if (byId('joc-statNonSwift')) byId('joc-statNonSwift').textContent = state.jocAnalytics.swift.nonSwift.toLocaleString();
    if (byId('joc-statManual')) byId('joc-statManual').textContent = state.jocAnalytics.swift.manual.toLocaleString();
    if (byId('joc-statPending')) byId('joc-statPending').textContent = state.jocAnalytics.swift.pending.toLocaleString();

    // STEP 10: Create pivot table — only if SCAC Full Name, TEUs and the
    // TOP 10 Criteria lookup sheet are all available.
    setStep(10, 'Creating pivot table…');
    await yieldFrame();
    let pivotHeaders = null, pivotRows = [];
    if (has('SCAC Full Name') && has('TEUs') && state.lookupSheets && Array.isArray(state.lookupSheets.top10)){
      log('INFO', 'Creating Pivot Table...');
      const scacFullIdx = headers.indexOf('SCAC Full Name');
      const teuIdx      = headers.indexOf('TEUs');

      const aggMap = new Map();
      for (const r of rows){
        const key = r[scacFullIdx];
        if (key == null || String(key).trim() === '' || NULL_VALS.has(String(key))) continue;
        const rawTeu = r[teuIdx];
        const teu = parseFloat(String(rawTeu).replace(/,/g,''));
        const prev = aggMap.get(key) || 0;
        aggMap.set(key, prev + (isNaN(teu) ? 0 : teu));
      }

      const sorted = [...aggMap.entries()].sort((a,b) => b[1]-a[1]);
      const fwdMap = buildLookupMap(state.lookupSheets.top10, 'SCAC Full Name', 'Forwarder');
      const crrMap = buildLookupMap(state.lookupSheets.top10, 'SCAC Full Name', 'Carrier');

      pivotHeaders = ['SCAC Full Name','Sum of TEUs','Forwarder','Carrier'];
      pivotRows = sorted.map(([name, teuSum]) => {
        const k = cleanString(name);
        const fwd = fwdMap.get(k) ?? '';
        const crr = crrMap.get(k) ?? '';
        return [name, teuSum, fwd, crr];
      });

      state.stats.pivotRows = pivotRows.length;
      byId('joc-statPivot').textContent = pivotRows.length.toLocaleString();
      log('INFO', `Pivot table created with ${pivotRows.length} rows`);
    } else {
      if (!has('TEUs')) log('INFO', 'TEUs not detected — TEU-based analytics will be unavailable for this workbook.');
      else if (!has('SCAC Full Name')) log('INFO', 'SCAC not detected — SCAC-dependent pivot analytics skipped.');
      else log('INFO', 'TOP 10 Criteria lookup sheet not available — pivot skipped.');
      byId('joc-statPivot').textContent = '0';
    }

    // STEP 10b: Category Forwarder / NVOCC / Category Carrier — rebuilt to
    // use the just-built Pivot sheet (STEP 10) as the single source of
    // truth, per the new matching rules:
    //
    //   Category Forwarder:
    //     Pivot → filter the 'Forwarder' column (non-blank) → for each
    //     filtered row take Column A (SCAC Full Name) → search that
    //     COMPLETE SCAC Full Name in Main Data → SCAC Full Name → matching
    //     rows get Category Forwarder = "Top 12 Forwarders".
    //
    //   Category Carrier:
    //     Pivot → filter the 'Carrier' column (non-blank) → for each
    //     filtered row take Column A (SCAC Full Name) → take ONLY the
    //     FIRST WORD of that name (e.g. "MSC - MEDITERRANEAN SHIPPING
    //     COMPANY" → "MSC", "WAN HAI LINES LTD" → "WAN") → search that
    //     first word in Main Data → Carrier Group → matching rows get
    //     Category Carrier = "Top Carriers".
    //
    // The old logic (pulling a category value straight out of the TOP 10
    // Criteria lookup and matching Carrier the same way as Forwarder) has
    // been removed entirely — it is no longer used anywhere.
    // NVOCC keeps its previous behaviour: it carries the original SCAC Full
    // Name for every row classified as a Top 12 Forwarder.
    await yieldFrame();
    if (has('US Destination City') && has('SCAC Full Name') && pivotHeaders){
      log('INFO', 'Classifying Category Forwarder / NVOCC / Category Carrier from the Pivot sheet...');
      const pvScacIdx = pivotHeaders.indexOf('SCAC Full Name');
      const pvFwdIdx  = pivotHeaders.indexOf('Forwarder');
      const pvCrrIdx  = pivotHeaders.indexOf('Carrier');

      // Pivot → Forwarder filter → Column A (SCAC Full Name), matched in full.
      const top12ForwarderNames = new Set();
      // Pivot → Carrier filter → Column A (SCAC Full Name) → first word only.
      const topCarrierFirstWords = new Set();
      if (pvScacIdx !== -1){
        for (const pr of pivotRows){
          const scacFullName = pr[pvScacIdx];
          const k = cleanString(scacFullName);
          if (!k || NULL_VALS.has(String(scacFullName))) continue;
          if (pvFwdIdx !== -1){
            const fwdVal = pr[pvFwdIdx];
            if (fwdVal != null && String(fwdVal).trim() !== '' && !NULL_VALS.has(String(fwdVal))){
              top12ForwarderNames.add(k);
            }
          }
          if (pvCrrIdx !== -1){
            const crrVal = pr[pvCrrIdx];
            if (crrVal != null && String(crrVal).trim() !== '' && !NULL_VALS.has(String(crrVal))){
              const firstWord = k.split(' ')[0];
              if (firstWord) topCarrierFirstWords.add(firstWord);
            }
          }
        }
      }

      const classScacIdx = headers.indexOf('SCAC Full Name');
      const carrierGroupIdx = headers.indexOf('Carrier Group');
      const udcIdx = headers.indexOf('US Destination City');
      const insertPos = udcIdx + 1;

      let fwdMatched = 0, crrMatched = 0;
      const catFwdVals = new Array(rows.length);
      const nvoccVals  = new Array(rows.length);
      const catCrrVals = new Array(rows.length);

      for (let i = 0; i < rows.length; i++){
        const scacVal = rows[i][classScacIdx];
        const k = cleanString(scacVal);
        let fwd = '', nvocc = '', crr = '';
        if (k && !NULL_VALS.has(String(scacVal)) && top12ForwarderNames.has(k)){
          fwd = 'Top 12 Forwarders';
          nvocc = scacVal;
          fwdMatched++;
        }
        if (carrierGroupIdx !== -1){
          const cgVal = rows[i][carrierGroupIdx];
          const ck = cleanString(cgVal);
          if (ck && !NULL_VALS.has(String(cgVal)) && topCarrierFirstWords.has(ck)){
            crr = 'Top Carriers';
            crrMatched++;
          }
        }
        catFwdVals[i] = fwd;
        nvoccVals[i]  = nvocc;
        catCrrVals[i] = crr;
      }

      headers.splice(insertPos, 0, 'Category Forwarder');
      rows.forEach((r, i) => r.splice(insertPos, 0, catFwdVals[i]));
      headers.splice(insertPos + 1, 0, 'NVOCC');
      rows.forEach((r, i) => r.splice(insertPos + 1, 0, nvoccVals[i]));
      headers.splice(insertPos + 2, 0, 'Category Carrier');
      rows.forEach((r, i) => r.splice(insertPos + 2, 0, catCrrVals[i]));

      state.stats.forwarderMatched = fwdMatched;
      state.stats.carrierClassMatched = crrMatched;
      log('INFO', `Category Forwarder: ${fwdMatched.toLocaleString()} of ${rows.length.toLocaleString()} rows matched "Top 12 Forwarders" via Pivot → Forwarder → SCAC Full Name.`);
      log('INFO', `Category Carrier: ${crrMatched.toLocaleString()} of ${rows.length.toLocaleString()} rows matched "Top Carriers" via Pivot → Carrier → SCAC Full Name (first word) → Carrier Group.`);
    } else {
      if (!has('US Destination City')) log('INFO', 'US Destination City column not detected — Category Forwarder/NVOCC/Category Carrier classification skipped.');
      else if (!has('SCAC Full Name')) log('INFO', 'SCAC Full Name not detected — Category Forwarder/NVOCC/Category Carrier classification skipped.');
      else log('INFO', 'Pivot sheet not available — Category Forwarder/NVOCC/Category Carrier classification skipped.');
    }

    // STEP 11: Build Excel workbook
    setStep(11, 'Building Excel workbook…');
    await yieldFrame();
    log('INFO', 'Saving output file...');

    const displayHeaders = headers.map(h => {
      if (h === 'Shipper_Concat')   return 'Shipper';
      if (h === 'Consignee_Concat') return 'Consignee';
      return h;
    });

    if (hasFullSpec){
      // Full JOC structure — preserve the established, strict validation
      // and output layout exactly as before (now 30 columns: the original
      // 27 plus SWIFT TEU / OTHER TEU / SWIFT%SHARE inserted after 'SCAC
      // Full Name').
      const actualSpecCols = displayHeaders.slice(0, EXPECTED_HEADERS.length);
      const mismatches = [];
      EXPECTED_HEADERS.forEach((exp, i) => {
        if (actualSpecCols[i] !== exp) mismatches.push(`col ${i+1}: expected '${exp}', got '${actualSpecCols[i]}'`);
      });
      if (actualSpecCols.length < EXPECTED_HEADERS.length) mismatches.push(`Only ${actualSpecCols.length} columns, expected ${EXPECTED_HEADERS.length}`);
      if (mismatches.length) throw new Error('Post-export validation FAILED — header mismatch:\n' + mismatches.join('\n'));
      log('INFO', `Post-export validation PASSED: all ${EXPECTED_HEADERS.length} headers match expected_headers exactly`);
    } else {
      log('INFO', `Workbook processed with ${detection.count} of ${detection.total} recognized JOC fields — partial column set, established full-spec layout validation skipped.`);
    }
    // Hard guard: Main Data must never contain Swift intelligence columns.
    const forbiddenMainSwiftCols = new Set(['Swift Classification','Swift Matched Master','Swift Match Score','Swift Match Method','Swift Confidence','Swift Evidence']);
    const leakedSwiftCols = displayHeaders.filter(h => forbiddenMainSwiftCols.has(h));
    if (leakedSwiftCols.length) throw new Error(`Main Data validation FAILED — Swift intelligence columns must be on 'Swift & Non-Swift' only: ${leakedSwiftCols.join(', ')}`);
    log('INFO', `Main Data confirmed clean: ${displayHeaders.length} JOC columns; Swift intelligence is isolated to the dedicated sheet.`);
    log('INFO', `Total columns in output: ${displayHeaders.length}`);

    // FINAL COLUMN ORDER — enforced exactly per the required JOC output
    // sequence. The full-spec validation above still checks the original,
    // historical layout (untouched), so this reshaping only affects what
    // actually gets written to the Main Data sheet.
    //
    // Two header labels are normalized here to match the required names,
    // mirroring the pattern already used for Notify Party (the concatenated
    // field keeps the base name, the original raw field becomes "<X>
    // Group"), plus the two category columns renamed to their hyphenated
    // form:
    //   - the raw 'Shipper'   column  -> 'Shipper Group'
    //   - the raw 'Consignee' column  -> 'Consignee Group'
    //   - 'Category Forwarder'        -> 'Category-Forwarder'
    //   - 'Category Carrier'          -> 'Category-Carrier'
    const finalMainHeaders = headers.map(h => {
      if (h === 'Shipper_Concat')     return 'Shipper';
      if (h === 'Consignee_Concat')   return 'Consignee';
      if (h === 'Shipper')            return 'Shipper Group';
      if (h === 'Consignee')          return 'Consignee Group';
      if (h === 'Category Forwarder') return 'Category-Forwarder';
      if (h === 'Category Carrier')   return 'Category-Carrier';
      return h;
    });

    const FINAL_COLUMN_ORDER = [
      'Shipper','Shipper Group','Shipper Address','Shipper City','Shipper State',
      'Consignee','Consignee Group','Consignee Address','Consignee City','Consignee State',
      'Notify Party','Notify Party Group','Notify Party Address','Notify Party City','Notify Party State',
      'Bill of Lading Number','Swift Branch','Weight','Weight Unit','TEUs',
      'Port of Departure','Port of Arrival',
      'Arrival Date','Arrival','Month','Financial Year',
      'Container Piece Count','Territory of Origin',
      'Carrier','Carrier Group','Commodity','Marks Container Number','Marks Description','Estimated Value',
      'Also Notify Party','Also Notify Party Address','Also Notify Party City','Also Notify Party State',
      'Coastal Region','Commodity Short Description','Container Number','Final Destination','Clearing District',
      'HS Code','Inbond Code','JOC Code','Place of Receipt','Port of Arrival Code','Port of Departure Code',
      'Pre Carrier','Quantity of Commodity Short Description','Region of Origin','Region',
      'SCAC','SCAC Full Name','SWIFT TEU','OTHER TEU','SWIFT%SHARE',
      'Vessel Name','Voyage Number','Quantity','Quantity Type','IMO Number','Mode of Transport',
      'US Destination State','US Destination City',
      'Category-Forwarder','NVOCC','Category-Carrier'
    ];

    const finalOrderIdx = [];
    const usedFinalIdx = new Set();
    FINAL_COLUMN_ORDER.forEach(name => {
      const idx = finalMainHeaders.indexOf(name);
      if (idx !== -1 && !usedFinalIdx.has(idx)){
        finalOrderIdx.push(idx);
        usedFinalIdx.add(idx);
      }
    });
    // Any column not covered by the fixed spec above (should not normally
    // happen for a full JOC workbook) is preserved and appended at the end
    // so no data is ever silently dropped.
    finalMainHeaders.forEach((h, idx) => { if (!usedFinalIdx.has(idx)) finalOrderIdx.push(idx); });

    const orderedMainHeaders = finalOrderIdx.map(i => finalMainHeaders[i]);
    const orderedMainRows = rows.map(r => finalOrderIdx.map(i => r[i]));
    log('INFO', `Final column order enforced: ${orderedMainHeaders.length} columns.`);

    // FAST XLSX OUTPUT
    // ExcelJS creates a full object model for every cell. With 67k+ rows this
    // can take minutes and consume huge amounts of memory. SheetJS writes the
    // same tabular data directly and is dramatically faster for this workload.
    if (typeof XLSX === 'undefined') throw new Error('XLSX export library is unavailable.');

    const wb = XLSX.utils.book_new();

    function addFastSheet(name, hdrs, dataRows){
      const ws = XLSX.utils.aoa_to_sheet([hdrs]);
      // Append in chunks so the browser can repaint between large allocations.
      const CHUNK = 12000;
      for (let i = 0; i < dataRows.length; i += CHUNK){
        XLSX.utils.sheet_add_aoa(ws, dataRows.slice(i, i + CHUNK), { origin: -1 });
      }

      // Keep the useful compact widths without scanning all 67k rows.
      const sampleCount = Math.min(dataRows.length, 250);
      const widths = hdrs.map(h => Math.min(String(h ?? '').length + 2, 50));
      for (let ci = 0; ci < hdrs.length; ci++){
        let maxLen = widths[ci] || 8;
        for (let ri = 0; ri < sampleCount; ri++){
          const v = dataRows[ri]?.[ci];
          if (v != null && v !== '') maxLen = Math.max(maxLen, Math.min(String(v).length + 2, 50));
        }
        widths[ci] = Math.max(8, Math.min(maxLen, 50));
      }
      ws['!cols'] = widths.map(w => ({ wch: w }));
      XLSX.utils.book_append_sheet(wb, ws, name);
      return ws;
    }

    log('INFO', 'Writing Main Data sheet (fast mode)…');
    await yieldFrame();
    addFastSheet('Main Data', orderedMainHeaders, orderedMainRows);

    // Dedicated binary classification sheet: ONE ROW PER UNIQUE VALID SHIPPER.
    // ORDER and PERSONAL INFORMATION were already excluded while building
    // state.jocAnalytics.rows. This keeps the intelligence sheet compact and
    // removes duplicate shipper rows while Main Data retains every processed
    // source row. Example: 67,523 Main Data rows -> ~9,911 unique shippers here.
    log('INFO', 'Writing Swift & Non-Swift sheet (unique shippers, fast mode)…');
    await yieldFrame();
    const classHeaders = ['JOC Row','Shipper','Matched With','Swift / Non-Swift','Match Score','Second Score','Score Margin','Match Method','Confidence','Evidence'];
    const uniqueShippers = Array.isArray(state.jocAnalytics?.rows) ? state.jocAnalytics.rows : [];
    const classRows = new Array(uniqueShippers.length);
    for (let i = 0; i < uniqueShippers.length; i++){
      const g = uniqueShippers[i];
      const shipper = String(g?.shipper ?? '');
      if (!shipper || jocIsExcludedShipper(shipper)) { classRows[i] = null; continue; }
      const result = swiftMap.get(jocNorm(shipper));
      classRows[i] = [
        i + 2,
        shipper,
        result?.bestName || 'No reliable master match',
        result?.remark === 'Swift' ? 'Swift' : 'Non-Swift',
        result?.bestScore ?? '',
        result?.secondScore ?? '',
        result?.margin ?? '',
        result?.method || '',
        result?.strength || '',
        (result?.evidence || []).join(' | ')
      ];
      if ((i % 2500) === 0) await yieldFrame();
    }
    addFastSheet('Swift & Non-Swift', classHeaders, classRows.filter(Boolean));

    log('INFO', 'Writing Pivot sheet (fast mode)…');
    await yieldFrame();
    addFastSheet('Pivot', pivotHeaders, pivotRows);

    log('INFO', 'Serialising workbook (fast SheetJS writer)…');
    await yieldFrame();
    const buffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array', compression: true });
    state.outputBlob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

    finishSteps();
    log('INFO','═'.repeat(60));
    log('INFO','PROCESSING COMPLETED SUCCESSFULLY');
    log('INFO',`Total rows processed: ${rows.length}`);
    log('INFO',`Pivot table rows: ${pivotRows.length}`);
    log('INFO','═'.repeat(60));

    const sub = `${rows.length.toLocaleString()} rows · ${displayHeaders.length} columns · ${pivotRows.length} pivot rows · ${(state.outputBlob.size/1024/1024).toFixed(1)} MB`;
    byId('joc-downloadSub').textContent = sub;
    const swiftSummary = state.jocAnalytics?.swift || {swift:0,nonSwift:0,manual:0,pending:0,total:0};
    // JOC uses the exact same shared classification engine as Swift & Non-Swift
    // Intelligence (SwiftToolkit.classifyJOCShippers -> classifyOne). A record
    // the engine could not confidently call Swift or Non-Swift is REVIEW
    // ('Manual Check' / 'Pending Verification') and must stay that way here —
    // JOC never forces an ambiguous record into Swift or Non-Swift.
    const swiftSummaryEl = byId('joc-swift-summary');
    if (swiftSummaryEl){
      const blocked = Number(swiftSummary.manual||0) + Number(swiftSummary.pending||0);
      swiftSummaryEl.innerHTML = `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap;"><div style="font-weight:800; color:#172033;">Swift & Non-Swift shipper segregation</div><span style="padding:3px 8px; border-radius:999px; background:${blocked?'#FFF7ED':'#ECFDF5'}; color:${blocked?'#C2410C':'#15803D'}; font-size:11px; font-weight:800;">'Ready for Data Hub'</span></div><div style="display:flex; gap:14px; flex-wrap:wrap; margin-top:7px; font-size:12px; color:#475569;"><span><b style="color:#2563EB;">${Number(swiftSummary.swift||0).toLocaleString()}</b> Swift</span><span><b style="color:#15803D;">${Number(swiftSummary.nonSwift||0).toLocaleString()}</b> Non-Swift</span><span><b style="color:#64748B;">0</b> Review</span></div><div style="margin-top:7px; font-size:11.5px; color:#64748B;">The Data Hub version is marked <b>JOC</b> and <b>Contact numbers required</b>. Unverified classifications are never silently treated as Swift or Non-Swift.</div>`;
    }
    const addBtn = byId('joc-addToDataHubBtn');
    if (addBtn){
      const blocked = Number(swiftSummary.manual||0) + Number(swiftSummary.pending||0);
      addBtn.disabled = blocked > 0 || !S.isAdmin;
      addBtn.title = !S.isAdmin ? 'Only Admin can add a JOC database to Data Hub' : (blocked ? 'Resolve all Manual Check / Pending Verification records first' : 'Add classified JOC shippers to Data Hub');
    }
    byId('joc-downloadSection').classList.remove('hidden');
  }

  // ── PROCESSING CORE ──────────────────────────────────────────────────────
  // The actual validation + pipeline run, independent of any button/DOM
  // state. Used by the manual "Process JOC File" button AND by the folder
  // explorer's automatic processing queue — exactly one code path runs the
  // pipeline, no matter where the files came from.
  async function runProcessingCore(){
    log('INFO', '═'.repeat(60));
    log('INFO', 'STARTING DATA PROCESSING PIPELINE');
    log('INFO', '═'.repeat(60));

    if (!state.mainFile) {
      throw new Error('Source workbook is not loaded.');
    }
    if (!state.lookupFile) {
      throw new Error('Lookup / Master workbook is not loaded.');
    }
    if (!state.mainData) {
      throw new Error(
        `Source workbook "${state.mainFile.name}" was found but its data could not be loaded.`
      );
    }
    if (!state.lookupSheets) {
      throw new Error(
        `Lookup workbook "${state.lookupFile.name}" was found but its lookup sheets could not be loaded.`
      );
    }

    log('INFO', `Main file: ${state.mainFile.name}`);
    log('INFO', `Lookup file: ${state.lookupFile.name}`);
    log(
      'INFO',
      `Main data: ${state.mainData.rows.length.toLocaleString()} rows × ${state.mainData.headers.length} columns`
    );

    const missingMainColumns = REQUIRED_MAIN_COLS.filter(
      col => !state.mainData.headers.includes(col)
    );
    if (missingMainColumns.length) {
      throw new Error(
        `Source workbook is missing required columns: ${missingMainColumns.join(', ')}`
      );
    }
    log('INFO', '✓ Required source columns validated.');

    const requiredLookups = [
      ['carrier_group', 'Carrier Group'],
      ['scac', 'SCAC Code & SCAC Full Name'],
      ['por_region', 'POR & Region'],
      ['top10', 'TOP 10 Criteria']
    ];

    for (const [key, name] of requiredLookups) {
      if (!Array.isArray(state.lookupSheets[key])) {
        throw new Error(`Lookup workbook sheet "${name}" could not be loaded.`);
      }
      log('INFO', `✓ ${name}: ${state.lookupSheets[key].length.toLocaleString()} rows`);
    }

    log('INFO', '✓ Pre-flight validation passed.');
    log('INFO', 'Starting existing JOC pipeline...');

    await runPipeline();

    log('INFO', '═'.repeat(60));
    log('INFO', 'PROCESSING COMPLETED SUCCESSFULLY');
    log('INFO', '═'.repeat(60));

    return { rows: state.mainData.rows.length, cols: state.mainData.headers.length };
  }

  // Public, DOM-free entry point: runs the pipeline against whatever is
  // currently loaded via loadMainFile()/loadLookupFile() and resolves with
  // a result object instead of throwing — used by the folder explorer to
  // process many files in sequence without touching button/DOM state.
  async function processCurrentFiles(){
    state.outputBlob = null;
    currentStep = -1;
    try{
      const stats = await runProcessingCore();
      return { ok: true, rows: stats.rows, cols: stats.cols };
    } catch(e){
      console.error('JOC PROCESSING ERROR:', e);
      const message = e?.message || String(e);
      log('ERROR', '═'.repeat(60));
      log('ERROR', 'PROCESSING FAILED');
      log('ERROR', `Reason: ${message}`);
      log('ERROR', '═'.repeat(60));
      return { ok: false, error: message };
    }
  }

  // ── RUN BUTTON (manual fallback panel) ───────────────────────────────────
async function onRunClick() {
  if (state.processing) return;
  state.processing = true;
  const runBtn = byId('joc-runBtn');
  setLoading(runBtn, true);
  const downloadSection = byId('joc-downloadSection');
  if (downloadSection) downloadSection.classList.add('hidden');
  try {
    if (!state.mainFile) throw new Error('Source workbook is not loaded.');
    if (!state.lookupFile) throw new Error('Lookup / Master workbook is not loaded.');
    state.outputBlob = null;
    currentStep = -1;
    const result = await runProcessingCore();
    if (!result || !state.outputBlob) throw new Error('JOC processing completed without an output workbook.');
    await saveCurrentProcessedWorkbookToJOC(state.mainFile.name, result.rows);
    toast('JOC processing complete — Swift / Non-Swift classified workbook is ready.', 'success');
  } catch (e) {
    console.error('JOC PROCESSING ERROR:', e);
    log('ERROR', `PROCESSING FAILED: ${e?.message || e}`);
    toast(`JOC processing failed: ${e?.message || e}`, 'error');
  } finally {
    state.processing = false;
    setLoading(runBtn, false);
    checkRunReady();
  }
}


  // ── DOWNLOADS ────────────────────────────────────────────────────────────
  function triggerDownload(blob, filename){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1000);
  }

  function downloadExcel(){
    if (!state.outputBlob) return;
    const ts = new Date().toISOString().replace(/[:.]/g,'').slice(0,15);
    const name = `PIERS_JOC_Swift_NonSwift_Classified_${ts}.xlsx`;
    triggerDownload(state.outputBlob, name);
    log('INFO', `Downloaded: ${name}`);
  }

  function downloadLog(){
    const ts = new Date().toISOString().replace(/[:.]/g,'').slice(0,15);
    const text = state.logLines.join('\n');
    const blob = new Blob([text], { type: 'text/plain' });
    triggerDownload(blob, `processing_log_${ts}.log`);
  }

  // ── VIEW SWITCHING (landing ↔ toolkit) ──────────────────────────────────
  function openLanding(){
    byId('toolkits-landing').classList.remove('hidden');
    byId('toolkits-joc').classList.add('hidden');
  }
  function openJOC(){
    byId('toolkits-landing').classList.add('hidden');
    byId('toolkits-joc').classList.remove('hidden');
  }

  // ── INIT ─────────────────────────────────────────────────────────────────
  function init(){
    if (initialized) return;
    initialized = true;

    const card = byId('toolkit-card-joc');
    if (card) card.addEventListener('click', openJOC);
    const backBtn = byId('joc-back-btn');
    if (backBtn) backBtn.addEventListener('click', openLanding);

    setupZone('joc-mainZone','joc-mainFile','joc-mainFileName', loadMainFileObject);
    setupZone('joc-lookupZone','joc-lookupFile','joc-lookupFileName', loadLookupFileObject);

    const runBtn = byId('joc-runBtn');
    if (runBtn) runBtn.addEventListener('click', onRunClick);

    const clearBtn = byId('joc-clearLogBtn');
    if (clearBtn) clearBtn.addEventListener('click', () => {
      byId('joc-logBox').innerHTML = '';
      state.logLines = [];
    });

    const dlExcelBtn = byId('joc-downloadExcelBtn');
    if (dlExcelBtn) dlExcelBtn.addEventListener('click', downloadExcel);
    const dlLogBtn = byId('joc-downloadLogBtn');
    if (dlLogBtn) dlLogBtn.addEventListener('click', downloadLog);
    const addToDataHubBtn = byId('joc-addToDataHubBtn');
    if (addToDataHubBtn) addToDataHubBtn.addEventListener('click', addClassifiedJOCToDataHub);

    log('INFO', 'JOC Data Processor ready');
    log('INFO', 'Upload main file and lookup file to begin');
  }

  return {
    init,
    loadMainFile: loadMainFileObject,
    loadLookupFile: loadLookupFileObject,
    classifyWorkbook,
    detectLookupWorkbook,
    readWorkbookInfo,
    processCurrentFiles,
    getOutputBlob: () => state.outputBlob,
    getLogText: () => state.logLines.join('\n'),
    getAnalytics: () => state.jocAnalytics,
    getSwiftClassification: () => state.swiftClassification,
    getSourceFileName: () => state.mainFile?.name || 'JOC Workbook',
  };
})();
JOCToolkit.init();

/* ==========================================================================
   JOC LIBRARY — persisted processed workbooks + shipper-level intelligence.
   Workbook bytes are stored in Supabase Storage when cloud sync is available,
   with IndexedDB retained as a local safety cache/offline fallback.
   ========================================================================== */
const JOCLibrary = (() => {
  /* CLOUD-FIRST JOC LIBRARY
     - Workbook bytes: Supabase Storage
     - Library index/metadata: one small manifest JSON per user
     - IndexedDB: only a local safety cache + migration source
     This removes the old "stored on this device" limitation. */
  const CLOUD_BUCKETS=['joc-workbooks','avatars'];
  const CLOUD_PREFIX='joc-library';
  const LOCAL_DB='swift_cargo_joc_library_db', LOCAL_VERSION=1, LOCAL_STORE='books';
  let localDbPromise=null, activeBucket=null;

  function openLocalDb(){
    if(localDbPromise)return localDbPromise;
    localDbPromise=new Promise((resolve,reject)=>{
      const req=indexedDB.open(LOCAL_DB,LOCAL_VERSION);
      req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(LOCAL_STORE))db.createObjectStore(LOCAL_STORE,{keyPath:'id'});};
      req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error);
    });
    return localDbPromise;
  }
  async function localPut(book){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(LOCAL_STORE,'readwrite');tx.objectStore(LOCAL_STORE).put(book);tx.oncomplete=()=>resolve(book);tx.onerror=()=>reject(tx.error);});}
  async function localGet(id){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(LOCAL_STORE,'readonly');const req=tx.objectStore(LOCAL_STORE).get(id);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});}
  async function localAll(){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(LOCAL_STORE,'readonly');const req=tx.objectStore(LOCAL_STORE).getAll();req.onsuccess=()=>resolve((req.result||[]).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)));req.onerror=()=>reject(req.error);});}
  async function localRemove(id){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(LOCAL_STORE,'readwrite');tx.objectStore(LOCAL_STORE).delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}

  function cloudReady(){return !!(supa && S.session?.user?.id);}
  function userPrefix(){return `${S.session.user.id}/${CLOUD_PREFIX}`;}
  function manifestPath(){return `${userPrefix()}/index.json`;}
  function workbookPath(id){return `${userPrefix()}/${id}.xlsx`;}
  function errText(err){return String(err?.message||err||'').toLowerCase();}
  function isMissingBucket(err){const m=errText(err);return /bucket.*not found|bucket.*does not exist|invalid bucket/.test(m);}
  function isMissingObject(err){
    const m=errText(err), status=Number(err?.statusCode||err?.status||err?.status_code||0);
    return status===404 || status===400 || /object.*not found|resource.*not found|not found|no such object|404/.test(m);
  }

  async function downloadManifest(bucket){
    const {data,error}=await supa.storage.from(bucket).download(manifestPath());
    if(error)throw error;
    try{
      const parsed=JSON.parse(await data.text());
      return Array.isArray(parsed)?parsed:[];
    }catch(e){return [];}
  }
  async function findCloudBucket(){
    if(!cloudReady())return null;
    if(activeBucket)return activeBucket;
    for(const bucket of CLOUD_BUCKETS){
      try{
        const items=await downloadManifest(bucket);
        activeBucket=bucket;
        return bucket;
      }catch(e){
        if(isMissingBucket(e))continue;
        if(isMissingObject(e)){
          // A missing manifest means the bucket itself is usable. This also
          // avoids requiring Storage LIST permission just to show the library.
          activeBucket=bucket;
          return bucket;
        }
      }
    }
    return null;
  }
  function serializeBook(book){
    return {
      id:book.id,name:book.name,sourceFileName:book.sourceFileName||'Processed workbook',
      createdAt:Number(book.createdAt)||Date.now(),rowCount:Number(book.rowCount)||0,
      totals:book.totals||{shippers:0,teus:0,weight:0,weightUnits:[]},
      swiftClassification:book.swiftClassification||null,
      totalsPending:!!book.totalsPending
    };
  }
  async function cloudPut(book){
    let lastErr=null;
    for(const bucket of CLOUD_BUCKETS){
      try{
        let manifest=[];
        try{manifest=await downloadManifest(bucket);}catch(e){
          if(!isMissingObject(e))throw e;
        }
        const clean=serializeBook(book);
        const next=manifest.filter(x=>x&&x.id!==clean.id); next.unshift(clean);
        const {error:fileErr}=await supa.storage.from(bucket).upload(workbookPath(clean.id),book.blob,{upsert:true,contentType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',cacheControl:'3600'});
        if(fileErr)throw fileErr;
        const metaBlob=new Blob([JSON.stringify(next)],{type:'application/json'});
        const {error:manifestErr}=await supa.storage.from(bucket).upload(manifestPath(),metaBlob,{upsert:true,contentType:'application/json',cacheControl:'60'});
        if(manifestErr)throw manifestErr;
        activeBucket=bucket;
        return {...clean,blob:book.blob,cloud:true,bucket};
      }catch(e){
        lastErr=e;
        if(!isMissingBucket(e)){
          // If this bucket exists but rejects the operation, try the fallback.
          continue;
        }
      }
    }
    throw lastErr||new Error('No usable Supabase Storage bucket is available.');
  }
  async function cloudAll(){
    if(!cloudReady())return null;
    for(const bucket of CLOUD_BUCKETS){
      try{
        const manifest=await downloadManifest(bucket);
        activeBucket=bucket;
        return manifest.map(b=>({...b,cloud:true,bucket})).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
      }catch(e){
        if(isMissingObject(e)){
          activeBucket=bucket;
          return [];
        }
        if(isMissingBucket(e))continue;
      }
    }
    return null;
  }
  async function cloudGet(id){
    if(!cloudReady())return null;
    const buckets=activeBucket?[activeBucket,...CLOUD_BUCKETS.filter(x=>x!==activeBucket)]:CLOUD_BUCKETS;
    for(const bucket of buckets){
      try{
        const manifest=await downloadManifest(bucket);
        const meta=manifest.find(x=>x.id===id); if(!meta)continue;
        const {data:blob,error}=await supa.storage.from(bucket).download(workbookPath(id));
        if(error)throw error;
        activeBucket=bucket;
        return {...meta,blob,cloud:true,bucket};
      }catch(e){if(isMissingBucket(e))continue;}
    }
    return null;
  }
  async function cloudRemove(id){
    const bucket=activeBucket||await findCloudBucket();
    if(!bucket)return;
    const manifest=await downloadManifest(bucket).catch(e=>isMissingObject(e)?[]:Promise.reject(e));
    const next=manifest.filter(x=>x&&x.id!==id);
    const {error:fileErr}=await supa.storage.from(bucket).remove([workbookPath(id)]);
    if(fileErr && !isMissingObject(fileErr))throw fileErr;
    const metaBlob=new Blob([JSON.stringify(next)],{type:'application/json'});
    const {error:manifestErr}=await supa.storage.from(bucket).upload(manifestPath(),metaBlob,{upsert:true,contentType:'application/json',cacheControl:'60'});
    if(manifestErr)throw manifestErr;
  }

  async function put(book){
    /* FAST / RELIABLE SAVE: local commit first, cloud sync second.
       A Supabase Storage error must never make the user rerun a 67k+ row job. */
    await localPut(book);
    if(cloudReady()){
      try{
        const saved=await cloudPut(book);
        await localPut({...saved,blob:book.blob});
        return saved;
      }catch(e){
        console.warn('JOC cloud save failed; local save retained:',e);
        return {...book,cloud:false,cloudSyncPending:true,cloudError:errText(e)};
      }
    }
    return {...book,cloud:false};
  }
  async function get(id){
    if(cloudReady()){
      try{const cloud=await cloudGet(id);if(cloud){await localPut(cloud);return cloud;}}catch(e){console.warn('Cloud JOC open failed, trying local cache',e);}
    }
    return localGet(id);
  }
  async function all(){
    /*
      FIX: never let an empty/missing Supabase manifest hide locally saved JOCs.

      The old implementation treated a valid-but-empty cloud manifest as the
      complete source of truth. If yesterday's save was retained locally
      because Storage/RLS/network sync failed, today's cloudAll() returned []
      and the UI incorrectly showed "No saved JOC workbooks yet".

      We now:
        1. Always read the local safety cache.
        2. Read cloud metadata when available.
        3. Merge both sets by workbook id.
        4. Keep local copies that are not yet in the cloud.
        5. Attempt background migration/sync without blocking the UI.
    */
    const local = await localAll();

    if(cloudReady()){
      try{
        const cloud = await cloudAll();

        if(cloud !== null){
          const merged = new Map();

          // Cloud metadata is authoritative when the same workbook exists
          // in both places, but retain the local blob for offline/open support.
          for(const b of cloud){
            const lb = local.find(x => x.id === b.id);
            merged.set(b.id, lb?.blob ? {...b, blob:lb.blob} : b);
          }

          // Never hide locally saved workbooks just because cloud metadata is
          // missing, empty, or was not synced yet.
          for(const b of local){
            if(!merged.has(b.id)){
              merged.set(b.id, b);

              // Best-effort migration. Do not block rendering on Storage.
              if(b.blob){
                Promise.resolve()
                  .then(() => cloudPut(b))
                  .then(saved => localPut({...saved, blob:b.blob}))
                  .catch(e => console.warn('JOC background cloud sync failed', b.id, e));
              }
            }
          }

          const result = Array.from(merged.values())
            .sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));

          // Refresh the local metadata cache for cloud records, but never
          // overwrite a local workbook blob with metadata-only cloud data.
          for(const b of result){
            if(b.blob) await localPut(b);
          }

          return result;
        }
      }catch(e){
        console.warn('Cloud JOC library unavailable, using local cache',e);
      }
    }

    return local;
  }
  async function remove(id){
    if(cloudReady()){try{await cloudRemove(id);}catch(e){console.warn('Cloud JOC delete failed',e);throw e;}}
    await localRemove(id);
  }
  return {put,get,all,remove,ensureBucket:findCloudBucket};
})();

let jocLibraryBooks=[], jocActiveBook=null, jocActiveRows=[], jocFilteredRows=[];
function jocNumber(v){
  if(v==null||v==='') return 0;
  if(typeof v==='number'&&Number.isFinite(v)) return v;
  const s=String(v).replace(/,/g,'').replace(/[^\d.+-]/g,'').trim(), n=Number(s);
  return Number.isFinite(n)?n:0;
}
function jocText(v){return String(v==null?'':v).trim();}
function jocNorm(v){return jocText(v).replace(/\s+/g,' ').toUpperCase();}
function jocUniqueValues(values){
  const seen=new Set(),out=[];
  for(const v of values){const s=jocText(v);if(!s)continue;const k=jocNorm(s);if(seen.has(k))continue;seen.add(k);out.push(s);}
  return out;
}
function jocIsExcludedShipper(v){const n=jocNorm(v);return n==='ORDER'||n==='PERSONAL INFORMATION';}
function jocFmtNumber(v,decimals=2){
  return (Number(v)||0).toLocaleString(undefined,{maximumFractionDigits:decimals});
}
function jocFmtWeightValue(v){
  // User requested whole-number display, e.g. 450.97 kg -> 450 kg.
  return Math.trunc(Number(v)||0).toLocaleString();
}
function jocWeightDisplay(weightUnits, fallbackWeight){
  const parts = (weightUnits||[])
    .filter(x => x && Number(x.value))
    .map(x => `${jocFmtWeightValue(x.value)}${x.unit ? ` ${x.unit}` : ''}`.trim());
  if (parts.length) return parts.join(' / ');
  return jocFmtWeightValue(fallbackWeight);
}
function jocWeightUnitSummary(weightUnits){
  const parts = (weightUnits||[])
    .filter(x => x && Number(x.value))
    .map(x => x.unit || '')
    .filter(Boolean);
  return [...new Set(parts.map(jocNorm))].map(k => parts.find(x => jocNorm(x)===k)).join(' / ');
}
function jocFmtDate(ts){if(!ts)return '—';try{return new Date(ts).toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric'});}catch(e){return '—';}}
function jocSafeFileName(s){return String(s||'JOC').replace(/[<>:"/\\|?*\x00-\x1F]/g,'_').replace(/\s+/g,' ').trim()||'JOC';}
function jocHeaderIndexes(headers){
  const idx={};
  (headers||[]).forEach((h,i)=>{const k=jocNorm(h);if(!idx[k])idx[k]=[];idx[k].push(i);});
  return idx;
}
function jocPickColumn(indexes,name,occurrence=0){
  const arr=indexes[jocNorm(name)]||[];return arr[occurrence]??arr[0]??-1;
}

/* JOC aggregation uses the second visible Shipper column because the first
   is the generated Shipper_Concat field. ORDER and PERSONAL INFORMATION are
   excluded by exact normalized value. */
async function jocParseBook(book){
  const wb=XLSX.read(await book.blob.arrayBuffer(),{type:'array',cellDates:true});
  const sheet=wb.Sheets['Main Data']||wb.Sheets[wb.SheetNames[0]];
  if(!sheet)throw new Error('No data sheet found in the saved JOC workbook.');
  const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true});
  if(!matrix.length)return [];
  const headers=matrix[0].map(v=>jocText(v)),idx=jocHeaderIndexes(headers);
  const shipperIdx=jocPickColumn(idx,'Shipper',1),teuIdx=jocPickColumn(idx,'TEUs'),arrivalIdx=jocPickColumn(idx,'Port of Arrival'),departureIdx=jocPickColumn(idx,'Port of Departure'),weightIdx=jocPickColumn(idx,'Weight'),unitIdx=jocPickColumn(idx,'Weight Unit'),codeIdx=jocPickColumn(idx,'JOC Code');
  if(shipperIdx<0)throw new Error('The saved workbook does not contain a Shipper column.');
  const groups=new Map();
  for(let r=1;r<matrix.length;r++){
    const row=matrix[r]||[],rawShipper=jocText(row[shipperIdx]);
    if(!rawShipper||jocIsExcludedShipper(rawShipper))continue;
    const key=jocNorm(rawShipper);
    let g=groups.get(key);
    if(!g)g={shipper:rawShipper,teus:0,weight:0,weightByUnit:new Map(),arrivals:[],departures:[],jocCodes:[]};
    g.teus+=jocNumber(row[teuIdx]);
    const w=jocNumber(row[weightIdx]),unit=jocText(row[unitIdx]);
    g.weight+=w;
    if(w){const uk=jocNorm(unit||'UNSPECIFIED');g.weightByUnit.set(uk,(g.weightByUnit.get(uk)||0)+w);}
    if(arrivalIdx>=0)g.arrivals.push(row[arrivalIdx]);
    if(departureIdx>=0)g.departures.push(row[departureIdx]);
    if(codeIdx>=0)g.jocCodes.push(row[codeIdx]);
    groups.set(key,g);
  }
  return Array.from(groups.values()).map(g=>({
    shipper:g.shipper,teus:g.teus,weight:g.weight,
    weightUnits:Array.from(g.weightByUnit.entries()).map(([unit,value])=>({unit:unit==='UNSPECIFIED'?'':unit,value})),
    arrivals:jocUniqueValues(g.arrivals),departures:jocUniqueValues(g.departures),jocCodes:jocUniqueValues(g.jocCodes)
  }));
}
function jocTotals(rows){
  const unitMap=new Map();
  for(const r of rows||[]) for(const x of (r.weightUnits||[])){
    const k=jocNorm(x.unit||'UNSPECIFIED');unitMap.set(k,(unitMap.get(k)||0)+(Number(x.value)||0));
  }
  return {
    shippers:(rows||[]).length,
    teus:(rows||[]).reduce((s,r)=>s+(Number(r.teus)||0),0),
    weight:(rows||[]).reduce((s,r)=>s+(Number(r.weight)||0),0),
    weightUnits:Array.from(unitMap.entries()).map(([unit,value])=>({unit:unit==='UNSPECIFIED'?'':unit,value}))
  };
}

function jocBookCard(book){
  const pending=!!book.totalsPending; const t=book.totals||{shippers:0,teus:0,weight:0,weightUnits:[]};
  const weightText=pending?'Calculating…':jocWeightDisplay(t.weightUnits,t.weight);
  return `<div class="joc-library-card" data-joc-id="${esc(book.id)}">
    <div class="joc-library-card-top"><div class="joc-library-card-id"><div class="joc-library-card-icon"><img src="assets/joc-logo.png" alt="JOC logo" onerror="this.style.display='none';this.nextElementSibling.style.display='block';"><svg style="display:none" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 12h8M8 16h5M8 8h3"/></svg></div><div style="min-width:0;"><div class="joc-library-card-name">${esc(book.name)}<span class="joc-library-card-joc-badge">JOC</span></div><div class="joc-library-card-source" title="${esc(book.sourceFileName||'')}">${esc(book.sourceFileName||'Processed workbook')} · <span style="color:#1D4ED8; font-weight:800;">JOC</span></div></div></div><div class="joc-library-card-date">${esc(jocFmtDate(book.createdAt))}</div></div>
    <div class="joc-library-card-kpis">

  <div class="joc-library-mini">
    <div class="joc-library-mini-icon">
      <a href="https://ibb.co/mrTcBLY2"><img src="https://i.ibb.co/5X4R9NzS/shippers.png" alt="shippers" border="0"></a>    </div>
    <div class="joc-library-mini-value ${pending?'pending':''}">
      ${pending?'Calculating…':jocFmtNumber(t.shippers,0)}
    </div>
    <div class="joc-library-mini-label">Total Shippers</div>
  </div>

  <div class="joc-library-mini">
    <div class="joc-library-mini-icon">
      <a href="https://ibb.co/nMzhntL7"><img src="https://i.ibb.co/whMDwjzS/TEUs.png" alt="TEUs" border="0"></a>
    </div>
    <div class="joc-library-mini-value ${pending?'pending':''}">
      ${pending?'Calculating…':jocFmtNumber(t.teus)}
    </div>
    <div class="joc-library-mini-label">Total TEUs</div>
  </div>

  <div class="joc-library-mini">
    <div class="joc-library-mini-icon">
      <a href="https://ibb.co/qLMZcjdh"><img src="https://i.ibb.co/0pjw62c1/weight.png" alt="weight" border="0"></a>
    </div>
    <div class="joc-library-mini-value ${pending?'pending':''}">
      ${weightText}
    </div>
    <div class="joc-library-mini-label">Weight</div>
  </div>

</div>
    <div class="joc-library-card-foot"><span>${jocFmtNumber(book.rowCount||0,0)} processed rows${book.swiftClassification ? ` · ${jocFmtNumber(book.swiftClassification.swift||0,0)} Swift · ${jocFmtNumber(book.swiftClassification.nonSwift||0,0)} Non-Swift` : ''}</span><div style="display:flex;align-items:center;gap:8px;"><button type="button" class="joc-card-delete-btn" data-joc-delete="${esc(book.id)}" title="Delete JOC workbook" onclick="event.stopPropagation(); deleteJOCBookById('${esc(book.id)}'); return false;"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a2 2 0 0 1 2 2v0m8 0-1 14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2L4 6h16Z"/></svg></button><b>Open intelligence →</b></div></div>
  </div>`;
}
function jocGetLibraryFilterState(){
  const val=id=>document.getElementById(id)?.value?.trim()||'';
  return {
    sourceFile:val('joc-library-filter-source'),
    shipperMin:val('joc-library-filter-shipper-min'),
    shipperMax:val('joc-library-filter-shipper-max'),
    teuMin:val('joc-library-filter-teu-min'),
    teuMax:val('joc-library-filter-teu-max'),
    weightMin:val('joc-library-filter-weight-min'),
    weightMax:val('joc-library-filter-weight-max')
  };
}
function jocPopulateLibrarySourceFiles(){
  const select=$('#joc-library-filter-source');if(!select)return;
  const current=select.value;
  const names=jocUniqueValues((jocLibraryBooks||[]).map(book=>jocText(book.sourceFileName)));
  select.innerHTML='<option value="">All Source Files</option>'+names.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');
  if(names.includes(current))select.value=current;
}
function jocLibraryFilterIsActive(f){
  return !!(f.sourceFile||f.shipperMin!==''||f.shipperMax!==''||f.teuMin!==''||f.teuMax!==''||f.weightMin!==''||f.weightMax!=='');
}
function jocApplyLibraryFilters(){
  const grid=$('#joc-library-grid'),summary=$('#joc-library-summary'),status=$('#joc-library-filter-status');
  if(!grid)return;
  const f=jocGetLibraryFilterState();
  let books=[...(jocLibraryBooks||[])];

  if(f.sourceFile){
    const target=jocNorm(f.sourceFile);
    books=books.filter(book=>jocNorm(book.sourceFileName)===target);
  }
  if(f.shipperMin!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.shippers)>=Number(f.shipperMin));
  if(f.shipperMax!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.shippers)<=Number(f.shipperMax));
  if(f.teuMin!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.teus)>=Number(f.teuMin));
  if(f.teuMax!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.teus)<=Number(f.teuMax));
  if(f.weightMin!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.weight)>=Number(f.weightMin));
  if(f.weightMax!=='')books=books.filter(book=>!book.totalsPending&&jocNumber(book.totals?.weight)<=Number(f.weightMax));

  if(summary){
    summary.textContent=jocLibraryFilterIsActive(f)
      ? `${books.length.toLocaleString()} of ${jocLibraryBooks.length.toLocaleString()} saved JOC workbooks match the current filters`
      : `${jocLibraryBooks.length.toLocaleString()} saved JOC workbook${jocLibraryBooks.length===1?'':'s'} · stored securely in your Supabase JOC Library`;
  }
  if(status){
    status.textContent=jocLibraryFilterIsActive(f)
      ? `${books.length.toLocaleString()} matching workbook${books.length===1?'':'s'}`
      : '';
  }
  if(!books.length){
    grid.innerHTML=`<div class="joc-library-empty"><div style="font-size:16px;font-weight:800;color:var(--text);margin-bottom:7px;">No JOC workbooks match these filters</div><div>Adjust the filter values or use Clear Filters to show all saved workbooks.</div></div>`;
    return;
  }
  grid.innerHTML=books.map(jocBookCard).join('');
  $all('.joc-library-card',grid).forEach(card=>card.addEventListener('click',()=>openJOCDetail(card.dataset.jocId)));
}
function jocClearLibraryFilters(){
  ['joc-library-filter-source','joc-library-filter-shipper-min','joc-library-filter-shipper-max','joc-library-filter-teu-min','joc-library-filter-teu-max','joc-library-filter-weight-min','joc-library-filter-weight-max']
    .forEach(id=>{const el=$('#'+id);if(el)el.value='';});
  jocApplyLibraryFilters();
}
function renderJOCLibrary(){
  const grid=$('#joc-library-grid'),summary=$('#joc-library-summary');if(!grid)return;
  jocPopulateLibrarySourceFiles();
  jocApplyLibraryFilters();
}
async function loadJOCLibrary(){
  try{jocLibraryBooks=await JOCLibrary.all();renderJOCLibrary();}catch(e){console.error('JOC library load failed',e);toast('Could not load saved JOC workbooks.','error');}
}
let jocPageNumber=1;
const JOC_RENDER_PAGE_SIZE=100;
let jocFilterTimer=null;
// Multi-value tag state for Port of Arrival / Port of Departure — each Enter press adds one
// independent tag; every active tag stays applied together (OR-matched) until removed.
let jocArrivalTags=[];
let jocDepartureTags=[];
function jocTagsArrayFor(fieldKey){ return fieldKey==='arrival' ? jocArrivalTags : jocDepartureTags; }
function jocRenderTagChips(fieldKey){
  const wrap=$('#joc-filter-'+fieldKey+'-wrap');
  const input=$('#joc-filter-'+fieldKey);
  if(!wrap||!input)return;
  $all('.joc-tag-chip',wrap).forEach(el=>el.remove());
  jocTagsArrayFor(fieldKey).forEach(v=>{
    const chip=document.createElement('span');
    chip.className='joc-tag-chip';
    chip.innerHTML=`<span>${esc(v)}</span><button type="button" class="joc-tag-chip-remove" aria-label="Remove ${esc(v)}">&times;</button>`;
    chip.querySelector('button').addEventListener('click',()=>jocRemoveTag(fieldKey,v));
    wrap.insertBefore(chip,input);
  });
}
function jocAddTag(fieldKey,rawValue){
  const value=String(rawValue||'').trim();
  if(!value)return;
  const arr=jocTagsArrayFor(fieldKey);
  if(!arr.some(v=>v.toLowerCase()===value.toLowerCase()))arr.push(value);
  const input=$('#joc-filter-'+fieldKey);
  if(input)input.value='';
  jocRenderTagChips(fieldKey);
  jocApplyFilters(true);
}
function jocRemoveTag(fieldKey,value){
  const arr=jocTagsArrayFor(fieldKey);
  const idx=arr.findIndex(v=>v.toLowerCase()===String(value).toLowerCase());
  if(idx>-1)arr.splice(idx,1);
  jocRenderTagChips(fieldKey);
  jocApplyFilters(true);
}
function jocClearTags(fieldKey){
  const arr=jocTagsArrayFor(fieldKey);
  arr.length=0;
  jocRenderTagChips(fieldKey);
}

function jocGetFilterState(){
  const val=id=>document.getElementById(id)?.value?.trim()||'';
  return{
    shipper:val('joc-filter-shipper').toLowerCase(),
    arrivalTags:[...jocArrivalTags],
    departureTags:[...jocDepartureTags],
    teuMin:val('joc-filter-teu-min'),teuMax:val('joc-filter-teu-max'),
    weightMin:val('joc-filter-weight-min'),weightMax:val('joc-filter-weight-max'),
    sort:document.getElementById('joc-filter-sort')?.value||'teus_desc',
    limit:document.getElementById('joc-filter-limit')?.value||'all'
  };
}

function jocCompactValues(values,max=3){
  const arr=Array.isArray(values)?values.filter(Boolean):[];
  if(!arr.length)return '—';
  const visible=arr.slice(0,max);
  const hidden=arr.slice(max);
  const all=arr.map(v=>`<span class="joc-port-chip joc-port-chip-all">${esc(v)}</span>`).join('');
  return `<div class="joc-port-list">
    <span class="joc-port-visible">
      ${visible.map(v=>`<span class="joc-port-chip">${esc(v)}</span>`).join('')}
      ${hidden.length?`<button type="button" class="joc-port-more" data-expanded="false" aria-label="Show all ${hidden.length} more ports">+${hidden.length} more</button>`:''}
    </span>
    ${hidden.length?`<span class="joc-port-expanded" hidden>${all}<button type="button" class="joc-port-more joc-port-less" data-expanded="true">Show less</button></span>`:''}
  </div>`;
}

function jocPopulateSuggestions(){
  const fill=(id,values)=>{
    const el=document.getElementById(id);if(!el)return;
    const seen=new Set(),out=[];
    for(const v of values||[]){
      const s=jocText(v),k=jocNorm(s);
      if(!s||seen.has(k))continue;
      seen.add(k);out.push(s);
    }
    out.sort((a,b)=>a.localeCompare(b));
    // Keep the native datalist light even for very large JOC books.
    el.innerHTML=out.slice(0,1200).map(v=>`<option value="${esc(v)}"></option>`).join('');
  };
  fill('joc-shipper-suggestions',(jocActiveRows||[]).map(r=>r.shipper));
  fill('joc-arrival-suggestions',(jocActiveRows||[]).flatMap(r=>r.arrivals||[]));
  fill('joc-departure-suggestions',(jocActiveRows||[]).flatMap(r=>r.departures||[]));
}

// ---------- Port Search Dashboard (spec: appears ONLY for Port of Arrival / Port of Departure searches) ----------
// Reads the exact same filtered `rows` array the table renders from, so the dashboard and the
// table are always in sync — there is no separate/stale copy of the dataset here.
function jocUpdatePortDashboard(f,rows){
  const panel=$('#joc-port-dashboard');
  if(!panel)return;
  const arrivalActive=f.arrivalTags&&f.arrivalTags.length>0;
  const departureActive=f.departureTags&&f.departureTags.length>0;
  const active=arrivalActive||departureActive;
  panel.classList.toggle('hidden',!active);
  if(!active)return; // Port filter cleared -> dashboard disappears.

  const t=jocTotals(rows);
  const shipEl=$('#joc-port-total-shippers'),teuEl=$('#joc-port-total-teus'),wtEl=$('#joc-port-total-weight');
  if(shipEl)shipEl.textContent=jocFmtNumber(t.shippers,0);
  if(teuEl)teuEl.textContent=jocFmtNumber(t.teus);
  if(wtEl)wtEl.textContent=jocWeightDisplay(t.weightUnits,t.weight);

  const titleParts=[];
  if(arrivalActive)titleParts.push(`Port of Arrival: ${f.arrivalTags.join(', ')}`);
  if(departureActive)titleParts.push(`Port of Departure: ${f.departureTags.join(', ')}`);
  const titleEl=$('#joc-port-dashboard-title');
  if(titleEl)titleEl.textContent=titleParts.join('   ·   ');
}

function jocApplyFilters(resetPage=true){
  if(resetPage)jocPageNumber=1;
  const f=jocGetFilterState();
  let rows=[...(jocActiveRows||[])];

  const contains=(arr,q)=>!q||(arr||[]).some(v=>String(v||'').toLowerCase().includes(q));
  const containsAnyTag=(arr,tags)=>!tags.length||tags.some(tag=>contains(arr,tag.toLowerCase()));
  if(f.shipper)rows=rows.filter(r=>r.shipper.toLowerCase().includes(f.shipper));
  if(f.arrivalTags.length)rows=rows.filter(r=>containsAnyTag(r.arrivals,f.arrivalTags));
  if(f.departureTags.length)rows=rows.filter(r=>containsAnyTag(r.departures,f.departureTags));
  if(f.teuMin!=='')rows=rows.filter(r=>r.teus>=Number(f.teuMin));
  if(f.teuMax!=='')rows=rows.filter(r=>r.teus<=Number(f.teuMax));
  if(f.weightMin!=='')rows=rows.filter(r=>r.weight>=Number(f.weightMin));
  if(f.weightMax!=='')rows=rows.filter(r=>r.weight<=Number(f.weightMax));

  if(f.sort==='teus_asc')rows.sort((a,b)=>a.teus-b.teus||a.shipper.localeCompare(b.shipper));
  else if(f.sort==='weight_desc')rows.sort((a,b)=>b.weight-a.weight||a.shipper.localeCompare(b.shipper));
  else if(f.sort==='weight_asc')rows.sort((a,b)=>a.weight-b.weight||a.shipper.localeCompare(b.shipper));
  else if(f.sort==='shipper_asc')rows.sort((a,b)=>a.shipper.localeCompare(b.shipper));
  else if(f.sort==='shipper_desc')rows.sort((a,b)=>b.shipper.localeCompare(a.shipper));
  else rows.sort((a,b)=>b.teus-a.teus||b.weight-a.weight||a.shipper.localeCompare(b.shipper));

  const matchingCount=rows.length;
  jocUpdatePortDashboard(f,rows); // Port Search Dashboard: recalculated from the same filtered set as the table, every time filters change.
  const capped=f.limit==='all'?rows:rows.slice(0,Number(f.limit));
  jocFilteredRows=capped;

  const totalPages=Math.max(1,Math.ceil(capped.length/JOC_RENDER_PAGE_SIZE));
  if(jocPageNumber>totalPages)jocPageNumber=totalPages;
  const pageStart=(jocPageNumber-1)*JOC_RENDER_PAGE_SIZE;
  const pageRows=capped.slice(pageStart,pageStart+JOC_RENDER_PAGE_SIZE);

  const summary=$('#joc-filter-result-summary');
  if(summary)summary.textContent=`${matchingCount.toLocaleString()} matching shippers`;

  const tbody=$('#joc-detail-tbody');
  if(!tbody)return;

  // Only 100 rows are ever mounted in the DOM. This is the key smoothness fix.
  tbody.innerHTML=pageRows.length
    ?pageRows.map(r=>`<tr>
        <td><b>${esc(r.shipper)}</b></td>
        <td>${jocFmtNumber(r.teus)}</td>
        <td>${jocCompactValues(r.arrivals,3)}</td>
        <td>${jocCompactValues(r.departures,3)}</td>
        <td>${esc(jocWeightDisplay(r.weightUnits,r.weight))}</td>
      </tr>`).join('')
    :`<tr><td colspan="5" style="text-align:center;padding:38px;color:var(--text-secondary);">No shippers match the current filters.</td></tr>`;

  const foot=$('#joc-table-foot');
  if(foot)foot.textContent=`Showing ${pageRows.length.toLocaleString()} of ${capped.length.toLocaleString()} ${f.limit==='all'?'matching':'selected'} shippers`;

  const info=$('#joc-page-info');
  if(info)info.textContent=`Page ${jocPageNumber} / ${totalPages}`;

  const prev=$('#joc-page-prev'),next=$('#joc-page-next');
  if(prev)prev.disabled=jocPageNumber<=1;
  if(next)next.disabled=jocPageNumber>=totalPages;
}

function jocScheduleFilter(){
  clearTimeout(jocFilterTimer);
  jocFilterTimer=setTimeout(()=>requestAnimationFrame(()=>jocApplyFilters(true)),140);
}

function jocRenderPage(delta){
  const f=jocGetFilterState();
  const totalPages=Math.max(1,Math.ceil((jocFilteredRows||[]).length/JOC_RENDER_PAGE_SIZE));
  jocPageNumber=Math.max(1,Math.min(totalPages,jocPageNumber+delta));
  jocApplyFilters(false);
}

function jocRenderDetail(book,rows){
  jocActiveBook=book;jocActiveRows=rows||[];jocPageNumber=1;jocPopulateSuggestions();$('#joc-library-grid')?.classList.add('hidden');$('.joc-page-toolbar')?.classList.add('hidden');$('#joc-detail')?.classList.remove('hidden');
  $('#joc-detail-title').textContent=book.name;$('#joc-detail-sub').textContent=`${jocFmtNumber(book.rowCount||0,0)} processed rows · ORDER and PERSONAL INFORMATION excluded · Swift/Non-Swift matched · 0 Manual Check · saved ${jocFmtDate(book.createdAt)}`;
  const t=jocTotals(jocActiveRows);$('#joc-detail-total-shipper').textContent=jocFmtNumber(t.shippers,0);$('#joc-detail-total-teus').textContent=jocFmtNumber(t.teus);$('#joc-detail-total-weight').textContent=jocWeightDisplay(t.weightUnits,t.weight);jocApplyFilters();
}
async function openJOCDetail(id){
  try{
    const book=await JOCLibrary.get(id);
    if(!book)throw new Error('That JOC workbook could not be found.');
    resetJOCFilters();
    const rows=Array.isArray(book.analyticsRows)?book.analyticsRows:await jocParseBook(book);
    jocRenderDetail(book,rows);
  }catch(e){toast(`Could not open JOC: ${e.message||e}`,'error');}
}
function closeJOCDetail(){jocActiveBook=null;jocActiveRows=[];jocFilteredRows=[];$('#joc-detail')?.classList.add('hidden');$('#joc-library-grid')?.classList.remove('hidden');$('.joc-page-toolbar')?.classList.remove('hidden');renderJOCLibrary();}
function downloadJOCBook(){if(!jocActiveBook?.blob)return;const url=URL.createObjectURL(jocActiveBook.blob),a=document.createElement('a');a.href=url;a.download=`${jocSafeFileName(jocActiveBook.name)}.xlsx`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);}
async function deleteJOCBookById(id){
  try{
    const book=await JOCLibrary.get(id);
    if(!book)return;
    if(!window.confirm(`Delete the saved JOC "${book.name}"? This permanently removes it from the JOC Library and Supabase cloud storage.`))return;
    await JOCLibrary.remove(id);
    if(jocActiveBook?.id===id){jocActiveBook=null;jocActiveRows=[];jocFilteredRows=[];$('#joc-detail')?.classList.add('hidden');$('#joc-library-grid')?.classList.remove('hidden');$('.joc-page-toolbar')?.classList.remove('hidden');}
    await loadJOCLibrary();
    toast('JOC deleted.','success');
  }catch(e){toast(`Could not delete JOC: ${e.message||e}`,'error');}
}
async function deleteJOCBook(){if(!jocActiveBook)return;return deleteJOCBookById(jocActiveBook.id);}
function resetJOCFilters(){['joc-filter-shipper','joc-filter-arrival','joc-filter-departure','joc-filter-teu-min','joc-filter-teu-max','joc-filter-weight-min','joc-filter-weight-max'].forEach(id=>{const el=$('#'+id);if(el)el.value='';});jocClearTags('arrival');jocClearTags('departure');if($('#joc-filter-sort'))$('#joc-filter-sort').value='teus_desc';if($('#joc-filter-limit'))$('#joc-filter-limit').value='all';jocPageNumber=1;jocApplyFilters(true);}
function bindJOCPage(){
  if(window.__jocPageBound)return;window.__jocPageBound=true;
  $('#joc-library-refresh')?.addEventListener('click',loadJOCLibrary);
  $('#joc-library-filter-apply')?.addEventListener('click',jocApplyLibraryFilters);
  $('#joc-library-filter-clear')?.addEventListener('click',jocClearLibraryFilters);
  $('#joc-library-filter-source')?.addEventListener('change',jocApplyLibraryFilters);
  $('#joc-detail-back')?.addEventListener('click',closeJOCDetail);$('#joc-detail-download')?.addEventListener('click',downloadJOCBook);$('#joc-detail-delete')?.addEventListener('click',deleteJOCBook);$('#joc-filter-reset')?.addEventListener('click',resetJOCFilters);
  ['joc-filter-shipper','joc-filter-code','joc-filter-teu-min','joc-filter-teu-max','joc-filter-weight-min','joc-filter-weight-max'].forEach(id=>$('#'+id)?.addEventListener('input',jocScheduleFilter));
  // Port of Arrival / Port of Departure: type a value, press Enter -> becomes its own tag (no +, comma, or other separator needed).
  // Backspace on an empty field is a quick way to remove the most recently added tag, same as other tag-input UIs.
  ['arrival','departure'].forEach(fieldKey=>{
    const input=$('#joc-filter-'+fieldKey);
    if(!input)return;
    input.addEventListener('keydown',e=>{
      if(e.key==='Enter'){
        e.preventDefault();
        jocAddTag(fieldKey,input.value);
      }else if(e.key==='Backspace'&&!input.value){
        const arr=jocTagsArrayFor(fieldKey);
        if(arr.length)jocRemoveTag(fieldKey,arr[arr.length-1]);
      }
    });
  });
  ['joc-filter-sort','joc-filter-limit'].forEach(id=>$('#'+id)?.addEventListener('change',()=>jocApplyFilters(true)));
  $('#joc-page-prev')?.addEventListener('click',()=>jocRenderPage(-1));
  $('#joc-page-next')?.addEventListener('click',()=>jocRenderPage(1));

  // Expand/collapse all hidden arrival/departure ports without rebuilding the table.
  $('#joc-detail-tbody')?.addEventListener('click',(ev)=>{
    const btn=ev.target.closest('.joc-port-more');
    if(!btn)return;
    const wrap=btn.closest('.joc-port-list');
    if(!wrap)return;
    const visible=wrap.querySelector('.joc-port-visible');
    const expanded=wrap.querySelector('.joc-port-expanded');
    if(!visible||!expanded)return;
    const open=btn.dataset.expanded==='false';
    visible.hidden=open;
    expanded.hidden=!open;
    const opener=wrap.querySelector('.joc-port-visible .joc-port-more');
    if(opener)opener.setAttribute('aria-expanded',open?'true':'false');
    if(open) expanded.querySelector('.joc-port-less')?.focus();
  });
}
async function renderJOCPage(){bindJOCPage();if(!jocLibraryBooks.length)await loadJOCLibrary();else renderJOCLibrary();}
function requestJOCName(suggested){
  // JOC saves are fully automatic: never block processing with a naming dialog.
  const base=String(suggested||'JOC Output').trim()||'JOC Output';
  const now=new Date();
  const stamp=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')]
    .join('-')+' '+[String(now.getHours()).padStart(2,'0'),String(now.getMinutes()).padStart(2,'0'),String(now.getSeconds()).padStart(2,'0')].join('-');
  return Promise.resolve(`${base} • ${stamp}`);
}

async function addClassifiedJOCToDataHub(){
  const button = byId('joc-addToDataHubBtn');
  if (button?.dataset.busy === '1') return false;
  if (button) { button.dataset.busy = '1'; button.disabled = true; button.textContent = 'Checking JOC duplicates…'; }
  if (!guardSupa()) { if (button) { button.dataset.busy=''; button.disabled=false; button.textContent='Add Classified JOC to Data Hub'; } return false; }
  if (!S.isAdmin){ toast('Only Admins can add a JOC workbook to Data Hub.', 'error'); if(button){button.dataset.busy='';button.disabled=false;button.textContent='Add Classified JOC to Data Hub';} return false; }

  const analytics = JOCToolkit.getAnalytics ? JOCToolkit.getAnalytics() : null;
  const swift = JOCToolkit.getSwiftClassification ? JOCToolkit.getSwiftClassification() : null;
  if (!analytics || !Array.isArray(analytics.rows) || !analytics.rows.length){
    toast('No classified JOC shippers are available.', 'error');
    if(button){button.dataset.busy='';button.disabled=false;button.textContent='Add Classified JOC to Data Hub';}
    return false;
  }

  // JOC DUPLICATE PROTECTION
  // Exact company identity only: trim, collapse whitespace, uppercase.
  // No fuzzy matching, similarity scoring, partial matching, or AI decisions.
  const exactShipperKey = value => String(value ?? '').trim().toUpperCase().replace(/\s+/g, ' ');

  if (button) button.textContent = 'Checking existing JOC shippers…';

  // Query ALL existing JOC records directly from Supabase instead of relying on
  // S.records (which is intentionally capped at 50,000 rows).
  let existingJocRows = [];
  try{
    const { data: existingData, error: existingErr } = await supa
      .from('records')
      .select('company_name,database_name')
      .ilike('database_name', 'JOC - %')
      .limit(1000000);
    if(existingErr) throw existingErr;
    existingJocRows = Array.isArray(existingData) ? existingData : [];
  }catch(e){
    console.error('JOC duplicate scan failed:', e);
    toast(`Could not check existing JOC shippers: ${e.message || e}`, 'error');
    if(button){button.dataset.busy='';button.disabled=false;button.textContent='Add Classified JOC to Data Hub';}
    return false;
  }

  const existingShippers = new Set(
    existingJocRows.map(r => exactShipperKey(r.company_name)).filter(Boolean)
  );

  const removedDuplicates = [];
  const newAnalyticsRows = [];
  const seenThisImport = new Set();

  for (const g of analytics.rows){
    const shipper = String(g?.shipper ?? '').trim();
    const key = exactShipperKey(shipper);
    if (!key) continue;

    if (existingShippers.has(key)){
      removedDuplicates.push({
        shipper,
        reason: 'Exact duplicate already exists in JOC Data Hub'
      });
      continue;
    }

    if (seenThisImport.has(key)){
      removedDuplicates.push({
        shipper,
        reason: 'Exact duplicate appears more than once in this JOC import'
      });
      continue;
    }

    seenThisImport.add(key);
    existingShippers.add(key);
    newAnalyticsRows.push(g);
  }

  // Keep the result visible in the JOC app for this processing run.
  window.__lastJOCDedup = {
    checkedAt: new Date().toISOString(),
    sourceFile: String(JOCToolkit.getSourceFileName ? JOCToolkit.getSourceFileName() : 'JOC Workbook'),
    originalCount: analytics.rows.length,
    addedCount: newAnalyticsRows.length,
    removedCount: removedDuplicates.length,
    removedDuplicates
  };

  const summaryEl = byId('joc-swift-summary');
  if (summaryEl){
    const swiftCount = newAnalyticsRows.filter(g => g.swiftClassification === 'Swift').length;
    const nonSwiftCount = newAnalyticsRows.length - swiftCount;
    const removedHtml = removedDuplicates.length
      ? `<details style="margin-top:10px;">
           <summary style="cursor:pointer; font-weight:800; color:#B45309;">
             Removed Duplicate Shippers (${removedDuplicates.length.toLocaleString()})
           </summary>
           <div style="margin-top:8px; max-height:220px; overflow:auto; border-top:1px solid #F1E2C5; padding-top:7px;">
             ${removedDuplicates.map((d,i)=>`<div style="padding:5px 0; border-bottom:1px solid #F4F4F6; font-size:11.5px;">
               <b>${i+1}. ${esc(d.shipper)}</b><span style="color:#64748B;"> — ${esc(d.reason)}</span>
             </div>`).join('')}
           </div>
         </details>`
      : `<div style="margin-top:9px; color:#15803D; font-size:12px; font-weight:700;">No duplicate shippers removed.</div>`;

    summaryEl.innerHTML = `
      <div style="font-weight:800; color:#172033;">JOC Data Hub duplicate check completed ✓</div>
      <div style="display:flex; gap:14px; flex-wrap:wrap; margin-top:8px; font-size:12px; color:#475569;">
        <span><b>${analytics.rows.length.toLocaleString()}</b> Processed Shippers</span>
        <span style="color:#B45309;"><b>${removedDuplicates.length.toLocaleString()}</b> Duplicate Shippers Removed</span>
        <span style="color:#15803D;"><b>${newAnalyticsRows.length.toLocaleString()}</b> New Shippers</span>
      </div>
      ${removedHtml}
    `;
  }

  if (!newAnalyticsRows.length){
    if (button) {
      button.dataset.busy='';
      button.disabled=false;
      button.textContent='All JOC Shippers Already Exist ✓';
    }
    toast(`No new JOC shippers to add. ${removedDuplicates.length.toLocaleString()} duplicate shippers were removed.`, 'success');
    return true;
  }

  const sourceFile = String(JOCToolkit.getSourceFileName ? JOCToolkit.getSourceFileName() : 'JOC Workbook');
  const base = sourceFile.replace(/\.(xlsx|xlsm|xls)$/i,'').trim() || 'JOC Workbook';
  const name = await requestJOCName(`JOC - ${base}`);

  const headers = ['Contact Person','Position','Company Name','Location','Personal Email 1','Personal Email 2','Business Email 1','Business Email 2','Mobile Phone 1','Mobile Phone 2','Work Phone 1','Work Phone 2','Numbers From Company Website 1','Numbers From Company Website 2','Linkedin 1','Company Website 1','Remark'];

  const rows = newAnalyticsRows.map(g => {
    const classification = g.swiftClassification === 'Swift' ? 'Swift' : 'Non-Swift';
    const match = g.swiftMatchedMaster ? `Matched: ${g.swiftMatchedMaster}` : 'No Swift master match';
    const score = g.swiftMatchScore !== '' && g.swiftMatchScore != null ? `Score: ${g.swiftMatchScore}%` : 'Score: —';
    const remark = `JOC • ${classification} • ${match} • ${score} • Contact numbers required`;
    return ['', '', g.shipper || '', '', '', '', '', '', '', '', '', '', '', '', '', '', remark];
  });

  const mapping = {};
  headers.forEach((h,i)=>mapping[i]=h.replace(/ \d+$/,'').replace(/^Numbers From Company Website/, 'company_website_number').replace(/^Mobile Phone/, 'mobile_phone').replace(/^Work Phone/, 'work_phone').replace(/^Personal Email/, 'personal_email').replace(/^Business Email/, 'business_email').replace(/^Linkedin/, 'linkedin').replace(/^Company Website/, 'company_website').replace('Contact Person','contact_person').replace('Position','position').replace('Company Name','company_name').replace('Location','location').replace('Remark','remark'));
  Object.keys(mapping).forEach(i=>{
    const h=headers[Number(i)];
    const m=h.match(/^(.*) (1|2)$/);
    if (m){
      const baseName=m[1];
      const suffix=m[2];
      const baseMap={ 'Personal Email':'personal_email','Business Email':'business_email','Mobile Phone':'mobile_phone','Work Phone':'work_phone','Numbers From Company Website':'company_website_number','Linkedin':'linkedin','Company Website':'company_website' };
      if(baseMap[baseName]) mapping[i]=`${baseMap[baseName]}_${suffix}`;
    }
  });

  const jocFingerprint = `joc_${jocNorm(base)}_${Date.now()}_${Math.random().toString(36).slice(2,10)}`;
  if (button) button.textContent = 'Adding new JOC shippers…';

  const dbResult = await performImport({
    dbName:name, originalFilename:`[JOC] ${base}.xlsx`, assignedTo:'', assignUser:{id:null,name:null,email:null},
    headers, rows, mapping, source:'joc', sourceFingerprint:jocFingerprint,
    onProgress:(done,total)=>{
      const pct=total?Math.round(done/total*100):100;
      logJOCDataHubProgress(done,total,pct);
    }
  });

  if (!dbResult.ok){
    toast(`Could not add JOC to Data Hub: ${dbResult.error}`, 'error');
    if(button){button.dataset.busy='';button.disabled=false;button.textContent='Add Classified JOC to Data Hub';}
    return false;
  }

  try{ dhAddTag([dbResult.dbRow.id], 'JOC'); }catch(e){}
  try{ dhAddTag([dbResult.dbRow.id], 'CONTACT-NUMBERS-REQUIRED'); }catch(e){}
  await Promise.all([loadDatabases(), loadRecords(), loadUpdates()]);
  renderDatabaseList(); renderDashboard(); renderAllDataFilters(); renderCalendar(); renderAnalyticsFilters(); renderAnalyticsPage(); renderSettings();

  // Restore the duplicate report after the normal Data Hub refresh.
  const finalSummaryEl = byId('joc-swift-summary');
  if (finalSummaryEl){
    const removedHtml = removedDuplicates.length
      ? `<details open style="margin-top:10px;">
           <summary style="cursor:pointer; font-weight:800; color:#B45309;">
             Removed Duplicate Shippers (${removedDuplicates.length.toLocaleString()})
           </summary>
           <div style="margin-top:8px; max-height:220px; overflow:auto; border-top:1px solid #F1E2C5; padding-top:7px;">
             ${removedDuplicates.map((d,i)=>`<div style="padding:5px 0; border-bottom:1px solid #F4F4F6; font-size:11.5px;">
               <b>${i+1}. ${esc(d.shipper)}</b><span style="color:#64748B;"> — ${esc(d.reason)}</span>
             </div>`).join('')}
           </div>
         </details>`
      : `<div style="margin-top:9px; color:#15803D; font-size:12px; font-weight:700;">No duplicate shippers removed.</div>`;
    finalSummaryEl.innerHTML = `
      <div style="font-weight:800; color:#172033;">JOC Data Hub import completed ✓</div>
      <div style="display:flex; gap:14px; flex-wrap:wrap; margin-top:8px; font-size:12px; color:#475569;">
        <span><b>${newAnalyticsRows.length.toLocaleString()}</b> New Shippers Added</span>
        <span style="color:#B45309;"><b>${removedDuplicates.length.toLocaleString()}</b> Duplicate Shippers Removed</span>
        <span><b>${analytics.rows.length.toLocaleString()}</b> Processed Shippers</span>
      </div>
      ${removedHtml}
    `;
  }

  toast(`JOC database added to Data Hub: ${name}. ${removedDuplicates.length.toLocaleString()} duplicate shippers removed.`, 'success');
  if(button){button.dataset.busy='';button.disabled=false;button.textContent='Added to Data Hub ✓';}
  if (typeof showPage === 'function') showPage('alldata');
  setTimeout(()=>{ renderDatabaseList(); }, 50);
  return true;
}
function logJOCDataHubProgress(done,total,pct){
  const el=byId('joc-swift-summary');
  if(el && total) el.innerHTML=`<div style="font-weight:800; color:#1D4ED8;">Adding classified JOC to Data Hub… ${pct}%</div><div style="font-size:12px; color:#64748B; margin-top:4px;">${done.toLocaleString()} / ${total.toLocaleString()} shippers</div>`;
}

async function saveProcessedOutputToJOC(sourceFileName,rowCount){
  const blob=JOCToolkit.getOutputBlob();
  if(!blob)return{saved:false,reason:'no-output'};
  const suggested=String(sourceFileName||'JOC Output').replace(/\.(xlsx|xlsm|xls)$/i,'').trim()||'JOC Output';
  const clean=await requestJOCName(suggested);

  const analytics=JOCToolkit.getAnalytics ? JOCToolkit.getAnalytics() : null;
  const swift=JOCToolkit.getSwiftClassification ? JOCToolkit.getSwiftClassification() : null;
  const book={id:`joc_${Date.now()}_${Math.random().toString(36).slice(2,9)}`,name:clean,sourceFileName:String(sourceFileName||'Processed workbook'),createdAt:Date.now(),rowCount:Number(rowCount)||0,blob,
    totals:analytics?.totals || {shippers:0,teus:0,weight:0,weightUnits:[]},
    analyticsRows:analytics?.rows || null,
    swiftClassification:swift?.summary || analytics?.swift || null,
    totalsPending:!analytics};
  try{
    // Save locally first so a Storage/API failure can never force the user
    // to run the expensive 67k+ row JOC processor again.
    const saved=await JOCLibrary.put(book);
    jocLibraryBooks=await JOCLibrary.all();
    renderJOCLibrary();
    if(saved.cloudSyncPending){
      toast(`"${clean}" saved to JOC. Cloud sync is pending; your workbook is safe on this device.`,'success');
    }else if(saved.cloud){
      toast(`"${clean}" saved permanently to JOC.`,'success');
    }else{
      toast(`"${clean}" saved to JOC.`,'success');
    }
    return{saved:true,book:saved};
  }catch(e){console.error('JOC save failed',e);toast(`Could not save JOC "${clean}": ${e.message||e}`,'error');return{saved:false,reason:'error',error:e.message||String(e)};}
}
async function saveCurrentProcessedWorkbookToJOC(sourceFileName,rowCount){return saveProcessedOutputToJOC(sourceFileName,rowCount);}


/* ==========================================================================
   SWIFT & NON-SWIFT INTELLIGENCE — Company-Identity-Only / Zero Review / Zero Manual.

   Second Toolkit, added alongside JOC. Entirely self-contained: its own
   module, its own IDs (prefixed "sw-"), its own IndexedDB store. Nothing
   here reads or writes JOCToolkit/JocLocalFolder state, and nothing in
   those modules is touched.

   SAFETY PRINCIPLE
   -----------------
   Similarity is evidence, not proof. A record is only auto-decided (Swift
   or Non-Swift) when the evidence is deterministic or overwhelming AND
   there is no conflicting identifier AND no closely-competing candidate.
   Everything else — including every case where the algorithm is merely
   "pretty confident" — is routed to a capped, risk-ranked Manual
   Verification queue (max 50 at a time). Records beyond that cap are
   never silently auto-resolved: they stay "Pending Verification".

   PIPELINE
   --------
   normalize -> exact identity -> verified alias -> identifier match ->
   multi-signal candidate scoring -> conflict detection -> uniqueness /
   margin check -> Safe Swift | Safe Non-Swift | Manual Check (top 50 by
   risk) | Pending Verification -> human decision -> verified knowledge
   (aliases / negative matches / audit trail) -> re-run.

   The permanent Swift master (parsed + indexed) is stored in IndexedDB so
   it survives reload/restart without re-uploading. Target customer lists
   are job-specific and are never persisted. Verified knowledge (aliases,
   negative matches, audit trail) IS persisted, per spec §7/§27/§30.
   ========================================================================== */
const SwiftToolkit = (() => {

  const DB_NAME = 'swift_master_db';
  const DB_VERSION = 2;
  const STORE = 'master';
  const MASTER_KEY = 'permanentMaster';
  const ALIAS_KEY = 'verifiedAliases';       // { observedNormalized: {canonicalOriginal, verifiedAt, source, count} }
  const NEGATIVE_KEY = 'negativeMatches';    // { "obsNorm|candNorm": {verifiedAt, source} }
  const AUDIT_KEY = 'auditTrail';            // [ {ts, target, candidate, previousDecision, newDecision, reason, type} ]

  /* ---------- centralized configuration (spec §44) ---------- */
  const MATCH_CONFIG = {
    maxManualChecks: 50,
    // When true, no record is left in Review/Manual Check/Pending Verification —
    // classifyOne() resolves every would-be Review verdict to Swift or Non-Swift
    // using the swift.minimumScore bar below. Set to false to restore the
    // original conservative behavior (ambiguous cases routed to a human).
    forceBinaryDecision: true,
    swift: { minimumScore: 90, minimumMargin: 7 },
    // maximumSafeScore: legacy "both best & second are trivially low" floor — still used
    // by the negative-match-memory path. viableMatchCeiling is the new, broader boundary
    // (surgical fix): below it, a best score with no credible competing candidate is a
    // safe Non-Swift decision rather than an automatic Manual Check. At/above it (up to
    // the Swift threshold) the record sits in the genuinely uncertain boundary band and
    // stays Manual — this intentionally does NOT touch swift.minimumScore/minimumMargin.
    nonSwift: { maximumSafeScore: 55, viableMatchCeiling: 85 },
    review: {
      maxCandidates: 5,
      // A second-place candidate only counts as a genuine competitor if its OWN
      // score clears this bar. A low-score also-ran (e.g. 54 while best is 97)
      // must never by itself force Manual Check — only a credible near-duplicate
      // (e.g. 94 while best is 97) should. Fixes over-routing of clearly-unique
      // strong matches into Manual Check.
      competingCandidateMinScore: 80,
    },
    safety: {
      identifierConflictRequiresManual: true,
      competingCandidateRequiresManual: true,
      duplicateMasterRequiresManual: true,
    },
  };


  /* Identifier column detection patterns, in priority-tier order (spec §8/§9) */
  const IDENTIFIER_FIELDS = [
    { key: 'gstin',  tier: 'A', test: /\bgstin\b|\bgst\s*no/i },
    { key: 'cin',    tier: 'A', test: /\bcin\b/i },
    { key: 'pan',    tier: 'A', test: /\bpan\b/i },
    { key: 'iec',    tier: 'A', test: /\biec\b/i },
    { key: 'regno',  tier: 'A', test: /registration\s*(no|number)|company\s*registration/i },
    { key: 'email',  tier: 'B', test: /e[-\s]?mail/i },
    { key: 'phone',  tier: 'B', test: /\bphone\b|\bmobile\b|\bcontact\s*no/i },
    { key: 'website',tier: 'B', test: /website|\bdomain\b/i },
    { key: 'address',tier: 'C', test: /\baddress\b/i },
    { key: 'pincode',tier: 'C', test: /pincode|postal\s*code|\bpin\b/i },
    { key: 'city',   tier: 'C', test: /\bcity\b/i },
    { key: 'state',  tier: 'C', test: /\bstate\b/i },
    { key: 'contact',tier: 'C', test: /contact\s*person/i },
  ];
  const TIER_A_KEYS = IDENTIFIER_FIELDS.filter(f => f.tier === 'A').map(f => f.key);
  const TIER_B_KEYS = IDENTIFIER_FIELDS.filter(f => f.tier === 'B').map(f => f.key);

  let masterMeta = null;      // { fileName, uploadedAt, rowCount, columnName, idColumns }
  let masterEntries = [];     // [{ original, normalized, tokens, meaningfulTokens, core, ident:{} }]
  let masterIndex = null;     // { exactIndex, coreIndex, tokenIndex, prefixIndex, identIndex }
  let masterDuplicates = [];  // duplicate groups found in the master
  let masterQuality = null;   // { total, unique, duplicates, withIdentifiers, withoutIdentifiers, health }

  let targetMeta = null;      // { fileName, rowCount, columnName, idColumns }
  let targetEntries = null;   // parsed target rows, same entry shape as master

  let lastResults = null;     // [{ original, remark, bestName, bestScore, secondScore, reason, ... evidence }]
  let lastRunStats = null;    // { total, swift, nonSwift, manual, pending, ms, rate, conflictRate, coverage }
  let lastOutputBlob = null;
  let running = false;

  let verifiedAliases = {};   // persisted
  let negativeMatches = {};   // persisted
  let auditTrail = [];        // persisted

  let manualQueue = [];       // risk-ranked, capped-to-50 subset of current Manual Check results (indices into lastResults)
  let manualCursor = 0;       // position within manualQueue for the workbench

  function byId(id){ return document.getElementById(id); }
  function show(el, on){ if (el) el.classList.toggle('hidden', !on); }
  function escHtml(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  /* ---------- IndexedDB: persists master + verified knowledge ----------
     No version number is passed to indexedDB.open(): this opens at whatever
     version already exists for this origin/DB name, and only runs
     onupgradeneeded (to create the store) the first time the DB is created.
     Hardcoding DB_VERSION here previously caused "requested version (1) is
     less than existing version (2)" failures for anyone whose browser had
     already bumped this database to a higher version in an earlier session —
     that error is unrecoverable from JS and blocks the master from loading
     at all, so it must never be forced. */
  function openDb(){
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME);
      req.onupgradeneeded = () => {
        if (!req.result.objectStoreNames.contains(STORE)) req.result.createObjectStore(STORE);
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }
  async function idbSet(key, value){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(value, key);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
  async function idbGet(key){
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, 'readonly');
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => reject(req.error);
    });
  }
  async function loadVerifiedKnowledge(){
    try{
      verifiedAliases = (await idbGet(ALIAS_KEY)) || {};
      negativeMatches = (await idbGet(NEGATIVE_KEY)) || {};
      auditTrail = (await idbGet(AUDIT_KEY)) || [];
    } catch(e){ verifiedAliases = {}; negativeMatches = {}; auditTrail = []; }
  }
  async function saveAliases(){ try{ await idbSet(ALIAS_KEY, verifiedAliases); } catch(e){} }
  async function saveNegatives(){ try{ await idbSet(NEGATIVE_KEY, negativeMatches); } catch(e){} }
  async function saveAudit(){ try{ await idbSet(AUDIT_KEY, auditTrail); } catch(e){} }

  function logAudit(entry){
    auditTrail.unshift(Object.assign({ ts: Date.now() }, entry));
    if (auditTrail.length > 5000) auditTrail.length = 5000;
    saveAudit();
  }

  /* ---------- practical company-identity normalization ---------- */
  function stripAccents(s){ try { return s.normalize('NFD').replace(/[\u0300-\u036f]/g,''); } catch(e){ return s; } }
  const COMPANY_LEGAL_TOKENS = new Set(['LTD','LIMITED','PVT','PRIVATE','LLP','LLC','INC','INCORPORATED','CORP','CORPORATION','CO','COMPANY','PLC','GMBH','SA','BV','AG','PTY','PROPRIETARY']);
  // NOTE: GROUP/HOLDING are deliberately NOT filtered out as "structure" tokens.
  // A parent/holding-style suffix is exactly the kind of addition that can mean
  // a DIFFERENT legal entity (spec: identity-changing additions, corporate
  // relationship caution) — so it must stay visible to the identity-token
  // comparison rather than being silently discarded like "international"/"india".
  const BUSINESS_STRUCTURE_TOKENS = new Set(['THE','AND','OF','FOR','IN','AT','ON','BY','TO','A','AN','DIVISION','DIVISIONS','DIV','UNIT','UNITS','BRANCH','BRANCHES','SYSTEM','SYSTEMS','DEPARTMENT','DEPT','BUSINESS','BUSINESSUNIT','ENTERPRISE','ENTERPRISES','COMPANY','CO','CORPORATION','CORP','PRIVATE','PVT','INTERNATIONAL','INTL','GLOBAL','INDIA','INDIAN','AMERICA','AMERICAN','ASIA','ASIAN','EUROPE','EUROPEAN','SERVICES','SERVICE']);
  const WORD_CANON = {AND:'AND',INTL:'INTERNATIONAL',INTLNL:'INTERNATIONAL',INTERNTNL:'INTERNATIONAL',TECH:'TECHNOLOGY',TECHNOL:'TECHNOLOGY',TECHNOLOGY:'TECHNOLOGY',TECHNOLOGIES:'TECHNOLOGY',SYS:'SYSTEM',SYSTEM:'SYSTEM',SYSTEMS:'SYSTEM',SOLN:'SOLUTION',SOLNS:'SOLUTION',SOLUTION:'SOLUTION',SOLUTIONS:'SOLUTION',TYRE:'TYRE',TYRES:'TYRE',TIRE:'TIRE',TIRES:'TIRE',IND:'INDUSTRIAL',INDUSTRIAL:'INDUSTRIAL',INDUSTRIES:'INDUSTRIAL',INDUSTRY:'INDUSTRIAL',MFG:'MANUFACTURING',MANUF:'MANUFACTURING',MANUFACTURER:'MANUFACTURING',MANUFACTURERS:'MANUFACTURING',CORP:'CORPORATION',CORPORATION:'CORPORATION',CO:'COMPANY',COMPANY:'COMPANY',ASSOC:'ASSOCIATES',ASSOCS:'ASSOCIATES',ASSOCIATE:'ASSOCIATES',ENTERPRIZE:'ENTERPRISE',ENTERPRIZES:'ENTERPRISE',ENTERPRISE:'ENTERPRISE',ENTERPRISES:'ENTERPRISE',CTR:'CENTER',CNTR:'CENTER',SVCS:'SERVICES',SVC:'SERVICE',LOGSTCS:'LOGISTICS',LOGISTIC:'LOGISTICS',LOGISTICS:'LOGISTICS',PVT:'PRIVATE',LTD:'LIMITED',GROUP:'GROUP',GROUPS:'GROUP',HOLDING:'HOLDING',HOLDINGS:'HOLDING',TRADING:'TRADING',TRADE:'TRADING',TRANSPORT:'TRANSPORT',TRANSPORTS:'TRANSPORT',TRANSPORTATION:'TRANSPORT',EXPORT:'EXPORT',EXPORTS:'EXPORT',IMPORT:'IMPORT',IMPORTS:'IMPORT',BROS:'BROTHERS',BROTHER:'BROTHERS',BROTHERS:'BROTHERS'};
  /* Words whose PRESENCE ON ONE SIDE ONLY materially changes what business the
     entity is in (spec §8/§9/§20/§21). These are never stripped from the
     identity-token set (unlike pure filler such as "international"/"pvt"); an
     asymmetric identity-changing token is treated as a standalone reason to
     stop short of an automatic SWIFT decision, no matter how high the rest of
     the name similarity scores. This is a deliberately small, illustrative
     seed list (mirrors the examples in the spec) — the master-driven rarity
     (tokenFreq / IDF) below is what actually does the heavy lifting on
     "generic vs distinctive", not this list. */
  const IDENTITY_CHANGING_TOKENS = new Set(['INDUSTRIAL','MANUFACTURING','TRADING','TECHNOLOGY','HOLDING','GROUP','CAPITAL','FINANCE','FINANCIAL','AUTOMOTIVE','MARINE','CHEMICAL','CHEMICALS','PHARMA','PHARMACEUTICAL','PHARMACEUTICALS','RETAIL','CONSTRUCTION','ENGINEERING','ELECTRONICS','TEXTILE','TEXTILES','FOODS','FOOD','BEVERAGE','BEVERAGES','MOTORS','MOTOR','MINING','ENERGY','POWER','INFRASTRUCTURE','REALTY','PROPERTIES','HOSPITALITY','AVIATION','TELECOM','MEDIA','ENTERTAINMENT','AGRO','AGRICULTURE','STEEL','CEMENT','PLASTICS','PACKAGING','CONSULTING','CONSULTANTS','INSURANCE','BANK','BANKING','JEWELLERS','JEWELLERY','APPAREL','GARMENTS']);
  const SUFFIX_TOKENS = new Set([...COMPANY_LEGAL_TOKENS]);
  const SUFFIX_CANON = {PRIVATE:'PVT',LIMITED:'LTD',COMPANY:'CO',CORPORATION:'CORP',INCORPORATED:'INC'};
  function normalizeName(raw){
    let s=stripAccents(String(raw==null?'':raw)).toUpperCase().replace(/&/g,' AND ').replace(/[.,'’()\-\/\\]+/g,' ').replace(/[^A-Z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
    if(!s)return '';
    const out=[],seen=new Set();
    for(const rawTok of s.split(' ')){ const tok=WORD_CANON[rawTok]||SUFFIX_CANON[rawTok]||rawTok; if(!tok||seen.has(tok))continue; seen.add(tok); out.push(tok); }
    return out.join(' ');
  }
  function tokenize(s){ return s?s.split(' ').filter(Boolean):[]; }
  function canonicalToken(t){ return WORD_CANON[t]||t; }
  function meaningfulTokens(tokens){ return tokens.filter(t=>!SUFFIX_TOKENS.has(t)&&t.length>1).map(canonicalToken); }
  function coreName(tokens){ return tokens.filter(t=>!SUFFIX_TOKENS.has(t)).map(canonicalToken).join(' '); }
  function identityTokensOf(tokens){ return meaningfulTokens(tokens).filter(t=>!BUSINESS_STRUCTURE_TOKENS.has(t)&&!SUFFIX_TOKENS.has(t)); }
  function compactName(s){ return String(s||'').replace(/[^A-Z0-9]/g,''); }
  function acronymOf(tokens){ return (tokens||[]).filter(t=>t&&!SUFFIX_TOKENS.has(t)).map(t=>canonicalToken(t)[0]).join(''); }
  function prefixSimilarity(a,b){ const x=String(a||''),y=String(b||''); const n=Math.min(x.length,y.length); if(!n)return 0; let i=0; while(i<n&&x[i]===y[i])i++; return i/Math.max(x.length,y.length); }
  function normalizeIdentValue(key,raw){ if(raw==null)return ''; let s=String(raw).trim(); if(!s)return ''; if(key==='email'||key==='website')return s.toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/$/,''); if(key==='phone')return s.replace(/[^\d]/g,'').replace(/^0+/,'').slice(-10); if(key==='gstin'||key==='pan'||key==='cin'||key==='iec'||key==='regno'||key==='pincode')return s.toUpperCase().replace(/\s+/g,''); return s.toUpperCase().replace(/\s+/g,' ').trim(); }
  function makeEntry(original,identRaw){ const normalized=normalizeName(original),tokens=tokenize(normalized),ident={}; if(identRaw)Object.keys(identRaw).forEach(k=>{const v=normalizeIdentValue(k,identRaw[k]);if(v)ident[k]=v;}); const meaningful=meaningfulTokens(tokens),core=coreName(tokens),identityTokens=identityTokensOf(tokens),identityCore=identityTokens.join(' '); return {original:String(original==null?'':original).trim(),normalized,tokens,meaningfulTokens:meaningful,identityTokens,core,identityCore,compact:compactName(core),identityCompact:compactName(identityCore),acronym:acronymOf(meaningful),identityAcronym:acronymOf(identityTokens),soundexKey:meaningful.map(t=>soundex(t)).filter(Boolean).slice(0,3).join('-'),ident}; }
  function yieldToBrowser(timeout=50){ return new Promise(resolve=>{ if(window.requestIdleCallback)requestIdleCallback(()=>resolve(),{timeout}); else setTimeout(resolve,0); }); }
  async function buildEntriesChunked(rows, identRows, onProgress){
    const out = new Array(rows.length);
    const CHUNK = 1000;
    for (let start = 0; start < rows.length; start += CHUNK){
      const end = Math.min(start + CHUNK, rows.length);
      for (let i = start; i < end; i++) out[i] = makeEntry(rows[i], identRows ? identRows[i] : null);
      if (onProgress) onProgress(end, rows.length);
      await yieldToBrowser(35);
    }
    return out;
  }

  /* ---------- blocking index (exact / alias / token / prefix / identifier) ---------- */
  function buildIndex(entries){
    const exactIndex = new Map();
    const coreIndex = new Map();
    const tokenIndex = new Map();
    const prefixIndex = new Map();
    const soundexIndex = new Map();
    const compactPrefixIndex = new Map();
    const trigramIndex = new Map();
    const tokenFreq = new Map();
    const identIndex = {}; // key -> Map(value -> [idx,...])
    IDENTIFIER_FIELDS.forEach(f => { identIndex[f.key] = new Map(); });

    entries.forEach((e, idx) => {
      if (e.normalized){
        if (!exactIndex.has(e.normalized)) exactIndex.set(e.normalized, []);
        exactIndex.get(e.normalized).push(idx);
      }
      if (e.core && e.core.length >= 3){
        if (!coreIndex.has(e.core)) coreIndex.set(e.core, []);
        coreIndex.get(e.core).push(idx);
      }
      const toks = e.meaningfulTokens.length ? e.meaningfulTokens : e.tokens;
      const seenToks = new Set();
      toks.forEach(t => {
        if (!tokenIndex.has(t)) tokenIndex.set(t, new Set());
        tokenIndex.get(t).add(idx);
        if (!seenToks.has(t)){ tokenFreq.set(t, (tokenFreq.get(t) || 0) + 1); seenToks.add(t); }
      });
      const grams = new Set();
      const sig = e.identityCompact || e.compact || '';
      for (let gi = 0; gi < sig.length - 2; gi++) grams.add(sig.slice(gi, gi + 3));
      grams.forEach(g => { if (!trigramIndex.has(g)) trigramIndex.set(g, new Set()); trigramIndex.get(g).add(idx); });
      const pre = e.core.slice(0, 4);
      if (pre){
        if (!prefixIndex.has(pre)) prefixIndex.set(pre, new Set());
        prefixIndex.get(pre).add(idx);
      }
      if (e.soundexKey){
        const firstSound = e.soundexKey.split('-')[0];
        if (firstSound){
          if (!soundexIndex.has(firstSound)) soundexIndex.set(firstSound, new Set());
          soundexIndex.get(firstSound).add(idx);
        }
      }
      if (e.compact){
        const cpre = e.compact.slice(0, 5);
        if (cpre){
          if (!compactPrefixIndex.has(cpre)) compactPrefixIndex.set(cpre, new Set());
          compactPrefixIndex.get(cpre).add(idx);
        }
      }
      Object.keys(e.ident || {}).forEach(k => {
        const v = e.ident[k];
        if (!v) return;
        const m = identIndex[k];
        if (!m) return;
        if (!m.has(v)) m.set(v, []);
        m.get(v).push(idx);
      });
    });
    const identitySignatureIndex = new Map();
    entries.forEach((e,i)=>{
      const ids = identityTokensStrict(e);
      ids.forEach(t=>{ const sig=t.slice(0,3)+'|'+t.slice(-2)+'|'+t.length; if(!identitySignatureIndex.has(sig))identitySignatureIndex.set(sig,new Set()); identitySignatureIndex.get(sig).add(i); });
    });
    return { exactIndex, coreIndex, tokenIndex, prefixIndex, soundexIndex, compactPrefixIndex, trigramIndex, tokenFreq, identIndex, identitySignatureIndex };
  }

  /* ---------- master duplicate detection + quality score (spec §31/§32) ---------- */
  function analyzeMasterQuality(entries, index){
    const dupGroups = [];
    index.exactIndex.forEach((idxs, key) => { if (idxs.length > 1) dupGroups.push({ type: 'Exact normalized name', key, idxs }); });
    index.coreIndex.forEach((idxs, key) => {
      const uniqueOriginals = new Set(idxs.map(i => entries[i].normalized));
      if (idxs.length > 1 && uniqueOriginals.size > 1) dupGroups.push({ type: 'Same core (alias) name', key, idxs });
    });
    TIER_A_KEYS.concat(TIER_B_KEYS).forEach(k => {
      const m = index.identIndex[k];
      if (!m) return;
      m.forEach((idxs, val) => {
        if (idxs.length > 1){
          const distinctNames = new Set(idxs.map(i => entries[i].normalized));
          if (distinctNames.size > 1) dupGroups.push({ type: `Same ${k.toUpperCase()}, different name`, key: val, idxs });
        }
      });
    });
    let withIdentifiers = 0;
    entries.forEach(e => { if (Object.keys(e.ident || {}).length) withIdentifiers++; });
    const uniqueNormalized = index.exactIndex.size;
    const duplicateRecords = entries.length - uniqueNormalized;
    const health = dupGroups.length === 0 ? 'Excellent'
      : dupGroups.length <= Math.max(3, Math.round(entries.length * 0.005)) ? 'Good'
      : 'Needs Review';
    return {
      total: entries.length,
      unique: uniqueNormalized,
      duplicateRecords: Math.max(0, duplicateRecords),
      duplicateGroups: dupGroups.length,
      withIdentifiers,
      withoutIdentifiers: entries.length - withIdentifiers,
      health,
      groups: dupGroups.slice(0, 200),
    };
  }

  function getCandidates(entry, index){
    // High-recall retrieval: exact/core/token/phonetic/prefix plus character
    // trigrams. Candidate ordering is deliberately based on the strongest
    // evidence first, so the safety cap never randomly drops useful matches.
    const scores = new Map();
    const add = (idx, weight) => scores.set(idx, (scores.get(idx) || 0) + weight);
    const toks = entry.identityTokens?.length ? entry.identityTokens : (entry.meaningfulTokens.length ? entry.meaningfulTokens : entry.tokens);
    toks.forEach(t => {
      const bucket = index.tokenIndex.get(t);
      if (bucket) bucket.forEach(i => add(i, 10 + Math.max(0, 8 - Math.log2((index.tokenFreq.get(t) || 1)))));
    });
    const pre = entry.core.slice(0, 4);
    if (pre){ const bucket = index.prefixIndex.get(pre); if (bucket) bucket.forEach(i => add(i, 3)); }
    const firstSound = (entry.soundexKey || '').split('-')[0];
    if (firstSound){ const bucket = index.soundexIndex.get(firstSound); if (bucket) bucket.forEach(i => add(i, 2)); }
    const cpre = (entry.compact || '').slice(0, 5);
    if (cpre){ const bucket = index.compactPrefixIndex.get(cpre); if (bucket) bucket.forEach(i => add(i, 2)); }
    const sig = entry.identityCompact || entry.compact || '';
    const grams = new Set();
    for (let i = 0; i < sig.length - 2; i++) grams.add(sig.slice(i, i + 3));
    grams.forEach(g => { const bucket = index.trigramIndex.get(g); if (bucket) bucket.forEach(i => add(i, 1)); });
    // PERFORMANCE (spec §31): the index already orders candidates by strongest
    // blocking evidence first (rare-token weight, prefix/soundex/trigram
    // support), so truncating here does not change which company wins — it
    // only stops the expensive per-candidate scoring pass (Dice/Levenshtein/
    // token-alignment) from running against hundreds of near-certain
    // non-matches. This was 1800; on large JOC files with common tokens
    // ("logistics", "trading"...) that meant tens of thousands of rows each
    // running ~1800 expensive comparisons, which is what froze the UI.
    return [...scores.entries()].sort((a,b) => b[1]-a[1]).slice(0, 70).map(x => x[0]);
  }

  /* ---------- similarity signals ---------- */
  function bigrams(s){ const b = []; for (let i = 0; i < s.length - 1; i++) b.push(s.substring(i, i + 2)); return b; }
  function diceCoefficient(a, b){
    if (!a || !b) return 0;
    if (a === b) return 1;
    const ba = bigrams(a), bb = bigrams(b);
    if (!ba.length || !bb.length) return 0;
    const map = new Map();
    ba.forEach(x => map.set(x, (map.get(x) || 0) + 1));
    let matches = 0;
    bb.forEach(x => { const c = map.get(x); if (c > 0){ matches++; map.set(x, c - 1); } });
    return (2 * matches) / (ba.length + bb.length);
  }
  function jaccard(a, b){
    if (!a.length && !b.length) return 1;
    const sa = new Set(a), sb = new Set(b);
    let inter = 0; sa.forEach(x => { if (sb.has(x)) inter++; });
    const union = new Set([...sa, ...sb]).size;
    return union ? inter / union : 0;
  }
  const SOUNDEX_CODES = { B:1,F:1,P:1,V:1, C:2,G:2,J:2,K:2,Q:2,S:2,X:2,Z:2, D:3,T:3, L:4, M:5,N:5, R:6 };
  function soundex(word){
    const s = String(word || '').replace(/[^A-Z]/g, '');
    if (!s) return '';
    let out = s[0], last = SOUNDEX_CODES[s[0]] || 0;
    for (let i = 1; i < s.length && out.length < 4; i++){
      const c = SOUNDEX_CODES[s[i]];
      if (c && c !== last) out += c;
      last = c || 0;
    }
    return (out + '000').slice(0, 4);
  }

  function levenshteinRatio(a, b){
    a = String(a || ''); b = String(b || '');
    if (!a && !b) return 1;
    if (!a || !b) return 0;
    if (a === b) return 1;
    if (Math.abs(a.length - b.length) > 8) return 0;
    let prev = new Array(b.length + 1);
    let cur = new Array(b.length + 1);
    for (let j = 0; j <= b.length; j++) prev[j] = j;
    for (let i = 1; i <= a.length; i++){
      cur[0] = i;
      for (let j = 1; j <= b.length; j++) cur[j] = Math.min(cur[j-1] + 1, prev[j] + 1, prev[j-1] + (a[i-1] === b[j-1] ? 0 : 1));
      [prev, cur] = [cur, prev];
    }
    return 1 - prev[b.length] / Math.max(a.length, b.length);
  }
  function tokenBestAverage(aTokens, bTokens){
    if (!aTokens.length || !bTokens.length) return 0;
    let total = 0;
    for (const a of aTokens){
      let best = 0;
      for (const b of bTokens){
        if (a === b){ best = 1; break; }
        if (Math.abs(a.length-b.length) <= 4) best = Math.max(best, levenshteinRatio(a,b));
      }
      total += best;
    }
    return total / aTokens.length;
  }
  function orderedTokenSimilarity(aTokens, bTokens){
    if (!aTokens.length || !bTokens.length) return 0;
    let last = -1, matched = 0;
    for (const a of aTokens){
      let found = -1;
      for (let i = last + 1; i < bTokens.length; i++){
        if (a === bTokens[i] || levenshteinRatio(a,bTokens[i]) >= 0.88){ found = i; break; }
      }
      if (found >= 0){ matched++; last = found; }
    }
    return matched / Math.max(aTokens.length, bTokens.length);
  }

  /* Advanced entity-resolution score. It rewards multiple independent signals,
     weights rare business tokens more heavily, and explicitly penalises
     distinctive target tokens that the candidate fails to explain. */
  function scoreCandidateRaw(target, cand, index){
    const tTok = target.meaningfulTokens.length ? target.meaningfulTokens : target.tokens;
    const cTok = cand.meaningfulTokens.length ? cand.meaningfulTokens : cand.tokens;
    const tId = target.identityTokens?.length ? target.identityTokens : tTok;
    const cId = cand.identityTokens?.length ? cand.identityTokens : cTok;
    const tokenJaccard = jaccard(tId, cId);
    const shared = tId.reduce((n, t) => n + (cId.includes(t) ? 1 : 0), 0);
    const tokenCoverage = Math.min(1, shared / Math.max(1, tId.length));
    const reverseCoverage = Math.min(1, shared / Math.max(1, cId.length));
    const tokenBalance = Math.min(1, Math.min(tId.length, cId.length) / Math.max(1, Math.max(tId.length, cId.length)));
    const charDice = diceCoefficient(target.core, cand.core);
    const identityDice = diceCoefficient(target.identityCompact || target.compact, cand.identityCompact || cand.compact);
    const editRatio = levenshteinRatio(target.identityCompact || target.compact, cand.identityCompact || cand.compact);
    const tokenEdit = tokenBestAverage(tId, cId);
    const ordered = orderedTokenSimilarity(tId, cId);
    const firstTokenDice = diceCoefficient(tTok[0] || '', cTok[0] || '');
    const acronymMatch = (target.acronym && cand.acronym && (target.acronym === cand.acronym || target.acronym === cand.compact || cand.acronym === target.compact)) ? 1 : 0;
    const identityAcronymMatch = target.identityAcronym && cand.identityAcronym && target.identityAcronym === cand.identityAcronym ? 1 : 0;
    const compactContainment = target.compact && cand.compact && (target.compact.includes(cand.compact) || cand.compact.includes(target.compact)) ? 1 : 0;

    let weightedShared = 0, weightedTarget = 0, weightedCandidate = 0;
    for (const t of tId){
      const w = 1 + Math.log1p((index?.tokenFreq?.get(t) ? 1000 / index.tokenFreq.get(t) : 4));
      weightedTarget += w;
      if (cId.includes(t)) weightedShared += w;
    }
    for (const c of cId){
      const w = 1 + Math.log1p((index?.tokenFreq?.get(c) ? 1000 / index.tokenFreq.get(c) : 4));
      weightedCandidate += w;
    }
    const weightedRecall = weightedTarget ? weightedShared / weightedTarget : 0;
    const weightedPrecision = weightedCandidate ? weightedShared / weightedCandidate : 0;
    const distinctivePenalty = Math.max(0, weightedRecall - weightedPrecision) * 16;

    let score = tokenJaccard * 16
      + tokenCoverage * 12
      + reverseCoverage * 7
      + weightedRecall * 16
      + weightedPrecision * 10
      + charDice * 10
      + identityDice * 9
      + editRatio * 7
      + tokenEdit * 7
      + ordered * 4
      + tokenBalance * 4
      + firstTokenDice * 2
      + acronymMatch * 5
      + identityAcronymMatch * 4
      + compactContainment * 2
      - distinctivePenalty;

    if (target.normalized === cand.normalized) score = 100;
    else if (target.identityCompact && target.identityCompact === cand.identityCompact) score = Math.max(score, 97);
    else if (target.compact && target.compact === cand.compact) score = Math.max(score, 96);

    return { score: Math.max(0, Math.min(100, score)), tokenJaccard, tokenCoverage, reverseCoverage, tokenBalance, charDice, identityDice, editRatio, tokenEdit, ordered, acronymMatch, identityAcronymMatch, compactContainment, weightedRecall, weightedPrecision };
  }

  /* compare identifier fields between target and a candidate -> { agree:[], conflict:[], tierAConflict, tierBConflict } */
  function compareIdentifiers(target, cand){
    const agree = [], conflict = [];
    Object.keys(target.ident || {}).forEach(k => {
      const tv = target.ident[k];
      const cv = (cand.ident || {})[k];
      if (!tv || !cv) return;
      if (tv === cv) agree.push(k);
      else conflict.push(k);
    });
    const tierAConflict = conflict.some(k => TIER_A_KEYS.includes(k));
    const tierBConflict = conflict.some(k => TIER_B_KEYS.includes(k));
    return { agree, conflict, tierAConflict, tierBConflict };
  }

  function aliasKeyFor(normalized){ return normalized; }
  function negKeyFor(aNorm, bNorm){ return aNorm < bNorm ? `${aNorm}|${bNorm}` : `${bNorm}|${aNorm}`; }

  /* ---------- common-name / distinctiveness protection (spec §5/§6/§18) ----------
     A company's identity is only as strong as its rarest meaningful token. This
     is calculated fresh from the actual master (tokenFreq), never hardcoded:
     an identity token counts as "distinctive" when it is rare enough in the
     master and long enough to be a real word, not an abbreviation fragment.
     If NONE of a company's identity tokens clear that bar, its name is built
     entirely from generic/common business vocabulary and fuzzy similarity
     alone must never be treated as proof of identity (spec §18).

     TIGHTENED: the old bar (0.8% of the master, ~40 companies in a 5,000-row
     master) let ordinary industry vocabulary — "wovens", "gears",
     "handicrafts", "associates", "pharmaceuticals" — pass as "distinctive"
     just because it happened not to repeat much in one particular master,
     even though it isn't a real brand identity the way "Tsubaki" or "Cummins"
     is. A SINGLE shared token is the highest-risk case (spec §23 — a short
     name carries less information) so it now needs a materially stricter,
     length-aware bar than a multi-token identity does. */
  function hasDistinctiveIdentity(tId, index, masterCount){
    if (!tId || !tId.length) return false;
    const multiTokenBar = Math.max(3, Math.round((masterCount || 0) * 0.0015));
    if (tId.length === 1){
      const t = tId[0];
      const singleTokenBar = Math.max(2, Math.round((masterCount || 0) * 0.0006));
      return t.length >= 6 && ((index?.tokenFreq?.get(t) || 0) <= singleTokenBar);
    }
    return tId.some(t => t.length >= 4 && ((index?.tokenFreq?.get(t) || 0) <= multiTokenBar));
  }


  /* ---------- identity-changing addition detection (spec §8/§9/§20/§21) ----------
     Returns the set of identity-changing tokens present on ONLY one side of the
     comparison. A shared identity-changing token (both names say "Trading") is
     not a conflict — only an asymmetric one is, because it signals the two
     names may describe different lines of business or a different legal
     entity within the same brand family. */
  function identityChangingConflict(targetTokens, candTokens){
    const tSet = new Set(targetTokens || []), cSet = new Set(candTokens || []);
    const onlyTarget = (targetTokens || []).filter(t => IDENTITY_CHANGING_TOKENS.has(t) && !cSet.has(t));
    const onlyCand = (candTokens || []).filter(t => IDENTITY_CHANGING_TOKENS.has(t) && !tSet.has(t));
    const tokens = [...new Set([...onlyTarget, ...onlyCand])];
    return { conflict: tokens.length > 0, tokens };
  }

  /* ---------- CENTRALIZED COMPANY-ID-ONLY RESOLVER ----------
     One authoritative decision engine for Swift Intelligence and JOC.
     IMPORTANT: phone/email/website/address/GST/CIN/PAN/contact/person data are
     deliberately ignored. Fuzzy string similarity is never sufficient proof.
     Every non-empty name is deterministically classified as Swift or Non swift.
  */
  const IDENTITY_GENERIC_TOKENS = new Set([
    'THE','AND','OF','FOR','IN','AT','ON','BY','TO','A','AN',
    'LOGISTICS','LOGISTIC','SHIPPING','SHIPMENT','CARGO','FREIGHT','FORWARDING',
    'TRANSPORT','TRANSPORTS','TRANSPORTATION','EXPORT','EXPORTS','IMPORT','IMPORTS',
    'EXIM','TRADING','TRADE','SERVICES','SERVICE','SOLUTIONS','SOLUTION','SYSTEM','SYSTEMS',
    'TECHNOLOGY','TECHNOLOGIES','TECH','INDUSTRIAL','INDUSTRY','INDUSTRIES',
    'ENTERPRISE','ENTERPRISES','COMPANY','CORPORATION','CORP','CO','AGENCIES','AGENCY',
    'ASSOCIATES','ASSOCIATE','ASSOC','LIMITED','LTD','PRIVATE','PVT','LLP','LLC','INC',
    'INCORPORATED','PLC','GMBH','SA','BV','AG','PTY','PROPRIETARY',
    'INDIA','INDIAN','SHANGHAI','CHINA','CHINESE','ASIA','ASIAN','EUROPE','EUROPEAN',
    'AMERICA','AMERICAN','GLOBAL','INTERNATIONAL','INTL','WORLDWIDE',
    'VALVES','VALVE','WOVENS','WOVEN','WOODS','METAL','METALS','VIBRATION','CONTROL',
    'POWER','ENERGY','CHEM','CHEMICAL','CHEMICALS','MARINE','HYDRAULICS',
    'CARGOES','PRODUCTS','PRODUCT','MANUFACTURING','MANUFACTURER','MANUFACTURERS',
    'TECHNICAL','ENGINEERING','ENGINEERS','CONSTRUCTION','CONSULTING','CONSULTANTS',
    'FINANCE','FINANCIAL','CAPITAL','RETAIL','AUTOMOTIVE','ELECTRONICS','TEXTILE','TEXTILES',
    'FOOD','FOODS','BEVERAGE','BEVERAGES','MOTORS','MOTOR','MINING','INFRASTRUCTURE',
    'REALTY','PROPERTIES','HOSPITALITY','AVIATION','TELECOM','MEDIA','ENTERTAINMENT',
    'AGRO','AGRICULTURE','STEEL','CEMENT','PLASTICS','PACKAGING','APPAREL','GARMENTS',
    'CENTER','CENTRE','DIVISION','DIVISIONS','DIV','UNIT','UNITS','BRANCH','BRANCHES',
    'DEPARTMENT','DEPT','BUSINESS','BUSINESSUNIT','BROTHERS','BROS','SEZ','EOU','EPC','SBU','CHE','PLANT','WORKS','FACTORY','FACILITY','FACILITIES'
  ]);
  const IDENTITY_LEGAL_TOKENS = new Set([...COMPANY_LEGAL_TOKENS]);
  const IDENTITY_GEO_TOKENS = new Set([
    'INDIA','INDIAN','SHANGHAI','CHINA','CHINESE','ASIA','ASIAN','EUROPE','EUROPEAN',
    'AMERICA','AMERICAN','MUMBAI','DELHI','DUBAI','SINGAPORE','JAPAN','JAPANESE',
    'KOREA','KOREAN','TAIWAN','TAIWANESE','GERMANY','GERMAN','FRANCE','FRENCH',
    'UK','UAE','USA','US','CANADA','CANADIAN','AUSTRALIA','AUSTRALIAN'
  ]);

  const IDENTITY_SOFT_QUALIFIER_TOKENS = new Set([
    'SEZ','EOU','EPC','SBU','CHE','DIVISION','DIVISIONS','DIV','UNIT','UNITS','BRANCH','BRANCHES',
    'DEPARTMENT','DEPT','PLANT','WORKS','FACTORY','FACILITY','FACILITIES','CENTER','CENTRE'
  ]);
  function isGenericIdentityToken(t){
    const x=canonicalToken(String(t||'').toUpperCase());
    return !x || /^\d+$/.test(x) || x.length<=1 || IDENTITY_GENERIC_TOKENS.has(x) || IDENTITY_LEGAL_TOKENS.has(x) || IDENTITY_GEO_TOKENS.has(x) || IDENTITY_SOFT_QUALIFIER_TOKENS.has(x);
  }
  function identityTokensStrict(entry){
    const toks=[...new Set((entry.tokens||[]).map(canonicalToken))];
    return toks.filter(t=>!isGenericIdentityToken(t));
  }
  function identityTokenFrequency(index,t){ return Number(index?.tokenFreq?.get(t)||0); }
  function distinctiveWeight(index,t){
    const f=identityTokenFrequency(index,t);
    if(f<=1)return 100;
    if(f<=3)return 60;
    if(f<=10)return 35;
    if(f<=30)return 15;
    return 5;
  }
  function identityTokenClose(a,b){
    if(a===b)return 1;
    // Controlled typo/morphology is intentionally narrow: one edit only, on a
    // sufficiently long distinctive token. Similarity by itself is never a
    // positive decision signal.
    if(a.length<6 || b.length<6)return 0;
    if(Math.abs(a.length-b.length)>1)return 0;
    const r=levenshteinRatio(a,b);
    return r>=0.88 ? r : 0;
  }
  function companyIdentityProfile(entry,index){
    const all=[...new Set((entry.tokens||[]).map(canonicalToken))];
    const distinctive=identityTokensStrict(entry);
    const generic=all.filter(t=>isGenericIdentityToken(t));
    const weights=new Map(distinctive.map(t=>[t,distinctiveWeight(index,t)]));
    return {all,distinctive,generic,weights};
  }

  function buildIdentityOnlyIndex(entries){
    const exactIndex=new Map(), tokenIndex=new Map(), tokenFreq=new Map(), identityCoreIndex=new Map();
    entries.forEach((e,i)=>{
      const p=companyIdentityProfile(e,{tokenFreq});
      e.identityTokens=p.distinctive;
      e.identityCore=p.distinctive.join(' ');
      e.identityCompact=compactName(e.identityCore);
      e.identityProfile=p;
      if(e.normalized){ if(!exactIndex.has(e.normalized))exactIndex.set(e.normalized,[]); exactIndex.get(e.normalized).push(i); }
      if(!identityCoreIndex.has(e.identityCore))identityCoreIndex.set(e.identityCore,[]);
      identityCoreIndex.get(e.identityCore).push(i);
      p.distinctive.forEach(t=>{ if(!tokenIndex.has(t))tokenIndex.set(t,new Set()); tokenIndex.get(t).add(i); });
      const seen=new Set();
      p.distinctive.forEach(t=>{ if(!seen.has(t)){tokenFreq.set(t,(tokenFreq.get(t)||0)+1);seen.add(t);} });
    });
    // Recompute profiles after frequencies are known so rarity is master-driven.
    entries.forEach(e=>{e.identityProfile=companyIdentityProfile(e,{tokenFreq});e.identityTokens=e.identityProfile.distinctive;e.identityCore=e.identityTokens.join(' ');e.identityCompact=compactName(e.identityCore);});
    // Keep the standalone identity index self-sufficient too. Controlled typo
    // lookup uses a compact first/last/length signature; no master-wide fuzzy scan.
    const identitySignatureIndex=new Map();
    entries.forEach((e,i)=>{
      (e.identityTokens||[]).forEach(t=>{
        const sig=t.slice(0,3)+'|'+t.slice(-2)+'|'+t.length;
        if(!identitySignatureIndex.has(sig))identitySignatureIndex.set(sig,new Set());
        identitySignatureIndex.get(sig).add(i);
      });
    });
    return {exactIndex,tokenIndex,tokenFreq,identityCoreIndex,identitySignatureIndex};
  }

  function getIdentityCandidates(entry,index){
    const p=entry.identityProfile||companyIdentityProfile(entry,index);
    const scores=new Map();
    const add=(i,w)=>scores.set(i,(scores.get(i)||0)+w);
    // Rare/distinctive exact-token blocking first. Generic-only tokens are NEVER blockers.
    p.distinctive.forEach(t=>{
      const b=index.tokenIndex.get(t); if(b) b.forEach(i=>add(i,distinctiveWeight(index,t)));
    });
    // Controlled typo blocking: compare only against candidates sharing a first/last
    // signature with a distinctive target token; never run fuzzy matching across master.
    p.distinctive.forEach(t=>{
      // Allow a one-character length difference for controlled typo candidates.
      // Prefix+suffix blocking keeps this bounded and prevents target×master fuzzy work.
      for(const len of [t.length-1,t.length,t.length+1]){
        if(len<4)continue;
        const sig=t.slice(0,3)+'|'+t.slice(-2)+'|'+len;
        const b=index.identitySignatureIndex?.get(sig); if(b)b.forEach(i=>add(i,12));
      }
    });
    return [...scores.entries()].sort((a,b)=>b[1]-a[1]).slice(0,60).map(x=>x[0]);
  }

  function identityContextTokens(entry){
    const toks=[...new Set((entry.tokens||[]).map(canonicalToken))];
    // Context is deliberately NOT identity proof. It is conflict evidence.
    // Generic business words may be weak individually, but different business
    // descriptors on the two sides must block an automatic Swift decision.
    return toks.filter(t=>{
      if(!t || t.length<=1)return false;
      if(IDENTITY_SOFT_QUALIFIER_TOKENS.has(t))return false;
      if(IDENTITY_LEGAL_TOKENS.has(t) || IDENTITY_GEO_TOKENS.has(t))return false;
      if(['THE','AND','OF','FOR','IN','AT','ON','BY','TO','A','AN'].includes(t))return false;
      return isGenericIdentityToken(t);
    });
  }

  function contextConflict(targetContext, masterContext){
    const t=new Set(targetContext||[]), m=new Set(masterContext||[]);
    if(!t.size)return false; // Brand-only target may legitimately map to a fuller master name.
    if(!m.size)return true;  // Target explicitly says what kind of entity it is; master does not.
    const shared=[...t].filter(x=>m.has(x));
    const targetCoverage=shared.length/t.size;
    const masterCoverage=shared.length/m.size;
    // For a named/descriptive target, require the descriptive vocabulary to be
    // preserved exactly. Generic words are weak identity evidence, but an
    // added/replaced descriptor can still denote a different business/entity.
    return targetCoverage<1 || masterCoverage<1;
  }

  function resolveSwiftCustomer(companyName, masterIndex, masterEntries){
    const entry=typeof companyName==='object' && companyName ? companyName : makeEntry(companyName,null);
    const entries=Array.isArray(masterEntries)?masterEntries:[];
    const index=masterIndex || buildIdentityOnlyIndex(entries);
    const result={
      remark:'Non swift',bestName:null,bestScore:0,secondScore:0,margin:0,method:'NO_IDENTITY_EVIDENCE',
      strength:'Strong',confidence:100,evidence:[],why:[],candidates:[],identConflict:false,
      decisionReason:'Insufficient distinctive company-name evidence; conservative binary fallback is Non-Swift.'
    };
    if(!entry.normalized){ result.method='EMPTY_NAME'; result.decisionReason='The company name is empty after normalization.'; return result; }

    // LEVEL 1: exact normalized name is deterministic.
    const exact=index.exactIndex.get(entry.normalized)||[];
    if(exact.length){
      const m=entries[exact[0]];
      result.remark='Swift'; result.bestName=m.original; result.bestScore=100; result.confidence=100;
      result.method='EXACT_NORMALIZED'; result.strength='Deterministic'; result.evidence=['Exact normalized company name'];
      result.decisionReason='Target and Swift master company names are identical after normalization.'; return result;
    }

    const tp=companyIdentityProfile(entry,index);
    const tc=identityContextTokens(entry);
    entry.identityProfile=tp; entry.identityTokens=tp.distinctive; entry.identityCore=tp.distinctive.join(' ');
    if(!tp.distinctive.length){
      result.method='GENERIC_ONLY'; result.evidence=['No distinctive company identity token remains after removing generic, legal and geographic words.'];
      result.decisionReason='Only generic/legal/geographic wording is present; shared business vocabulary cannot prove customer identity.';
      return result;
    }

    // Candidate retrieval remains indexed; never scan the whole master with fuzzy matching.
    const candIdxs=getIdentityCandidates(entry,index);
    const scored=[];
    for(const i of candIdxs){
      const m=entries[i], mp=m.identityProfile||companyIdentityProfile(m,index), mt=mp.distinctive;
      if(!mt.length)continue;
      const mc=identityContextTokens(m);
      const shared=[]; const typo=[];
      for(const t of tp.distinctive){
        if(mt.includes(t))shared.push(t);
        else{
          let best=0,bestTok='';
          for(const c of mt){const r=identityTokenClose(t,c);if(r>best){best=r;bestTok=c;}}
          if(best>=0.88)typo.push([t,bestTok,best]);
        }
      }
      const matched=[...shared,...typo.map(x=>x[0])];
      const matchedMaster=[...shared,...typo.map(x=>x[1])];
      const coverage=tp.distinctive.length?matched.length/tp.distinctive.length:0;
      const precision=mt.length?matchedMaster.length/mt.length:0;
      const weightedTotal=tp.distinctive.reduce((n,t)=>n+distinctiveWeight(index,t),0)||1;
      const weightedShared=shared.reduce((n,t)=>n+distinctiveWeight(index,t),0)+typo.reduce((n,x)=>n+distinctiveWeight(index,x[0])*x[2],0);
      const weightedCoverage=weightedShared/weightedTotal;
      const extras=mt.filter(t=>!matchedMaster.includes(t));
      const descriptorConflict=contextConflict(tc,mc);
      // Descriptor agreement is a gate, not a fuzzy score. It cannot turn weak
      // identity evidence into Swift; it only prevents false positives.
      const contextShared=tc.filter(t=>mc.includes(t));
      const contextCoverage=tc.length?contextShared.length/tc.length:1;
      const score=Math.round((weightedCoverage*.65+precision*.20+coverage*.15)*1000)/10;
      scored.push({i,coverage,precision,weightedCoverage,score,shared,typo,extras,descriptorConflict,contextCoverage,tc,mc});
    }
    // Rank compatible business-name context ahead of conflicting candidates.
    // Context is not identity proof, but it is important negative evidence: a
    // matching root with the wrong descriptor must not outrank the same root
    // with the correct descriptor.
    scored.sort((a,b)=>{
      if(a.descriptorConflict!==b.descriptorConflict)return a.descriptorConflict?1:-1;
      if(a.contextCoverage!==b.contextCoverage)return b.contextCoverage-a.contextCoverage;
      return b.score-a.score;
    });
    const best=scored[0],second=scored[1];
    if(!best){
      result.method='NO_DISTINCTIVE_CANDIDATE'; result.evidence=['No master candidate shares a distinctive company token.'];
      result.decisionReason='No meaningful company-identity evidence connects this target to the Swift master.'; return result;
    }
    result.bestName=entries[best.i].original; result.bestScore=best.score; result.secondScore=second?.score||0; result.margin=best.score-(second?.score||0);
    result.candidates=scored.slice(0,5).map(x=>({name:entries[x.i].original,score:x.score,coverage:x.coverage,precision:x.precision,descriptorConflict:x.descriptorConflict}));

    const masterDistinctiveCount=best.extras.length;
    const competing=best.descriptorConflict ? scored.slice(1) : scored.filter(x=>!x.descriptorConflict).slice(1);
    const secondCompatible=competing[0];
    const uniqueEnough=!secondCompatible || best.score-secondCompatible.score>=12;
    const contextCompatible=!best.descriptorConflict;

    /*
       STRICT IDENTITY GATE
       --------------------
       Do not infer identity from token overlap, rarity, fuzzy score, or a
       "one extra master token" rule.  A non-exact name can only become Swift
       when the distinctive identity is identical AND the remaining token
       differences are demonstrably harmless qualifiers/legal/geographic or
       generic business descriptors.

       This deliberately rejects cases such as:
         SMART STRUCTURES -> SMART SHADES STRUCTURES
         NUTS FOR YOU -> NUTS TO YOU
         THE PURCHASE MANAGER -> K A PURCHASE MANAGER
       while still allowing:
         VAJRA USA -> VAJRA SHIPPING SERVICES PRIVATE LIMITED
         HY TECH USA -> HY TECHNOLOGY LTD
    */
    const harmlessQualifierTokens=new Set([
      ...COMPANY_LEGAL_TOKENS,
      ...IDENTITY_GEO_TOKENS,
      ...IDENTITY_SOFT_QUALIFIER_TOKENS,
      ...IDENTITY_GENERIC_TOKENS
    ]);
    // Generic connector words are not identity proof and are NOT harmless
    // substitutions: changing FOR -> TO, for example, can change the name.
    ['THE','AND','OF','FOR','IN','AT','ON','BY','TO','A','AN'].forEach(t=>harmlessQualifierTokens.delete(t));

    function proofSequence(e){
      return [...new Set((e.tokens||[]).map(canonicalToken))]
        .filter(t=>t && !harmlessQualifierTokens.has(t));
    }
    function sameIdentityProofSequence(target,master,allowTypo){
      const a=proofSequence(target), b=proofSequence(master);
      if(a.length!==b.length)return false;
      return a.every((t,i)=>t===b[i] || (allowTypo && identityTokenClose(t,b[i])>=0.88));
    }
    function controlledDistinctiveTypoOnly(){
      if(best.typo.length!==1 || best.shared.length!==Math.max(0,tp.distinctive.length-1))return false;
      if(best.extras.length!==0)return false;
      const t=best.typo[0][0], c=best.typo[0][1];
      return t.length>=6 && c.length>=6 && distinctiveWeight(index,t)>=35 && identityTokenClose(t,c)>=0.88;
    }

    const exactIdentitySet=best.coverage===1 && best.precision===1 && masterDistinctiveCount===0;
    const sameProofIdentity=exactIdentitySet && sameIdentityProofSequence(entry,entries[best.i],false);
    const sameProofIdentityWithTypo=exactIdentitySet && sameIdentityProofSequence(entry,entries[best.i],true);
    const shortenedIdentityAllowed=exactIdentitySet && best.coverage===1 && sameProofIdentity;
    const strongMulti=tp.distinctive.length>=2 && best.coverage===1 && best.precision===1 && masterDistinctiveCount===0 && sameProofIdentity;
    const typoStrong=controlledDistinctiveTypoOnly() && sameProofIdentityWithTypo;

    if(uniqueEnough && contextCompatible && (shortenedIdentityAllowed || strongMulti || typoStrong)){
      const m=entries[best.i];
      result.remark='Swift'; result.bestScore=Math.max(result.bestScore,98); result.confidence=99;
      result.method=best.typo.length?'CONTROLLED_DISTINCTIVE_TYPO':'STRONG_DISTINCTIVE_IDENTITY'; result.strength='High';
      result.evidence=[
        'Distinctive company identity is preserved exactly',
        `Identity coverage ${Math.round(best.coverage*100)}%`,
        best.typo.length?'One controlled spelling difference on the same distinctive identity':'All distinctive identity tokens agree',
        'Any remaining differences are limited to permitted legal/geographic/generic qualifiers'
      ];
      result.decisionReason=best.typo.length
        ? `Swift — distinctive company identity is preserved; only one controlled spelling difference is accepted between "${entry.original}" and "${m.original}".`
        : `Swift — distinctive identity "${tp.distinctive.join(' ')}" is preserved exactly; remaining differences are only permitted legal, geographic, or generic business qualifiers.`;
      return result;
    }

    // NEGATIVE EVIDENCE ALWAYS OVERRIDES FUZZY / RARITY SCORE.
    if(best.descriptorConflict){
      result.method='DESCRIPTOR_CONTEXT_CONFLICT'; result.strength='Strong';
      result.evidence=['Different business descriptors/context on target and master.'];
      result.decisionReason=`The names share identity vocabulary but their business descriptors conflict (${best.tc.join(', ')||'none'} vs ${best.mc.join(', ')||'none'}); similarity cannot override this conflict.`;
      return result;
    }
    if(best.extras.length || best.coverage<1){
      result.method='DISTINCTIVE_IDENTITY_CONFLICT'; result.strength='Strong';
      result.evidence=['Distinctive identity is incomplete or conflicts with the master candidate.'];
      result.decisionReason='A distinctive company root is missing or replaced by a different distinctive root; fuzzy/string similarity cannot override this conflict.';
      return result;
    }

    result.method='AMBIGUOUS_IDENTITY_NON_SWIFT'; result.evidence=['Identity evidence is not strong enough to prove the same customer.'];
    result.decisionReason='Company-name evidence is insufficient for a defensible same-customer decision; conservative binary fallback is Non-Swift.';
    return result;
  }

  function classifyOne(entry,index,entries){ return resolveSwiftCustomer(entry,index,entries); }

  async function classifyAllChunked(entries,index,master,onProgress){
    const results=new Array(entries.length), tally={swift:0,nonSwift:0,manual:0};
    // Browser-friendly time-sliced processing. Expensive fuzzy work is limited to
    // small distinctive-token candidate buckets, never target × master.
    const TIME_BUDGET_MS=35; let i=0;
    while(i<entries.length){
      const started=performance.now();
      while(i<entries.length && performance.now()-started<TIME_BUDGET_MS){
        const r=classifyOne(entries[i],index,master); r.original=entries[i].original; r.ident={};
        results[i]=r; if(r.remark==='Swift')tally.swift++; else tally.nonSwift++; i++;
      }
      if(onProgress)onProgress(i,entries.length,tally);
      await yieldToBrowser(10);
    }
    return results;
  }

  // Binary mode has no review tier by design. Keep these compatibility functions
  // so existing UI/event handlers cannot throw, but they always return an empty queue.
  function riskScoreOf(r){return r?.remark==='Swift'?0:1;}
  function riskLevelOf(r){return 'LOW';}
  function applyReviewTiers(results){
    (results||[]).forEach(r=>{if(r.remark!=='Swift'&&r.remark!=='Non swift')r.remark='Non swift';});
    return [];
  }
  function buildManualQueue(results){return [];}

  /* ---------- reading a workbook: name column + dynamically detected identifier columns ---------- */
  async function readWorkbookColumns(file){
    const buf = await file.arrayBuffer();
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(buf);
    const ws = wb.worksheets[0];
    if (!ws) throw new Error('No worksheet found in this workbook.');
    const headers = [];
    ws.getRow(1).eachCell({ includeEmpty: true }, (cell, c) => {
      headers[c - 1] = cell.value != null ? String(cell.value).trim() : '';
    });
    const present = headers.map((h, i) => ({ h, i })).filter(x => x.h !== '');
    let colIdx;
    if (present.length <= 1){
      colIdx = present.length ? present[0].i : 0;
    } else {
      const preferred = present.find(x => /^(customer( name)?|company( name)?|name)$/i.test(x.h));
      colIdx = preferred ? preferred.i : present[0].i;
    }
    const columnName = headers[colIdx] || 'Customer';

    // dynamic identifier column detection (spec §8) — only fields that exist are used
    const identCols = {}; // key -> colIdx
    present.forEach(({ h, i }) => {
      if (i === colIdx) return;
      for (const f of IDENTIFIER_FIELDS){
        if (f.test.test(h) && identCols[f.key] === undefined){ identCols[f.key] = i; break; }
      }
    });

    const cellText = (cell) => {
      const v = cell.value;
      if (v == null) return '';
      if (typeof v === 'object' && Array.isArray(v.richText)) return v.richText.map(t => t.text).join('');
      if (typeof v === 'object' && v.text != null) return String(v.text);
      if (typeof v === 'object' && v.result != null) return String(v.result);
      return String(v);
    };

    const rows = [];
    const identRows = [];
    const rawRows = []; // full original row values, keyed by header, for pass-through export
    const totalRows = ws.rowCount;
    for (let r = 2; r <= totalRows; r++){
      const row = ws.getRow(r);
      const s = cellText(row.getCell(colIdx + 1)).trim();
      if (!s) continue;
      rows.push(s);
      const ident = {};
      Object.keys(identCols).forEach(k => { const t = cellText(row.getCell(identCols[k] + 1)).trim(); if (t) ident[k] = t; });
      identRows.push(ident);
      const raw = {};
      headers.forEach((h, i) => { if (h) raw[h] = cellText(row.getCell(i + 1)); });
      rawRows.push(raw);
    }
    return { columnName, rows, identRows, rawRows, headers, idColumns: Object.keys(identCols) };
  }

  async function buildOutputWorkbook(originals, results, columnName, rawRows, extraHeaders){
    const wb = new ExcelJS.Workbook();
    const ws = wb.addWorksheet('Classified');
    const passHeaders = (extraHeaders || []).filter(h => h && h !== columnName);
    const cols = [
      { header: columnName || 'Customer', key: 'customer', width: 38 },
      ...passHeaders.map((h, i) => ({ header: h, key: `src${i}`, width: 20 })),
      { header: 'Matched With', key: 'matchedWith', width: 38 },
      { header: 'Decision', key: 'decision', width: 20 },
      { header: 'Confidence %', key: 'confidencePct', width: 12 },
      { header: 'Similarity Score', key: 'simScore', width: 14 },
      { header: 'Decision Confidence', key: 'confidence', width: 16 },
      { header: 'Best Score', key: 'bestScore', width: 12 },
      { header: 'Second Score', key: 'secondScore', width: 12 },
      { header: 'Score Margin', key: 'margin', width: 12 },
      { header: 'Match Method', key: 'method', width: 18 },
      { header: 'Decision Reason', key: 'decisionReason', width: 60 },
      { header: 'Evidence', key: 'evidence', width: 46 },
      { header: 'Competing Candidates', key: 'altCandidates', width: 40 },
      { header: 'Risk Level', key: 'risk', width: 12 },
      { header: 'Verification Status', key: 'verStatus', width: 18 },
      { header: 'Engine Decision', key: 'engineDecision', width: 16 },
      { header: 'Manual Decision', key: 'manualDecision', width: 16 },
      { header: 'Verified By', key: 'verBy', width: 16 },
      { header: 'Verified At', key: 'verAt', width: 20 },
    ];
    ws.columns = cols;
    for (let i = 0; i < originals.length; i++){
      const r = results[i] || {};
      const row = {
        customer: originals[i],
        matchedWith: r.bestName || 'No reliable match',
        decision: r.remark,
        confidencePct: r.confidence != null ? `${r.confidence}%` : '',
        simScore: r.bestName ? `${r.bestScore}%` : '',
        confidence: r.strength || '',
        bestScore: r.bestScore != null ? r.bestScore : '',
        secondScore: r.secondScore != null ? r.secondScore : '',
        margin: r.margin != null ? r.margin : '',
        method: r.method || r.reason || '',
        decisionReason: r.decisionReason || '',
        evidence: (r.evidence || []).join(' | '),
        altCandidates: (r.candidates || []).slice(1, 4).map(c => `${c.name} (${c.score}%)`).join(' | '),
        risk: r.risk || '',
        verStatus: r.remark === 'Manual Check' ? 'Awaiting Review' : (r.remark === 'Pending Verification' ? 'Pending Verification' : (r.verified ? 'Human Verified' : 'Auto')),
        engineDecision: r.engineRemark || r.remark || '',
        manualDecision: r.manualDecision || '',
        verBy: r.verifiedBy || '',
        verAt: r.verifiedAt ? new Date(r.verifiedAt).toLocaleString() : '',
      };
      passHeaders.forEach((h, hi) => { row[`src${hi}`] = (rawRows && rawRows[i]) ? rawRows[i][h] : ''; });
      ws.addRow(row);
    }
    ws.getRow(1).font = { bold: true };
    const buf = await wb.xlsx.writeBuffer();
    return new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  }

  function triggerDownload(blob, filename){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1000);
  }

  function fmtTime(ms){ if (!ms) return '—'; return new Date(ms).toLocaleString([], { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }); }

  /* ---------- master: load from IndexedDB on startup ---------- */
  async function loadPermanentMasterFromDb(){
    try{
      const rec = await idbGet(MASTER_KEY);
      if (!rec){ renderMasterCard(); return; }
      masterMeta = rec.meta;
      masterEntries = rec.entries;
      setMasterStatus('Loading saved master index…', 'pill-gray');
      masterIndex = buildIndex(masterEntries);
      masterQuality = analyzeMasterQuality(masterEntries, masterIndex);
      renderMasterCard();
      renderMasterQuality();
      renderRunButtonState();
    } catch(e){
      console.error('Swift master load failed', e);
      renderMasterCard();
    }
  }

  function setMasterStatus(text, pillClass){
    const t = byId('sw-master-status-text'); if (t) t.textContent = text;
    const p = byId('sw-master-status-pill');
    if (p && pillClass){ p.className = 'pill ' + pillClass; }
  }

  /* ---------- master: ingest an uploaded file as the permanent master ---------- */
  async function ingestMasterFile(file){
    try{
      setMasterStatus('Reading workbook…', 'pill-gray');
      const { columnName, rows, identRows, idColumns } = await readWorkbookColumns(file);
      if (!rows.length) throw new Error('No customer names found in this file.');
      const entries = await buildEntriesChunked(rows, identRows, (done, total) => {
        setMasterStatus(`Normalizing ${done.toLocaleString()} / ${total.toLocaleString()}…`, 'pill-gray');
      });
      setMasterStatus('Building match index…', 'pill-gray');
      await new Promise(r => setTimeout(r, 0));
      const index = buildIndex(entries);
      masterEntries = entries;
      masterIndex = index;
      masterQuality = analyzeMasterQuality(entries, index);
      masterMeta = { fileName: file.name, uploadedAt: Date.now(), rowCount: entries.length, columnName, idColumns };
      await idbSet(MASTER_KEY, { meta: masterMeta, entries: masterEntries });
      renderMasterCard();
      renderMasterQuality();
      renderRunButtonState();
      const idNote = idColumns.length ? ` · Identifiers detected: ${idColumns.join(', ').toUpperCase()}` : '';
      toast(`Swift master loaded — ${entries.length.toLocaleString()} customers indexed.${idNote}`, 'success');
    } catch(e){
      setMasterStatus('Failed to load master file', 'pill-red');
      toast(`Couldn't load the Swift master: ${e.message || e}`, 'error');
    }
  }

  function renderMasterCard(){
    const summary = byId('sw-master-summary');
    const foot = byId('sw-master-foot');
    const zone = byId('sw-masterZone');
    const synced = byId('sw-master-synced');
    if (!masterMeta){
      setMasterStatus('No permanent master configured yet', 'pill-gray');
      show(foot, false); show(zone, true);
      if (summary) summary.innerHTML = '';
      show(byId('sw-master-quality'), false);
      return;
    }
    setMasterStatus(masterMeta.fileName, 'pill-green');
    const pill = byId('sw-master-status-pill'); if (pill) pill.textContent = '● Connected';
    show(zone, false); show(foot, true);
    if (synced) synced.textContent = `Permanent Master · Rows: ${masterMeta.rowCount.toLocaleString()} · Last Updated: ${fmtTime(masterMeta.uploadedAt)}`;
    if (summary){
      summary.innerHTML = `
        <span class="pill pill-blue">${masterMeta.rowCount.toLocaleString()} rows indexed</span>
        <span class="pill pill-white">Column: ${escHtml(masterMeta.columnName)}</span>
        ${masterMeta.idColumns && masterMeta.idColumns.length ? `<span class="pill pill-white">Identifiers: ${escHtml(masterMeta.idColumns.join(', ').toUpperCase())}</span>` : ''}
      `;
    }
  }

  function renderMasterQuality(){
    const el = byId('sw-master-quality');
    if (!el || !masterQuality) return;
    const q = masterQuality;
    const healthColor = q.health === 'Excellent' ? '#15803D' : (q.health === 'Good' ? '#B45309' : '#B91C1C');
    el.innerHTML = `
      <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:8px;">
        <div style="font-weight:700; font-size:13px;">Master Health</div>
        <span class="pill" style="background:${healthColor}20; color:${healthColor}; font-weight:700;">${escHtml(q.health)}</span>
      </div>
      <div style="display:flex; flex-wrap:wrap; gap:8px; font-size:12px;">
        <span class="pill pill-white">Unique: ${q.unique.toLocaleString()}</span>
        <span class="pill pill-white">Duplicate groups: ${q.duplicateGroups.toLocaleString()}</span>
        <span class="pill pill-white">With identifiers: ${q.withIdentifiers.toLocaleString()}</span>
        <span class="pill pill-white">Without identifiers: ${q.withoutIdentifiers.toLocaleString()}</span>
      </div>
      ${q.duplicateGroups > 0 ? `<div class="joc-cloud-sub" style="margin-top:8px; color:#B91C1C;">Master Quality Warning — ${q.duplicateGroups.toLocaleString()} duplicate/ambiguous master record group(s) detected. Classification may require additional manual verification.</div>` : ''}
    `;
    show(el, true);
  }

  /* ---------- target: ingest the file to classify ---------- */
  async function ingestTargetFile(file){
    try{
      byId('sw-status-text').textContent = 'Reading target file…';
      const { columnName, rows, identRows, rawRows, headers, idColumns } = await readWorkbookColumns(file);
      if (!rows.length) throw new Error('No customer names found in this file.');
      targetEntries = await buildEntriesChunked(rows, identRows, () => {});
      targetMeta = { fileName: file.name, rowCount: rows.length, columnName, idColumns, rawRows, headers };
      const meta = byId('sw-target-meta');
      const idNote = idColumns.length ? ` · Identifiers: ${idColumns.join(', ').toUpperCase()}` : '';
      if (meta) meta.textContent = `${rows.length.toLocaleString()} rows detected · Column: "${columnName}"${idNote} · Status: Ready`;
      renderRunButtonState();
    } catch(e){
      targetEntries = null; targetMeta = null;
      toast(`Couldn't read the target file: ${e.message || e}`, 'error');
      renderRunButtonState();
    }
  }

  function renderRunButtonState(){
    const btn = byId('sw-runBtn');
    const statusText = byId('sw-status-text');
    const ready = !!(masterEntries.length && targetEntries && targetEntries.length && !running);
    if (btn) btn.disabled = !ready;
    if (statusText && !running){
      if (!masterEntries.length) statusText.textContent = 'Upload a Swift master and a target file to begin…';
      else if (!targetEntries || !targetEntries.length) statusText.textContent = 'Swift master ready — upload a target customer database.';
      else statusText.textContent = 'Ready — click Start Classification.';
    }
  }

  /* ---------- run the classification pipeline ---------- */
  async function runClassification(){
    if (running || !masterEntries.length || !targetEntries || !targetEntries.length) return;
    running = true;
    renderRunButtonState();
    const icon = byId('sw-runBtnIcon'); const label = byId('sw-runBtnText');
    if (icon) icon.textContent = '⏳'; if (label) label.textContent = 'Classifying…';
    show(byId('sw-progressWrap'), true);
    show(byId('sw-resultsSection'), false);
    const fill = byId('sw-progressFill');
    const progressText = byId('sw-progressText');
    const statusText = byId('sw-status-text');

    const t0 = performance.now();
    const results = await classifyAllChunked(targetEntries, masterIndex, masterEntries, (done, total, tally) => {
      const pct = Math.round((done / total) * 100);
      if (fill) fill.style.width = pct + '%';
      if (progressText) progressText.textContent =
        `Processing ${done.toLocaleString()} / ${total.toLocaleString()} (${pct}%) · `
        + `Swift ${tally.swift.toLocaleString()} · Non Swift ${tally.nonSwift.toLocaleString()}`;
      if (statusText) statusText.textContent = 'Running Zero-Risk classification…';
    });
    const ms = Math.max(1, Math.round(performance.now() - t0));

    manualQueue = buildManualQueue(results); // always empty in binary JOC mode
    manualCursor = 0;

    lastResults = results;
    finalizeStatsAndRender(ms);
    running = false;
    if (icon) icon.textContent = '▶'; if (label) label.textContent = 'Start Classification';
    show(byId('sw-progressWrap'), false);
    if (progressText) progressText.textContent = '';
    renderRunButtonState();
  }

  function finalizeStatsAndRender(ms){
    const results = lastResults;
    const swiftCount = results.filter(r => r.remark === 'Swift').length;
    const nonSwiftCount = results.filter(r => r.remark === 'Non swift').length;
    const manualCount = results.filter(r => r.remark === 'Manual Check').length;
    const pendingCount = results.filter(r => r.remark === 'Pending Verification').length;
    const conflictCount = results.filter(r => r.method === 'CONFLICT').length;
    const autoResolved = swiftCount + nonSwiftCount;
    lastRunStats = {
      total: results.length, swift: swiftCount, nonSwift: nonSwiftCount, manual: manualCount, pending: pendingCount,
      ms, rate: Math.round(results.length / (ms / 1000)),
      coverage: results.length ? Math.round((autoResolved / results.length) * 1000) / 10 : 0,
      conflictRate: results.length ? Math.round((conflictCount / results.length) * 1000) / 10 : 0,
    };
    (async () => {
      lastOutputBlob = await buildOutputWorkbook(
        targetEntries.map(e => e.original), results, targetMeta.columnName,
        targetMeta.rawRows, targetMeta.headers
      );
      renderResults();
    })();
  }

  function renderResults(){
    if (!lastRunStats) return;
    show(byId('sw-resultsSection'), true);
    const set = (id, val) => { const el = byId(id); if (el) el.textContent = val; };
    set('sw-statTotal', lastRunStats.total.toLocaleString());
    set('sw-statSwift', lastRunStats.swift.toLocaleString());
    set('sw-statNonSwift', lastRunStats.nonSwift.toLocaleString());
    set('sw-statManual', lastRunStats.manual.toLocaleString());
    set('sw-statPending', lastRunStats.pending.toLocaleString());
    set('sw-statTime', (lastRunStats.ms / 1000).toFixed(1) + 's');
    set('sw-statRate', lastRunStats.rate.toLocaleString() + '/s');
    set('sw-statCoverage', lastRunStats.coverage + '%');
    set('sw-statConflict', lastRunStats.conflictRate + '%');
    const sub = byId('sw-resultsSub');
    if (sub) sub.textContent = `${targetMeta.fileName} classified against ${masterMeta.fileName}. Zero-Risk Decision Mode · Human Verification Safeguard.`;
    show(byId('sw-reviewBtn'), manualQueue.length > 0);
    show(byId('sw-finalizeBtn'), manualQueue.length > 0 || lastRunStats.pending > 0);

    const banner = byId('sw-finalize-banner');
    if (banner){
      if (manualQueue.length > 0 || lastRunStats.pending > 0){
        const totalUnresolved = lastRunStats.manual + lastRunStats.pending;
        banner.innerHTML = `FINALIZATION BLOCKED — ${totalUnresolved.toLocaleString()} record(s) remain unverified. `
          + (lastRunStats.pending > 0 ? `${manualQueue.length} highest-risk records are queued for review; ${lastRunStats.pending.toLocaleString()} more exceed the ${MATCH_CONFIG.maxManualChecks}-review safety limit and remain <b>Pending Verification</b>. ` : '')
          + `Resolve the queue or export as-is with records explicitly labeled Pending Verification.`;
        show(banner, true);
      } else {
        show(banner, false);
      }
    }

    renderReasonBreakdown();
  }

  /* ---------- diagnostic: WHY are records landing in Manual/Pending? (spec §19) ---------- */
  function renderReasonBreakdown(){
    let el = byId('sw-reason-breakdown');
    const host = byId('sw-finalize-banner');
    if (!el && host && host.parentElement){
      el = document.createElement('div');
      el.id = 'sw-reason-breakdown';
      el.style.margin = '10px 0';
      host.parentElement.insertBefore(el, host.nextSibling);
    }
    if (!el || !lastResults) return;

    const unresolved = lastResults.filter(r => r.remark === 'Manual Check' || r.remark === 'Pending Verification');
    if (!unresolved.length){ el.innerHTML = ''; return; }

    const buckets = {
      'Identity conflict (GSTIN/phone/email/etc. disagree)': 0,
      'Competing high-score candidates (narrow margin, credible 2nd)': 0,
      'Ambiguous score — no confident Swift or Non-Swift signal': 0,
      'Duplicate/ambiguous master identity': 0,
      'No identifier available to disambiguate': 0,
    };
    unresolved.forEach(r => {
      if (r.method === 'CONFLICT') buckets['Identity conflict (GSTIN/phone/email/etc. disagree)']++;
      else if (r.method === 'MASTER_DUPLICATE') buckets['Duplicate/ambiguous master identity']++;
      else if (r.method === 'MULTI_SIGNAL' || (r.debug && r.debug.secondCredible && r.debug.margin < MATCH_CONFIG.swift.minimumMargin)) buckets['Competing high-score candidates (narrow margin, credible 2nd)']++;
      else buckets['Ambiguous score — no confident Swift or Non-Swift signal']++;
      // Informational overlay only (spec §13) — absence of an identifier is not itself
      // the decision reason, so it does not gate which primary bucket a record lands in.
      if (!r.ident || !Object.keys(r.ident).length) buckets['No identifier available to disambiguate']++;
    });

    const scoreBand = { '55–70': 0, '70–85': 0, '85–92': 0, '92+ (blocked by margin/conflict)': 0 };
    unresolved.forEach(r => {
      const s = r.bestScore || 0;
      if (s >= 92) scoreBand['92+ (blocked by margin/conflict)']++;
      else if (s >= 85) scoreBand['85–92']++;
      else if (s >= 70) scoreBand['70–85']++;
      else scoreBand['55–70']++;
    });

    el.innerHTML = `
      <div class="panel" style="margin-bottom:0;">
        <div style="font-weight:800; font-size:13px; margin-bottom:8px;">Why are ${unresolved.length.toLocaleString()} records unresolved? (diagnostic breakdown)</div>
        <div style="display:grid; grid-template-columns:1fr auto; gap:4px 12px; font-size:12.5px; margin-bottom:10px;">
          ${Object.entries(buckets).map(([label, count]) => `<div>${escHtml(label)}</div><div style="font-weight:700; text-align:right;">${count.toLocaleString()}</div>`).join('')}
        </div>
        <div style="font-size:11px; color:#6B7280; margin-bottom:4px;">Best-match score distribution among unresolved records:</div>
        <div style="display:grid; grid-template-columns:1fr auto; gap:4px 12px; font-size:12.5px;">
          ${Object.entries(scoreBand).map(([label, count]) => `<div>${escHtml(label)}</div><div style="font-weight:700; text-align:right;">${count.toLocaleString()}</div>`).join('')}
        </div>
      </div>
    `;
  }

  function downloadOutput(){
    if (!lastOutputBlob) return;
    const ts = new Date().toISOString().replace(/[:.]/g,'').slice(0,15);
    const safe = (targetMeta && targetMeta.fileName ? targetMeta.fileName : 'customers').replace(/\.(xlsx|xlsm|xls)$/i,'');
    triggerDownload(lastOutputBlob, `Swift_Classification_${safe}_${ts}.xlsx`);
  }

  /* ---------- manual verification workbench (spec §18-23, §40) ---------- */
  function currentManualIndex(){ return manualQueue[manualCursor]; }

  function renderReviewProgress(){
    const wrap = byId('sw-review-progress');
    if (!wrap) return;
    const total = manualQueue.length;
    const done = manualCursor;
    const pct = total ? Math.round((done / total) * 100) : 0;
    wrap.innerHTML = `
      <div style="display:flex; justify-content:space-between; font-size:12px; font-weight:700; margin-bottom:4px;">
        <span>Manual Review ${Math.min(done + 1, total)} / ${total}</span>
        <span>Remaining: ${Math.max(0, total - done)}</span>
      </div>
      <div class="progress-outer"><div class="progress-inner" style="width:${pct}%;"></div></div>
    `;
  }

  function riskBadge(risk){
    const map = { HIGH: '#B91C1C', MEDIUM: '#B45309', LOW: '#166534' };
    const c = map[risk] || '#6B7280';
    return `<span class="pill" style="background:${c}20; color:${c}; font-weight:700;">${escHtml(risk || 'LOW')} RISK</span>`;
  }

  function renderReviewCard(){
    const list = byId('sw-review-list');
    if (!list) return;
    if (!manualQueue.length){
      list.innerHTML = '<div class="joc-cloud-sub">No ambiguous records — everything was resolved automatically or is beyond the review cap (Pending Verification).</div>';
      renderReviewProgress();
      return;
    }
    if (manualCursor >= manualQueue.length){
      list.innerHTML = `<div class="joc-cloud-sub">All ${manualQueue.length} queued records have been reviewed. Close this window and click <b>Finalize &amp; Recheck</b>.</div>`;
      renderReviewProgress();
      return;
    }
    const idx = currentManualIndex();
    const r = lastResults[idx];
    const candidates = r.candidates || (r.bestName ? [{ name: r.bestName, score: r.bestScore, tokenJaccard: null, charDice: null, agree: [], conflict: [] }] : []);

    list.innerHTML = `
      <div class="panel" style="margin-bottom:0;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:10px; flex-wrap:wrap;">
          <div>
            <div style="font-size:11px; text-transform:uppercase; color:#6B7280; font-weight:700;">Target</div>
            <div style="font-size:16px; font-weight:800;">${escHtml(r.original)}</div>
          </div>
          ${riskBadge(r.risk)}
        </div>

        <div style="margin-top:12px;">
          <div style="font-size:11px; text-transform:uppercase; color:#6B7280; font-weight:700;">Best Match</div>
          <div style="font-size:14px; font-weight:700;">${escHtml(r.bestName || '— no candidate —')}</div>
        </div>

        <div style="margin-top:14px; background:#F9FAFB; border-radius:10px; padding:10px 12px;">
          <div style="font-size:11px; text-transform:uppercase; color:#6B7280; font-weight:700; margin-bottom:6px;">Why Manual?</div>
          <ul style="margin:0; padding-left:18px; font-size:13px; line-height:1.6;">
            ${(r.why && r.why.length ? r.why : ['Ambiguous evidence']).map(w => `<li>${escHtml(w)}</li>`).join('')}
          </ul>
        </div>

        <div style="margin-top:12px;">
          <div style="font-size:11px; text-transform:uppercase; color:#6B7280; font-weight:700; margin-bottom:6px;">Match Evidence</div>
          <div style="font-size:13px; line-height:1.7;">
            ${(r.evidence || []).map(e => `✓ ${escHtml(e)}`).join('<br>') || '—'}
          </div>
        </div>

        ${candidates.length ? `
        <div style="margin-top:14px;">
          <div style="font-size:11px; text-transform:uppercase; color:#6B7280; font-weight:700; margin-bottom:6px;">Alternative Matches (top ${candidates.length})</div>
          <div style="display:flex; flex-direction:column; gap:6px;">
            ${candidates.map((c, ci) => `
              <div style="display:flex; justify-content:space-between; align-items:center; gap:10px; background:#fff; border:1px solid #E5E7EB; border-radius:8px; padding:8px 10px;">
                <div style="min-width:0;">
                  <div style="font-size:13px; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">#${ci + 1} ${escHtml(c.name)}</div>
                  <div style="font-size:11px; color:#6B7280;">
                    Overall ${c.score}%${c.tokenJaccard != null ? ` · Name ${c.tokenJaccard}%` : ''}${c.charDice != null ? ` · Char ${c.charDice}%` : ''}
                    ${c.agree && c.agree.length ? ` · Agrees: ${c.agree.join(',').toUpperCase()}` : ''}
                    ${c.conflict && c.conflict.length ? ` · <span style="color:#B91C1C;">Conflicts: ${c.conflict.join(',').toUpperCase()}</span>` : ''}
                  </div>
                </div>
              </div>
            `).join('')}
          </div>
        </div>` : ''}

        <div style="margin-top:16px; display:flex; gap:8px; flex-wrap:wrap;">
          <button class="btn btn-primary" id="sw-btn-confirm-swift" style="flex:1;">✓ Confirm Swift <span style="opacity:.6; font-weight:400;">(1)</span></button>
          <button class="btn" id="sw-btn-confirm-nonswift" style="flex:1; background:#FEE2E2; color:#B91C1C;">✕ Confirm Non-Swift <span style="opacity:.6; font-weight:400;">(2)</span></button>
          <button class="btn btn-sm" id="sw-btn-skip" style="flex:0 0 auto;">→ Skip (3)</button>
        </div>
        <div class="joc-cloud-sub" style="margin-top:8px;">Keyboard: 1 = Swift · 2 = Non-Swift · 3 = Skip · ↑/↓ = Navigate</div>
      </div>
    `;

    byId('sw-btn-confirm-swift').addEventListener('click', () => decideCurrent('Swift'));
    byId('sw-btn-confirm-nonswift').addEventListener('click', () => decideCurrent('Non swift'));
    byId('sw-btn-skip').addEventListener('click', () => decideCurrent('Skip'));

    renderReviewProgress();
  }

  function decideCurrent(decision){
    const idx = currentManualIndex();
    if (idx == null) return;
    const r = lastResults[idx];
    const prevDecision = r.remark;
    // Preserve the engine's original evidence/decision the first time this
    // record is touched — a manual override must never overwrite it (spec §35).
    if (r.engineRemark === undefined){
      r.engineRemark = prevDecision;
      r.engineConfidence = r.confidence;
      r.engineDecisionReason = r.decisionReason;
    }

    if (decision === 'Swift'){
      r.remark = 'Swift';
      r.manualDecision = 'Swift';
      r.verified = true; r.verifiedBy = 'Human'; r.verifiedAt = Date.now();
      r.method = 'MANUAL_VERIFIED';
      // learn: verified alias, deterministic for future runs (spec §6)
      if (r.bestName){
        const key = aliasKeyFor(normalizeName(r.original));
        const prior = verifiedAliases[key];
        verifiedAliases[key] = { canonicalOriginal: r.bestName, verifiedAt: Date.now(), source: 'manual', count: (prior && prior.count || 0) + 1 };
        saveAliases();
      }
      logAudit({ target: r.original, candidate: r.bestName, previousDecision: prevDecision, newDecision: 'Swift', reason: 'Human verified', type: 'manual_swift' });
    } else if (decision === 'Non swift'){
      r.remark = 'Non swift';
      r.manualDecision = 'Non swift';
      r.verified = true; r.verifiedBy = 'Human'; r.verifiedAt = Date.now();
      r.method = 'MANUAL_VERIFIED';
      // learn: negative match, so this exact pairing never resurfaces as Swift (spec §7)
      if (r.bestName){
        const negKey = negKeyFor(normalizeName(r.original), normalizeName(r.bestName));
        negativeMatches[negKey] = { verifiedAt: Date.now(), source: 'manual' };
        saveNegatives();
      }
      logAudit({ target: r.original, candidate: r.bestName, previousDecision: prevDecision, newDecision: 'Non swift', reason: 'Human verified — not the same company', type: 'manual_nonswift' });
    } else {
      // Skip — stays pending, not counted as resolved
      logAudit({ target: r.original, candidate: r.bestName, previousDecision: prevDecision, newDecision: 'Skipped', reason: 'Reviewer skipped', type: 'manual_skip' });
      manualCursor++;
      renderReviewCard();
      refreshCardKpis();
      return;
    }
    manualCursor++;
    renderReviewCard();
    refreshCardKpis();
  }

  function openReview(){
    if (!lastResults) return;
    manualCursor = manualQueue.findIndex((idx) => lastResults[idx].remark === 'Manual Check');
    if (manualCursor < 0) manualCursor = manualQueue.length;
    renderReviewCard();
    show(byId('sw-review-overlay'), true);
    document.addEventListener('keydown', reviewKeyHandler);
  }
  function closeReview(){
    show(byId('sw-review-overlay'), false);
    document.removeEventListener('keydown', reviewKeyHandler);
    // recompute stats/output so partial progress is reflected even before Finalize
    if (lastResults) recomputeAfterManualEdits();
  }
  function reviewKeyHandler(e){
    if (byId('sw-review-overlay').classList.contains('hidden')) return;
    if (e.key === '1' || e.key.toLowerCase() === 's') decideCurrent('Swift');
    else if (e.key === '2' || e.key.toLowerCase() === 'n') decideCurrent('Non swift');
    else if (e.key === '3' || e.key === 'Enter') decideCurrent('Skip');
    else if (e.key === 'ArrowDown'){ manualCursor = Math.min(manualQueue.length, manualCursor + 1); renderReviewCard(); }
    else if (e.key === 'ArrowUp'){ manualCursor = Math.max(0, manualCursor - 1); renderReviewCard(); }
  }

  function recomputeAfterManualEdits(){
    if (!lastResults) return;
    const swiftCount = lastResults.filter(r => r.remark === 'Swift').length;
    const nonSwiftCount = lastResults.filter(r => r.remark === 'Non swift').length;
    const manualCount = lastResults.filter(r => r.remark === 'Manual Check').length;
    const pendingCount = lastResults.filter(r => r.remark === 'Pending Verification').length;
    if (lastRunStats){
      lastRunStats.swift = swiftCount; lastRunStats.nonSwift = nonSwiftCount;
      lastRunStats.manual = manualCount; lastRunStats.pending = pendingCount;
      lastRunStats.coverage = lastResults.length ? Math.round(((swiftCount + nonSwiftCount) / lastResults.length) * 1000) / 10 : 0;
    }
    manualQueue = manualQueue.filter(idx => lastResults[idx].remark === 'Manual Check');
    renderResults();
    (async () => {
      lastOutputBlob = await buildOutputWorkbook(targetEntries.map(e => e.original), lastResults, targetMeta.columnName, targetMeta.rawRows, targetMeta.headers);
    })();
  }

  /* ---------- Finalize & Recheck: rerun classification using freshly learned knowledge (spec §26) ---------- */
  async function finalizeAndRecheck(){
    if (!targetEntries || !masterIndex) return;
    const btn = byId('sw-finalizeBtn');
    if (btn) btn.disabled = true;
    const statusText = byId('sw-status-text');
    if (statusText) statusText.textContent = 'Re-running classification with verified knowledge…';
    const t0 = performance.now();
    const results = await classifyAllChunked(targetEntries, masterIndex, masterEntries, () => {});
    // preserve human decisions already made this session — manual verification is authoritative
    if (lastResults){
      results.forEach((r, i) => {
        const prev = lastResults[i];
        if (prev && prev.verified) Object.assign(r, prev);
      });
    }
    const ms = Math.max(1, Math.round(performance.now() - t0));
    manualQueue = buildManualQueue(results);
    manualCursor = 0;
    lastResults = results;
    finalizeStatsAndRender(ms);
    if (btn) btn.disabled = false;
    toast('Reclassification complete — verified knowledge applied.', 'success');
  }

  function refreshCardKpis(){
    if (!lastRunStats) return;
    const set = (id, val) => { const el = byId(id); if (el) el.textContent = val; };
    set('sw-card-kpi-master', masterMeta ? masterMeta.rowCount.toLocaleString() : '0');
    set('sw-card-kpi-checked', lastRunStats.total.toLocaleString());
    set('sw-card-kpi-swift', lastRunStats.swift.toLocaleString());
    set('sw-card-kpi-manual', lastRunStats.manual.toLocaleString());
  }

  /* ---------- Golden Test Set validation (spec §25) ---------- */
  async function runGoldenTest(file){
    const results = byId('sw-golden-results');
    if (!masterIndex){ toast('Load a Swift master before running the golden test.', 'error'); return; }
    try{
      const { rows, rawRows, headers } = await readWorkbookColumns(file);
      // find the "expected decision" column from raw rows
      const expectedHeader = headers.find(h => /expected\s*decision|expected/i.test(h || ''));
      let correct = 0, incorrect = 0; const failures = [];
      rows.forEach((name, i) => {
        const raw = rawRows[i] || {};
        const expected = expectedHeader ? String(raw[expectedHeader] || '').trim() : '';
        if (!expected) return;
        const entry = makeEntry(name, null);
        const r = classifyOne(entry, masterIndex, masterEntries);
        const expNorm = /non/i.test(expected) ? 'Non swift' : (/manual|pending/i.test(expected) ? 'Manual Check' : 'Swift');
        const gotNorm = r.remark === 'Pending Verification' ? 'Manual Check' : r.remark;
        if (gotNorm === expNorm) correct++;
        else { incorrect++; failures.push({ name, expected: expNorm, got: gotNorm }); }
      });
      const total = correct + incorrect;
      const pct = total ? Math.round((correct / total) * 1000) / 10 : 0;
      if (results){
        results.innerHTML = `
          <div class="panel" style="margin-bottom:0;">
            <div style="font-weight:800; margin-bottom:6px;">Golden Test Results</div>
            <div style="font-size:13px; line-height:1.8;">
              Total: ${total}<br>
              Correct: ${correct}<br>
              Incorrect: ${incorrect}<br>
              Accuracy: <b>${pct}%</b> ${pct === 100 ? '(100% Golden Test Accuracy)' : ''}
            </div>
            ${incorrect > 0 ? `
              <div style="margin-top:10px; color:#B91C1C; font-weight:700; font-size:13px;">Validation Failed — 1 or more golden records were misclassified.</div>
              <ul style="margin:6px 0 0; padding-left:18px; font-size:12px;">
                ${failures.slice(0, 20).map(f => `<li>${escHtml(f.name)} — expected ${escHtml(f.expected)}, got ${escHtml(f.got)}</li>`).join('')}
              </ul>
            ` : ''}
          </div>
        `;
      }
    } catch(e){
      if (results) results.innerHTML = `<div class="joc-cloud-sub" style="color:#B91C1C;">Couldn't run golden test: ${escHtml(e.message || e)}</div>`;
    }
  }

  async function classifyJOCShippers(names, onProgress){
    if (!masterEntries.length) await loadPermanentMasterFromDb();
    if (!masterEntries.length || !masterIndex){
      throw new Error('Permanent Swift Customer Master is not loaded. Import it once in Swift & Non-Swift Intelligence before processing JOC files.');
    }
    const cleanNames = (names || []).map(v => String(v == null ? '' : v).trim()).filter(Boolean);
    if (!cleanNames.length) return [];
    const entries = await buildEntriesChunked(cleanNames, null, onProgress);
    const results = await classifyAllChunked(entries, masterIndex, masterEntries, onProgress);
    const manual = buildManualQueue(results);
    manualCursor = 0;
    return results;
  }

  function renderKnowledgeSummary(){
    const el = byId('sw-knowledge-summary');
    if (!el) return;
    el.textContent = `Verified aliases: ${Object.keys(verifiedAliases).length.toLocaleString()} · Negative matches: ${Object.keys(negativeMatches).length.toLocaleString()} · Audit entries: ${auditTrail.length.toLocaleString()}`;
  }

  /* ---------- dropzone wiring (same pattern as JOCToolkit's setupZone) ---------- */
  function setupZone(zoneId, inputId, fileNameId, onFile){
    const zone = byId(zoneId), input = byId(inputId), nameEl = byId(fileNameId);
    if (!zone || !input || !nameEl) return;
    zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('drag'); });
    zone.addEventListener('dragleave', () => zone.classList.remove('drag'));
    zone.addEventListener('drop', e => {
      e.preventDefault(); zone.classList.remove('drag');
      const f = e.dataTransfer.files[0]; if (f) handle(f);
    });
    input.addEventListener('change', () => { if (input.files[0]) handle(input.files[0]); });
    function handle(f){ nameEl.textContent = f.name; zone.classList.add('loaded'); onFile(f); }
  }

  /* ---------- view switching (landing ↔ toolkit) ---------- */
  function openLanding(){
    byId('toolkits-landing').classList.remove('hidden');
    byId('toolkits-swift').classList.add('hidden');
  }
  function openSwift(){
    byId('toolkits-landing').classList.add('hidden');
    byId('toolkits-swift').classList.remove('hidden');
  }

  let initialized = false;
  function init(){
    if (initialized) return;
    initialized = true;

    const card = byId('toolkit-card-swift');
    if (card) card.addEventListener('click', openSwift);
    const backBtn = byId('sw-back-btn');
    if (backBtn) backBtn.addEventListener('click', openLanding);

    setupZone('sw-masterZone', 'sw-masterFile', 'sw-masterFileName', ingestMasterFile);
    setupZone('sw-targetZone', 'sw-targetFile', 'sw-targetFileName', ingestTargetFile);
    setupZone('sw-goldenZone', 'sw-goldenFile', 'sw-goldenFileName', runGoldenTest);

    const replaceBtn = byId('sw-master-replace-btn');
    if (replaceBtn) replaceBtn.addEventListener('click', () => byId('sw-masterFile').click());

    const runBtn = byId('sw-runBtn');
    if (runBtn) runBtn.addEventListener('click', runClassification);

    const dlBtn = byId('sw-downloadBtn');
    if (dlBtn) dlBtn.addEventListener('click', downloadOutput);

    const reviewBtn = byId('sw-reviewBtn');
    if (reviewBtn) reviewBtn.addEventListener('click', openReview);
    const reviewClose = byId('sw-review-close');
    if (reviewClose) reviewClose.addEventListener('click', closeReview);
    const reviewOverlay = byId('sw-review-overlay');
    if (reviewOverlay) reviewOverlay.addEventListener('click', (e) => { if (e.target === reviewOverlay) closeReview(); });

    const finalizeBtn = byId('sw-finalizeBtn');
    if (finalizeBtn) finalizeBtn.addEventListener('click', finalizeAndRecheck);

    const knowledgeToggle = byId('sw-knowledge-toggle');
    if (knowledgeToggle) knowledgeToggle.addEventListener('click', () => {
      const body = byId('sw-knowledge-body');
      const open = body.classList.contains('hidden');
      show(body, open);
      knowledgeToggle.textContent = open ? 'Hide' : 'Show';
      if (open) renderKnowledgeSummary();
    });

    renderRunButtonState();
    loadVerifiedKnowledge().then(renderKnowledgeSummary);
    loadPermanentMasterFromDb();
  }

  return { init, classifyJOCShippers, resolveSwiftCustomer };
})();
SwiftToolkit.init();

/* ==========================================================================
   TOOLKITS — COMPANY NAME EXACT LOOKUP & REMOVAL
   Additive module. It only READS the existing `records` / `databases` tables
   through the app's authenticated `supa` client and deletes exact-match rows
   through the same `supa.from('records').delete()` path the Data Hub already
   uses (RLS + Admin-only rule preserved). No new tables, no schema changes.

   MATCH RULE (deterministic, no fuzzy logic of any kind):
     trim(uploaded) === trim(records.company_name)
   Case, spelling, punctuation, abbreviations and inner spacing are NOT altered.
   (normalizeCompanyName() is deliberately NOT used: it strips "Ltd/Limited/Pvt"
   and punctuation, which would make "ABC LIMITED" match "ABC LTD".)
   ========================================================================== */
const CompanyExactRemovalToolkit = (() => {
  const CASE_SENSITIVE = true;   // exact means exact; flip only if the business rule changes
  const PAGE = 1000, CONCURRENCY = 4, DELETE_BATCH = 200, PREVIEW_ROWS = 200;
  const ONE_COLUMN_ERROR = 'Please upload an Excel file containing only one column.';

  const byId = id => document.getElementById(id);
  const tick = () => new Promise(r => setTimeout(r, 0));
  const delay = ms => new Promise(r => setTimeout(r, ms));
  const clean = v => String(v ?? '').trim();
  const keyOf = v => CASE_SENSITIVE ? clean(v) : clean(v).toLowerCase();
  const fmt = n => Number(n || 0).toLocaleString();
  const isAdminUser = () => typeof S !== 'undefined' && !!S.isAdmin;
  const escH = s => (typeof esc === 'function') ? esc(s) : String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const notify = (msg, type) => { if (typeof toast === 'function') toast(msg, type || ''); };

  const st = { busy:false, upload:null, lookup:null, summary:null, blob:null, filename:'' };

  // ── progress steps ──────────────────────────────────────────────────────
  const STEP_KEYS = ['read','check','found','remove','generate','done'];
  const STEP_DEFAULT = {
    read:'Reading Excel...', check:'Checking Data Hub databases...', found:'Exact matches found: 0',
    remove:'Removing matched records...', generate:'Generating result file...', done:'Completed'
  };
  let stepState = {}, stepLabel = {};
  function resetSteps(){ stepState = {}; stepLabel = { ...STEP_DEFAULT }; paintSteps(); }
  function setStep(k, state, label){
    stepState[k] = state; if (label) stepLabel[k] = label; paintSteps();
  }
  function paintSteps(){
    const ul = byId('cx-steps'); if (!ul) return;
    ul.innerHTML = STEP_KEYS.map(k => {
      const s = stepState[k] || 'pending';
      return `<li class="cx-step ${s}"><span class="cx-step-dot">${s === 'done' ? '✓' : ''}</span><span>${escH(stepLabel[k])}</span></li>`;
    }).join('');
  }
  function setProgress(pct, text){
    const f = byId('cx-progressFill'); if (f) f.style.width = Math.max(0, Math.min(100, pct)) + '%';
    const t = byId('cx-progressText'); if (t && text !== undefined) t.textContent = text;
  }
  const show = (id, on) => { const el = byId(id); if (el) el.classList.toggle('hidden', !on); };

  // ── errors ──────────────────────────────────────────────────────────────
  function showError(msg){ const e = byId('cx-error'); if (e){ e.textContent = msg; e.classList.remove('hidden'); } }
  function clearError(){ const e = byId('cx-error'); if (e){ e.textContent = ''; e.classList.add('hidden'); } }

  // ── reset ───────────────────────────────────────────────────────────────
  function resetAll(){
    st.upload = st.lookup = st.summary = st.blob = null; st.filename = '';
    clearError();
    show('cx-progress-card', false); show('cx-preview-card', false); show('cx-results', false);
    const inp = byId('cx-file'); if (inp) inp.value = '';
    const z = byId('cx-zone'); if (z) z.classList.remove('loaded');
    const n = byId('cx-fileName'); if (n) n.textContent = '';
    const m = byId('cx-fileMeta'); if (m) m.textContent = '';
    setProgress(0, ''); resetSteps();
  }

  // ── 1. READ + VALIDATE the workbook (never modifies the file) ────────────
  async function parseWorkbook(file){
    const buf = await file.arrayBuffer(); await tick();
    const wb = XLSX.read(buf, { type:'array' });
    if (!wb.SheetNames.length) throw new Error('The workbook contains no sheets.');
    const sheetName = wb.SheetNames[0];
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { header:1, defval:'', blankrows:false, raw:true });
    await tick();

    // Columns that actually hold data (fully blank columns/rows are ignored).
    const used = new Set();
    for (const r of rows) for (let c = 0; c < r.length; c++) if (clean(r[c]) !== '') used.add(c);
    if (used.size === 0) throw new Error('The uploaded file is empty — no company names were found.');
    if (used.size > 1) throw new Error(ONE_COLUMN_ERROR);

    const col = [...used][0];
    const header = clean(rows[0][col]);                       // any header name is accepted
    const names = rows.slice(1).map(r => clean(r[col])).filter(Boolean);
    if (!names.length) throw new Error('The file has a header but no company names below it.');

    // Duplicate uploaded names → each unique name is processed once.
    const seen = new Map();
    names.forEach(n => { const k = keyOf(n); if (!seen.has(k)) seen.set(k, n); });
    const unique = [...seen.values()];
    return { sheetName, header, totalRows:names.length, unique, duplicateRows:names.length - unique.length };
  }

  // ── 2. EXACT LOOKUP across every Data Hub database the user can read ─────
  async function fetchDatabases(){
    const map = new Map(); let from = 0;
    while (true){
      const { data, error } = await supa.from('databases').select('id,name').order('id',{ascending:true}).range(from, from + PAGE - 1);
      if (error) throw error;
      (data || []).forEach(d => map.set(String(d.id), clean(d.name)));
      if (!data || data.length < PAGE) break;
      from += PAGE;
    }
    return map;
  }
  async function fetchPage(from){
    let lastErr;
    for (let attempt = 0; attempt < 3; attempt++){
      const { data, error } = await supa.from('records')
        .select('id,company_name,database_id,database_name')
        .order('id',{ascending:true}).range(from, from + PAGE - 1);
      if (!error) return data || [];
      lastErr = error; await delay(400 * (attempt + 1));
    }
    throw lastErr;
  }

  async function runLookup(unique){
    const dbMap = await fetchDatabases();
    const wanted = new Set(unique.map(keyOf));
    const hits = new Map();            // key → [record, …]
    let scanned = 0;
    const onRows = rows => {
      for (const r of rows){
        const k = keyOf(r.company_name);
        if (k && wanted.has(k)){
          if (!hits.has(k)) hits.set(k, []);
          hits.get(k).push(r);
        }
      }
      scanned += rows.length;
    };
    const paint = total => {
      setStep('found', 'active', `Exact matches found: ${fmt(hits.size)}`);
      setProgress(total ? Math.min(99, (scanned / total) * 100) : 50,
        `Scanned ${fmt(scanned)}${total ? ' of ' + fmt(total) : ''} Data Hub records across ${fmt(dbMap.size)} database(s)`);
    };

    let total = null;
    try {
      const { count, error } = await supa.from('records').select('id',{count:'exact',head:true});
      if (!error && typeof count === 'number') total = count;
    } catch (_) {}

    const starts = [];
    if (total) for (let s = 0; s < total; s += PAGE) starts.push(s);
    let next = 0, aborted = false;
    const worker = async () => {
      while (!aborted){
        const i = next++; if (i >= starts.length) return;
        try { onRows(await fetchPage(starts[i])); }
        catch (e){ aborted = true; throw e; }
        paint(total); await tick();
      }
    };
    await Promise.all(Array.from({ length: Math.min(CONCURRENCY, starts.length) }, worker));
    // Sequential tail: also covers rows added mid-scan (and the no-count case).
    let from = starts.length * PAGE;
    while (true){
      const rows = await fetchPage(from); onRows(rows); paint(total); await tick();
      if (rows.length < PAGE) break;
      from += PAGE;
    }
    if (total && scanned < total)
      throw new Error(`Data Hub scan was incomplete (${fmt(scanned)} of ${fmt(total)} records read). Nothing was changed — please try again.`);

    // Build result rows in uploaded order.
    const matchedRows = [], notFound = [];
    unique.forEach(name => {
      const recs = hits.get(keyOf(name));
      if (!recs || !recs.length){ notFound.push(name); return; }
      recs.map(r => ({
        uploaded: name,
        matchedName: r.company_name,
        dbName: dbMap.get(String(r.database_id)) || clean(r.database_name) || 'Database name unavailable',
        recordId: r.id,
        status: 'Pending'
      })).sort((a, b) => a.dbName.localeCompare(b.dbName) || String(a.recordId).localeCompare(String(b.recordId), undefined, { numeric:true }))
        .forEach(x => matchedRows.push(x));
    });
    return { matchedRows, notFound, exactMatches:hits.size, databasesChecked:dbMap.size, scanned };
  }

  // ── stat helpers / rendering ─────────────────────────────────────────────
  const statCard = (label, value) => `<div class="joc-stat-card"><div class="joc-stat-value">${escH(value)}</div><div class="joc-stat-label">${escH(label)}</div></div>`;

  function renderPreview(){
    const { upload, lookup } = st;
    byId('cx-preview-stats').innerHTML = [
      statCard('Total Uploaded', fmt(upload.totalRows)),
      statCard('Unique Names', fmt(upload.unique.length)),
      statCard('Exact Matches', fmt(lookup.exactMatches)),
      statCard('Records To Remove', fmt(lookup.matchedRows.length)),
      statCard('Not Found', fmt(lookup.notFound.length)),
      statCard('Databases Checked', fmt(lookup.databasesChecked))
    ].join('');

    const warn = [];
    if (upload.duplicateRows) warn.push(`${fmt(upload.duplicateRows)} repeated name row(s) in the file were processed once.`);
    if (!isAdminUser()) warn.push('Only Admins can delete Data Hub records (same rule as the Data Hub). You can review the matches, but removal is disabled for your account.');
    byId('cx-preview-warn').innerHTML = warn.length ? `<div class="cx-warn">${warn.map(escH).join('<br>')}</div>` : '';

    const shown = lookup.matchedRows.slice(0, PREVIEW_ROWS);
    byId('cx-preview-table').innerHTML = `
      <div class="cx-table-wrap"><table class="cx-table">
        <thead><tr><th>Uploaded Company Name</th><th>Matched Company Name</th><th>Database Name</th><th>Record ID</th></tr></thead>
        <tbody>${shown.map(m => `<tr><td>${escH(m.uploaded)}</td><td>${escH(m.matchedName)}</td><td>${escH(m.dbName)}</td><td>${escH(m.recordId)}</td></tr>`).join('')}</tbody>
      </table></div>
      ${lookup.matchedRows.length > shown.length ? `<div class="cx-note">Showing the first ${fmt(shown.length)} of ${fmt(lookup.matchedRows.length)} matches. The full list is in the result file.</div>` : ''}`;

    const rm = byId('cx-removeBtn'); rm.disabled = !isAdminUser();
    show('cx-preview-card', true);
  }

  function renderResults(summary){
    const removedNote = summary.recordsNotRemoved
      ? `<div class="cx-warn">${fmt(summary.recordsNotRemoved)} matched record(s) could NOT be removed (blocked by permissions or a database error). They are marked in the Status column of the result file.</div>` : '';
    byId('cx-resultsTitle').textContent = 'Completed';
    byId('cx-resultsSub').textContent = `Processed ${summary.processedAt}. Result workbook contains the Matched, Not Matched and Summary sheets.`;
    byId('cx-result-stats').innerHTML = [
      statCard('Total Uploaded', fmt(summary.totalUploaded)),
      statCard('Exact Matches', fmt(summary.exactMatches)),
      statCard('Records Removed', fmt(summary.recordsRemoved)),
      statCard('Not Found', fmt(summary.notFound)),
      statCard('Databases Checked', fmt(summary.databasesChecked)),
      statCard('Unique Names', fmt(summary.uniqueNames))
    ].join('');
    byId('cx-result-warn').innerHTML = removedNote;
    show('cx-preview-card', false); show('cx-results', true);
  }

  // ── 3. RESULT WORKBOOK ───────────────────────────────────────────────────
  function buildWorkbook(summary){
    const { matchedRows, notFound } = st.lookup;
    const wb = XLSX.utils.book_new();

    const matched = [['Uploaded Company Name','Matched Company Name','Database Name','Record ID','Status'],
      ...matchedRows.map(m => [m.uploaded, m.matchedName, m.dbName, m.recordId, m.status])];
    const wsM = XLSX.utils.aoa_to_sheet(matched);
    wsM['!cols'] = [{wch:38},{wch:38},{wch:28},{wch:38},{wch:26}];
    XLSX.utils.book_append_sheet(wb, wsM, 'Matched');

    const nm = [['Uploaded Company Name','Status'], ...notFound.map(n => [n, 'Not Found'])];
    const wsN = XLSX.utils.aoa_to_sheet(nm);
    wsN['!cols'] = [{wch:44},{wch:14}];
    XLSX.utils.book_append_sheet(wb, wsN, 'Not Matched');

    const rowsS = [['Metric','Value'],
      ['Total Uploaded', summary.totalUploaded],
      ['Unique Company Names Processed', summary.uniqueNames],
      ['Repeated Name Rows Skipped', summary.duplicateRows],
      ['Exact Matches', summary.exactMatches],
      ['Records Removed', summary.recordsRemoved],
      ['Matched Records Not Removed', summary.recordsNotRemoved],
      ['Not Found', summary.notFound],
      ['Databases Checked', summary.databasesChecked],
      ['Matching Rule', 'Exact match after trimming surrounding spaces' + (CASE_SENSITIVE ? ' (case-sensitive)' : '')],
      ['Processing Date/Time', summary.processedAt]];
    const wsS = XLSX.utils.aoa_to_sheet(rowsS);
    wsS['!cols'] = [{wch:36},{wch:52}];
    XLSX.utils.book_append_sheet(wb, wsS, 'Summary');

    const out = XLSX.write(wb, { bookType:'xlsx', type:'array' });
    return new Blob([out], { type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  }
  function downloadResult(){
    if (!st.blob) return;
    const a = document.createElement('a');
    a.href = URL.createObjectURL(st.blob); a.download = st.filename; a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  }
  function stamp(){
    const d = new Date(), p = n => String(n).padStart(2, '0');
    return `${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
  }

  // Generates the workbook, shows results, refreshes existing Data Hub views.
  async function finalize(recordsRemoved, recordsNotRemoved){
    setStep('generate', 'active'); setProgress(96, 'Generating result file…'); await tick();
    const { upload, lookup } = st;
    const summary = {
      totalUploaded: upload.totalRows, uniqueNames: upload.unique.length, duplicateRows: upload.duplicateRows,
      exactMatches: lookup.exactMatches, recordsRemoved, recordsNotRemoved,
      notFound: lookup.notFound.length, databasesChecked: lookup.databasesChecked,
      processedAt: new Date().toLocaleString()
    };
    st.summary = summary;
    st.blob = buildWorkbook(summary);
    st.filename = `Company_Exact_Lookup_Removal_${stamp()}.xlsx`;
    setStep('generate', 'done'); setStep('done', 'done'); setProgress(100, 'Completed');
    renderResults(summary);
  }

  // ── 4. REMOVE exact matches (existing delete path; RLS is respected) ─────
  async function removeMatched(){
    if (st.busy || !st.lookup) return;
    if (!isAdminUser()){ notify('Only Admins can delete records.', 'error'); return; }
    st.busy = true; closeModal();
    show('cx-preview-card', false);
    try {
      const { matchedRows } = st.lookup;
      const ids = [...new Set(matchedRows.map(m => m.recordId))];
      setStep('remove', 'active'); setProgress(0, `Removing 0 of ${fmt(ids.length)} records…`);
      const removed = new Set(), failed = new Map();
      for (let i = 0; i < ids.length; i += DELETE_BATCH){
        const batch = ids.slice(i, i + DELETE_BATCH);
        try {
          // .select('id') returns only the rows actually deleted, so a delete that RLS
          // silently blocks is reported honestly instead of being counted as removed.
          const { data, error } = await supa.from('records').delete().in('id', batch).select('id');
          if (error) throw error;
          (data || []).forEach(d => removed.add(String(d.id)));
        } catch (e){
          batch.forEach(id => failed.set(String(id), (e && e.message) || 'Database error'));
        }
        setProgress(Math.min(94, ((i + batch.length) / ids.length) * 94), `Removing ${fmt(Math.min(i + DELETE_BATCH, ids.length))} of ${fmt(ids.length)} records…`);
        await tick();
      }
      let notRemoved = 0;
      matchedRows.forEach(m => {
        const id = String(m.recordId);
        if (removed.has(id)) m.status = 'Removed';
        else { notRemoved++; m.status = failed.has(id) ? `Not Removed – ${failed.get(id)}` : 'Not Removed – blocked by permissions'; }
      });
      dhOnRecordsRemoved([...removed]);
      setStep('remove', 'done');

      // Refresh the app's existing views exactly as the Data Hub's own delete flows do.
      try {
        if (typeof loadRecords === 'function') await loadRecords();
        if (typeof refreshAllDataView === 'function') refreshAllDataView();
        if (typeof renderDatabaseList === 'function') renderDatabaseList();
        if (typeof renderDashboard === 'function') renderDashboard();
      } catch (e){ console.warn('[CX toolkit] view refresh failed', e); }

      await finalize(removed.size, notRemoved);
      if (typeof logAudit === 'function') logAudit('company_exact_lookup_removal', {
        uploaded: st.upload.totalRows, unique: st.upload.unique.length, exact_matches: st.lookup.exactMatches,
        records_removed: removed.size, records_not_removed: notRemoved, not_found: st.lookup.notFound.length
      });
      notify(`${fmt(removed.size)} record(s) removed.`, notRemoved ? '' : 'success');
    } catch (e){
      console.error('[CX toolkit] removal failed', e);
      notify('Removal failed: ' + ((e && e.message) || e), 'error');
      show('cx-preview-card', true);
    } finally { st.busy = false; }
  }

  // ── modal ────────────────────────────────────────────────────────────────
  function openModal(){
    if (!st.lookup || !st.lookup.matchedRows.length) return;
    if (!isAdminUser()){ notify('Only Admins can delete records.', 'error'); return; }
    byId('cx-confirm-uploaded').textContent = fmt(st.upload.unique.length);
    byId('cx-confirm-matches').textContent  = fmt(st.lookup.exactMatches);
    byId('cx-confirm-records').textContent  = fmt(new Set(st.lookup.matchedRows.map(m => m.recordId)).size);
    byId('cx-confirm-overlay').classList.remove('hidden');
  }
  function closeModal(){ byId('cx-confirm-overlay').classList.add('hidden'); }

  // ── file handling (whole pipeline up to the confirmation step) ───────────
  async function handleFile(file){
    if (st.busy) return;
    resetAll();
    const zone = byId('cx-zone');
    if (!/\.xlsx$/i.test(file.name)){ showError('Only .xlsx files are supported.'); return; }
    byId('cx-fileName').textContent = file.name; zone.classList.add('loaded');
    st.busy = true;
    show('cx-progress-card', true); resetSteps();
    try {
      setStep('read', 'active'); setProgress(5, 'Reading Excel…'); await tick();
      st.upload = await parseWorkbook(file);
      setStep('read', 'done');
      byId('cx-fileMeta').textContent =
        `Column “${st.upload.header || '(no header)'}” · sheet “${st.upload.sheetName}” · ${fmt(st.upload.totalRows)} company name(s)` +
        (st.upload.duplicateRows ? ` (${fmt(st.upload.duplicateRows)} repeated, will be processed once)` : '');

      setStep('check', 'active'); setProgress(8, 'Checking Data Hub databases…'); await tick();
      st.lookup = await runLookup(st.upload.unique);
      setStep('check', 'done');
      setStep('found', 'done', `Exact matches found: ${fmt(st.lookup.exactMatches)}`);
      setProgress(100, `Lookup finished — ${fmt(st.lookup.scanned)} records checked`);

      if (!st.lookup.matchedRows.length){
        setStep('remove', 'skipped', 'Removing matched records… (nothing to remove)');
        await finalize(0, 0);
        notify('No exact matches found. Nothing was removed.', '');
      } else {
        renderPreview();
        notify(`${fmt(st.lookup.exactMatches)} exact match(es) found. Review, then confirm removal.`, 'success');
      }
    } catch (e){
      console.error('[CX toolkit]', e);
      show('cx-progress-card', false);
      const msg = (e && e.message) || String(e);
      showError(msg);
      if (msg === ONE_COLUMN_ERROR) notify(msg, 'error');
      byId('cx-zone').classList.remove('loaded'); byId('cx-fileName').textContent = '';
      byId('cx-file').value = '';
    } finally { st.busy = false; }
  }

  // ── view switching + init ────────────────────────────────────────────────
  function openLanding(){ byId('toolkits-landing').classList.remove('hidden'); byId('toolkits-cx').classList.add('hidden'); }
  function openView(){ byId('toolkits-landing').classList.add('hidden'); byId('toolkits-cx').classList.remove('hidden'); }

  let initialized = false;
  function init(){
    if (initialized) return; initialized = true;
    const card = byId('toolkit-card-cx'); if (card) card.addEventListener('click', openView);
    const back = byId('cx-back-btn'); if (back) back.addEventListener('click', openLanding);

    const zone = byId('cx-zone'), input = byId('cx-file');
    if (zone && input){
      zone.addEventListener('dragover', e => { e.preventDefault(); zone.classList.add('drag'); });
      zone.addEventListener('dragleave', () => zone.classList.remove('drag'));
      zone.addEventListener('drop', e => { e.preventDefault(); zone.classList.remove('drag'); const f = e.dataTransfer.files[0]; if (f) handleFile(f); });
      input.addEventListener('change', () => { if (input.files[0]) handleFile(input.files[0]); });
    }
    byId('cx-removeBtn').addEventListener('click', openModal);
    byId('cx-cancelBtn').addEventListener('click', () => { if (!st.busy) resetAll(); });
    byId('cx-againBtn').addEventListener('click', () => { if (!st.busy) resetAll(); });
    byId('cx-downloadBtn').addEventListener('click', downloadResult);
    byId('cx-confirm-cancel').addEventListener('click', closeModal);
    byId('cx-confirm-ok').addEventListener('click', removeMatched);
    // Clicking the backdrop or pressing Esc only ever CANCELS — it can never confirm a deletion.
    byId('cx-confirm-overlay').addEventListener('click', e => { if (e.target.id === 'cx-confirm-overlay') closeModal(); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !byId('cx-confirm-overlay').classList.contains('hidden')) closeModal(); });
    resetSteps();
  }
  return { init };
})();
CompanyExactRemovalToolkit.init();
JocDataLocation.init();
JocLocalFolder.init();

async function boot(){
  if (!supa){
    $('#intro').classList.add('fade-out');
    setTimeout(()=>{
      $('#intro').style.display='none';
      $('#auth-screen').classList.remove('hidden');
      showAuthView('login');
      $('#login-alert').className='auth-alert error';
      $('#login-alert').textContent='Supabase is not configured yet — set CONFIG.SUPABASE_URL and CONFIG.SUPABASE_ANON_KEY at the top of the <script>.';
    }, 180);
    return;
  }

  const isRecovery = window.location.hash.includes('type=recovery');
  const { data: { session } } = await supa.auth.getSession();

  supa.auth.onAuthStateChange((event, sess)=>{
    if (event === 'PASSWORD_RECOVERY'){
      $('#intro').classList.add('fade-out');
      setTimeout(()=>{ $('#intro').style.display='none'; $('#auth-screen').classList.remove('hidden'); showAuthView('reset'); }, 180);
    }
  });

  // No artificial 2.2s startup wait. Session is already known, so transition immediately.
  $('#intro').classList.add('fade-out');
  setTimeout(async ()=>{
    $('#intro').style.display='none';
    if (isRecovery){ $('#auth-screen').classList.remove('hidden'); showAuthView('reset'); return; }
    if (session){ await onAuthed(session); }
    else { $('#auth-screen').classList.remove('hidden'); showAuthView('login'); }
  }, 180);
}


/* ---------- Appointment -> Calendar bridge (uses existing daily_entries.notes JSON) ----------
   No schema changes: appointment dates/details already live inside daily_entries.notes.
   The cache is refreshed after appointment saves and once after authentication so
   calendar reloads continue to show every permanently saved appointment. */
async function updRefreshAppointmentCalendarCache(){
  if(!S.session) return [];
  const scopedUpdates=(S.isAdmin?S.updates:S.updates.filter(u=>String(u.owner_id)===String(S.session.user.id)));
  const rows=await updFetchAllHistory(scopedUpdates.map(u=>u.id));
  const byId=new Map(scopedUpdates.map(u=>[String(u.id),u]));
  const out=[],seen=new Set();
  rows.forEach(row=>{
    const u=byId.get(String(row.update_id));
    const v=updParseDailyRow(row);
    (v.appointmentDetails||[]).forEach(d=>{
      const date=String(d.appointmentDate||d.appointment_date||'').slice(0,10);
      if(!date) return;
      const fp=updAppointmentFingerprint(d);
      if(!fp || seen.has(fp)) return;
      seen.add(fp);
      out.push({detail:d,row,update:u});
    });
  });
  S._appointmentCalendarRecords=out;
  return out;
}

/* ===================== REAL WORKSPACE CALENDAR ACTIVITY =====================
   Replaces the old demo/raw-title calendar presentation with compact, real
   activity markers. Existing manual calendar events remain untouched.
   System activity is derived from the existing databases/records/reminders
   data, so nothing new is written to Supabase and no historical data is lost.
   ========================================================================== */
(function installRealCalendarActivity(){
  const _oldCalEventLoad = calEventLoad;
  const _oldCalEventSave = calEventSave;

  function calSystemDatabases(){
    const all = Array.isArray(S.databases) ? S.databases : [];
    return S.isAdmin ? all : all.filter(d=>String(d.assigned_user_id||'')===String(S.session?.user?.id||''));
  }
  function calDateOnly(v){
    if(!v) return null;
    const d = new Date(v);
    return isNaN(d.getTime()) ? null : calIsoDate(d);
  }
  function calActivityEventsForDate(date){
    const dateKey = typeof date==='string' ? date : calIsoDate(date);
    const dbs = calSystemDatabases();
    const out=[];

    // Database imported.
    dbs.filter(d=>calDateOnly(d.upload_date)===dateKey).forEach(d=>out.push({
      id:'sys-import-'+d.id, derived:true, kind:'import', type:'import', date:dateKey,
      title:'Database imported', start:'', end:'',
      description:`${d.name||'Database'} was imported into the workspace.`,
      related:d.name||'Workspace', priority:'Normal', database:d
    }));

    // Database assigned/reassigned.
    dbs.filter(d=>d.assigned_user_id && calDateOnly(d.assigned_at)===dateKey).forEach(d=>out.push({
      id:'sys-assignment-'+d.id+'-'+dateKey, derived:true, kind:'assignment', type:'assignment', date:dateKey,
      title:'Database assigned', start:'', end:'',
      description:`${d.name||'Database'} was assigned to ${d.assigned_user_name||d.assigned_to||'a user'}.`,
      related:d.name||'Workspace', priority:'High', database:d,
      assignedUserName:d.assigned_user_name||d.assigned_to||'—'
    }));

    // Follow-up dates on records. One compact event per day, regardless of how
    // many customer rows are scheduled, so the month view stays clean.
    const records = Array.isArray(S.records) ? S.records : [];
    const followups = records.filter(r=>{
      if(!r || !r.follow_up_date) return false;
      if(String(r.follow_up_date).slice(0,10)!==dateKey) return false;
      if(S.isAdmin) return true;
      const db=calSystemDatabases().find(d=>String(d.id)===String(r.database_id));
      return !!db;
    });
    if(followups.length){
      const names=[...new Set(followups.map(r=>r.company_name||r.contact_name||r.database_name||'Customer').filter(Boolean))];
      out.push({
        id:'sys-followup-'+dateKey, derived:true, kind:'followup', type:'followup', date:dateKey,
        title:`Follow-ups · ${followups.length}`, start:'', end:'',
        description:`${followups.length} customer follow-up${followups.length===1?'':'s'} scheduled for this date.`,
        related:names.slice(0,3).join(', ')+(names.length>3?'…':''), priority:'High',
        followups
      });
    }

    // Existing reminder system is also represented as a compact activity chip.
    const rems = typeof reminderEventsFor==='function' ? reminderEventsFor(new Date(dateKey+'T12:00:00').toDateString()) : [];
    if(rems.length) out.push({
      id:'sys-reminder-'+dateKey, derived:true, kind:'reminder', type:'reminder', date:dateKey,
      title:`Reminders · ${rems.length}`, start:'', end:'',
      description:`${rems.length} reminder${rems.length===1?'':'s'} on this date.`,
      related:[...new Set(rems.map(r=>r.company_name||r.database_name||'Reminder').filter(Boolean))].slice(0,3).join(', '),
      priority:'Normal', reminders:rems
    });

    // Permanently saved appointments from daily_entries. Each appointment gets
    // its own calendar activity and a dedicated appointment icon/type.
    const appointments=(S._appointmentCalendarRecords||[]).filter(x=>{
      const date=String(x.detail?.appointmentDate||x.detail?.appointment_date||'').slice(0,10);
      if(date!==dateKey) return false;
      if(S.isAdmin) return true;
      return String(x.update?.owner_id||'')===String(S.session?.user?.id||'');
    });
    appointments.forEach((x,i)=>{
      const d=x.detail||{}, u=x.update||{};
      out.push({
        id:'sys-appointment-'+updAppointmentFingerprint(d)+'-'+i,
        derived:true, kind:'appointment', type:'appointment', date:dateKey, start:'', end:'',
        title:d.companyName||d.company_name||'Appointment',
        description:`Appointment with ${d.companyName||d.company_name||'customer'}${d.contactPerson?', contact: '+d.contactPerson:''}.`,
        related:d.databaseName||d.database_name||u.database_name||'Workspace',
        priority:'High', appointment:d, appointmentRow:x.row, assignedUserName:updUserDisplay(u)
      });
    });

    // User-created/manual calendar events are retained exactly as before.
    (S.cal.events||[]).filter(e=>e.date===dateKey).forEach(e=>out.push({...e,derived:false,kind:'manual'}));
    return out;
  }

  function calAllActivityEvents(){
    const dates=new Set();
    calSystemDatabases().forEach(d=>{const a=calDateOnly(d.upload_date), b=calDateOnly(d.assigned_at); if(a)dates.add(a);if(b)dates.add(b);});
    (S.records||[]).forEach(r=>{if(r.follow_up_date)dates.add(String(r.follow_up_date).slice(0,10));});
    (typeof myReminders==='function'?myReminders():[]).forEach(r=>{const d=calDateOnly(r.reminder_date);if(d)dates.add(d);});
    (S._appointmentCalendarRecords||[]).forEach(x=>{const d=String(x.detail?.appointmentDate||x.detail?.appointment_date||'').slice(0,10);if(d)dates.add(d);});
    (S.cal.events||[]).forEach(e=>{if(e.date)dates.add(e.date);});
    let all=[]; dates.forEach(d=>{all=all.concat(calActivityEventsForDate(d));});
    return all;
  }

  function activityTypeMeta(kind){
    return {
      import:{label:'Import',icon:CAL_ICO_IMPORT,cls:'import'},
      assignment:{label:'Assignment',icon:CAL_ICO_ASSIGN,cls:'assignment'},
      followup:{label:'Follow-up',icon:CAL_ICO_FOLLOWUP,cls:'followup'},
      reminder:{label:'Reminder',icon:CAL_ICO_REMINDER,cls:'reminder'},
      appointment:{label:'Appointment',icon:(typeof CAL_ICO_APPOINTMENT!=='undefined'?CAL_ICO_APPOINTMENT:CAL_ICO_MANUAL),cls:'appointment'},
      manual:{label:'Event',icon:CAL_ICO_MANUAL,cls:'manual'}
    }[kind] || {label:'Event',icon:CAL_ICO_MANUAL,cls:'manual'};
  }
  function activityChip(e){
    const m=activityTypeMeta(e.kind||e.type);
    const count = e.kind==='followup' ? (e.followups?.length||1) : e.kind==='reminder' ? (e.reminders?.length||1) : 1;
    const label=e.kind==='import'?'Import':e.kind==='assignment'?'Assignment':e.kind==='followup'?'Follow-up':e.kind==='reminder'?'Reminder':(e.title||'Event');
    const countBadge = count>1 ? `<span class="icon-count">${count>99?'99+':count}</span>` : '';
    return `<button type="button" class="cal-activity-chip ${m.cls}" data-event-id="${esc(e.id)}" title="${esc(label+(e.title&&e.kind!=='manual'?` · ${e.title}`:''))}" onclick="event.stopPropagation()"><span class="ic">${m.icon}</span>${countBadge}</button>`;
  }
  function dayClasses(date,events){
    return [
      events.some(e=>e.kind==='import')?'cal-has-import':'',
      events.some(e=>e.kind==='assignment')?'cal-has-assignment':'',
      events.some(e=>e.kind==='followup')?'cal-has-followup':'',
      events.some(e=>e.kind==='reminder')?'cal-has-reminder':'',
      events.length?'cal-activity-day':''
    ].filter(Boolean).join(' ');
  }

  // Override the legacy helpers used by all three calendar views.
  window.calWorkspaceEventsFor = function(day){ return calActivityEventsForDate(day); };
  window.calFilteredEvents = function(){
    const q=(S.cal.search||'').trim().toLowerCase(), f=S.cal.filter;
    return calAllActivityEvents().filter(e=>{
      const matchesType=!f || (f==='assignment' ? e.kind==='assignment' : e.type===f || (f==='reminder'&&e.kind==='reminder'));
      const hay=[e.title,e.description,e.related,e.type,e.kind,e.assignedUserName].join(' ').toLowerCase();
      return matchesType && (!q || hay.includes(q));
    });
  };
  window.calEventsFor = function(dateStr){
    return calSystemDatabases().filter(d=>new Date(d.upload_date).toDateString()===dateStr);
  };

  window.calEventMeta = function(e){
    const m=activityTypeMeta(e.kind||e.type);
    return {label:m.label,color:m.cls==='import'?'blue':m.cls==='assignment'?'violet':m.cls==='followup'?'green':m.cls==='reminder'?'orange':m.cls==='appointment'?'appointment':'cyan',icon:m.icon};
  };

  window.calEventPill = function(e){ return activityChip(e); };

  window.calUpcoming = function(){
    const now=calIsoDate(new Date());
    const all=calFilteredEvents().filter(e=>e.date>=now).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)).slice(0,7);
    const el=$('#cal-upcoming-list'); if(!el)return;
    $('#cal-upcoming-count').textContent=all.length;
    el.innerHTML=all.length ? all.map(e=>{
      const m=activityTypeMeta(e.kind||e.type), count=e.kind==='followup'?(e.followups?.length||1):e.kind==='reminder'?(e.reminders?.length||1):1;
      return `<div class="upcoming-item" data-event-id="${esc(e.id)}"><div class="upcoming-date">${new Date(e.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div><div class="upcoming-main"><span class="upcoming-dot ${m.cls}" style="background:${m.cls==='import'?'#3159E0':m.cls==='assignment'?'#7C3AED':m.cls==='followup'?'#10B981':m.cls==='reminder'?'#F59E0B':m.cls==='appointment'?'#E11D48':'#0EA5E9'}"></span><div><div class="upcoming-title">${esc(e.title)}</div><div class="upcoming-time">${count} item${count===1?'':'s'} · ${esc(m.label)}</div></div></div></div>`;
    }).join('') : `<div class="upcoming-empty-rich"><svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="10" width="32" height="30" rx="4.5"/><line x1="8" y1="19" x2="40" y2="19"/><line x1="16" y1="6" x2="16" y2="13"/><line x1="32" y1="6" x2="32" y2="13"/><path d="M17.5 28.5l4 4 8-8.5" stroke-width="1.6"/></svg><div class="e-title">No upcoming activity</div><div class="e-sub">You're all caught up!</div><div class="e-body">No events or reminders match your current filters.</div></div>`;
    $all('.upcoming-item',el).forEach(x=>x.addEventListener('click',()=>{const e=calAllActivityEvents().find(z=>z.id===x.dataset.eventId);if(e)openCalEventDetail(e)}));
  };

  window.wirePremiumEventClicks = function(){
    $all('[data-event-id]', $('#cal-body')).forEach(x=>x.addEventListener('click',ev=>{
      ev.stopPropagation(); const e=calAllActivityEvents().find(z=>z.id===x.dataset.eventId); if(e)openCalEventDetail(e);
    }));
  };

  window.renderPremiumCalendarBody = function(){
    const cursor=S.cal.cursor;
    if(S.cal.view==='agenda'){
      const all=calFilteredEvents().sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
      const groups={}; all.forEach(e=>(groups[e.date]??=[]).push(e)); const dates=Object.keys(groups).sort();
      $('#cal-body').innerHTML=dates.length?`<div class="agenda-premium">${dates.map(date=>`<div class="agenda-day-head">${new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()}</div>${groups[date].map(e=>{const m=activityTypeMeta(e.kind||e.type), count=e.kind==='followup'?(e.followups?.length||1):e.kind==='reminder'?(e.reminders?.length||1):1;return `<div class="agenda-event-row" data-event-id="${esc(e.id)}"><div class="agenda-event-time">${calTimeLabel(e.start)||'—'}</div><div class="agenda-event-icon">${m.icon}</div><div><div class="agenda-event-title">${esc(e.title)}</div><div class="agenda-event-sub">${count} item${count===1?'':'s'} · ${esc(m.label)}${e.related?' · '+esc(e.related):''}</div></div></div>`}).join('')}</div>`).join('')}</div>`:`<div class="agenda-premium"><div class="upcoming-empty">No activity found.</div></div>`;
      wirePremiumEventClicks(); return;
    }
    if(S.cal.view==='week'){
      const start=new Date(cursor); start.setDate(cursor.getDate()-cursor.getDay());
      const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d;});
      let html='<div class="cal-week-grid"><div class="week-time"></div>'+days.map(d=>{const ev=calFilteredEvents().filter(e=>e.date===calIsoDate(d));const today=d.toDateString()===new Date().toDateString();return `<div class="week-head ${today?'today':''} ${ev.length?'has-events':''}">${d.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}<strong>${d.getDate()}</strong>${ev.length?`<small>${ev.length} activity</small>`:''}</div>`}).join('');
      const hours=Array.from({length:12},(_,i)=>i+8);
      hours.forEach(h=>{html+=`<div class="week-time-label">${h%12||12}:00 ${h>=12?'PM':'AM'}</div>`;days.forEach(d=>{const ev=calFilteredEvents().filter(e=>e.date===calIsoDate(d));html+=`<div class="week-slot">${h===8?ev.slice(0,4).map(e=>{const m=activityTypeMeta(e.kind||e.type);return `<div class="week-event ${m.cls==='import'?'blue':m.cls==='assignment'?'violet':m.cls==='followup'?'green':m.cls==='reminder'?'orange':'cyan'}" data-event-id="${esc(e.id)}">${m.icon} ${esc(e.title)}</div>`}).join(''):''}</div>`;});});
      html+='</div>'; $('#cal-body').innerHTML=html; wirePremiumEventClicks(); return;
    }
    const first=new Date(cursor.getFullYear(),cursor.getMonth(),1), startDay=new Date(first); startDay.setDate(first.getDate()-first.getDay());
    let html='<div class="cal-grid">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-dow">${d}</div>`).join('');
    for(let i=0;i<42;i++){
      const day=new Date(startDay);day.setDate(startDay.getDate()+i);const dateKey=calIsoDate(day),other=day.getMonth()!==cursor.getMonth(),today=day.toDateString()===new Date().toDateString();
      const ev=calFilteredEvents().filter(e=>e.date===dateKey); const classes=dayClasses(day,ev);
      const chips=ev.slice(0,4).map(activityChip).join('');
      const more=ev.length>4?`<div class="cal-more-activity">+${ev.length-4} more activity</div>`:'';
      const tooltip=ev.length?ev.map(e=>`${activityTypeMeta(e.kind||e.type).label}: ${e.title}`).join('\n'):'No workspace activity';
      html+=`<div class="cal-cell ${other?'other':''} ${today?'today':''} ${classes}" data-daynum="${day.getTime()}" data-tip="${esc(tooltip)}"><div class="cal-daynum">${day.getDate()}</div><div class="cal-activity-stack">${chips}${more}</div></div>`;
    }
    html+='</div>'; $('#cal-body').innerHTML=html;
    $all('.cal-cell',$('#cal-body')).forEach(cell=>cell.addEventListener('click',()=>{const day=new Date(parseInt(cell.dataset.daynum));openCalendarActivityDay(day);}));
    wirePremiumEventClicks();
  };

  window.openCalendarActivityDay = function(day){
    const dateKey=calIsoDate(day), events=calActivityEventsForDate(dateKey); $all('#page-calendar .cal-cell').forEach(c=>c.classList.toggle('is-selected', c.dataset.daynum===String(day.getTime())));
    const imports=events.filter(e=>e.kind==='import'), assignments=events.filter(e=>e.kind==='assignment'), followups=events.find(e=>e.kind==='followup'), reminders=events.find(e=>e.kind==='reminder'), manual=events.filter(e=>e.kind==='manual');
    $('#day-modal-title').textContent=day.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});
    let html='';
    const appointments=events.filter(e=>e.kind==='appointment');
    const stats=[[CAL_ICO_IMPORT,imports.length,'Imported'],[CAL_ICO_ASSIGN,assignments.length,'Assigned'],[CAL_ICO_FOLLOWUP,followups?.followups?.length||0,'Follow-ups'],[CAL_ICO_REMINDER,reminders?.reminders?.length||0,'Reminders'],[(typeof CAL_ICO_APPOINTMENT!=='undefined'?CAL_ICO_APPOINTMENT:CAL_ICO_MANUAL),appointments.length,'Appointments']];
    html+=`<div class="cal-activity-summary">${stats.map(x=>`<div class="cal-activity-stat"><span class="ic">${x[0]}</span><div><div class="n">${x[1].toLocaleString()}</div><div class="l">${x[2]}</div></div></div>`).join('')}</div>`;
    if(imports.length){html+=`<div class="day-detail-count"><strong><span class="day-detail-ic">${CAL_ICO_IMPORT}</span>Imports</strong> — ${imports.length}</div>`;html+=imports.map(e=>`<div class="day-stat-row"><div class="day-stat-top"><div class="day-stat-ic">${DAY_ICON_DB}</div><div class="day-stat-body"><div class="n">${esc(e.database?.name||e.related||'Database')}</div></div><span class="pill pill-green">Imported</span></div><div class="day-stat-grid"><div class="day-stat-field"><div class="k">Assigned User</div><div class="v">${esc(e.database?.assigned_user_name||e.database?.assigned_to||'—')}</div></div><div class="day-stat-field"><div class="k">Customers</div><div class="v">${Number(e.database?.customer_count||0).toLocaleString()}</div></div><div class="day-stat-field"><div class="k">Imported</div><div class="v">${fmtDateTime(e.database?.upload_date)}</div></div></div></div>`).join('');}
    if(assignments.length){html+=`<div class="day-detail-count" style="margin-top:18px;padding-top:16px;border-top:1px solid #F0F0F6;"><strong><span class="day-detail-ic">${CAL_ICO_ASSIGN}</span>Assignments</strong> — ${assignments.length}</div>`;html+=assignments.map(e=>`<div class="day-stat-row"><div class="day-stat-top"><div class="day-stat-ic">${ICON_USER_SM}</div><div class="day-stat-body"><div class="n">${esc(e.database?.name||'Database')}</div></div><span class="pill pill-blue">${esc(e.assignedUserName||'Assigned')}</span></div><div class="day-stat-grid"><div class="day-stat-field"><div class="k">Assigned To</div><div class="v">${esc(e.assignedUserName||'—')}</div></div><div class="day-stat-field"><div class="k">Assigned By</div><div class="v">${esc(e.database?.assigned_by_name||'—')}</div></div><div class="day-stat-field"><div class="k">Time</div><div class="v">${fmtTime(e.database?.assigned_at)}</div></div></div></div>`).join('');}
    if(followups){html+=`<div class="day-detail-count" style="margin-top:18px;padding-top:16px;border-top:1px solid #F0F0F6;"><strong><span class="day-detail-ic">${CAL_ICO_FOLLOWUP}</span>Follow-ups</strong> — ${followups.followups.length}</div>`;html+=followups.followups.slice(0,30).map(r=>`<div class="day-stat-row"><div class="day-stat-top"><div class="day-stat-ic">${CAL_ICO_FOLLOWUP}</div><div class="day-stat-body"><div class="n">${esc(r.company_name||r.contact_name||'Customer')}</div></div><span class="pill pill-green">Follow-up</span></div><div class="day-stat-grid"><div class="day-stat-field"><div class="k">Database</div><div class="v">${esc(r.database_name||'—')}</div></div><div class="day-stat-field"><div class="k">Follow-up Date</div><div class="v">${fmtDate(r.follow_up_date)}</div></div></div></div>`).join('');if(followups.followups.length>30)html+=`<div class="hint">Showing first 30 follow-ups for this date.</div>`;}
    if(reminders?.reminders?.length){html+=renderDayRemindersSection(day);}
    if(appointments.length){
      html+=`<div class="day-detail-count" style="margin-top:18px;padding-top:16px;border-top:1px solid #F0F0F6;"><strong><span class="day-detail-ic">${typeof CAL_ICO_APPOINTMENT!=='undefined'?CAL_ICO_APPOINTMENT:CAL_ICO_MANUAL}</span>Appointments</strong> — ${appointments.length}</div>`;
      html+=appointments.map(e=>{const d=e.appointment||{};return `<div class="day-stat-row cal-appointment-row"><div class="day-stat-top"><div class="day-stat-ic">${typeof CAL_ICO_APPOINTMENT!=='undefined'?CAL_ICO_APPOINTMENT:CAL_ICO_MANUAL}</div><div class="day-stat-body"><div class="n">${esc(d.companyName||d.company_name||e.title||'Appointment')}</div><div class="s">${esc(d.contactPerson||'')} ${d.position?'· '+esc(d.position):''}</div></div><span class="pill pill-red">Appointment</span></div><div class="day-stat-grid"><div class="day-stat-field"><div class="k">Database</div><div class="v">${esc(d.databaseName||d.database_name||e.related||'—')}</div></div><div class="day-stat-field"><div class="k">Appointment Date</div><div class="v">${esc(d.appointmentDate||d.appointment_date||dateKey)}</div></div><div class="day-stat-field"><div class="k">Salesperson</div><div class="v">${esc(d.salesperson||'—')}</div></div><div class="day-stat-field"><div class="k">Branch</div><div class="v">${esc(d.branch||'—')}</div></div><div class="day-stat-field"><div class="k">Assigned User</div><div class="v">${esc(e.assignedUserName||'—')}</div></div><div class="day-stat-field"><div class="k">Phone</div><div class="v">${esc((d.phoneNumbers||[]).join(', ')||'—')}</div></div></div></div>`}).join('');
    }
    if(manual.length){html+=`<div class="day-detail-count" style="margin-top:18px;padding-top:16px;border-top:1px solid #F0F0F6;"><strong><span class="day-detail-ic">${CAL_ICO_MANUAL}</span>Other Events</strong> — ${manual.length}</div>`;html+=manual.map(e=>`<div class="day-stat-row"><div class="day-stat-top"><div class="day-stat-ic">${CAL_ICO_MANUAL}</div><div class="day-stat-body"><div class="n">${esc(e.title)}</div></div></div><div class="hint" style="margin-top:8px;">${esc(e.description||'')}</div></div>`).join('');}
    if(!events.length) html+=`<div class="day-empty-state"><div class="ic">${ICON_CAL_SM}</div><div class="t">No workspace activity</div><div class="d">Nothing was imported, assigned, scheduled for follow-up, or reminded on this date.</div></div>`;
    $('#day-modal-body').innerHTML=html;
    if(reminders?.reminders?.length) wireDayReminderCardActions(day);
    $('#day-modal-overlay').classList.remove('hidden');
  };

  window.openCalEventDetail = function(e){
    if(!e)return;
    if(e.derived){ openCalendarActivityDay(new Date(e.date+'T12:00:00')); return; }
    const meta=calEventMeta(e);
    $('#evt-detail-type').textContent=meta.label.toUpperCase();$('#evt-detail-title').textContent=e.title;
    $('#cal-event-detail-body').innerHTML=`<div class="cal-detail-hero"><div style="font-size:14px;font-weight:700;color:#2448B9;display:flex;align-items:center;gap:8px"><span style="width:16px;height:16px;display:inline-flex">${meta.icon}</span>${esc(meta.label)}</div><div style="font-size:13px;color:#667085;margin-top:6px">${esc(e.description||'No description added.')}</div></div><div class="cal-detail-grid"><div class="cal-detail-item"><div class="k">Date & Time</div><div class="v">${new Date(e.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'})} · ${calTimeLabel(e.start)||'All day'}${e.end?' – '+calTimeLabel(e.end):''}</div></div><div class="cal-detail-item"><div class="k">Priority</div><div class="v">${esc(e.priority||'Normal')}</div></div><div class="cal-detail-item"><div class="k">Related</div><div class="v">${esc(e.related||'Workspace')}</div></div><div class="cal-detail-item"><div class="k">Reminder</div><div class="v">${e.reminder&&e.reminder!=='none'?esc(e.reminder)+' minutes before':'No reminder'}</div></div></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:18px"><button class="btn" id="cal-event-delete">Delete</button><button class="btn btn-primary" id="cal-event-edit">Edit</button></div>`;
    $('#cal-event-detail-overlay').classList.remove('hidden');
    $('#cal-event-delete').onclick=()=>{S.cal.events=S.cal.events.filter(x=>x.id!==e.id);_oldCalEventSave();$('#cal-event-detail-overlay').classList.add('hidden');renderCalendar();toast('Event deleted','success')};
    $('#cal-event-edit').onclick=()=>{openCalEventModal(e);$('#cal-event-detail-overlay').classList.add('hidden')};
  };

  window.renderCalendar = function(){
    const cursor=S.cal.cursor;$('#cal-month-label').textContent=cursor.toLocaleDateString(undefined,{month:'long',year:'numeric'});
    const sel=$('#cal-month-select');if(sel){sel.innerHTML=Array.from({length:12},(_,i)=>`<option value="${i}">${new Date(cursor.getFullYear(),i,1).toLocaleDateString(undefined,{month:'long'})}</option>`).join('');sel.value=cursor.getMonth();}
    renderPremiumCalendarBody();calUpcoming();
  };

  // Hydrate appointment dates from permanent daily_entries on initial workspace load.
  updRefreshAppointmentCalendarCache().then(()=>{ if($('#page-calendar')?.classList.contains('active')) window.renderCalendar(); }).catch(e=>console.warn('[APPOINTMENT CALENDAR LOAD FAILED]',e));

  // Remove the six demo seed events that made the calendar look like a sample
  // screen. User-created events are preserved.
  if(Array.isArray(S.cal.events)){
    const cleaned=S.cal.events.filter(e=>!/^seed-/.test(String(e.id||'')));
    if(cleaned.length!==S.cal.events.length){S.cal.events=cleaned;_oldCalEventSave();}
  }
})();


/* ==========================================================================
   EXISTING EMAIL BUTTON EXTENSION — Swift Cargo templates
   --------------------------------------------------------------------------
   This block intentionally changes only the existing Email quick action.
   It does not alter Supabase schema/RLS/authentication or the other drawer
   actions.
   ========================================================================== */
(function initSwiftCargoEmailFlow(){
  const choice = $('#swift-email-choice-overlay');
  const composer = $('#swift-email-composer-overlay');
  if (!choice || !composer) return;

  let emailRecord = null;
  let activeTemplate = 'manual';

  // Permanent Company Profile PDF reference in existing Supabase Storage.
  const getConfiguredProfileAttachment = () => window.SwiftEmailAutomation?.attachment?.() || null;
  const getConfiguredProfileAttachmentUrl = () => getConfiguredProfileAttachment() ? 'supabase-storage-reference' : '';

  function currentRecord(){
    const id = currentDrawerRecordId;
    if (!id) return null;
    return (S.records || []).find(x => String(x.id) === String(id)) || null;
  }

  function businessEmail(r){
    return String(
      r?.business_email_1 ||
      r?.business_email_2 ||
      r?.personal_email_1 ||
      r?.personal_email_2 ||
      ''
    ).trim();
  }

  function contactName(r, email=''){
    const direct = String(r?.contact_person || '').trim();
    if (direct) return direct;
    const fallback = extractGreetingName(email);
    return fallback || 'Sir';
  }

  function titleCase(s){
    return String(s || '').toLowerCase().replace(/(^|[\s'-])([a-z])/g, (_,a,b)=>a+b.toUpperCase());
  }

  function extractGreetingName(email){
    const local = String(email || '').trim().split('@')[0] || '';
    if (!local) return '';
    const cleaned = local
      .replace(/[0-9]+/g,' ')
      .replace(/[._-]+/g,' ')
      .replace(/\s+/g,' ')
      .trim();
    if (!cleaned) return '';
    const first = cleaned.split(' ')[0] || '';
    if (!/^[a-zA-Z]{2,20}$/.test(first)) return '';
    const lower = first.toLowerCase();
    const blocked = new Set([
      'info','sales','admin','support','contact','office','hello','enquiry','inquiry',
      'accounts','account','billing','finance','hr','career','careers','jobs','marketing',
      'logistics','shipping','cargo','service','services','mail','email','team','company',
      'export','imports','import','purchase','purchases','booking','bookings','customer'
    ]);
    if (blocked.has(lower)) return '';
    return titleCase(first);
  }

  function greetingFor(email){
    const n = extractGreetingName(email);
    return n ? `Dear ${n} sir,` : 'Dear Sir,';
  }

  const escEmailHtml = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

  function companyProfileHtml(email, record){
    const name = contactName(record, email);
    const greeting = name && name !== 'Sir' ? `Dear ${escEmailHtml(name)},` : 'Dear Sir,';
    return `
      <div>${greeting}</div>
      <div><br></div>
      <div>Greetings from Swift Cargo India!</div>
      <div><br></div>
      <div>Hope you’re doing well. This is Fabin Gladstone from Swift Cargo. I would like to introduce my company to you. <mark class="email-highlight">Please find attached the Swift Cargo Company Profile PDF for your reference.</mark></div>
      <div><br></div>
      <div>It was a pleasure speaking with you, I'm seeking for business collaboration opportunity from India with regards to US Freight and Logistics Solutions. I would like to take this opportunity to introduce my organization.</div>
      <div><br></div>
      <div>• Swift Cargo is among the <mark class="email-highlight">top 3 freight solutions provider in the India US trade lane.</mark></div>
      <div>• We have 3 decades of proven expertise- Founded in 1992.</div>
      <div>• We have a 30-year-old presence with <mark class="email-highlight">18-plus branches in India, three in the USA (LA, Houston &amp; NJ) along with Thailand, Canada &amp; Dubai.</mark></div>
      <div>• We do all sectors, but the US is our strong point.</div>
      <div>• We have expertise in most commodities with <mark class="email-highlight">our own FMC (Federal Maritime Commission) registered Bill of Lading and own carrier contracts with competitive rates.</mark></div>
      <div>• We are also <mark class="email-highlight">CTPAT (Customs-Trade Partnership Against Terrorism)</mark> compliant.</div>
      <div>• We have <mark class="email-highlight">our own Licensed Customs Broker and have a dedicated warehousing and trucking team in the US to cater to your consignee’s warehouse location.</mark></div>
      <div>• We carry over 75,000+ TEUs annually.</div>
      <div>• We carry substantial import volumes too, both FCL as well as LCL.</div>
      <div><br></div>
      <div>Swift also has a dominating presence in other parts of the globe with its well-developed, strong Agent Networks &amp; Partnerships.</div>
    `;
  }

  function quotationHtml(){
    return `
      <div>Please find the best rates for your inquiry below</div>
      <div><br></div>
      <div>POL:</div>
      <div><br></div>
      <div>POD:</div>
      <div><br></div>
      <div>Freight:                         +locals+GST</div>
      <div><br></div>
      <div>T.T:                             30 Days.</div>
      <div><br></div>
      <div>Line:</div>
      <div><br></div>
      <div>Validity:</div>
      <div><br></div>
      <div>-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x-x</div>
      <div><br></div>
      <div>POL:</div>
      <div><br></div>
      <div>POD:</div>
      <div><br></div>
      <div>Freight:                         +locals+GST</div>
      <div><br></div>
      <div>T.T:                             30 Days.</div>
      <div><br></div>
      <div>Line:</div>
      <div><br></div>
      <div>Validity:</div>
      <div><br></div>
      <div><b>NOTE:</b></div>
      <div><br></div>
      <div>• No-show and cancellation charges will be at <b>actuals</b>.</div>
      <div>• Subject to <b>cargo acceptance and space availability</b>.</div>
      <div>• Subject to <b>GRI, EFS, and War Surcharge</b>, if applicable.</div>
    `;
  }

  function htmlToPlain(html){
    const box = document.createElement('div');
    box.innerHTML = html;
    return (box.innerText || box.textContent || '').replace(/\u00a0/g,' ');
  }

  function showOverlay(el){
    el.classList.remove('hidden');
    el.setAttribute('aria-hidden','false');
  }
  function hideOverlay(el){
    el.classList.add('hidden');
    el.setAttribute('aria-hidden','true');
  }

  let previewAttachmentFile = null;

  function showChoice(record){
    emailRecord = record || currentRecord();
    showOverlay(choice);
  }

  function updateAttachmentState(template){
    const wrap = $('#swift-email-attachment');
    const name = $('#swift-email-attachment-name');
    const status = $('#swift-email-attachment-status');
    const err = $('#swift-email-error');
    if (!wrap || !name || !status) return;

    wrap.classList.remove('show');
    if (template !== 'company-profile') return;

    const configured = getConfiguredProfileAttachmentUrl();
    name.textContent = 'Swift Cargo Company Profile.pdf';
    status.textContent = configured ? 'Configured attachment' : 'Attachment not configured';
    wrap.classList.add('show');
    if (configured && err){ err.textContent=''; err.classList.remove('show'); }
  }

  async function openComposer(template, record){
    emailRecord = record || currentRecord();
    activeTemplate = template;
    const to = businessEmail(emailRecord);

    $('#swift-email-to').value = to;
    $('#swift-email-subject').value =
      template === 'company-profile' ? 'Swift Cargo Company Profile' :
      template === 'quotation' ? 'Quotation' : '';

    const editor = $('#swift-email-editor');
    editor.innerHTML =
      template === 'company-profile' ? companyProfileHtml(to, emailRecord) :
      template === 'quotation' ? quotationHtml() : '';

    $('#swift-email-composer-title').textContent =
      template === 'company-profile' ? 'Swift Cargo Company Profile' :
      template === 'quotation' ? 'Quotation' : 'Manual Mail';

    $('#swift-email-composer-sub').textContent =
      template === 'manual' ? 'Blank composer — only the recipient is prefilled.' :
      'Review and edit the template before creating the email draft.';

    const note = $('#swift-email-foot-note');
    if (note) note.textContent = template === 'manual'
      ? 'To is taken from Business Email 1 when available.'
      : 'Click Preview & Confirm to review before downloading.';

    const sendBtn=$('#swift-email-send');
    if(sendBtn) sendBtn.textContent = template === 'company-profile' ? 'Preview & Confirm' : 'Open Email';

    const err = $('#swift-email-error');
    if (err){ err.textContent=''; err.classList.remove('show'); }

    updateAttachmentState(template);
    if(template === 'company-profile' && window.SwiftEmailAutomation){
      try{
        const s=await window.SwiftEmailAutomation.pdfStatus();
        if(!s.exists) updateAttachmentState(template);
      }catch(_){}
    }
    hideOverlay(choice);
    showOverlay(composer);
    setTimeout(()=>$('#swift-email-editor')?.focus(), 50);
  }

  async function openEmailPreview(){
    const to = String($('#swift-email-to')?.value || '').trim();
    const subject = String($('#swift-email-subject')?.value || '').trim();
    const editor = $('#swift-email-editor');
    const bodyHtml = editor?.innerHTML || '';
    const bodyText = htmlToPlain(bodyHtml);
    const err = $('#swift-email-error');

    if (!to){
      if (err){ err.textContent='Enter a recipient before continuing.'; err.classList.add('show'); }
      $('#swift-email-to')?.focus();
      return;
    }
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)){
      if (err){ err.textContent='Enter a valid recipient email address.'; err.classList.add('show'); }
      $('#swift-email-to')?.focus();
      return;
    }

    if(activeTemplate === 'company-profile'){
      const attachment = getConfiguredProfileAttachment();
      if (!attachment){
        if (err){ err.textContent='Company Profile PDF is not configured. Ask an Admin to upload it in Settings → Email Automation.'; err.classList.add('show'); }
        return;
      }
      try{
        const s=await window.SwiftEmailAutomation.pdfStatus();
        if(!s.exists) throw new Error('The configured Company Profile PDF was not found in Supabase Storage.');
      }catch(e){
        if (err){ err.textContent='Attachment check failed: '+(e?.message||e); err.classList.add('show'); }
        return;
      }
      previewAttachmentFile = null;
      $('#swift-email-preview-to').value = to;
      $('#swift-email-preview-subject').value = subject;
      $('#swift-email-preview-body').innerHTML = bodyHtml;
      $('#swift-email-preview-attachment-name').textContent = attachment.filename || 'Swift Cargo Company Profile.pdf';
      $('#swift-email-preview-attachment-status').textContent = 'Stored PDF will be attached to the .eml';
      const inp=$('#swift-email-preview-attachment-input'); if(inp) inp.value='';
      hideOverlay(composer);
      showOverlay($('#swift-email-preview-overlay'));
      return;
    }

    // Quotation / Manual Mail keep their existing mailto behavior.
    const href = `mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bodyText)}`;
    window.location.href = href;
  }

  function returnToComposer(){
    const previewBody=$('#swift-email-preview-body');
    $('#swift-email-to').value=$('#swift-email-preview-to').value;
    $('#swift-email-subject').value=$('#swift-email-preview-subject').value;
    $('#swift-email-editor').innerHTML=previewBody?.innerHTML||'';
    hideOverlay($('#swift-email-preview-overlay'));
    showOverlay(composer);
    setTimeout(()=>$('#swift-email-editor')?.focus(),50);
  }

  function sanitizeEmlFilename(name){
    return String(name||'email').replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,' ').trim().slice(0,100)||'email';
  }

  // RFC 2047 is used only when a header value actually contains non-ASCII
  // characters. Plain ASCII headers remain plain text so Outlook never displays
  // an encoded token such as =?UTF-8?B?...?= for a normal email address/subject.
  function encodeMimeHeader(value){
    const text=String(value||'').replace(/[\r\n]+/g,' ').trim();
    if(!text) return '';
    if(/^[\x20-\x7E]*$/.test(text)) return text;
    const bytes=new TextEncoder().encode(text);
    let binary='';
    const chunk=0x8000;
    for(let i=0;i<bytes.length;i+=chunk){
      binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+chunk,bytes.length)));
    }
    const b64=btoa(binary);
    return '=?UTF-8?B?'+b64+'?=';
  }

  function formatMailbox(displayName,email){
    const address=String(email||'').replace(/[\r\n<>]/g,'').trim();
    if(!address) return '';
    const name=String(displayName||'').replace(/[\r\n"]/g,' ').trim();
    if(!name) return `<${address}>`;
    const safeName=encodeMimeHeader(name);
    return `${safeName} <${address}>`;
  }

  function base64LinesFromArrayBuffer(buffer){
    const bytes=new Uint8Array(buffer);
    let binary='';
    const chunk=0x8000;
    for(let i=0;i<bytes.length;i+=chunk){
      binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+chunk,bytes.length)));
    }
    const b64=btoa(binary), lines=[];
    for(let i=0;i<b64.length;i+=76) lines.push(b64.slice(i,i+76));
    return lines.join('\r\n');
  }

  function base64LinesFromUtf8(text){
    return base64LinesFromArrayBuffer(new TextEncoder().encode(String(text||'')).buffer);
  }

  function escapeHeaderFilename(name){
    return String(name||'attachment.pdf').replace(/[\r\n"]/g,'_').trim() || 'attachment.pdf';
  }

  async function confirmAndDownloadEmail(){
    const err=$('#swift-email-preview-error');
    const btn=$('#swift-email-confirm-download');
    if(err){err.textContent='';err.classList.remove('show');}

    const to=String($('#swift-email-preview-to')?.value||'').trim();
    const subject=String($('#swift-email-preview-subject')?.value||'').trim();
    const bodyHtml=$('#swift-email-preview-body')?.innerHTML||'';
    const bodyText=htmlToPlain(bodyHtml);

    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)){
      if(err){err.textContent='Enter a valid recipient email address.';err.classList.add('show');}
      return;
    }
    if(!subject){
      if(err){err.textContent='Subject cannot be empty.';err.classList.add('show');}
      return;
    }
    if(!bodyText.trim()){
      if(err){err.textContent='Email body cannot be empty.';err.classList.add('show');}
      return;
    }

    if(btn)btn.disabled=true;
    try{
      let pdfBlob=previewAttachmentFile;
      let filename='Swift Cargo Company Profile.pdf';

      if(!pdfBlob){
        const attachment=getConfiguredProfileAttachment();
        if(!attachment)throw new Error('No PDF attachment is configured.');
        const result=await supa.storage.from(attachment.bucket).download(attachment.path);
        if(result.error)throw result.error;
        pdfBlob=result.data;
        filename='Swift Cargo Company Profile.pdf';
      }else{
        filename='Swift Cargo Company Profile.pdf';
      }

      if(!pdfBlob)throw new Error('Could not load the PDF attachment.');
      const pdfBuffer=await pdfBlob.arrayBuffer();
      const boundary='=_SwiftCargo_Mixed_'+crypto.randomUUID();
      const altBoundary='=_SwiftCargo_Alt_'+crypto.randomUUID();

      const senderEmail=String(S.session?.user?.email||'').trim();
      if(!senderEmail) throw new Error('The current account has no sender email address.');
      const senderName=String(S.profile?.full_name||S.profile?.username||'Swift Cargo').trim();
      const recipientName=contactName(emailRecord, to);
      const normalizedHtml=String(bodyHtml||'').replace(/\r?\n/g,'\r\n');
      const normalizedText=String(bodyText||'').replace(/\r?\n/g,'\r\n');
      const safeFilename=escapeHeaderFilename(filename);

      // RFC 5322 + MIME message. All text parts are UTF-8/base64 so Outlook does
      // not misinterpret Unicode or expose raw MIME transfer data in the message.
      const eml=[
        `From: ${formatMailbox(senderName,senderEmail)}`,
        `To: ${formatMailbox(recipientName,to)}`,
        `Subject: ${encodeMimeHeader(subject)}`,
        `Date: ${new Date().toUTCString()}`,
        'MIME-Version: 1.0',
        'X-Unsent: 1',
        `Content-Type: multipart/mixed; boundary="${boundary}"`,
        '',
        `--${boundary}`,
        `Content-Type: multipart/alternative; boundary="${altBoundary}"`,
        '',
        `--${altBoundary}`,
        'Content-Type: text/plain; charset=UTF-8',
        'Content-Transfer-Encoding: base64',
        '',
        base64LinesFromUtf8(normalizedText),
        '',
        `--${altBoundary}`,
        'Content-Type: text/html; charset=UTF-8',
        'Content-Transfer-Encoding: base64',
        '',
        base64LinesFromUtf8(normalizedHtml),
        '',
        `--${altBoundary}--`,
        '',
        `--${boundary}`,
        `Content-Type: application/pdf; name="${safeFilename}"`,
        'Content-Transfer-Encoding: base64',
        `Content-Disposition: attachment; filename="${safeFilename}"`,
        '',
        base64LinesFromArrayBuffer(pdfBuffer),
        '',
        `--${boundary}--`,
        ''
      ].join('\r\n');

      const blob=new Blob([new TextEncoder().encode(eml)],{type:'message/rfc822'});
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');
      a.href=url;
      a.download=sanitizeEmlFilename(subject)+'.eml';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),5000);

      hideOverlay($('#swift-email-preview-overlay'));
      toast('Outlook-compatible email .eml downloaded successfully','success');
    }catch(e){
      if(err){err.textContent='Could not create the .eml file: '+(e?.message||e);err.classList.add('show');}
    }finally{
      if(btn)btn.disabled=false;
    }
  }

  document.addEventListener('click', e=>{
    const emailBtn = e.target.closest?.('[data-email-action="1"]');
    if (emailBtn){
      e.preventDefault();
      e.stopPropagation();
      const r = currentRecord();
      const email = String(r?.business_email_1 || '').trim();
      showChoice(r || {business_email_1: email});
      return;
    }

    const option = e.target.closest?.('[data-email-template]');
    if (option){
      e.preventDefault();
      openComposer(option.dataset.emailTemplate, emailRecord || currentRecord());
    }
  }, true);

  $('#swift-email-choice-close')?.addEventListener('click', ()=>hideOverlay(choice));
  $('#swift-email-composer-close')?.addEventListener('click', ()=>hideOverlay(composer));
  $('#swift-email-cancel')?.addEventListener('click', ()=>hideOverlay(composer));
  $('#swift-email-send')?.addEventListener('click', openEmailPreview);

  $('#swift-email-preview-close')?.addEventListener('click', ()=>hideOverlay($('#swift-email-preview-overlay')));
  $('#swift-email-preview-edit')?.addEventListener('click', returnToComposer);
  $('#swift-email-confirm-download')?.addEventListener('click', confirmAndDownloadEmail);
  $('#swift-email-preview-overlay')?.addEventListener('click', e=>{ if(e.target.id==='swift-email-preview-overlay') hideOverlay(e.currentTarget); });

  $('#swift-email-preview-attachment-input')?.addEventListener('change', e=>{
    const file=e.target.files?.[0];
    if(!file)return;
    if(file.type!=='application/pdf'&&!/\.pdf$/i.test(file.name)){
      const err=$('#swift-email-preview-error');
      if(err){err.textContent='Only PDF files are allowed.';err.classList.add('show');}
      e.target.value='';
      return;
    }
    previewAttachmentFile=file;
    $('#swift-email-preview-attachment-name').textContent=file.name;
    $('#swift-email-preview-attachment-status').textContent='Local PDF selected for this .eml only';
    const err=$('#swift-email-preview-error'); if(err){err.textContent='';err.classList.remove('show');}
  });

  choice.addEventListener('click', e=>{ if(e.target === choice) hideOverlay(choice); });
  composer.addEventListener('click', e=>{ if(e.target === composer) hideOverlay(composer); });

  document.addEventListener('keydown', e=>{
    if(e.key !== 'Escape') return;
    const preview=$('#swift-email-preview-overlay');
    if(preview && !preview.classList.contains('hidden')) hideOverlay(preview);
    else if(!choice.classList.contains('hidden')) hideOverlay(choice);
    else if(!composer.classList.contains('hidden')) hideOverlay(composer);
  });

  $all('[data-email-cmd]', composer).forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const cmd = btn.dataset.emailCmd;
      const editor = $('#swift-email-editor');
      editor?.focus();
      if(cmd === 'hilite'){
        document.execCommand('backColor', false, '#FFEB00');
      } else {
        document.execCommand(cmd, false, null);
      }
    });
  });
})();

boot();
